INSERT INTO exercises (external_id, name, category, body_part, equipment, target, muscle_group, secondary_muscles, instructions_es, gif_url, image_url)
VALUES
('0001', '3/4 sit-up', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0001-2gPfomN.gif', '/exercises/images/0001-2gPfomN.jpg'),
('0002', '45° side bend', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia abajo a los lados. Manteniendo la espalda recta y el core activado, flexiona lentamente el torso hacia un lado, bajando la mano hacia la rodilla. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0002-Hy9D21L.gif', '/exercises/images/0002-Hy9D21L.jpg'),
('0003', 'air bike', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza. Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados. Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha. Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda. Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado.', '/exercises/gifs/0003-1ZFqTDN.gif', '/exercises/images/0003-1ZFqTDN.jpg'),
('1512', 'all fours squad stretch', 'Pierna', 'upper legs', 'body weight', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas. Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión. Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps. Mantén esta posición durante 20-30 segundos. Cambia de pierna y repite el estiramiento del otro lado.', '/exercises/gifs/1512-qBcKorM.gif', '/exercises/images/1512-qBcKorM.jpg'),
('0006', 'alternate heel touchers', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos hacia los lados, paralelos al suelo. Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho. Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0006-qaZVsGk.gif', '/exercises/images/0006-qaZVsGk.jpg'),
('0007', 'alternate lateral pulldown', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids'], 'Siéntate en la máquina de cable con la espalda recta y los pies apoyados en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Inclínate ligeramente hacia atrás y lleva las agarraderas hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0007-4IKbhHV.gif', '/exercises/images/0007-4IKbhHV.jpg'),
('1368', 'ankle circles', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'ankle stabilizers', ARRAY['ankle stabilizers'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Levanta una pierna del suelo y rota el tobillo con un movimiento circular. Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria. Repite con la otra pierna.', '/exercises/gifs/1368-uL9CsKm.gif', '/exercises/images/1368-uL9CsKm.jpg'),
('3294', 'archer push up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros. Extiende un brazo hacia el lado, paralelo al suelo. Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado. Empuja hacia arriba para volver a la posición inicial. Repite del otro lado, extendiendo el brazo opuesto hacia el lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/3294-A9qxk2F.gif', '/exercises/images/3294-A9qxk2F.jpg'),
('2355', 'arm slingers hanging bent knee legs', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'back'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las rodillas flexionadas formando un ángulo de 90 grados. Activa el core y levanta las rodillas hacia el pecho, acercándolas lo más posible a los codos. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2355-uWpxD4v.gif', '/exercises/images/2355-uWpxD4v.jpg'),
('2333', 'arm slingers hanging straight legs', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'back'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas estiradas hacia abajo. Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo. Mantén un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2333-PXTIwgu.gif', '/exercises/images/2333-PXTIwgu.jpg'),
('3214', 'arms apart circular toe touch (male)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Manteniendo las piernas rectas, flexiona el torso hacia adelante desde la cintura y lleva la mano derecha hacia los dedos de los pies. Mientras bajas, levanta simultáneamente la pierna izquierda recta detrás de ti, manteniendo el equilibrio. Regresa a la posición inicial y repite el movimiento llevando la mano izquierda hacia los dedos de los pies y levantando la pierna derecha detrás de ti. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/3214-RtyAsy1.gif', '/exercises/images/3214-RtyAsy1.jpg'),
('3204', 'arms overhead full sit-up (male)', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos por encima de la cabeza, manteniéndolos rectos. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso quede erguido. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3204-NAkmgdx.gif', '/exercises/images/3204-NAkmgdx.jpg'),
('0009', 'assisted chest dip (kneeling)', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla. Agarra las agarraderas con las palmas hacia abajo y los brazos completamente extendidos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa por un momento, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0009-PAgTVaK.gif', '/exercises/images/0009-PAgTVaK.jpg'),
('0011', 'assisted hanging knee raise', 'Core', 'waist', 'assisted', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, flexionando las caderas y las rodillas. Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0011-03lzqwk.gif', '/exercises/images/0011-03lzqwk.jpg'),
('0010', 'assisted hanging knee raise with throw down', 'Core', 'waist', 'assisted', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas. Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo. Deja que las piernas se balanceen de vuelta hacia arriba y repite el movimiento el número de repeticiones deseado.', '/exercises/gifs/0010-8K0w2yA.gif', '/exercises/images/0010-8K0w2yA.jpg'),
('1708', 'assisted lying calves stretch', 'Pantorrilla', 'lower legs', 'assisted', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Túmbate sobre tu espalda con las piernas extendidas. Flexiona una rodilla y coloca el pie plano sobre el suelo. Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite con la otra pierna.', '/exercises/gifs/1708-GxDwDX0.gif', '/exercises/images/1708-GxDwDX0.jpg'),
('1709', 'assisted lying glutes stretch', 'Pierna', 'upper legs', 'assisted', 'glutes', 'hamstrings', ARRAY['hamstrings'], 'Túmbate sobre tu espalda con las piernas extendidas. Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla. Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho. Mantén el estiramiento durante 20-30 segundos. Suelta y repite del otro lado.', '/exercises/gifs/1709-yn0LjwL.gif', '/exercises/images/1709-yn0LjwL.jpg'),
('1710', 'assisted lying gluteus and piriformis stretch', 'Pierna', 'upper legs', 'assisted', 'glutes', 'hamstrings', ARRAY['hamstrings'], 'Túmbate sobre tu espalda con las piernas extendidas. Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla. Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite del otro lado.', '/exercises/gifs/1710-RQNVT10.gif', '/exercises/images/1710-RQNVT10.jpg'),
('0012', 'assisted lying leg raise with lateral throw down', 'Core', 'waist', 'assisted', 'abs', 'hip flexors', ARRAY['hip flexors', 'obliques'], 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas. Manteniendo las piernas juntas, bájalas hacia un lado hasta que queden a pocos centímetros del suelo. Haz una pausa por un momento, luego levanta las piernas de vuelta a la posición inicial. Repite el movimiento hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0012-UGhRD1A.gif', '/exercises/images/0012-UGhRD1A.jpg'),
('0013', 'assisted lying leg raise with throw down', 'Core', 'waist', 'assisted', 'abs', 'hip flexors', ARRAY['hip flexors', 'quadriceps'], 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el core y levanta las piernas del suelo, manteniéndolas rectas. Eleva las piernas hasta que queden perpendiculares al suelo. Baja las piernas de vuelta a la posición inicial. Simultáneamente, lanza las piernas hacia el suelo, manteniéndolas rectas. Eleva las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0013-VX5YKR5.gif', '/exercises/images/0013-VX5YKR5.jpg'),
('0015', 'assisted parallel close grip pull-up', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la máquina al peso y la altura deseados. Coloca las manos en las barras paralelas con un agarre cerrado, con las palmas mirándose entre sí. Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el suelo. Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las barras, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de las barras. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0015-vrhHa6D.gif', '/exercises/images/0015-vrhHa6D.jpg'),
('0016', 'assisted prone hamstring', 'Pierna', 'upper legs', 'assisted', 'hamstrings', 'glutes', ARRAY['glutes', 'lower back'], 'Túmbate boca abajo sobre una esterilla o un banco con las piernas completamente extendidas. Pide a un compañero o usa una banda elástica para sujetar tus tobillos. Activa los isquiotibiales y levanta las piernas hacia los glúteos, manteniendo las rodillas rectas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0016-VedGSby.gif', '/exercises/images/0016-VedGSby.jpg'),
('1713', 'assisted prone lying quads stretch', 'Pierna', 'upper legs', 'assisted', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Túmbate boca abajo en el suelo con las piernas extendidas. Flexiona la rodilla izquierda y lleva la mano izquierda hacia atrás para agarrar el pie o el tobillo izquierdo. Jala suavemente el pie izquierdo hacia los glúteos, sintiendo un estiramiento en el cuádriceps izquierdo. Mantén el estiramiento durante 20-30 segundos, luego suelta. Repite con la pierna derecha.', '/exercises/gifs/1713-YUYAMEj.gif', '/exercises/images/1713-YUYAMEj.jpg'),
('1714', 'assisted prone rectus femoris stretch', 'Core', 'waist', 'assisted', 'abs', 'quadriceps', ARRAY['quadriceps'], 'Túmbate boca abajo en el suelo con las piernas rectas. Flexiona la rodilla derecha y lleva la mano derecha hacia atrás para agarrar el pie o el tobillo derecho. Jala suavemente el pie o el tobillo derecho hacia los glúteos, sintiendo un estiramiento en la parte frontal del muslo derecho. Mantén el estiramiento durante 20-30 segundos. Suelta y repite del otro lado.', '/exercises/gifs/1714-2Ryn564.gif', '/exercises/images/1714-2Ryn564.jpg'),
('0017', 'assisted pull-up', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la máquina a los valores de peso y altura deseados. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo. Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de las agarraderas. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0017-kiJ4Z2K.gif', '/exercises/images/0017-kiJ4Z2K.jpg'),
('1716', 'assisted seated pectoralis major stretch with stability ball', 'Pecho', 'chest', 'assisted', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti. Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1716-RoV1Rfa.gif', '/exercises/images/1716-RoV1Rfa.jpg'),
('1712', 'assisted side lying adductor stretch', 'Pierna', 'upper legs', 'assisted', 'adductors', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Túmbate de lado con las piernas rectas y apiladas una sobre la otra. Flexiona ligeramente la pierna de abajo para mayor estabilidad. Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón. Manteniendo la pierna de arriba recta, bájala lentamente hacia el suelo, sintiendo un estiramiento en la parte interna del muslo. Mantén el estiramiento durante 20-30 segundos. Regresa a la posición inicial y repite del otro lado.', '/exercises/gifs/1712-hC6oYY5.gif', '/exercises/images/1712-hC6oYY5.jpg'),
('1758', 'assisted sit-up', 'Core', 'waist', 'assisted', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en el borde de un banco o pide a alguien que te sujete los pies. Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1758-aumB2IV.gif', '/exercises/images/1758-aumB2IV.jpg'),
('1431', 'assisted standing chin-up', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la máquina al nivel de asistencia deseado. Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén el pecho arriba y los hombros atrás, activa el core y flexiona ligeramente las rodillas. Levanta el cuerpo flexionando los codos y llevándolos hacia abajo, en dirección a los costados. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1431-7OeHptV.gif', '/exercises/images/1431-7OeHptV.jpg'),
('1432', 'assisted standing pull-up', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la máquina a los valores de peso y altura deseados. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Activa los dorsales y los bíceps, y levántate hacia las agarraderas. Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda. Bájate lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1432-f4xtKBj.gif', '/exercises/images/1432-f4xtKBj.jpg'),
('0018', 'assisted standing triceps extension (with towel)', 'Brazo', 'upper arms', 'assisted', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza. Mantén los codos cerca de las orejas y la parte superior de los brazos quieta. Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior. Haz una pausa por un momento, luego baja lentamente la toalla de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0018-7HcfMBP.gif', '/exercises/images/0018-7HcfMBP.jpg'),
('0019', 'assisted triceps dip (kneeling)', 'Brazo', 'upper arms', 'leverage machine', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Ajusta la máquina al peso y la altura deseados. Arrodíllate sobre la almohadilla frente a la máquina, con las manos sujetando las agarraderas. Baja el cuerpo flexionando los codos, manteniendo la espalda recta y cerca de la máquina. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0019-J60bN17.gif', '/exercises/images/0019-J60bN17.jpg'),
('2364', 'assisted wide-grip chest dip (kneeling)', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla. Agarra las agarraderas con un agarre amplio y mantén los codos ligeramente flexionados. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/2364-PnZJIrk.gif', '/exercises/images/2364-PnZJIrk.jpg'),
('3220', 'astride jumps (male)', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Salta explosivamente hacia arriba, extendiendo las piernas y los brazos. Mientras estás en el aire, separa las piernas y lleva los brazos hacia los lados. Aterriza suavemente con los pies separados a la altura de los hombros, flexionando las rodillas para absorber el impacto. Repite el número de repeticiones deseado.', '/exercises/gifs/3220-f9lVSSI.gif', '/exercises/images/3220-f9lVSSI.jpg'),
('3672', 'back and forth step', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada. Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial. Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso. Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante. Repite durante la duración o el número de repeticiones deseado.', '/exercises/gifs/3672-fNGumX0.gif', '/exercises/images/3672-fNGumX0.jpg'),
('1314', 'back extension on exercise ball', 'Espalda', 'back', 'stability ball', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1314-qLpO4vV.gif', '/exercises/images/1314-qLpO4vV.jpg'),
('3297', 'back lever', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms', 'core'], 'Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Flexiona las rodillas y llévalas hacia el pecho. Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo. Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3297-GaSzzuh.gif', '/exercises/images/3297-GaSzzuh.jpg'),
('1405', 'back pec stretch', 'Espalda', 'back', 'body weight', 'lats', 'shoulders', ARRAY['shoulders', 'chest'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos rectos frente a ti, paralelos al suelo. Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo. Entrelaza los dedos y gira las palmas alejándolas del cuerpo. Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del lado opuesto.', '/exercises/gifs/1405-chfnQnM.gif', '/exercises/images/1405-chfnQnM.jpg'),
('1473', 'backward jump', 'Pierna', 'upper legs', 'body weight', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies. Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto. Repite el número de repeticiones deseado.', '/exercises/gifs/1473-SaDOwk7.gif', '/exercises/images/1473-SaDOwk7.jpg'),
('0020', 'balance board', 'Pierna', 'upper legs', 'body weight', 'quads', 'calves', ARRAY['calves', 'hamstrings', 'glutes'], 'Coloca la tabla de equilibrio sobre una superficie plana. Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado. Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado. Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado. Repite el ejercicio con el otro pie.', '/exercises/gifs/0020-xAySMB0.gif', '/exercises/images/0020-xAySMB0.jpg'),
('0968', 'band alternating biceps curl', 'Brazo', 'upper arms', 'band', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca de los costados y flexiona lentamente un brazo hacia el hombro, apretando el bíceps en la parte superior. Baja el brazo de vuelta a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/0968-3omWx6P.gif', '/exercises/images/0968-3omWx6P.jpg'),
('0969', 'band alternating v-up', 'Core', 'waist', 'band', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda. Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies. Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra. Repite el movimiento, alternando la posición de las piernas en cada repetición. Continúa durante el número de repeticiones deseado.', '/exercises/gifs/0969-ztAa1RK.gif', '/exercises/images/0969-ztAa1RK.jpg'),
('0970', 'band assisted pull-up', 'Espalda', 'back', 'band', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la banda a una barra de dominadas o a un punto de anclaje resistente. Pisa la banda y agarra la barra con las palmas mirando hacia afuera, con las manos un poco más separadas que el ancho de los hombros. Cuélgate con los brazos completamente extendidos, manteniendo el core activado y los hombros abajo y atrás. Sube el cuerpo hacia la barra juntando los omóplatos y llevando los codos hacia abajo, en dirección a las caderas. Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0970-r1XNRYB.gif', '/exercises/images/0970-r1XNRYB.jpg'),
('0971', 'band assisted wheel rollerout', 'Core', 'waist', 'band', 'abs', 'lower back', ARRAY['lower back'], 'Arrodíllate en el suelo y sostén las agarraderas de la banda con ambas manos, con las palmas hacia abajo. Coloca la banda en el suelo frente a ti y posiciona las manos separadas a la altura de los hombros. Activa el core y rueda lentamente la rueda hacia adelante, extendiendo el cuerpo lo más que puedas mientras mantienes el control. Haz una pausa por un momento en el punto más lejano, luego rueda lentamente la rueda de vuelta hacia las rodillas para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0971-zhF9lW4.gif', '/exercises/images/0971-zhF9lW4.jpg'),
('1254', 'band bench press', 'Pecho', 'chest', 'band', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros. Extiende los brazos por completo, empujando las bandas alejándolas del pecho. Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados. Repite el número de repeticiones deseado.', '/exercises/gifs/1254-khlHMqs.gif', '/exercises/images/1254-khlHMqs.jpg'),
('0980', 'band bent-over hip extension', 'Pierna', 'upper legs', 'band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Sujeta la banda a un punto de anclaje resistente a la altura del tobillo. Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros. Da un paso atrás para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas. Flexiona las caderas e inclínate hacia adelante, manteniendo la columna en posición neutral. Extiende la pierna derecha recta hacia atrás, apretando los glúteos en la parte superior. Baja la pierna derecha de vuelta y repite con la pierna izquierda. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/0980-wSScovH.gif', '/exercises/images/0980-wSScovH.jpg'),
('0972', 'band bicycle crunch', 'Core', 'waist', 'band', 'abs', 'hip flexors', ARRAY['hip flexors', 'obliques'], 'Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas. Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha. Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda. Continúa alternando el movimiento de giro, como si estuvieras pedaleando una bicicleta, manteniendo el core activado durante todo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/0972-tZkGYZ9.gif', '/exercises/images/0972-tZkGYZ9.jpg'),
('0974', 'band close-grip pulldown', 'Espalda', 'back', 'band', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente. Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros. Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas. Activa el core y mantén la espalda recta mientras tiras de la banda hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte inferior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0974-DptumMx.gif', '/exercises/images/0974-DptumMx.jpg'),
('0975', 'band close-grip push-up', 'Brazo', 'upper arms', 'band', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Coloca una banda alrededor de la parte superior de los brazos, justo por encima de los codos. Adopta una posición de flexión de brazos con las manos justo debajo de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Flexiona los codos y baja el pecho hacia el suelo, manteniendo los codos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0975-ufaxB52.gif', '/exercises/images/0975-ufaxB52.jpg'),
('0976', 'band concentration curl', 'Brazo', 'upper arms', 'band', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco o silla con las piernas separadas y los pies apoyados en el suelo. Sostén un extremo de la banda en la mano y pisa el otro extremo con el pie del mismo lado. Inclínate ligeramente hacia adelante y apoya el codo en la parte interna del muslo, justo encima de la rodilla. Con la palma hacia arriba, flexiona lentamente la mano hacia el hombro, manteniendo quieta la parte superior del brazo. Haz una pausa por un momento en la parte superior, luego baja lentamente la mano de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0976-kmVVAfu.gif', '/exercises/images/0976-kmVVAfu.jpg'),
('3117', 'band fixed back close grip pulldown', 'Espalda', 'back', 'band', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la banda a un punto fijo por encima de ti, como una barra de dominadas o una viga resistente. Siéntate en un banco o silla frente a la banda, con los pies apoyados en el suelo y las rodillas flexionadas. Agarra la banda con un agarre cerrado, con las palmas hacia ti. Mantén la espalda recta y activa el core. Tira de la banda hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales. Suelta lentamente la banda de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/3117-4LoWllp.gif', '/exercises/images/3117-4LoWllp.jpg'),
('3116', 'band fixed back underhand pulldown', 'Espalda', 'back', 'band', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Da un paso atrás para generar tensión en la banda, manteniendo los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de la banda hacia el pecho, guiando el movimiento con los codos. Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales. Suelta lentamente la tensión de la banda y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3116-ZH68exZ.gif', '/exercises/images/3116-ZH68exZ.jpg'),
('1408', 'band hip lift', 'Pierna', 'upper legs', 'band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca una banda elástica justo por encima de las rodillas. Activa los glúteos y los músculos del core. Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1408-E4R8Hz1.gif', '/exercises/images/1408-E4R8Hz1.jpg'),
('0979', 'band horizontal pallof press', 'Core', 'waist', 'band', 'abs', 'obliques', ARRAY['obliques', 'glutes'], 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Ponte de pie perpendicular al punto de anclaje con los pies separados a la altura de los hombros. Agarra la agarradera de la banda con ambas manos y aléjate del punto de anclaje para generar tensión en la banda. Lleva las manos hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo. Activa el core y mantén una postura estable. Extiende los brazos rectos frente a ti, empujando la banda alejándola del cuerpo. Mantén la posición extendida durante unos segundos, enfocándote en mantener la tensión en el core. Lleva lentamente las manos de vuelta al pecho, resistiendo el tirón de la banda. Repite el número de repeticiones deseado.', '/exercises/gifs/0979-9pa4H5m.gif', '/exercises/images/0979-9pa4H5m.jpg'),
('0981', 'band jack knife sit-up', 'Core', 'waist', 'band', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda. Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0981-KCBKjma.gif', '/exercises/images/0981-KCBKjma.jpg'),
('0983', 'band kneeling one arm pulldown', 'Espalda', 'back', 'band', 'lats', 'biceps', ARRAY['biceps', 'rhomboids'], 'Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza. Arrodíllate y sostén la banda con una mano, con la palma hacia abajo. Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado. Activa los dorsales y tira de la banda hacia el costado, llevando el codo hacia las costillas. Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0983-pmnrOp0.gif', '/exercises/images/0983-pmnrOp0.jpg'),
('0985', 'band kneeling twisting crunch', 'Core', 'waist', 'band', 'abs', 'obliques', ARRAY['obliques'], 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Arrodíllate de espaldas al punto de anclaje y sostén la banda con ambas manos, manteniendo los codos flexionados y cerca de los costados. Activa el abdomen y gira lentamente el torso hacia un lado, llevando las manos hacia la cadera opuesta. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0985-225x2Vd.gif', '/exercises/images/0985-225x2Vd.jpg'),
('0984', 'band lying hip internal rotation', 'Pierna', 'upper legs', 'band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Túmbate sobre tu espalda con las piernas rectas y una banda elástica enrollada alrededor de los pies. Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies juntos. Rota lentamente las rodillas hacia afuera, separándolas entre sí, mientras mantienes los pies juntos. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0984-vIICElP.gif', '/exercises/images/0984-vIICElP.jpg'),
('1002', 'band lying straight leg raise', 'Core', 'waist', 'band', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las piernas rectas y los pies juntos. Coloca la banda alrededor de los arcos de los pies y sostén los extremos de la banda con las manos. Activando el abdomen, levanta ambas piernas del suelo hasta que queden perpendiculares al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1002-bbLR7fB.gif', '/exercises/images/1002-bbLR7fB.jpg'),
('0986', 'band one arm overhead biceps curl', 'Brazo', 'upper arms', 'band', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca un extremo de la banda bajo el pie. Sostén el otro extremo de la banda con el brazo completamente extendido por encima de la cabeza, con la palma hacia adelante. Manteniendo quieta la parte superior del brazo, flexiona el antebrazo hacia el hombro, apretando el bíceps. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0986-UNAB8ak.gif', '/exercises/images/0986-UNAB8ak.jpg'),
('0987', 'band one arm single leg split squat', 'Pierna', 'upper legs', 'band', 'quads', 'glutes', ARRAY['glutes', 'hamstrings'], 'Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos. Extiende una pierna hacia adelante y apoya la parte superior del pie sobre un banco o escalón detrás de ti. Sujétate de un apoyo con una mano para mantener el equilibrio. Flexiona la pierna de apoyo y baja el cuerpo hacia una posición de sentadilla, manteniendo la rodilla alineada con los dedos del pie. Empuja con el talón para regresar a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0987-arsYEd3.gif', '/exercises/images/0987-arsYEd3.jpg'),
('0988', 'band one arm standing low row', 'Espalda', 'back', 'band', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Sujeta la banda a un punto de anclaje estable a la altura de la cintura. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Sostén la banda con una mano, con la palma hacia adentro, y da un paso atrás para generar tensión en la banda. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Tira de la banda hacia la cintura, juntando los omóplatos. Haz una pausa por un momento en la parte superior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0988-km0sQC0.gif', '/exercises/images/0988-km0sQC0.jpg'),
('0989', 'band one arm twisting chest press', 'Pecho', 'chest', 'band', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Sujeta la banda a un punto de anclaje resistente a la altura del pecho. Ponte de pie con el costado hacia el punto de anclaje y agarra la banda con una mano. Aléjate del punto de anclaje para generar tensión en la banda. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Lleva la mano que sostiene la banda a través del cuerpo, hacia el hombro opuesto. Manteniendo la tensión en la banda, empuja la mano hacia adelante y alejándola del cuerpo, extendiendo el brazo. Regresa lentamente a la posición inicial y repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con la otra mano.', '/exercises/gifs/0989-c16nYGA.gif', '/exercises/images/0989-c16nYGA.jpg'),
('0990', 'band one arm twisting seated row', 'Espalda', 'back', 'band', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta. Sostén la banda con una mano y extiende el brazo completamente frente a ti. Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos. Al mismo tiempo, gira el torso hacia el lado del brazo que tira. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión de la banda y regresa a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0990-DKBwJrL.gif', '/exercises/images/0990-DKBwJrL.jpg'),
('0991', 'band pull through', 'Pierna', 'upper legs', 'band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Sujeta una banda elástica a un punto de anclaje resistente a nivel del suelo. Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros. Da un paso adelante para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas. Flexiona las caderas y lleva los glúteos hacia atrás, manteniendo una ligera flexión en las rodillas. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Empuja las caderas hacia adelante y aprieta los glúteos para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0991-VtTbiP3.gif', '/exercises/images/0991-VtTbiP3.jpg'),
('0992', 'band push sit-up', 'Core', 'waist', 'band', 'abs', 'shoulders', ARRAY['shoulders', 'chest'], 'Sujeta la banda de forma segura a un punto de anclaje estable. Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Sostén la banda con ambas manos y extiende los brazos rectos hacia el techo. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0992-zFzbBfL.gif', '/exercises/images/0992-zFzbBfL.jpg'),
('0994', 'band reverse wrist curl', 'Antebrazo', 'lower arms', 'band', 'forearms', 'forearms', ARRAY['forearms'], 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén la banda con un agarre prono, con las palmas hacia abajo, y envuélvela alrededor de los dedos. Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos. Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0994-Ezpnw9d.gif', '/exercises/images/0994-Ezpnw9d.jpg'),
('0996', 'band seated hip internal rotation', 'Pierna', 'upper legs', 'band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Coloca una banda elástica alrededor de los muslos, justo por encima de las rodillas. Mantén las rodillas flexionadas formando un ángulo de 90 grados y los pies separados a la altura de los hombros. Activa los glúteos y rota lentamente las rodillas hacia afuera, empujando contra la resistencia de la banda. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0996-9gbyYKk.gif', '/exercises/images/0996-9gbyYKk.jpg'),
('1011', 'band seated twist', 'Core', 'waist', 'band', 'abs', 'obliques', ARRAY['obliques'], 'Siéntate en el suelo con las piernas extendidas frente a ti y la espalda recta. Envuelve la banda alrededor de la cintura y sostén los extremos con ambas manos. Activa el abdomen y gira lentamente el torso hacia un lado, manteniendo la espalda recta y los pies en el suelo. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1011-S1JXDAG.gif', '/exercises/images/1011-S1JXDAG.jpg'),
('0997', 'band shoulder press', 'Hombro', 'shoulders', 'band', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies. Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados. Empuja la banda por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0997-peAeMR3.gif', '/exercises/images/0997-peAeMR3.jpg'),
('1018', 'band shrug', 'Espalda', 'back', 'band', 'traps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos. Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos. Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1018-trmte8s.gif', '/exercises/images/1018-trmte8s.jpg'),
('0998', 'band side triceps extension', 'Brazo', 'upper arms', 'band', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos, con las palmas hacia abajo. Extiende los brazos hacia los lados, manteniéndolos paralelos al suelo. Flexiona lentamente los codos y lleva las manos hacia los hombros, manteniendo quieta la parte superior de los brazos. Haz una pausa por un momento, luego extiende lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0998-obe5LMq.gif', '/exercises/images/0998-obe5LMq.jpg'),
('0999', 'band single leg calf raise', 'Pantorrilla', 'lower legs', 'band', 'calves', 'ankles', ARRAY['ankles', 'feet'], 'Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie izquierdo. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Levanta lentamente el talón izquierdo del suelo, llevando el peso del cuerpo hacia la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón izquierdo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la pierna derecha.', '/exercises/gifs/0999-9JprnPh.gif', '/exercises/images/0999-9JprnPh.jpg'),
('1000', 'band single leg reverse calf raise', 'Pantorrilla', 'lower legs', 'band', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie. Sujétate de un objeto estable para mantener el equilibrio. Levanta lentamente el talón del suelo, llevando el peso del cuerpo hacia la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', '/exercises/gifs/1000-QsSQWbf.gif', '/exercises/images/1000-QsSQWbf.jpg'),
('1001', 'band single leg split squat', 'Pierna', 'upper legs', 'band', 'quads', 'glutes', ARRAY['glutes', 'hamstrings'], 'Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos. Da un paso grande hacia adelante con el pie derecho y un paso más pequeño hacia atrás con el pie izquierdo. Flexiona las rodillas y baja el cuerpo hasta que el muslo derecho quede paralelo al suelo, manteniendo la rodilla izquierda ligeramente por encima del suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite del otro lado.', '/exercises/gifs/1001-y8bYM8w.gif', '/exercises/images/1001-y8bYM8w.jpg'),
('1004', 'band squat', 'Pierna', 'upper legs', 'band', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, con la banda colocada justo por encima de las rodillas. Manteniendo el pecho arriba y el core activado, lleva las caderas hacia atrás y flexiona las rodillas para bajar a una posición de sentadilla. Asegúrate de que las rodillas se alineen con los dedos de los pies y de que el peso recaiga en los talones. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1004-TUZLh71.gif', '/exercises/images/1004-TUZLh71.jpg'),
('1003', 'band squat row', 'Pierna', 'upper legs', 'band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'back'], 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti. Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1003-w1NOByi.gif', '/exercises/images/1003-w1NOByi.jpg'),
('1005', 'band standing crunch', 'Core', 'waist', 'band', 'abs', 'obliques', ARRAY['obliques'], 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros. Sostén la banda con ambas manos y llévala hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo. Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1005-Kzg30R7.gif', '/exercises/images/1005-Kzg30R7.jpg'),
('1022', 'band standing rear delt row', 'Hombro', 'shoulders', 'band', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies. Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Tira de la banda hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1022-tc5dYrf.gif', '/exercises/images/1022-tc5dYrf.jpg'),
('1007', 'band standing twisting crunch', 'Core', 'waist', 'band', 'abs', 'obliques', ARRAY['obliques'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de la espalda, cruzándola frente al pecho. Sujeta los extremos de la banda con las manos, manteniendo los codos flexionados y cerca de los costados. Activa el abdomen y gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta. Haz una pausa breve y luego vuelve a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1007-euq4pwp.gif', '/exercises/images/1007-euq4pwp.jpg'),
('1008', 'band step-up', 'Pierna', 'upper legs', 'band', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Coloca una banda alrededor de los muslos, justo por encima de las rodillas. Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas. Sube a la plataforma con el pie derecho, empujando con el talón. Extiende la pierna izquierda hacia atrás, manteniéndola recta. Baja el pie izquierdo de nuevo hasta el suelo. Repite subiendo a la plataforma con el pie izquierdo. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/1008-d5bTEPV.gif', '/exercises/images/1008-d5bTEPV.jpg'),
('1009', 'band stiff leg deadlift', 'Pierna', 'upper legs', 'band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los tobillos. Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo. Manteniendo la espalda recta y el core activado, flexiona las caderas y baja lentamente la parte superior del cuerpo hacia el suelo. Mientras bajas, empuja las caderas hacia atrás y deja que las rodillas se flexionen ligeramente. Baja la banda hacia el suelo, sintiendo un estiramiento en los isquiotibiales. Haz una pausa breve en la posición baja, luego activa los glúteos y los isquiotibiales para levantar la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1009-kuMiR2T.gif', '/exercises/images/1009-kuMiR2T.jpg'),
('1023', 'band straight back stiff leg deadlift', 'Pierna', 'upper legs', 'band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de las piernas. Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo. Manteniendo la espalda recta y las rodillas ligeramente flexionadas, flexiona las caderas y baja la banda hacia el suelo. Siente el estiramiento en los isquiotibiales mientras bajas la banda. Activa los glúteos y los isquiotibiales para levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1023-lHeUULr.gif', '/exercises/images/1023-lHeUULr.jpg'),
('1010', 'band straight leg deadlift', 'Espalda', 'back', 'band', 'spine', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los pies. Sujeta la banda con ambas manos, con las palmas mirando hacia el cuerpo, y mantén los brazos rectos. Activa el core y mantén una ligera flexión en las rodillas. Inclínate lentamente hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado. Baja la banda hacia el suelo manteniendo las piernas rectas. Haz una pausa breve en la posición baja y luego contrae los glúteos y los isquiotibiales para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1010-KUaoUV8.gif', '/exercises/images/1010-KUaoUV8.jpg'),
('1012', 'band twisting overhead press', 'Hombro', 'shoulders', 'band', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies. Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante. Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos. Mientras empujas, gira el torso hacia un lado, manteniendo las caderas estables. Haz una pausa breve en la parte alta y luego vuelve a la posición inicial. Repite el empuje y el giro hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1012-u4bAmKp.gif', '/exercises/images/1012-u4bAmKp.jpg'),
('1369', 'band two legs calf raise - (band under both legs) v. 2', 'Pantorrilla', 'lower legs', 'band', 'calves', 'ankles', ARRAY['ankles', 'feet'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca una banda elástica bajo ambos pies. Sujeta los extremos de la banda con las manos para mantener el equilibrio. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1369-jl6uxZV.gif', '/exercises/images/1369-jl6uxZV.jpg'),
('1013', 'band underhand pulldown', 'Espalda', 'back', 'band', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Extiende completamente los brazos por encima de la cabeza, manteniendo los codos ligeramente flexionados. Activa los dorsales y tira de la banda hacia abajo en dirección al pecho, juntando los omóplatos. Haz una pausa breve en la parte baja del movimiento, luego libera lentamente la tensión y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1013-k6tUeqS.gif', '/exercises/images/1013-k6tUeqS.jpg'),
('1014', 'band v-up', 'Core', 'waist', 'band', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda. Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1014-H6ETwO9.gif', '/exercises/images/1014-H6ETwO9.jpg'),
('1015', 'band vertical pallof press', 'Core', 'waist', 'band', 'abs', 'obliques', ARRAY['obliques', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho. Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda. Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda. Extiende los brazos rectos hacia delante, manteniendo las manos a la altura del pecho. Activa el core y empuja la banda alejándola del pecho, extendiendo completamente los brazos. Mantén la posición durante unos segundos y luego lleva lentamente la banda de vuelta hacia el pecho. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1015-G7PXMlT.gif', '/exercises/images/1015-G7PXMlT.jpg'),
('1016', 'band wrist curl', 'Antebrazo', 'lower arms', 'band', 'forearms', 'biceps', ARRAY['biceps', 'triceps'], 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sujeta la banda con ambas manos, con las palmas hacia arriba, y apoya los antebrazos sobre los muslos. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos. Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1016-vUTfFHw.gif', '/exercises/images/1016-vUTfFHw.jpg'),
('1017', 'band y-raise', 'Hombro', 'shoulders', 'band', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro. Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una ''Y'' con el cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1017-aHDy5O5.gif', '/exercises/images/1017-aHDy5O5.jpg'),
('0023', 'barbell alternate biceps curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra en cada mano, con las palmas mirando hacia delante. Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps. Continúa levantando las barras hasta que los bíceps estén completamente contraídos y las barras estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras comienzas a bajar lentamente las barras de vuelta a la posición inicial. Repite el número de repeticiones deseado, alternando los brazos.', '/exercises/gifs/0023-Yza7XrQ.gif', '/exercises/images/0023-Yza7XrQ.jpg'),
('0024', 'barbell bench front squat', 'Pierna', 'upper legs', 'barbell', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes', 'calves'], 'Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, justo debajo de la clavícula. Sujeta la barra con un agarre pronado, manteniendo los codos elevados y los brazos superiores paralelos al suelo. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado. Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0024-Y7YcmIJ.gif', '/exercises/images/0024-Y7YcmIJ.jpg'),
('0026', 'barbell bench squat', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Coloca una barra en un soporte de sentadillas a la altura del pecho. Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros. Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0026-W9pFVv1.gif', '/exercises/images/0026-W9pFVv1.jpg'),
('1316', 'barbell bent arm pullover', 'Espalda', 'back', 'barbell', 'lats', 'triceps', ARRAY['triceps', 'chest'], 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho. Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1316-cA9FuWG.gif', '/exercises/images/1316-cA9FuWG.jpg'),
('2407', 'barbell biceps curl (with arm blaster)', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba. Coloca los brazos superiores contra el soporte para brazos, manteniendo los codos cerca del torso. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2407-aee2Fcj.gif', '/exercises/images/2407-aee2Fcj.jpg'),
('0028', 'barbell clean and press', 'Pierna', 'upper legs', 'barbell', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes', 'shoulders', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti. Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo. Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho. Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba. Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0028-SGY8Zui.gif', '/exercises/images/0028-SGY8Zui.jpg'),
('0029', 'barbell clean-grip front squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'core'], 'Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante. Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla. Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/0029-qi996YS.gif', '/exercises/images/0029-qi996YS.jpg'),
('0030', 'barbell close-grip bench press', 'Brazo', 'upper arms', 'barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0030-J6Dx1Mu.gif', '/exercises/images/0030-J6Dx1Mu.jpg'),
('0033', 'barbell decline bench press', 'Pecho', 'chest', 'barbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0033-GrO65fd.gif', '/exercises/images/0033-GrO65fd.jpg'),
('0034', 'barbell decline bent arm pullover', 'Espalda', 'back', 'barbell', 'lats', 'triceps', ARRAY['triceps', 'chest'], 'Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos. Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho. Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial contrayendo los dorsales. Repite el número de repeticiones deseado.', '/exercises/gifs/0034-hMEptv0.gif', '/exercises/images/0034-hMEptv0.jpg'),
('0035', 'barbell decline close grip to skull press', 'Brazo', 'upper arms', 'barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta una barra con un agarre cerrado. Baja la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos. Haz una pausa breve y luego extiende los brazos para empujar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0035-LMGXZn8.gif', '/exercises/images/0035-LMGXZn8.jpg'),
('1255', 'barbell decline pullover', 'Pecho', 'chest', 'barbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos. Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros. Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la barra describiendo un arco detrás de la cabeza, sintiendo un estiramiento en el pecho y los hombros. Haz una pausa breve y luego devuelve la barra a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/1255-9sgNE2O.gif', '/exercises/images/1255-9sgNE2O.jpg'),
('0036', 'barbell decline wide-grip press', 'Pecho', 'chest', 'barbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Baja la barra hacia el pecho, manteniendo los codos hacia los lados. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0036-hl8DUh8.gif', '/exercises/images/0036-hl8DUh8.jpg'),
('0037', 'barbell decline wide-grip pullover', 'Espalda', 'back', 'barbell', 'lats', 'triceps', ARRAY['triceps', 'chest'], 'Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos. Sujeta una barra con un agarre amplio y extiende los brazos rectos por encima del pecho. Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos rectos. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0037-Hj4FOCd.gif', '/exercises/images/0037-Hj4FOCd.jpg'),
('0038', 'barbell drag curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba. Deja que la barra cuelgue a la longitud del brazo frente a los muslos. Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0038-IENzBdA.gif', '/exercises/images/0038-IENzBdA.jpg'),
('1370', 'barbell floor calf raise', 'Pantorrilla', 'lower legs', 'barbell', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Coloca una barra en el suelo frente a ti. Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Levanta los talones lo más alto posible, usando las pantorrillas para elevar el cuerpo. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1370-2IHEa2T.gif', '/exercises/images/1370-2IHEa2T.jpg'),
('0039', 'barbell front chest squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'core'], 'Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra frente al pecho con las manos separadas a la altura de los hombros, los codos apuntando hacia delante. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0039-IeTIEqg.gif', '/exercises/images/0039-IeTIEqg.jpg'),
('0041', 'barbell front raise', 'Hombro', 'shoulders', 'barbell', 'delts', 'biceps', ARRAY['biceps', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado. Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0041-b2Uoz54.gif', '/exercises/images/0041-b2Uoz54.jpg'),
('0040', 'barbell front raise and pullover', 'Pecho', 'chest', 'barbell', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Mantén los brazos rectos y levanta la barra frente a ti hasta que alcance la altura de los hombros. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. A continuación, baja la barra detrás de la cabeza, manteniendo los brazos rectos. Haz una pausa breve en la parte baja y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0040-33AzZeV.gif', '/exercises/images/0040-33AzZeV.jpg'),
('0042', 'barbell front squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'core'], 'Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra frente a los hombros, apoyándola sobre la clavícula y los hombros. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0042-zG0zs85.gif', '/exercises/images/0042-zG0zs85.jpg'),
('1545', 'barbell full zercher squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra en el pliegue de los codos, agarrándola con las manos para mantener la estabilidad. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, apretando los glúteos en la parte alta del movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/1545-vR1vold.gif', '/exercises/images/1545-vR1vold.jpg'),
('1409', 'barbell glute bridge', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos. Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa breve en la parte alta, apretando los glúteos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1409-qKBpF7I.gif', '/exercises/images/1409-qKBpF7I.jpg'),
('3562', 'barbell glute bridge two legs on bench (male)', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'core'], 'Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas. Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos. Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros. Haz una pausa breve en la parte alta, apretando los glúteos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3562-qg2PGl6.gif', '/exercises/images/3562-qg2PGl6.jpg'),
('0044', 'barbell good morning', 'Pierna', 'upper legs', 'barbell', 'hamstrings', 'lower back', ARRAY['lower back'], 'Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda. Manteniendo la espalda recta y el core activado, flexiona las caderas hacia delante, empujando los glúteos hacia atrás como si intentaras tocar la pared detrás de ti con ellos. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Haz una pausa breve y luego vuelve a la posición inicial apretando los glúteos y empujando las caderas hacia delante. Repite el número de repeticiones deseado.', '/exercises/gifs/0044-XlZ4lAC.gif', '/exercises/images/0044-XlZ4lAC.jpg'),
('0045', 'barbell guillotine bench press', 'Pecho', 'chest', 'barbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera. Haz una pausa breve cuando la barra esté justo encima del cuello. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0045-GXoaSgn.gif', '/exercises/images/0045-GXoaSgn.jpg'),
('0046', 'barbell hack squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos. Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0046-5VCj6iH.gif', '/exercises/images/0046-5VCj6iH.jpg'),
('1436', 'barbell high bar squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras comienzas a bajar en sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/1436-Gnfo4FM.gif', '/exercises/images/1436-Gnfo4FM.jpg'),
('0047', 'barbell incline bench press', 'Pecho', 'chest', 'barbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos a un ángulo de 45 grados. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0047-3TZduzM.gif', '/exercises/images/0047-3TZduzM.jpg'),
('0048', 'barbell incline reverse-grip press', 'Brazo', 'upper arms', 'barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Recuéstate en el banco y agarra la barra con un agarre invertido, con las manos un poco más separadas que el ancho de los hombros. Saca la barra del soporte y bájala hacia la parte superior del pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0048-641mIfk.gif', '/exercises/images/0048-641mIfk.jpg'),
('0049', 'barbell incline row', 'Espalda', 'back', 'barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho apoyado en el respaldo y los pies planos sobre el suelo. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Mantén la espalda recta y el core activado. Tira de la barra hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0049-dmgMp3n.gif', '/exercises/images/0049-dmgMp3n.jpg'),
('0050', 'barbell incline shoulder raise', 'Pecho', 'chest', 'barbell', 'serratus anterior', 'deltoids', ARRAY['deltoids', 'trapezius'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados. Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0050-xi0yckC.gif', '/exercises/images/0050-xi0yckC.jpg'),
('0051', 'barbell jefferson squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre pronado, apoyándola en la parte delantera del cuerpo, justo debajo de la cintura. Da un paso con el pie izquierdo hacia delante y el pie derecho hacia atrás, manteniendo los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Empuja con los talones para volver a ponerte de pie en la posición inicial. Repite el movimiento, alternando el pie delantero y el trasero en cada repetición.', '/exercises/gifs/0051-pkSoCW9.gif', '/exercises/images/0051-pkSoCW9.jpg'),
('0052', 'barbell jm bench press', 'Brazo', 'upper arms', 'barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0052-ZsiqXYa.gif', '/exercises/images/0052-ZsiqXYa.jpg'),
('0053', 'barbell jump squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo. Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies. Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado.', '/exercises/gifs/0053-1gFNTZV.gif', '/exercises/images/0053-1gFNTZV.jpg'),
('1410', 'barbell lateral lunge', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo. Flexiona la rodilla derecha y baja el cuerpo hacia una posición de zancada, manteniendo la pierna izquierda recta. Empuja con el pie derecho y vuelve a la posición inicial. Repite hacia el otro lado, dando el paso con el pie izquierdo.', '/exercises/gifs/1410-py1HSzx.gif', '/exercises/images/1410-py1HSzx.jpg'),
('1435', 'barbell low bar squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda. Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1435-bTpEUcm.gif', '/exercises/images/1435-bTpEUcm.jpg'),
('0054', 'barbell lunge', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda. Da un paso hacia delante con el pie derecho, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado.', '/exercises/gifs/0054-t8iSghb.gif', '/exercises/images/0054-t8iSghb.jpg'),
('1720', 'barbell lying back of the head tricep extension', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1720-yg8Totb.gif', '/exercises/images/1720-yg8Totb.jpg'),
('0055', 'barbell lying close-grip press', 'Brazo', 'upper arms', 'barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas mirando hacia los pies. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0055-EcaV7aL.gif', '/exercises/images/0055-EcaV7aL.jpg'),
('0056', 'barbell lying close-grip triceps extension', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas hacia arriba. Extiende completamente los brazos, levantando la barra por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0056-HJ63mSO.gif', '/exercises/images/0056-HJ63mSO.jpg'),
('0057', 'barbell lying extension', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0057-EMpUwRI.gif', '/exercises/images/0057-EMpUwRI.jpg'),
('0058', 'barbell lying lifting (on hip)', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta la barra con un agarre pronado y colócala sobre las caderas. Activando los glúteos, levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0058-SNFfUff.gif', '/exercises/images/0058-SNFfUff.jpg'),
('0061', 'barbell lying triceps extension', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0061-iZop9xO.gif', '/exercises/images/0061-iZop9xO.jpg'),
('0060', 'barbell lying triceps extension skull crusher', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve cuando la barra esté justo encima de la frente y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0060-h8LFzo9.gif', '/exercises/images/0060-h8LFzo9.jpg'),
('0063', 'barbell narrow stance squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0063-elhhVgj.gif', '/exercises/images/0063-elhhVgj.jpg'),
('0064', 'barbell one arm bent over row', 'Espalda', 'back', 'barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral. Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Baja la barra de vuelta a la posición inicial de forma controlada. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0064-Jsgsc27.gif', '/exercises/images/0064-Jsgsc27.jpg'),
('0065', 'barbell one arm floor press', 'Brazo', 'upper arms', 'barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho. Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0065-vtusOWT.gif', '/exercises/images/0065-vtusOWT.jpg'),
('0066', 'barbell one arm side deadlift', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado. Mantén la espalda recta y el core activado. Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado. Baja la barra tanto como puedas manteniendo una buena forma. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0066-2DxtqHL.gif', '/exercises/images/0066-2DxtqHL.jpg'),
('0067', 'barbell one arm snatch', 'Hombro', 'shoulders', 'barbell', 'delts', 'traps', ARRAY['traps', 'forearms', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba. Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo. Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo. Baja la barra de vuelta a la posición inicial de forma controlada. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0067-xHKN2s8.gif', '/exercises/images/0067-xHKN2s8.jpg'),
('0068', 'barbell one leg squat', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo. Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta. Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/0068-uKyN64F.gif', '/exercises/images/0068-uKyN64F.jpg'),
('0069', 'barbell overhead squat', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos. Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0069-gfk9kD4.gif', '/exercises/images/0069-gfk9kD4.jpg'),
('1411', 'barbell palms down wrist curl over a bench', 'Antebrazo', 'lower arms', 'barbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros. Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos. Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas. Repite el número de repeticiones deseado.', '/exercises/gifs/1411-yzYH9pI.gif', '/exercises/images/1411-yzYH9pI.jpg'),
('1412', 'barbell palms up wrist curl over a bench', 'Antebrazo', 'lower arms', 'barbell', 'forearms', 'biceps', ARRAY['biceps', 'shoulders'], 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1412-SJAA2IQ.gif', '/exercises/images/1412-SJAA2IQ.jpg'),
('3017', 'barbell pendlay row', 'Espalda', 'back', 'barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3017-r0z6xzQ.gif', '/exercises/images/3017-r0z6xzQ.jpg'),
('1751', 'barbell pin presses', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Coloca una barra en un rack de potencia a la altura del pecho. Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1751-bndCa3Q.gif', '/exercises/images/1751-bndCa3Q.jpg'),
('0071', 'barbell press sit-up', 'Core', 'waist', 'barbell', 'abs', 'shoulders', ARRAY['shoulders', 'chest'], 'Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, apoyándola sobre el pecho. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0071-wnEscH8.gif', '/exercises/images/0071-wnEscH8.jpg'),
('0072', 'barbell prone incline curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sujeta una barra con un agarre supino, separado a la altura de los hombros. Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0072-WLvTAv5.gif', '/exercises/images/0072-WLvTAv5.jpg'),
('0073', 'barbell pullover', 'Espalda', 'back', 'barbell', 'lats', 'chest', ARRAY['chest', 'triceps'], 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0073-i6LWjok.gif', '/exercises/images/0073-i6LWjok.jpg'),
('0022', 'barbell pullover to press', 'Espalda', 'back', 'barbell', 'lats', 'triceps', ARRAY['triceps', 'chest', 'shoulders'], 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales. Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho. Repite el número de repeticiones deseado.', '/exercises/gifs/0022-znLogoF.gif', '/exercises/images/0022-znLogoF.jpg'),
('0074', 'barbell rack pull', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Coloca una barra en un soporte a la altura de la rodilla. Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros. Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta. Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/0074-za9Ni4z.gif', '/exercises/images/0074-za9Ni4z.jpg'),
('0075', 'barbell rear delt raise', 'Hombro', 'shoulders', 'barbell', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0075-Ln9iTbU.gif', '/exercises/images/0075-Ln9iTbU.jpg'),
('0076', 'barbell rear delt row', 'Hombro', 'shoulders', 'barbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado. Tira de la barra hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0076-S9zHIvU.gif', '/exercises/images/0076-S9zHIvU.jpg'),
('0078', 'barbell rear lunge', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Empuja con el talón izquierdo para volver a la posición inicial. Repite con la otra pierna.', '/exercises/gifs/0078-VaP75jl.gif', '/exercises/images/0078-VaP75jl.jpg'),
('0077', 'barbell rear lunge v. 2', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Empuja con el talón izquierdo para volver a la posición inicial. Repite con la otra pierna.', '/exercises/gifs/0077-62Nw60O.gif', '/exercises/images/0077-62Nw60O.jpg'),
('0079', 'barbell revers wrist curl v. 2', 'Antebrazo', 'lower arms', 'barbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos separadas a la altura de los hombros. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0079-qDnGfDb.gif', '/exercises/images/0079-qDnGfDb.jpg'),
('2187', 'barbell reverse close-grip bench press', 'Brazo', 'upper arms', 'barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra esté justo encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/2187-YqJw82s.gif', '/exercises/images/2187-YqJw82s.jpg'),
('0080', 'barbell reverse curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos. Repite el número de repeticiones deseado.', '/exercises/gifs/0080-xNrS20v.gif', '/exercises/images/0080-xNrS20v.jpg'),
('0118', 'barbell reverse grip bent over row', 'Espalda', 'back', 'barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo. Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0118-SzX3uzM.gif', '/exercises/images/0118-SzX3uzM.jpg'),
('1256', 'barbell reverse grip decline bench press', 'Pecho', 'chest', 'barbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1256-DotAgEF.gif', '/exercises/images/1256-DotAgEF.jpg'),
('1257', 'barbell reverse grip incline bench press', 'Pecho', 'chest', 'barbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1257-DU7I633.gif', '/exercises/images/1257-DU7I633.jpg'),
('1317', 'barbell reverse grip incline bench row', 'Espalda', 'back', 'barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco frente al respaldo con el pecho apoyado contra él. Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado. Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento. Baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1317-8d8qJQI.gif', '/exercises/images/1317-8d8qJQI.jpg'),
('1721', 'barbell reverse grip skullcrusher', 'Brazo', 'upper arms', 'barbell', 'triceps', 'forearms', ARRAY['forearms'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros. Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas. Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1721-yRLPCLu.gif', '/exercises/images/1721-yRLPCLu.jpg'),
('0082', 'barbell reverse wrist curl', 'Antebrazo', 'lower arms', 'barbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0082-LsZkfU6.gif', '/exercises/images/0082-LsZkfU6.jpg'),
('0084', 'barbell rollerout', 'Core', 'waist', 'barbell', 'abs', 'lower back', ARRAY['lower back'], 'Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros. Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado. Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza. Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control. Repite el número de repeticiones deseado.', '/exercises/gifs/0084-7M66AVi.gif', '/exercises/images/0084-7M66AVi.jpg'),
('0083', 'barbell rollerout from bench', 'Core', 'waist', 'barbell', 'abs', 'shoulders', ARRAY['shoulders', 'triceps'], 'Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti. Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza. Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0083-Gxg9lDc.gif', '/exercises/images/0083-Gxg9lDc.jpg'),
('0086', 'barbell seated behind head military press', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza. Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0086-ngPpyRS.gif', '/exercises/images/0086-ngPpyRS.jpg'),
('0087', 'barbell seated bradford rocky press', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', '/exercises/gifs/0087-0dCyly0.gif', '/exercises/images/0087-0dCyly0.jpg'),
('1718', 'barbell seated close grip behind neck triceps extension', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante. Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1718-4CBIBOM.gif', '/exercises/images/1718-4CBIBOM.jpg'),
('0089', 'barbell seated close-grip concentration curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros. Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0089-1V1gj1u.gif', '/exercises/images/0089-1V1gj1u.jpg'),
('0090', 'barbell seated good morning', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda. Mantén la espalda recta y el pecho elevado. Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0090-d960PgE.gif', '/exercises/images/0090-d960PgE.jpg'),
('0091', 'barbell seated overhead press', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia delante. Empuja la barra por encima de la cabeza extendiendo completamente los brazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0091-kTbSH9h.gif', '/exercises/images/0091-kTbSH9h.jpg'),
('0094', 'barbell seated twist', 'Core', 'waist', 'barbell', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados. Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta. Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial. Repite el giro hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0094-dFSNDOA.gif', '/exercises/images/0094-dFSNDOA.jpg'),
('0096', 'barbell side bent v. 2', 'Core', 'waist', 'barbell', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo. Mantén la espalda recta y el core activado durante todo el ejercicio. Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0096-i4JkUaL.gif', '/exercises/images/0096-i4JkUaL.jpg'),
('0098', 'barbell side split squat', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas. Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones. Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0098-W31mMjd.gif', '/exercises/images/0098-W31mMjd.jpg'),
('0097', 'barbell side split squat v. 2', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros. Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo. Flexiona la rodilla derecha y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y la espalda recta. Empuja con el talón derecho para regresar a la posición inicial. Repite hacia el otro lado, dando el paso con el pie izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0097-HUEqZ1y.gif', '/exercises/images/0097-HUEqZ1y.jpg'),
('1756', 'barbell single leg deadlift', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono. Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio. Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada. Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1756-gEyURal.gif', '/exercises/images/1756-gEyURal.jpg'),
('0099', 'barbell single leg split squat', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta. Continúa bajando hasta que el muslo delantero quede paralelo al suelo. Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0099-gGNQmVt.gif', '/exercises/images/0099-gGNQmVt.jpg'),
('2799', 'barbell sitted alternate leg raise', 'Core', 'waist', 'barbell', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos. Manteniendo las piernas rectas, levanta una pierna lo más alto posible mientras mantienes la otra pierna en el suelo. Baja la pierna elevada y repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/2799-G7xoEzr.gif', '/exercises/images/2799-G7xoEzr.jpg'),
('2800', 'barbell sitted alternate leg raise (female)', 'Core', 'waist', 'barbell', 'abs', 'hip flexors', ARRAY['hip flexors', 'quadriceps'], 'Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos. Coloca las manos a los lados del banco para apoyarte. Manteniendo las piernas rectas, levanta una pierna lo más alto posible manteniéndola paralela al suelo. Baja la pierna y repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/2800-BCs0G2F.gif', '/exercises/images/2800-BCs0G2F.jpg'),
('0100', 'barbell skier', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo. Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0100-4Leypho.gif', '/exercises/images/0100-4Leypho.jpg'),
('0101', 'barbell speed squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras llevas las caderas hacia atrás y hacia abajo, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta. Repite el número de repeticiones deseado.', '/exercises/gifs/0101-euI1BwR.gif', '/exercises/images/0101-euI1BwR.jpg'),
('2810', 'barbell split squat v. 2', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia adelante con el pie derecho, manteniendo el torso erguido. Baja el cuerpo flexionando las rodillas y las caderas hasta que el muslo derecho quede paralelo al suelo. Haz una pausa breve, luego empuja con el talón derecho para volver a la posición inicial. Repite con la pierna izquierda adelante el número de repeticiones deseado.', '/exercises/gifs/2810-HBYyX94.gif', '/exercises/images/2810-HBYyX94.jpg'),
('0102', 'barbell squat (on knees)', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Comienza arrodillado en el suelo con las rodillas separadas a la altura de las caderas y las puntas de los pies apuntando hacia adelante. Coloca una barra sobre los hombros, sujetándola con agarre prono y las manos un poco más separadas que el ancho de los hombros. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas, manteniendo la espalda recta. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0102-oR7O9LW.gif', '/exercises/images/0102-oR7O9LW.jpg'),
('2798', 'barbell squat jump step rear lunge', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Impúlsate explosivamente hacia arriba, saltando del suelo lo más alto que puedas. Aterriza suavemente sobre los pies y de inmediato retrocede con una pierna hacia una zancada inversa. Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta. Empuja con el talón delantero para volver a la posición inicial. Repite la secuencia de salto y zancada con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/2798-RYcV1kH.gif', '/exercises/images/2798-RYcV1kH.jpg'),
('0103', 'barbell standing ab rollerout', 'Core', 'waist', 'barbell', 'abs', 'shoulders', ARRAY['shoulders', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente a los muslos. Activa el core y enrolla lentamente la barra hacia el suelo, manteniendo la espalda recta y los brazos extendidos. Continúa enrollando la barra hacia adelante hasta que el cuerpo esté completamente extendido y las manos queden justo sobre la cabeza. Haz una pausa breve, luego enrolla lentamente la barra de vuelta hacia los muslos, manteniendo el control y el core activado. Repite el número de repeticiones deseado.', '/exercises/gifs/0103-xnInPfE.gif', '/exercises/images/0103-xnInPfE.jpg'),
('0104', 'barbell standing back wrist curl', 'Antebrazo', 'lower arms', 'barbell', 'forearms', 'biceps', ARRAY['biceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono. Apoya la barra sobre el dorso de las manos con las palmas hacia abajo y los dedos apuntando hacia el cuerpo. Manteniendo los brazos superiores quietos, exhala y flexiona las muñecas hacia arriba lo más posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0104-2qTvJAZ.gif', '/exercises/images/0104-2qTvJAZ.jpg'),
('0105', 'barbell standing bradford press', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra frente a los hombros con agarre prono. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0105-dCPESfR.gif', '/exercises/images/0105-dCPESfR.jpg'),
('0106', 'barbell standing close grip curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos juntas. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Exhala al flexionar el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras comienzas a llevar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0106-4dUn2iv.gif', '/exercises/images/0106-4dUn2iv.jpg'),
('1456', 'barbell standing close grip military press', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, manos un poco más juntas que el ancho de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos cerca del cuerpo. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de nuevo a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/1456-wdRZISl.gif', '/exercises/images/1456-wdRZISl.jpg'),
('2414', 'barbell standing concentration curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba. Apoya la otra mano sobre el muslo para mayor estabilidad. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/2414-vsMcDi9.gif', '/exercises/images/2414-vsMcDi9.jpg'),
('0107', 'barbell standing front raise over head', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra frente a los muslos con agarre prono. Mantén la espalda recta y activa el core. Levanta lentamente la barra frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que la barra quede ligeramente por encima del nivel de los hombros. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0107-S8mo30S.gif', '/exercises/images/0107-S8mo30S.jpg'),
('0108', 'barbell standing leg calf raise', 'Pantorrilla', 'lower legs', 'barbell', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0108-rGwhJ5o.gif', '/exercises/images/0108-rGwhJ5o.jpg'),
('0110', 'barbell standing reverse grip curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona el peso contrayendo los bíceps, llevando la barra lo más cerca posible de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0110-LWuA3aZ.gif', '/exercises/images/0110-LWuA3aZ.jpg'),
('0111', 'barbell standing rocking leg calf raise', 'Pantorrilla', 'lower legs', 'barbell', 'calves', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, manteniendo el equilibrio sobre las puntas de los pies. Baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0111-6HiHHe0.gif', '/exercises/images/0111-6HiHHe0.jpg'),
('0112', 'barbell standing twist', 'Core', 'waist', 'barbell', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo. Activa el core y mantén la espalda recta durante todo el ejercicio. Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado izquierdo. Continúa alternando los giros el número de repeticiones deseado.', '/exercises/gifs/0112-yQe5HpE.gif', '/exercises/images/0112-yQe5HpE.jpg'),
('1629', 'barbell standing wide grip biceps curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos más separadas que el ancho de los hombros. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona la barra hacia los hombros, manteniendo los brazos superiores quietos. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1629-faHKVkK.gif', '/exercises/images/1629-faHKVkK.jpg'),
('1457', 'barbell standing wide military press', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', '/exercises/gifs/1457-Kyd9Rz5.gif', '/exercises/images/1457-Kyd9Rz5.jpg'),
('0113', 'barbell standing wide-grip curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros. Deja que la barra cuelgue a la longitud del brazo frente a los muslos, con las palmas mirando hacia afuera del cuerpo. Manteniendo los brazos superiores quietos, exhala y flexiona la barra hacia arriba contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0113-NdIb5Z1.gif', '/exercises/images/0113-NdIb5Z1.jpg'),
('0114', 'barbell step-up', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda. Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla. Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial. Repite con la pierna contraria. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/0114-Kxquu2E.gif', '/exercises/images/0114-Kxquu2E.jpg'),
('0115', 'barbell stiff leg good morning', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Manteniendo la espalda recta, inclínate hacia adelante desde las caderas, empujando los glúteos hacia atrás. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Activa los glúteos y los isquiotibiales para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0115-JrOHAZc.gif', '/exercises/images/0115-JrOHAZc.jpg'),
('0116', 'barbell straight leg deadlift', 'Pierna', 'upper legs', 'barbell', 'hamstrings', 'glutes', ARRAY['glutes', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las caderas y baja la barra hacia el suelo, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Baja la barra hasta que sientas un estiramiento en los isquiotibiales. Activa los isquiotibiales y los glúteos para levantar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0116-hrVQWvE.gif', '/exercises/images/0116-hrVQWvE.jpg'),
('0117', 'barbell sumo deadlift', 'Pierna', 'upper legs', 'barbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'lower back'], 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Coloca una barra en el suelo frente a ti, centrada entre los pies. Flexiona las rodillas y baja las caderas, manteniendo la espalda recta y el pecho elevado, para sujetar la barra con agarre prono. Activa el core y empuja con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas simultáneamente. Al levantar, mantén el pecho elevado y la espalda recta, y empuja las caderas hacia adelante para activar completamente los glúteos. Haz una pausa breve en la parte más alta, luego baja lentamente la barra de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/0117-KgI0tqW.gif', '/exercises/images/0117-KgI0tqW.jpg'),
('3305', 'barbell thruster', 'Hombro', 'shoulders', 'barbell', 'delts', 'quadriceps', ARRAY['quadriceps', 'glutes', 'hamstrings', 'core'], 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono. Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza. Baja la barra de nuevo a la altura de los hombros mientras vuelves a bajar a la posición de sentadilla. Repite el número de repeticiones deseado.', '/exercises/gifs/3305-f7Y9eDZ.gif', '/exercises/images/3305-f7Y9eDZ.jpg'),
('0120', 'barbell upright row', 'Hombro', 'shoulders', 'barbell', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta y el core activado, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0120-UDlhcO8.gif', '/exercises/images/0120-UDlhcO8.jpg'),
('0119', 'barbell upright row v. 2', 'Hombro', 'shoulders', 'barbell', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0119-83HoW9X.gif', '/exercises/images/0119-83HoW9X.jpg'),
('0121', 'barbell upright row v. 3', 'Hombro', 'shoulders', 'barbell', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo el core activado y la espalda recta, exhala mientras levantas la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0121-fI18Rbc.gif', '/exercises/images/0121-fI18Rbc.jpg'),
('0122', 'barbell wide bench press', 'Pecho', 'chest', 'barbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos ligeramente abiertos hacia afuera. Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0122-JsKq9so.gif', '/exercises/images/0122-JsKq9so.jpg'),
('1258', 'barbell wide reverse grip bench press', 'Pecho', 'chest', 'barbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo y las muñecas rectas. Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1258-945zpRg.gif', '/exercises/images/1258-945zpRg.jpg'),
('0124', 'barbell wide squat', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0124-s7HX1BY.gif', '/exercises/images/0124-s7HX1BY.jpg'),
('0123', 'barbell wide-grip upright row', 'Hombro', 'shoulders', 'barbell', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0123-RgJDRR1.gif', '/exercises/images/0123-RgJDRR1.jpg'),
('0127', 'barbell zercher squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra en el pliegue de los codos, con las manos agarrando la barra para mayor estabilidad. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0127-LSTChY9.gif', '/exercises/images/0127-LSTChY9.jpg'),
('3212', 'basic toe touch (male)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende las manos hacia las puntas de los pies, manteniendo las piernas lo más rectas posible. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3212-BbfB8Gb.gif', '/exercises/images/3212-BbfB8Gb.jpg'),
('0128', 'battling ropes', 'Hombro', 'shoulders', 'rope', 'delts', 'forearms', ARRAY['forearms', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta un extremo de la cuerda en cada mano, con las palmas mirándose entre sí. Levanta los brazos hasta la altura de los hombros, manteniendo los codos ligeramente flexionados. Comienza a hacer ondas alternas con las cuerdas, levantando y bajando rápidamente cada brazo. Continúa durante el tiempo o el número de repeticiones deseado.', '/exercises/gifs/0128-RJa4tCo.gif', '/exercises/images/0128-RJa4tCo.jpg'),
('3360', 'bear crawl', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'core', ARRAY['core', 'shoulders', 'triceps'], 'Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas. Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado. Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho. Continúa avanzando a gatas, alternando los movimientos de manos y pies. Mantén un ritmo constante y el core firme durante todo el ejercicio. Continúa durante la distancia o el tiempo deseado.', '/exercises/gifs/3360-0Yz8WdV.gif', '/exercises/images/3360-0Yz8WdV.jpg'),
('1259', 'behind head chest stretch', 'Pecho', 'chest', 'assisted', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Entrelaza los dedos detrás de la cabeza con los codos apuntando hacia afuera. Junta lentamente los omóplatos y empuja el pecho hacia adelante. Mantén el estiramiento durante 15-30 segundos. Suelta el estiramiento y repite cuantas veces lo desees.', '/exercises/gifs/1259-QoHIhPl.gif', '/exercises/images/1259-QoHIhPl.jpg'),
('0129', 'bench dip (knees bent)', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas. Desliza los glúteos fuera del banco y estira las piernas frente a ti, manteniendo los talones en el suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0129-RrLske5.gif', '/exercises/images/0129-RrLske5.jpg'),
('1399', 'bench dip on floor', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1399-9RT8oQW.gif', '/exercises/images/1399-9RT8oQW.jpg'),
('0130', 'bench hip extension', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings'], 'Siéntate en un banco con la espalda contra el banco y los pies planos en el suelo. Coloca las manos sobre el banco para apoyarte. Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0130-u27Kcdz.gif', '/exercises/images/0130-u27Kcdz.jpg'),
('3019', 'bench pull-ups', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho. Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros. Cuélgate con los brazos completamente extendidos y el cuerpo recto. Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos. Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie. Baja de nuevo a la posición inicial con control. Repite el número de repeticiones deseado.', '/exercises/gifs/3019-mExgrF9.gif', '/exercises/images/3019-mExgrF9.jpg'),
('3639', 'bent knee lying twist (male)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'obliques', ARRAY['obliques', 'hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos hacia los lados, perpendiculares al cuerpo. Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas. Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial. Repite el movimiento hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/3639-6sYyrRX.gif', '/exercises/images/3639-6sYyrRX.jpg'),
('1770', 'biceps leg concentration curl', 'Brazo', 'upper arms', 'body weight', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con las piernas separadas y los pies planos en el suelo. Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla. Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto. Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1770-sJFIDIp.gif', '/exercises/images/1770-sJFIDIp.jpg'),
('0139', 'biceps narrow pull-ups', 'Brazo', 'upper arms', 'body weight', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0139-50BETrz.gif', '/exercises/images/0139-50BETrz.jpg'),
('0140', 'biceps pull-up', 'Brazo', 'upper arms', 'body weight', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra. Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0140-guT8YnS.gif', '/exercises/images/0140-guT8YnS.jpg'),
('0137', 'body-up', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante. Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto. Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo. Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0137-U6G2gk9.gif', '/exercises/images/0137-U6G2gk9.jpg'),
('3543', 'bodyweight drop jump squat', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos. Mientras estás en el aire, junta rápidamente los pies. Aterriza suavemente sobre las puntas de los pies y de inmediato vuelve a bajar a una posición de sentadilla. Repite el número de repeticiones deseado.', '/exercises/gifs/3543-wfotm7S.gif', '/exercises/images/3543-wfotm7S.jpg'),
('1771', 'bodyweight kneeling triceps extension', 'Brazo', 'upper arms', 'body weight', 'triceps', 'shoulders', ARRAY['shoulders', 'chest'], 'Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas. Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante. Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones. Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo. Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1771-s0HKO2I.gif', '/exercises/images/1771-s0HKO2I.jpg'),
('1769', 'bodyweight side lying biceps curl', 'Brazo', 'upper arms', 'body weight', 'biceps', 'forearms', ARRAY['forearms'], 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo. Mantén el brazo superior junto al cuerpo y flexiona el codo para llevar el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1769-gscGLOU.gif', '/exercises/images/1769-gscGLOU.jpg'),
('3168', 'bodyweight squatting row', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando un objeto resistente o un entrenador de suspensión con los brazos extendidos. Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies. Desde la posición de sentadilla, tira del cuerpo hacia arriba en dirección al objeto o al entrenador de suspensión, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3168-3xK09Sk.gif', '/exercises/images/3168-3xK09Sk.jpg'),
('3167', 'bodyweight squatting row (with towel)', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una toalla frente a ti con las palmas hacia abajo. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Mientras bajas a la sentadilla, tira simultáneamente de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte más baja de la sentadilla, luego vuelve lentamente a la posición inicial mientras extiendes los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/3167-BReCuOn.gif', '/exercises/images/3167-BReCuOn.jpg'),
('1373', 'bodyweight standing calf raise', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'ankles', ARRAY['ankles', 'feet'], 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Coloca las manos sobre una pared o superficie estable para mantener el equilibrio. Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1373-bJYHBIN.gif', '/exercises/images/1373-bJYHBIN.jpg'),
('3156', 'bodyweight standing close-grip one arm row', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en una mano con agarre neutro. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/3156-v2DfH14.gif', '/exercises/images/3156-v2DfH14.jpg'),
('3158', 'bodyweight standing close-grip row', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende los brazos rectos frente a ti, sujetando la barra o las agarraderas con un agarre cerrado. Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos. Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3158-tig3PXb.gif', '/exercises/images/3158-tig3PXb.jpg'),
('3162', 'bodyweight standing one arm row', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna con una mano. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que la mancuerna cuelgue recta frente a ti, con el brazo completamente extendido. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/3162-xbkPfaw.gif', '/exercises/images/3162-xbkPfaw.jpg'),
('3161', 'bodyweight standing one arm row (with towel)', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/3161-O4oIqQD.gif', '/exercises/images/3161-O4oIqQD.jpg'),
('3166', 'bodyweight standing row', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo. Mantén la espalda recta y el core activado. Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3166-wd4ds3s.gif', '/exercises/images/3166-wd4ds3s.jpg'),
('3165', 'bodyweight standing row (with towel)', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una toalla frente a ti con ambas manos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Tira de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3165-uTv34oq.gif', '/exercises/images/3165-uTv34oq.jpg'),
('0138', 'bottoms-up', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo. Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0138-CI6baTY.gif', '/exercises/images/0138-CI6baTY.jpg'),
('1374', 'box jump down with one leg stabilization', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes'], 'Ponte de pie frente a una caja o plataforma con los pies separados a la altura de los hombros. Flexiona las rodillas y salta sobre la caja, aterrizando suavemente con un pie sobre la caja y el otro pie colgando del borde. Estabilízate sobre la caja con el pie que está sobre ella, mientras mantienes el otro pie fuera del suelo. Mantén esta posición durante unos segundos, activando los músculos de la pantorrilla para conservar el equilibrio. Baja lentamente con el pie que está sobre la caja, volviendo a la posición inicial. Repite el ejercicio con la otra pierna.', '/exercises/gifs/1374-iPm26QU.gif', '/exercises/images/1374-iPm26QU.jpg'),
('2466', 'bridge - mountain climber (cross body)', 'Core', 'waist', 'body weight', 'abs', 'glutes', ARRAY['glutes', 'quadriceps', 'hamstrings', 'shoulders', 'triceps'], 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo. Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho. Continúa alternando los lados, moviéndote a un ritmo controlado. Mantén las caderas niveladas y evita levantarlas demasiado alto o dejarlas caer demasiado bajo. Mantén un patrón de respiración constante durante todo el ejercicio. Repite el número de repeticiones deseado.', '/exercises/gifs/2466-9c6T1YX.gif', '/exercises/images/2466-9c6T1YX.jpg'),
('0870', 'butt-ups', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados, con las palmas hacia abajo. Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho. En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0870-qcNN2FN.gif', '/exercises/images/0870-qcNN2FN.jpg'),
('1494', 'butterfly yoga pose', 'Pierna', 'upper legs', 'body weight', 'adductors', 'hamstrings', ARRAY['hamstrings', 'groin'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados. Sujétate los tobillos o los pies con las manos. Siéntate erguido y alarga la columna. Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos. Mantén esta posición durante unas cuantas respiraciones. Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas.', '/exercises/gifs/1494-bWlZvXh.gif', '/exercises/images/1494-bWlZvXh.jpg'),
('0148', 'cable alternate shoulder press', 'Hombro', 'shoulders', 'cable', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas de la máquina de cable con agarre prono. Coloca las manos a la altura de los hombros, con las palmas mirando hacia adelante. Mantén el core activado y la espalda recta. Empuja una agarradera hacia arriba y hacia adelante hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', '/exercises/gifs/0148-KHPZL0b.gif', '/exercises/images/0148-KHPZL0b.jpg'),
('0149', 'cable alternate triceps extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados. Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/0149-Gchi5Tr.gif', '/exercises/images/0149-Gchi5Tr.jpg'),
('0150', 'cable bar lateral pulldown', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Ajusta la polea del cable a una posición alta y coloca una barra recta. Siéntate frente a la máquina de cable con los pies planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar. Tira de la barra hacia el pecho, guiando el movimiento con los codos y juntando los omóplatos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0150-eYnzaCm.gif', '/exercises/images/0150-eYnzaCm.jpg'),
('0151', 'cable bench press', 'Pecho', 'chest', 'cable', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables. Coloca los pies firmemente en el suelo y activa el core. Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados. Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti. Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0151-7xI5MXA.gif', '/exercises/images/0151-7xI5MXA.jpg'),
('1630', 'cable close grip curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1630-BCGQ6J5.gif', '/exercises/images/1630-BCGQ6J5.jpg'),
('1631', 'cable concentration curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco o silla con los pies planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con agarre supino y apoya el codo en la parte interna del muslo. Manteniendo el brazo superior quieto, exhala y flexiona la agarradera del cable hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta del movimiento, luego inhala y baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1631-NvfE43H.gif', '/exercises/images/1631-NvfE43H.jpg'),
('0152', 'cable concentration extension (on knee)', 'Brazo', 'upper arms', 'cable', 'triceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo. Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha. Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0152-Db7eEgw.gif', '/exercises/images/0152-Db7eEgw.jpg'),
('0153', 'cable cross-over lateral pulldown', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros. Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables. Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Tira de las agarraderas hacia abajo y a través del cuerpo, juntando los omóplatos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0153-OQ1otBN.gif', '/exercises/images/0153-OQ1otBN.jpg'),
('0154', 'cable cross-over revers fly', 'Hombro', 'shoulders', 'cable', 'delts', 'rhomboids', ARRAY['rhomboids', 'trapezius'], 'Coloca una agarradera en D en cada cable de polea baja y ponte de pie en el centro de la máquina de cable cruzado. Sujeta las agarraderas con agarre prono (palmas hacia abajo) y da un paso hacia adelante, colocando los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen activado. Con los brazos extendidos hacia los lados y ligeramente flexionados en los codos, exhala y junta los omóplatos mientras tiras de los cables hacia atrás y hacia arriba en un movimiento de apertura inversa. Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0154-aqvSOQE.gif', '/exercises/images/0154-aqvSOQE.jpg'),
('0155', 'cable cross-over variation', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Ajusta las poleas del cable a la altura del pecho. Ponte de pie en el centro de la máquina de cable con un pie delante del otro. Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados. Da un paso hacia adelante, manteniendo los brazos ligeramente flexionados. Con una ligera flexión en los codos, junta las manos frente al pecho. Haz una pausa breve, luego vuelve lentamente los brazos a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0155-0CXGHya.gif', '/exercises/images/0155-0CXGHya.jpg'),
('0868', 'cable curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con agarre supino, palmas hacia arriba. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0868-G08RZcQ.gif', '/exercises/images/0868-G08RZcQ.jpg'),
('0157', 'cable deadlift', 'Pierna', 'upper legs', 'cable', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'lower back'], 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo. Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás. Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie. Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0157-eGDudUV.gif', '/exercises/images/0157-eGDudUV.jpg'),
('0158', 'cable decline fly', 'Pecho', 'chest', 'cable', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ajusta la máquina de cable a una posición declinada. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti. Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado. Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0158-7saC5zz.gif', '/exercises/images/0158-7saC5zz.jpg'),
('1260', 'cable decline one arm press', 'Pecho', 'chest', 'cable', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la máquina de cable a una posición declinada. Ponte de pie de espaldas a la máquina y sujeta la agarradera con una mano. Colócate con la espalda contra el banco declinado y el brazo extendido recto frente a ti. Flexiona el codo y baja la agarradera hacia el pecho, manteniendo el brazo superior quieto. Haz una pausa breve en la parte más baja, luego empuja la agarradera de vuelta hacia la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1260-KHGNa16.gif', '/exercises/images/1260-KHGNa16.jpg'),
('1261', 'cable decline press', 'Pecho', 'chest', 'cable', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la máquina de cable a una posición declinada. Siéntate en el banco declinado frente a la máquina de cable. Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho. Mantén los pies planos en el suelo y la espalda firmemente apoyada en el banco. Exhala y empuja las agarraderas alejándolas del cuerpo, extendiendo completamente los brazos. Haz una pausa breve al final del movimiento, contrayendo los músculos del pecho. Inhala y vuelve lentamente las agarraderas a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1261-2Pya1cP.gif', '/exercises/images/1261-2Pya1cP.jpg'),
('0159', 'cable decline seated wide-grip row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en el banco declinado frente a la máquina de cable con los pies firmemente colocados en los reposapiés. Sujeta el accesorio del cable con un agarre prono amplio, palmas hacia abajo. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado. Tira del cable hacia la parte inferior del pecho, juntando los omóplatos. Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0159-kesXOpB.gif', '/exercises/images/0159-kesXOpB.jpg'),
('1632', 'cable drag curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1632-dXz8zjF.gif', '/exercises/images/1632-dXz8zjF.jpg'),
('0160', 'cable floor seated wide-grip row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en el suelo con las piernas extendidas y la espalda recta. Coloca una agarradera de cable en una polea baja y ubica la máquina de cable detrás de ti. Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado. Tira de la agarradera hacia la cintura, juntando los omóplatos. Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0160-veXwo0D.gif', '/exercises/images/0160-veXwo0D.jpg'),
('0161', 'cable forward raise', 'Hombro', 'shoulders', 'cable', 'delts', 'triceps', ARRAY['triceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti. Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0161-hvHhCv8.gif', '/exercises/images/0161-hvHhCv8.jpg'),
('0162', 'cable front raise', 'Hombro', 'shoulders', 'cable', 'delts', 'triceps', ARRAY['triceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que los brazos queden paralelos al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0162-u2X71Np.gif', '/exercises/images/0162-u2X71Np.jpg'),
('0164', 'cable front shoulder raise', 'Hombro', 'shoulders', 'cable', 'delts', 'trapezius', ARRAY['trapezius', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que los brazos queden paralelos al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0164-mTT3KLn.gif', '/exercises/images/0164-mTT3KLn.jpg'),
('1722', 'cable high pulley overhead tricep extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Coloca una cuerda en una polea alta y ponte de pie de espaldas a la máquina. Sujeta la cuerda con ambas manos y extiende los brazos por encima de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1722-1xHyxys.gif', '/exercises/images/1722-1xHyxys.jpg'),
('0167', 'cable high row (kneeling)', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Sujeta una barra recta a una máquina de cable a la altura del pecho. Ponte de rodillas frente a la máquina de cable y agarra la barra con un agarre prono, con las manos separadas a la altura de los hombros. Siéntate sobre los talones, manteniendo la espalda recta y el core activado. Jala la barra hacia la parte superior del abdomen, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte más alta del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0167-ZSJNetl.gif', '/exercises/images/0167-ZSJNetl.jpg'),
('0168', 'cable hip adduction', 'Pierna', 'upper legs', 'cable', 'adductors', 'glutes', ARRAY['glutes', 'quadriceps'], 'Sujeta el manguito de tobillo a tu tobillo y ponte de pie frente a la máquina de cable. Colócate lo suficientemente alejado de la máquina para que haya tensión en el cable. Coloca las manos sobre la máquina para apoyarte. Manteniendo la pierna recta, mueve lentamente la pierna por delante del cuerpo hacia la línea media. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0168-hBGWILP.gif', '/exercises/images/0168-hBGWILP.jpg'),
('0169', 'cable incline bench press', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Ajusta el banco a una inclinación de 45 grados. Sujeta las agarraderas del cable a las poleas altas. Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta las agarraderas con un agarre prono y llévalas a la altura de los hombros. Empuja las agarraderas hacia adelante y hacia arriba hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego baja lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0169-Vh0GsK4.gif', '/exercises/images/0169-Vh0GsK4.jpg'),
('1318', 'cable incline bench row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'rear deltoids'], 'Coloca un banco inclinado a un ángulo de 45 grados y sujeta una agarradera de cable a la polea baja. Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con un agarre prono y extiende los brazos completamente frente a ti. Inclínate hacia adelante desde las caderas manteniendo la espalda recta y el core activado. Jala la agarradera del cable hacia el pecho retrayendo los omóplatos y flexionando los codos. Aprieta los músculos de la espalda en la parte más alta del movimiento y luego extiende lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1318-yaMIo4D.gif', '/exercises/images/1318-yaMIo4D.jpg'),
('0171', 'cable incline fly', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Ajusta la máquina de cable a una posición baja y sujeta las agarraderas. Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado. Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0171-tBWXbIT.gif', '/exercises/images/0171-tBWXbIT.jpg'),
('0170', 'cable incline fly (on stability ball)', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Coloca un balón de estabilidad en un ángulo inclinado. Sujeta las agarraderas del cable a las poleas altas de una máquina de cable. Siéntate sobre el balón de estabilidad de espaldas a la máquina, con los pies firmemente apoyados en el suelo. Sujeta las agarraderas del cable con un agarre prono, con las palmas hacia adelante. Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado. Con un movimiento controlado, lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Continúa el movimiento hasta que los brazos queden paralelos al suelo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0170-27NNGFr.gif', '/exercises/images/0170-27NNGFr.jpg'),
('0172', 'cable incline pushdown', 'Espalda', 'back', 'cable', 'lats', 'triceps', ARRAY['triceps', 'shoulders'], 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Inclínate ligeramente hacia adelante y mantén la espalda recta. Jala la barra hacia abajo en dirección a tus muslos extendiendo los codos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0172-1PK5Uo3.gif', '/exercises/images/0172-1PK5Uo3.jpg'),
('0173', 'cable incline triceps extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ajusta la máquina de cable a una posición de polea baja. Sujeta una barra recta al cable. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono y extiende los brazos rectos por encima de la cabeza. Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado. Flexiona los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0173-Hx1WC8I.gif', '/exercises/images/0173-Hx1WC8I.jpg'),
('0174', 'cable judo flip', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques', 'shoulders'], 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo. Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo. Mientras rotas, gira el pie de atrás y permite que las caderas roten de forma natural. Extiende los brazos completamente y termina el movimiento llevando la agarradera del cable por encima del hombro. Vuelve a la posición inicial revirtiendo el movimiento, rotando el torso de regreso al centro. Repite el movimiento en el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0174-MvQPqVW.gif', '/exercises/images/0174-MvQPqVW.jpg'),
('0860', 'cable kickback', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados. Extiende el antebrazo hacia atrás, enderezando el brazo por completo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0860-HEJ6DIX.gif', '/exercises/images/0860-HEJ6DIX.jpg'),
('0175', 'cable kneeling crunch', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina. Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados. Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0175-WW95auq.gif', '/exercises/images/0175-WW95auq.jpg'),
('3697', 'cable kneeling rear delt row (with rope) (male)', 'Hombro', 'shoulders', 'cable', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids', 'biceps'], 'Sujeta una agarradera de cuerda a una polea baja y ponte de rodillas frente a la máquina. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y extiende los brazos completamente frente a ti. Manteniendo la espalda recta y el core activado, jala la cuerda hacia el cuerpo retrayendo los omóplatos. Aprieta los omóplatos al final del movimiento y mantén la posición por una breve pausa. Libera lentamente la tensión y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3697-G61cXLk.gif', '/exercises/images/3697-G61cXLk.jpg'),
('0176', 'cable kneeling triceps extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas frente a la máquina de cable. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y lleva las manos a los lados de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio. Extiende los antebrazos contrayendo los tríceps hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego vuelve lentamente a la posición inicial flexionando los codos. Repite el número de repeticiones deseado.', '/exercises/gifs/0176-KWdF2JI.gif', '/exercises/images/0176-KWdF2JI.jpg'),
('0177', 'cable lateral pulldown (with rope attachment)', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta un accesorio de cuerda a la máquina de cable en una posición alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala la cuerda hacia los costados, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento. Libera lentamente la tensión y permite que la cuerda vuelva a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0177-CuaWCmC.gif', '/exercises/images/0177-CuaWCmC.jpg'),
('2616', 'cable lateral pulldown with v-bar', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en la máquina de jalón de cable y agarra el accesorio en V con un agarre prono. Ajusta la almohadilla de rodillas para que tus muslos queden asegurados debajo de ella. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala el accesorio en V hacia la parte superior del pecho manteniendo los codos cerca del cuerpo. Aprieta los músculos de la espalda en la parte baja del movimiento. Regresa lentamente el accesorio en V a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/2616-4c9BhzB.gif', '/exercises/images/2616-4c9BhzB.jpg'),
('0178', 'cable lateral raise', 'Hombro', 'shoulders', 'cable', 'delts', 'traps', ARRAY['traps', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono. Mantén los brazos rectos y el core activado. Levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0178-goJ6ezq.gif', '/exercises/images/0178-goJ6ezq.jpg'),
('0179', 'cable low fly', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Sujeta las agarraderas a las poleas bajas de una máquina de cable y selecciona un peso adecuado. Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados, manteniendo una ligera flexión en los codos. Manteniendo el control, lleva lentamente los brazos hacia adelante con un movimiento amplio, cruzándolos frente al cuerpo. Haz una pausa por un momento en el punto más alto del movimiento, sintiendo el estiramiento en los músculos del pecho. Invierte el movimiento y regresa lentamente los brazos a la posición inicial, manteniendo la tensión en los músculos del pecho durante todo el recorrido. Repite el número de repeticiones deseado.', '/exercises/gifs/0179-FVmZVhk.gif', '/exercises/images/0179-FVmZVhk.jpg'),
('0180', 'cable low seated row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0180-hvV79Si.gif', '/exercises/images/0180-hvV79Si.jpg'),
('1634', 'cable lying bicep curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Coloca una barra recta en una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Extiende los brazos por completo, manteniendo los codos cerca de los costados. Manteniendo la parte superior de los brazos inmóvil, exhala y curva la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1634-otqIxU4.gif', '/exercises/images/1634-otqIxU4.jpg'),
('0182', 'cable lying close-grip curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Coloca una barra recta en una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Extiende los brazos por completo, manteniendo los codos cerca de los costados. Manteniendo la parte superior de los brazos inmóvil, curva la barra hacia el pecho contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Baja lentamente la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/0182-61GrD55.gif', '/exercises/images/0182-61GrD55.jpg'),
('0184', 'cable lying extension pullover (with rope attachment)', 'Espalda', 'back', 'cable', 'lats', 'triceps', ARRAY['triceps', 'shoulders'], 'Sujeta una cuerda a una máquina de cable y coloca la polea en la posición más alta. Túmbate en un banco con la cabeza orientada hacia la máquina de cable. Sujeta la cuerda con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la cuerda detrás de la cabeza manteniendo el control. Haz una pausa por un momento en la parte baja y luego sube lentamente la cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0184-Q2Eu1Ax.gif', '/exercises/images/0184-Q2Eu1Ax.jpg'),
('0185', 'cable lying fly', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo. Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho. Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0185-lJJ7Yq8.gif', '/exercises/images/0185-lJJ7Yq8.jpg'),
('0186', 'cable lying triceps extension v. 2', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con la cabeza orientada hacia la máquina de cable. Sujeta la agarradera de cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos por encima del pecho. Manteniendo la parte superior de los brazos inmóvil, baja lentamente la agarradera de cuerda hacia la frente flexionando los codos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0186-uxJcFUU.gif', '/exercises/images/0186-uxJcFUU.jpg'),
('0188', 'cable middle fly', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Sujeta los cables a ambos lados de una máquina de cable a la altura del pecho. Ponte de pie en el centro de la máquina con un pie ligeramente delante del otro. Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados. Mantén una ligera flexión en los codos y conserva una leve inclinación hacia adelante. Activa los músculos del pecho y lleva los brazos hacia adelante con un movimiento amplio. Haz una pausa por un momento en el centro y luego regresa lentamente los brazos a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0188-xLYSdtg.gif', '/exercises/images/0188-xLYSdtg.jpg'),
('0189', 'cable one arm bent over row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la agarradera del cable con una mano, con la palma hacia adentro, y extiende el brazo por completo. Jala la agarradera del cable hacia el cuerpo, manteniendo el codo cerca del costado, hasta que la mano llegue a la parte baja del pecho. Haz una pausa por un momento y luego extiende lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0189-EIsE3u8.gif', '/exercises/images/0189-EIsE3u8.jpg'),
('0190', 'cable one arm curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba. Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0190-YTur5nR.gif', '/exercises/images/0190-YTur5nR.jpg'),
('1262', 'cable one arm decline chest fly', 'Pecho', 'chest', 'cable', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Sujeta una agarradera en D a una máquina de cable con polea baja y coloca el banco en un ángulo declinado. Túmbate en el banco con la cabeza orientada hacia la máquina y agarra la agarradera con la mano derecha. Extiende el brazo recto por encima del pecho, manteniendo una ligera flexión en el codo. Con un movimiento controlado, baja el brazo hacia el lado hasta que la mano quede alineada con el hombro. Haz una pausa por un momento y luego invierte el movimiento para regresar el brazo a la posición inicial. Repite el número de repeticiones deseado y luego cambia al brazo izquierdo y repite el ejercicio.', '/exercises/gifs/1262-w4dLzSx.gif', '/exercises/images/1262-w4dLzSx.jpg'),
('1263', 'cable one arm fly on exercise ball', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y extiende el brazo hacia el lado, paralelo al suelo. Mantén el codo ligeramente flexionado y la palma hacia adelante. Lleva lentamente el brazo a través del cuerpo, apretando los músculos del pecho. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1263-hHy8tQG.gif', '/exercises/images/1263-hHy8tQG.jpg'),
('1264', 'cable one arm incline fly on exercise ball', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado. Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro. Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro. Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar el brazo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1264-P14Dz9D.gif', '/exercises/images/1264-P14Dz9D.jpg'),
('1265', 'cable one arm incline press', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Ajusta la máquina de cable a una posición de polea baja. Siéntate en un banco inclinado de espaldas a la máquina de cable. Sujeta la agarradera con una mano y llévala hasta la altura del hombro. Coloca los pies firmemente en el suelo y mantén una posición estable. Empuja la agarradera hacia adelante y hacia arriba, extendiendo el brazo por completo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1265-GKEH6jj.gif', '/exercises/images/1265-GKEH6jj.jpg'),
('1266', 'cable one arm incline press on exercise ball', 'Pecho', 'chest', 'cable', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado. Sujeta una agarradera del cable con una mano y coloca el brazo en un ángulo de 90 grados con el codo flexionado. Empuja la agarradera del cable hacia adelante y hacia arriba, extendiendo el brazo por completo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1266-6t00BsF.gif', '/exercises/images/1266-6t00BsF.jpg'),
('0191', 'cable one arm lateral bent-over', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'trapezius'], 'Ponte de pie con los pies separados a la altura de los hombros, frente a una máquina de cable. Sujeta la agarradera con una mano y retrocede un paso para crear tensión en el cable. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende el brazo hacia el lado, paralelo al suelo, con una ligera flexión en el codo. Regresa lentamente el brazo a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0191-dB07vDu.gif', '/exercises/images/0191-dB07vDu.jpg'),
('0192', 'cable one arm lateral raise', 'Hombro', 'shoulders', 'cable', 'delts', 'traps', ARRAY['traps', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta la agarradera del cable con una mano, con la palma hacia abajo, y colócate lo suficientemente alejado de la máquina para que haya tensión en el cable. Mantén el brazo recto y levántalo lentamente hacia el lado hasta que quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0192-wEulIzp.gif', '/exercises/images/0192-wEulIzp.jpg'),
('1633', 'cable one arm preacher curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott. Mantén la espalda recta y el core activado. Curva lentamente la agarradera del cable hacia el hombro, manteniendo la parte superior del brazo contra la almohadilla. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', '/exercises/gifs/1633-eHBlPsa.gif', '/exercises/images/1633-eHBlPsa.jpg'),
('1267', 'cable one arm press on exercise ball', 'Pecho', 'chest', 'cable', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y coloca el brazo a la altura del pecho, con el codo flexionado. Coloca la otra mano en la cadera para mantener el equilibrio. Empuja la agarradera del cable hacia adelante, extendiendo el brazo por completo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1267-MKIelrR.gif', '/exercises/images/1267-MKIelrR.jpg'),
('3563', 'cable one arm pulldown', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta una agarradera individual a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera con un agarre prono y extiende el brazo por completo. Mantén la espalda recta y el core activado. Jala la agarradera hacia abajo en dirección al costado, manteniendo el codo cerca del cuerpo. Haz una pausa por un momento en la parte baja del movimiento, apretando el dorsal. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el otro brazo.', '/exercises/gifs/3563-U5INZY6.gif', '/exercises/images/3563-U5INZY6.jpg'),
('1635', 'cable one arm reverse preacher curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la máquina de cable de modo que la polea quede en la posición más baja. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott. Mantén la espalda recta y el core activado durante todo el ejercicio. Curva lentamente el antebrazo hacia el bíceps, manteniendo la parte superior del brazo inmóvil contra la almohadilla. Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', '/exercises/gifs/1635-ZXnjcOQ.gif', '/exercises/images/1635-ZXnjcOQ.jpg'),
('0193', 'cable one arm straight back high row (kneeling)', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Sujeta una agarradera a una máquina de cable a la altura de la cintura. Ponte de rodillas frente a la máquina de cable y agarra la agarradera con una mano. Mantén la espalda recta y el core activado. Jala la agarradera hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el otro brazo.', '/exercises/gifs/0193-WrYPP2g.gif', '/exercises/images/0193-WrYPP2g.jpg'),
('1723', 'cable one arm tricep pushdown', 'Brazo', 'upper arms', 'cable', 'triceps', 'forearms', ARRAY['forearms'], 'Ponte de pie frente a una máquina de cable con un accesorio de barra recta a la altura del pecho. Sujeta la barra con un agarre prono y retrocede un paso para crear tensión en el cable. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Mantén la espalda recta y el core activado durante todo el ejercicio. Comienza con el brazo completamente extendido y perpendicular al suelo. Manteniendo la parte superior del brazo inmóvil, exhala y empuja la barra hacia abajo hasta que el brazo quede completamente extendido. Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1723-qRZ5S1N.gif', '/exercises/images/1723-qRZ5S1N.jpg'),
('1636', 'cable overhead curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y curva la barra hacia la frente, manteniendo la parte superior de los brazos inmóvil. Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps. Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/1636-wDUqY2u.gif', '/exercises/images/1636-wDUqY2u.jpg'),
('1637', 'cable overhead curl on exercise ball', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Siéntate sobre un balón de ejercicio y sujeta la agarradera del cable con un agarre supino. Extiende los brazos completamente por encima de la cabeza, manteniendo los codos cerca de las orejas. Curva lentamente el cable hacia la frente, manteniendo la parte superior de los brazos inmóvil. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1637-ioTf098.gif', '/exercises/images/1637-ioTf098.jpg'),
('0194', 'cable overhead triceps extension (rope attachment)', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Sujeta una cuerda a una máquina de cable en una posición alta. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y lleva las manos por encima de la cabeza. Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0194-2IxROQ1.gif', '/exercises/images/0194-2IxROQ1.jpg'),
('1319', 'cable palm rotational row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta una agarradera a una máquina de cable a la altura de la cintura. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera con un agarre prono, con las palmas hacia abajo. Retrocede un paso para crear tensión en el cable, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Jala la agarradera hacia el cuerpo, rotando las palmas hacia arriba mientras lo haces. Aprieta los omóplatos al final del movimiento. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1319-OmQ8w0p.gif', '/exercises/images/1319-OmQ8w0p.jpg'),
('0195', 'cable preacher curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, agarrando el accesorio del cable con un agarre supino. Mantén la espalda recta y los codos pegados a los costados. Curva lentamente el accesorio del cable hacia los hombros, apretando los bíceps en la parte más alta del movimiento. Haz una pausa por un momento y luego baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0195-P2lNrGL.gif', '/exercises/images/0195-P2lNrGL.jpg'),
('1268', 'cable press on exercise ball', 'Pecho', 'chest', 'cable', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y las rodillas en un ángulo de 90 grados. Sujeta las agarraderas del cable a la altura del pecho con las palmas hacia abajo y los codos flexionados. Activa el core y empuja las agarraderas del cable hacia adelante hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego libera lentamente la tensión, regresando las agarraderas del cable a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1268-vAwm6rK.gif', '/exercises/images/1268-vAwm6rK.jpg'),
('0196', 'cable pull through (with rope)', 'Pierna', 'upper legs', 'cable', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio de cuerda con ambas manos y da un paso hacia adelante, creando tensión en el cable. Flexiona las caderas y baja la parte superior del cuerpo hasta que quede paralela al suelo, manteniendo la espalda recta. Activa los glúteos y los isquiotibiales para llevar el cuerpo de vuelta hacia arriba, a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0196-OM46QHm.gif', '/exercises/images/0196-OM46QHm.jpg'),
('0198', 'cable pulldown', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la máquina de jalón de cable de modo que el asiento quede a una altura cómoda y la almohadilla de rodillas esté asegurada. Siéntate con la espalda recta y los pies apoyados planos en el suelo. Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y activa el core. Jala la barra del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0198-RVwzP10.gif', '/exercises/images/0198-RVwzP10.jpg'),
('0197', 'cable pulldown (pro lat bar)', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento para que tus muslos queden paralelos al suelo y tus pies queden apoyados planos en el suelo. Sujeta la barra de jalón con un agarre prono, un poco más separado que el ancho de los hombros. Siéntate e inclínate ligeramente hacia atrás, manteniendo el pecho elevado y la espalda recta. Jala la barra hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0197-qdRxqCj.gif', '/exercises/images/0197-qdRxqCj.jpg'),
('1638', 'cable pulldown bicep curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Sujeta una barra recta a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y curva lentamente la barra hacia los muslos, manteniendo las muñecas rectas. Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps. Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/1638-QTXKWPh.gif', '/exercises/images/1638-QTXKWPh.jpg'),
('0201', 'cable pushdown', 'Brazo', 'upper arms', 'cable', 'triceps', 'forearms', ARRAY['forearms'], 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y empuja la barra hacia abajo hasta que los codos queden completamente extendidos. Haz una pausa por un momento, luego inhala y regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0201-3ZflifB.gif', '/exercises/images/0201-3ZflifB.jpg'),
('0199', 'cable pushdown (straight arm) v. 2', 'Espalda', 'back', 'cable', 'lats', 'triceps', ARRAY['triceps', 'shoulders'], 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo. Activa el core y mantén la espalda recta mientras exhalas y empujas la barra hacia abajo en dirección a los muslos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', '/exercises/gifs/0199-PskORrA.gif', '/exercises/images/0199-PskORrA.jpg'),
('0200', 'cable pushdown (with rope attachment)', 'Brazo', 'upper arms', 'cable', 'triceps', 'forearms', ARRAY['forearms'], 'Sujeta un accesorio de cuerda a una polea alta en una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y empuja la cuerda hacia abajo extendiendo los codos hasta que los brazos queden completamente extendidos. Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial permitiendo que los codos se flexionen. Repite el número de repeticiones deseado.', '/exercises/gifs/0200-dU605di.gif', '/exercises/images/0200-dU605di.jpg'),
('0202', 'cable rear delt row (stirrups)', 'Hombro', 'shoulders', 'cable', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids', 'biceps'], 'Sujeta un asa de estribo a una polea de cable baja y ponte de pie frente a la máquina. Sujeta el asa con la mano izquierda y retrocede un paso con el pie derecho, colocando el cuerpo en un ligero ángulo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Con el brazo izquierdo extendido y la palma hacia abajo, jala el asa hacia el pecho retrayendo el omóplato. Haz una pausa por un momento en la parte más alta del movimiento, apretando el omóplato. Suelta lentamente el asa de vuelta a la posición inicial y repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el brazo derecho.', '/exercises/gifs/0202-yUdIGNs.gif', '/exercises/images/0202-yUdIGNs.jpg'),
('0203', 'cable rear delt row (with rope)', 'Hombro', 'shoulders', 'cable', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids', 'biceps'], 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera de cuerda con un agarre prono, con las palmas una frente a la otra. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Mantén los codos ligeramente flexionados y jala la cuerda hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte más alta del movimiento y luego libera lentamente la tensión, regresando a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0203-wqNPGCg.gif', '/exercises/images/0203-wqNPGCg.jpg'),
('0204', 'cable rear drive', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders', 'back'], 'Sujeta una agarradera a una máquina de cable con polea baja y ponte de pie de espaldas a la máquina. Sujeta la agarradera con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo los codos inmóviles, jala la agarradera de vuelta hacia el cuerpo, apretando los tríceps al final del movimiento. Regresa lentamente la agarradera a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0204-c3QQLPi.gif', '/exercises/images/0204-c3QQLPi.jpg'),
('0205', 'cable rear pulldown', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Ajusta la máquina de cable de modo que la polea quede en la posición más alta. Siéntate frente a la máquina con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta el accesorio del cable con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado. Jala el accesorio del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0205-SpsOSXk.gif', '/exercises/images/0205-SpsOSXk.jpg'),
('0873', 'cable reverse crunch', 'Core', 'waist', 'cable', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Sujeta un cable a una polea baja y túmbate boca arriba sobre un tapete. Sujeta el cable con ambas manos y extiende los brazos rectos hacia el techo. Flexiona las rodillas y levanta las piernas, llevando los muslos hacia el pecho. Mientras mantienes la parte superior del cuerpo estable, curva la pelvis hacia el pecho, levantando las caderas del tapete. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0873-RqOtqD7.gif', '/exercises/images/0873-RqOtqD7.jpg'),
('0206', 'cable reverse curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0206-eOG0r6v.gif', '/exercises/images/0206-eOG0r6v.jpg'),
('2406', 'cable reverse grip triceps pushdown (sz-bar) (with arm blaster)', 'Brazo', 'upper arms', 'cable', 'triceps', 'forearms', ARRAY['forearms'], 'Sujeta una barra recta a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y empuja lentamente la barra hacia abajo hasta que los brazos queden completamente extendidos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2406-ThKP69G.gif', '/exercises/images/2406-ThKP69G.jpg'),
('1413', 'cable reverse one arm curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino, con la palma hacia abajo. Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1413-gVlnLIJ.gif', '/exercises/images/1413-gVlnLIJ.jpg'),
('0209', 'cable reverse preacher curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, con las palmas hacia abajo y los codos completamente extendidos. Agarra las agarraderas del cable con un agarre supino, separadas a la altura de los hombros. Manteniendo la parte superior de los brazos inmóvil, exhala y curva las agarraderas hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/0209-IwX5NqK.gif', '/exercises/images/0209-IwX5NqK.jpg'),
('0210', 'cable reverse wrist curl', 'Antebrazo', 'lower arms', 'cable', 'forearms', 'forearms', ARRAY['forearms', 'wrists'], 'Sujeta un cable a una polea baja y siéntate en un banco frente a la máquina de cable. Sujeta la agarradera del cable con un agarre prono, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Haz una pausa por un momento en la parte alta, luego inhala y baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0210-eYmsEPR.gif', '/exercises/images/0210-eYmsEPR.jpg'),
('0207', 'cable reverse-grip pushdown', 'Brazo', 'upper arms', 'cable', 'triceps', 'forearms', ARRAY['forearms'], 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Usando los tríceps, empuja la barra hacia abajo hasta que los brazos queden completamente extendidos y los tríceps contraídos. Haz una pausa por un momento y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0207-VjYliFZ.gif', '/exercises/images/0207-VjYliFZ.jpg'),
('0208', 'cable reverse-grip straight back seated high row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala el cable hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0208-PNtsX17.gif', '/exercises/images/0208-PNtsX17.jpg'),
('1320', 'cable rope crossover seated row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado. Jala las cuerdas del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1320-UFGF6gk.gif', '/exercises/images/1320-UFGF6gk.jpg'),
('1321', 'cable rope elevated seated row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en el asiento elevado frente a la máquina de cable. Agarra las agarraderas de cuerda con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia atrás, conservando una ligera flexión en las rodillas. Jala el cable hacia el cuerpo retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa por un momento en la posición de contracción completa. Libera lentamente la tensión y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1321-c8oybX6.gif', '/exercises/images/1321-c8oybX6.jpg'),
('1322', 'cable rope extension incline bench row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados y sujeta una máquina de cable a la polea baja. Sujeta una agarradera de cuerda a la máquina de cable y siéntate en el banco inclinado frente a la máquina. Agarra la agarradera de cuerda con un agarre prono e inclínate hacia adelante, manteniendo la espalda recta. Extiende los brazos por completo, jalando la cuerda hacia la parte superior del pecho mientras mantienes los codos cerca del cuerpo. Aprieta los omóplatos al final del movimiento. Libera lentamente la tensión y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1322-MgKwAAo.gif', '/exercises/images/1322-MgKwAAo.jpg'),
('1639', 'cable rope hammer preacher curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Sujeta un accesorio de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra). Coloca la parte superior de los brazos contra la almohadilla del banco scott, manteniendo los codos ligeramente flexionados. Manteniendo la parte superior de los brazos inmóvil, exhala y curva la cuerda hacia los hombros contrayendo los bíceps. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1639-PcPe0P5.gif', '/exercises/images/1639-PcPe0P5.jpg'),
('1724', 'cable rope high pulley overhead tricep extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Sujeta una cuerda a una polea alta y ajusta el peso según corresponda. Ponte de pie de espaldas a la máquina de poleas con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas hacia abajo, y lleva las manos por encima de la cabeza. Mantén la parte superior de los brazos cerca de la cabeza y perpendicular al suelo. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1724-NN8nSNT.gif', '/exercises/images/1724-NN8nSNT.jpg'),
('1725', 'cable rope incline tricep extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Sujeta una cuerda a una polea alta y ajusta el banco inclinado a un ángulo cómodo. Ponte de pie de espaldas a la polea con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre prono y extiende los brazos rectos por encima de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio. Baja la cuerda detrás de la cabeza flexionando los codos hasta que los antebrazos toquen los bíceps. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1725-ZujAdR9.gif', '/exercises/images/1725-ZujAdR9.jpg'),
('1726', 'cable rope lying on floor tricep extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Sujeta una cuerda a una máquina de cable y colócala en la posición más baja. Túmbate en el suelo boca arriba, con la cabeza orientada hacia la máquina de cable. Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos hacia el techo. Mantén la parte superior de los brazos inmóvil y baja lentamente la cuerda hacia la frente, flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1726-U3ffHlY.gif', '/exercises/images/1726-U3ffHlY.jpg'),
('1640', 'cable rope one arm hammer preacher curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera de cuerda con un agarre supino, con las palmas hacia arriba. Coloca la parte superior del brazo contra la almohadilla del banco scott, manteniendo el codo ligeramente flexionado. Mantén la espalda recta y el core activado durante todo el ejercicio. Curva lentamente la agarradera de cuerda hacia el hombro, manteniendo la parte superior del brazo inmóvil. Aprieta el bíceps en la parte más alta del movimiento y luego baja lentamente la agarradera de cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1640-4hATdoB.gif', '/exercises/images/1640-4hATdoB.jpg'),
('1323', 'cable rope seated row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos. Jala las cuerdas del cable hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1323-SJqRxOt.gif', '/exercises/images/1323-SJqRxOt.jpg'),
('2144', 'cable seated chest press', 'Pecho', 'chest', 'cable', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ajusta la altura del asiento y las agarraderas del cable a una posición cómoda. Siéntate en el banco con la espalda recta y los pies apoyados planos en el suelo. Sujeta las agarraderas del cable con un agarre prono a la altura del hombro. Empuja las agarraderas hacia adelante y alejándolas del cuerpo, extendiendo los brazos por completo. Haz una pausa por un momento y luego regresa lentamente las agarraderas a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2144-nIR4Rwl.gif', '/exercises/images/2144-nIR4Rwl.jpg'),
('0212', 'cable seated crunch', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas flexionadas. Sujeta la agarradera del cable con ambas manos y colócala detrás de la cabeza. Activa el abdomen y curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte alta y luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0212-8xUv4J7.gif', '/exercises/images/0212-8xUv4J7.jpg'),
('1641', 'cable seated curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y la espalda recta. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo la parte superior de los brazos inmóvil, exhala y curva el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1641-8oYqOt9.gif', '/exercises/images/1641-8oYqOt9.jpg'),
('0213', 'cable seated high row (v-bar)', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Siéntate en la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta el accesorio en V con un agarre prono, con las palmas una frente a la otra y las manos separadas a la altura de los hombros. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala el accesorio en V hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa por un momento en el punto más alto de la contracción, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0213-pwt0pnM.gif', '/exercises/images/0213-pwt0pnM.jpg'),
('0214', 'cable seated one arm alternate row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en un banco frente a una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera con una mano y mantén el brazo completamente extendido frente a ti. Jala la agarradera hacia el cuerpo, retrayendo el omóplato y manteniendo el codo cerca del costado. Haz una pausa por un momento en la parte más alta del movimiento, apretando los músculos de la espalda. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', '/exercises/gifs/0214-vpp9Ku2.gif', '/exercises/images/0214-vpp9Ku2.jpg'),
('1642', 'cable seated one arm concentration curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y coloca el codo en la parte interna del muslo, justo arriba de la rodilla. Mantén la parte superior del brazo inmóvil y curva la agarradera del cable hacia el hombro mientras exhalas. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1642-rZ80Gbp.gif', '/exercises/images/1642-rZ80Gbp.jpg'),
('1643', 'cable seated overhead curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén la parte superior de los brazos inmóvil y los codos cerca de los costados. Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1643-DpWMFP5.gif', '/exercises/images/1643-DpWMFP5.jpg'),
('0215', 'cable seated rear lateral raise', 'Hombro', 'shoulders', 'cable', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta las agarraderas del cable con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo los brazos rectos, levántalos lentamente hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0215-x825CZm.gif', '/exercises/images/0215-x825CZm.jpg'),
('0861', 'cable seated row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las agarraderas con un agarre prono, manteniendo la espalda recta y los hombros relajados. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0861-fUBheHs.gif', '/exercises/images/0861-fUBheHs.jpg'),
('0216', 'cable seated shoulder internal rotation', 'Hombro', 'shoulders', 'cable', 'delts', 'rotator cuff', ARRAY['rotator cuff', 'triceps'], 'Siéntate en un banco o silla frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta la agarradera del cable con el brazo extendido recto frente a ti, paralelo al suelo. Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás y hacia abajo. Rota lentamente el brazo hacia adentro, llevando la agarradera del cable hacia el centro del cuerpo. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0216-YPoVrBi.gif', '/exercises/images/0216-YPoVrBi.jpg'),
('2399', 'cable seated twist', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti. Manteniendo el core activado, rota lentamente el torso hacia un lado, jalando el cable a través del cuerpo. Haz una pausa por un momento al final del rango de movimiento y luego rota lentamente de vuelta a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/2399-UEjSrKI.gif', '/exercises/images/2399-UEjSrKI.jpg'),
('0218', 'cable seated wide-grip row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala la agarradera hacia la parte baja del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto de la contracción. Suelta lentamente la agarradera de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/0218-qcY50ZD.gif', '/exercises/images/0218-qcY50ZD.jpg'),
('0219', 'cable shoulder press', 'Hombro', 'shoulders', 'cable', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ajusta la máquina de cable de modo que las agarraderas queden a la altura del hombro. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con un agarre prono y llévalas hasta la altura del hombro, con los codos flexionados y apuntando hacia afuera. Empuja las agarraderas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', '/exercises/gifs/0219-PzQanLE.gif', '/exercises/images/0219-PzQanLE.jpg'),
('0220', 'cable shrug', 'Espalda', 'back', 'cable', 'traps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta las agarraderas del cable con un agarre prono y deja que los brazos cuelguen frente a ti. Manteniendo los brazos rectos, encoge los hombros hacia las orejas. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0220-Eg98Ft9.gif', '/exercises/images/0220-Eg98Ft9.jpg'),
('0222', 'cable side bend', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con una mano. Mantén la espalda recta y el core activado. Flexiona lentamente la cintura hacia un lado, bajando la agarradera del cable hacia la rodilla. Haz una pausa breve y luego vuelve a la posición inicial. Repite del otro lado. Alterna los lados durante el número de repeticiones deseado.', '/exercises/gifs/0222-wPypxFY.gif', '/exercises/images/0222-wPypxFY.jpg'),
('0221', 'cable side bend crunch (bosu ball)', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando la agarradera del cable con una mano. Coloca la otra mano en la cadera. Activa el core y flexiona lentamente la cintura hacia el lado en que sujetas el cable, manteniendo la espalda recta. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0221-qatbkEd.gif', '/exercises/images/0221-qatbkEd.jpg'),
('0223', 'cable side crunch', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Coloca un mango de cable en una polea baja y ponte de pie de lado a la máquina. Agarra el mango con la mano más alejada de la máquina y coloca la otra mano en tu cadera. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Con el abdomen activado, flexiona la cintura hacia el lado, bajando el codo hacia la cadera. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0223-q2ADGqV.gif', '/exercises/images/0223-q2ADGqV.jpg'),
('1717', 'cable squat row (with rope attachment)', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Sujeta una cuerda a una máquina de cable a la altura de la cintura. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Agarra la cuerda con un agarre prono, con las manos separadas a la altura de los hombros. Activa el core y tira de la cuerda hacia tu cuerpo, apretando los omóplatos entre sí. Mantén los codos cerca del cuerpo y continúa tirando hasta que las manos lleguen a tu pecho. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente la cuerda y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1717-f7fnAIB.gif', '/exercises/images/1717-f7fnAIB.jpg'),
('1644', 'cable squatting curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Coloca un mango de cable en el ajuste más bajo de una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies. Mientras te agachas, flexiona el mango del cable hacia los hombros, manteniendo los codos cerca de los costados. Haz una pausa breve en la parte alta del movimiento, apretando los bíceps. Baja lentamente el mango del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1644-3XFdb1Z.gif', '/exercises/images/1644-3XFdb1Z.jpg'),
('0224', 'cable standing back wrist curl', 'Antebrazo', 'lower arms', 'cable', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre prono, con las palmas hacia abajo. Mantén los brazos rectos y los codos cerca de los costados. Flexiona lentamente las muñecas hacia arriba, llevando el mango del cable hacia tu cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0224-VhX2JdE.gif', '/exercises/images/0224-VhX2JdE.jpg'),
('1375', 'cable standing calf raise', 'Pantorrilla', 'lower legs', 'cable', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujétate de los mangos de la máquina de cable o coloca una correa de tobillo de cable en tus tobillos. Levanta los talones del suelo extendiendo los tobillos lo más alto posible. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1375-yl2IYyy.gif', '/exercises/images/1375-yl2IYyy.jpg'),
('0225', 'cable standing cross-over high reverse fly', 'Hombro', 'shoulders', 'cable', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids', 'rear deltoids'], 'Coloca un mango en D en cada lado de una máquina de cable a la altura de los hombros. Ponte de pie en el medio de la máquina de cable con los pies separados a la altura de los hombros. Agarra los mangos con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante. Mantén una ligera flexión en los codos y conserva la espalda recta durante todo el ejercicio. Activa los músculos de los hombros y aprieta los omóplatos entre sí mientras tiras de los mangos hacia la parte delantera de tu cuerpo. Haz una pausa breve en el punto máximo del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0225-P5p0j8B.gif', '/exercises/images/0225-P5p0j8B.jpg'),
('0226', 'cable standing crunch', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Coloca un mango de cable en una polea alta y ponte de pie de espaldas a la máquina. Sujeta el mango con ambas manos y colócalo detrás de la cabeza, manteniendo los codos flexionados. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Con el abdomen activado, exhala y flexiona el torso hacia las rodillas, llevando los codos hacia los muslos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0226-jpgqxiS.gif', '/exercises/images/0226-jpgqxiS.jpg'),
('0874', 'cable standing crunch (with rope attachment)', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Sujeta una cuerda a una máquina de cable a la altura del pecho. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos y llévala detrás de la cabeza, manteniendo los codos flexionados. Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando los codos hacia las rodillas. Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0874-XU3ePuv.gif', '/exercises/images/0874-XU3ePuv.jpg'),
('0227', 'cable standing fly', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Coloca los mangos en los cables a la altura del pecho. Ponte de pie con los pies separados a la altura de los hombros, de espaldas a la máquina de cable. Agarra los mangos con un agarre prono, con las palmas hacia adelante. Da un paso adelante para crear tensión en los cables. Mantén el core activado y la espalda recta durante todo el ejercicio. Con una ligera flexión en los codos, lleva lentamente los brazos hacia adelante y júntalos frente al pecho. Aprieta los músculos del pecho en el punto máximo del movimiento. Invierte lentamente el movimiento, regresando los brazos a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0227-Pr9Rhf4.gif', '/exercises/images/0227-Pr9Rhf4.jpg'),
('0228', 'cable standing hip extension', 'Pierna', 'upper legs', 'cable', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Sujeta un cable a una polea baja y ponte de pie de espaldas a la máquina. Coloca el cable alrededor de tu tobillo y ponte de pie con los pies separados a la altura de los hombros. Mantén el core activado y la espalda recta durante todo el ejercicio. Extiende lentamente la pierna hacia atrás, apretando los glúteos en la parte alta del movimiento. Haz una pausa breve y luego vuelve a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite con la otra pierna.', '/exercises/gifs/0228-Kpajagk.gif', '/exercises/images/0228-Kpajagk.jpg'),
('0229', 'cable standing inner curl', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Agarra el mango del cable con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona el mango del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el mango del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0229-YwnI4ja.gif', '/exercises/images/0229-YwnI4ja.jpg'),
('0230', 'cable standing lift', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con ambas manos y colócalo a la altura de la cintura. Activa el core y mantén la espalda recta durante todo el ejercicio. Manteniendo los brazos rectos, exhala y eleva el mango del cable hacia el hombro opuesto, rotando el torso. Haz una pausa breve en la parte alta, luego inhala y baja lentamente el mango del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0230-qFpAkpP.gif', '/exercises/images/0230-qFpAkpP.jpg'),
('0231', 'cable standing one arm triceps extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con la mano derecha, con la palma hacia abajo, y coloca el brazo completamente extendido y paralelo al suelo. Mantén el codo quieto y cerca del cuerpo. Flexiona lentamente el codo, bajando el mango del cable hacia la parte de atrás de la cabeza. Haz una pausa breve en la parte baja del movimiento, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo.', '/exercises/gifs/0231-sYCcnon.gif', '/exercises/images/0231-sYCcnon.jpg'),
('1376', 'cable standing one leg calf raise', 'Pantorrilla', 'lower legs', 'cable', 'calves', 'ankles', ARRAY['ankles', 'feet'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujétate de la máquina de cable para apoyarte. Levanta una pierna del suelo y equilíbrate sobre la otra pierna. Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/1376-fgc9Xdl.gif', '/exercises/images/1376-fgc9Xdl.jpg'),
('0232', 'cable standing pulldown (with rope)', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Sujeta una cuerda a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Agarra la cuerda con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira de la cuerda hacia abajo, hacia los muslos, apretando los bíceps. Haz una pausa breve en la parte baja, luego suelta lentamente la cuerda hacia arriba. Repite el número de repeticiones deseado.', '/exercises/gifs/0232-CvPn9WV.gif', '/exercises/images/0232-CvPn9WV.jpg'),
('0233', 'cable standing rear delt row (with rope)', 'Hombro', 'shoulders', 'cable', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids', 'biceps'], 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con ambas manos, con las palmas una frente a la otra, y retrocede un paso para crear tensión en el cable. Mantén la espalda recta y el core activado. Tira del cable hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa breve en el punto máximo del movimiento, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0233-ZfyAGhK.gif', '/exercises/images/0233-ZfyAGhK.jpg'),
('1727', 'cable standing reverse grip one arm overhead tricep extension', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre supino y extiende el brazo por encima de la cabeza, manteniendo el codo cerca de la cabeza. Mantén el brazo superior quieto y baja lentamente el mango del cable detrás de la cabeza flexionando el codo. Haz una pausa breve en la parte baja, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1727-i11JWU7.gif', '/exercises/images/1727-i11JWU7.jpg'),
('0234', 'cable standing row (v-bar)', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta y el core activado. Tira del accesorio en V hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0234-4f8RXP8.gif', '/exercises/images/0234-4f8RXP8.jpg'),
('0235', 'cable standing shoulder external rotation', 'Hombro', 'shoulders', 'cable', 'delts', 'rotator cuff', ARRAY['rotator cuff', 'trapezius'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta el mango del cable con el brazo extendido frente a ti, paralelo al suelo. Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás. Rota lentamente el brazo hacia afuera, alejándolo de tu cuerpo, manteniendo el codo en la misma posición. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0235-FWdVhcW.gif', '/exercises/images/0235-FWdVhcW.jpg'),
('0236', 'cable standing twist row (v-bar)', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Coloca un accesorio en V en una máquina de cable a la altura del pecho. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo. Da un paso atrás para crear tensión en el cable. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del accesorio en V hacia tu torso retrayendo los omóplatos y flexionando los codos. Mientras tiras, gira el torso hacia un lado, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento, sintiendo la contracción en la parte alta de la espalda. Suelta lentamente la tensión y regresa a la posición inicial, deshaciendo el giro del torso. Repite el movimiento el número de repeticiones deseado, alternando la dirección del giro en cada repetición.', '/exercises/gifs/0236-JOZhu2h.gif', '/exercises/images/0236-JOZhu2h.jpg'),
('1269', 'cable standing up straight crossovers', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Ponte de pie en el medio de una máquina de cable con los pies separados a la altura de los hombros. Sujeta los mangos de los cables con las palmas hacia abajo y los brazos extendidos hacia los lados. Manteniendo los brazos rectos, junta las manos frente a tu cuerpo, cruzándolas una sobre la otra. Haz una pausa breve, luego regresa lentamente a la posición inicial, manteniendo los brazos extendidos. Repite el número de repeticiones deseado.', '/exercises/gifs/1269-UKWTJWR.gif', '/exercises/images/1269-UKWTJWR.jpg'),
('0238', 'cable straight arm pulldown', 'Espalda', 'back', 'cable', 'lats', 'shoulders', ARRAY['shoulders', 'biceps'], 'Coloca una barra recta en la polea alta de una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo. Activa los dorsales y tira de la barra hacia abajo, hacia los muslos, manteniendo los brazos rectos durante todo el movimiento. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0238-x69MAlq.gif', '/exercises/images/0238-x69MAlq.jpg'),
('0237', 'cable straight arm pulldown (with rope)', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta una cuerda a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Agarra la cuerda con ambas manos, con las palmas hacia abajo. Extiende completamente los brazos frente a ti, manteniendo los codos ligeramente flexionados. Activa los dorsales y tira lentamente de la cuerda hacia abajo, hacia los muslos, manteniendo los brazos rectos. Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0237-DT14T9T.gif', '/exercises/images/0237-DT14T9T.jpg'),
('0239', 'cable straight back seated row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'forearms', 'shoulders'], 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Agarra los mangos del cable con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Tira de los mangos del cable hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0239-Tq6gbK6.gif', '/exercises/images/0239-Tq6gbK6.jpg'),
('0240', 'cable supine reverse fly', 'Hombro', 'shoulders', 'cable', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Coloca un mango en D en una máquina de cable con polea baja y túmbate boca abajo en un banco plano. Agarra el mango en D con cada mano, con las palmas hacia abajo, y extiende los brazos frente a ti. Manteniendo los brazos rectos, levántalos hacia los lados hasta que estén paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0240-PQcUlDi.gif', '/exercises/images/0240-PQcUlDi.jpg'),
('2464', 'cable thibaudeau kayak row', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Coloca un mango de cable en una polea baja y siéntate frente a la máquina con los pies planos en el suelo. Agarra el mango con la mano derecha y extiende completamente el brazo, manteniendo una ligera flexión en el codo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el abdomen activado. Tira del mango hacia tu torso retrayendo el omóplato y flexionando el codo, manteniendo el brazo cerca del cuerpo. Aprieta los músculos de la espalda en la parte alta del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo.', '/exercises/gifs/2464-ZgwWBoC.gif', '/exercises/images/2464-ZgwWBoC.jpg'),
('0241', 'cable triceps pushdown (v-bar)', 'Brazo', 'upper arms', 'cable', 'triceps', 'forearms', ARRAY['forearms'], 'Coloca un accesorio en V en la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte baja del movimiento, apretando los tríceps. Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control. Repite el número de repeticiones deseado.', '/exercises/gifs/0241-gAwDzB3.gif', '/exercises/images/0241-gAwDzB3.jpg'),
('2405', 'cable triceps pushdown (v-bar) (with arm blaster)', 'Brazo', 'upper arms', 'cable', 'triceps', 'forearms', ARRAY['forearms'], 'Coloca un accesorio en V en la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte baja del movimiento, apretando los tríceps. Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control. Repite el número de repeticiones deseado.', '/exercises/gifs/2405-OxJk1fg.gif', '/exercises/images/2405-OxJk1fg.jpg'),
('0242', 'cable tuck reverse crunch', 'Core', 'waist', 'cable', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Sujeta un cable a una polea baja y túmbate boca arriba sobre una esterilla. Sujeta el cable con ambas manos y extiende los brazos rectos por encima del pecho. Flexiona las rodillas y levanta las piernas, llevando las rodillas hacia el pecho. Al mismo tiempo, eleva la pelvis hacia el pecho, levantando las caderas del suelo. Haz una pausa breve en la parte alta, luego baja lentamente las piernas y las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0242-TXtXc84.gif', '/exercises/images/0242-TXtXc84.jpg'),
('0243', 'cable twist', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques'], 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados. Activa el core y gira el torso hacia la derecha, tirando del cable a través de tu cuerpo. Haz una pausa breve al final del movimiento, sintiendo la contracción en el abdomen y los oblicuos. Regresa lentamente a la posición inicial, resistiendo la tracción del cable. Repite el movimiento hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0243-aVs3BR3.gif', '/exercises/images/0243-aVs3BR3.jpg'),
('0862', 'cable twist (up-down)', 'Core', 'waist', 'cable', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados. Activa el core y gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0862-fhZQPlV.gif', '/exercises/images/0862-fhZQPlV.jpg'),
('0244', 'cable twisting pull', 'Espalda', 'back', 'cable', 'lats', 'shoulders', ARRAY['shoulders', 'biceps'], 'Coloca un mango de cable en una polea baja y ponte de pie frente a la máquina. Agarra el mango con la mano izquierda y aléjate de la máquina, extendiendo completamente el brazo. Coloca los pies separados a la altura de los hombros, con las rodillas ligeramente flexionadas. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del mango hacia tu cuerpo, rotando el torso hacia la derecha al hacerlo. Aprieta los músculos de la espalda al final del movimiento. Regresa lentamente a la posición inicial, manteniendo la tensión en el cable. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con la mano derecha.', '/exercises/gifs/0244-zCgxPbV.gif', '/exercises/images/0244-zCgxPbV.jpg'),
('1645', 'cable two arm curl on incline bench', 'Brazo', 'upper arms', 'cable', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra los mangos del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona los mangos hacia los hombros mientras contraes los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1645-H9y3Dkr.gif', '/exercises/images/1645-H9y3Dkr.jpg'),
('1728', 'cable two arm tricep kickback', 'Brazo', 'upper arms', 'cable', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta el mango del cable en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados. Manteniendo los brazos superiores quietos, extiende los antebrazos hacia atrás hasta que los brazos estén completamente extendidos. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1728-vvNjDJS.gif', '/exercises/images/1728-vvNjDJS.jpg'),
('0245', 'cable underhand pulldown', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza. Siéntate y agarra la barra de jalón con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala la barra hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0245-xBYcQHj.gif', '/exercises/images/0245-xBYcQHj.jpg'),
('1270', 'cable upper chest crossovers', 'Pecho', 'chest', 'cable', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Coloca los mangos en los cables a la altura del pecho. Ponte de pie en el centro de la máquina de cable con un pie ligeramente delante del otro. Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados. Mantén una ligera flexión en los codos y activa el core. Tira de los cables juntos frente al pecho, cruzándolos uno sobre el otro. Aprieta los músculos del pecho en el punto máximo del movimiento. Suelta lentamente los cables de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1270-j7XMAyn.gif', '/exercises/images/1270-j7XMAyn.jpg'),
('1324', 'cable upper row', 'Espalda', 'back', 'cable', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Sujeta una barra recta a una máquina de cable a la altura del pecho. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1324-PQStVXH.gif', '/exercises/images/1324-PQStVXH.jpg'),
('0246', 'cable upright row', 'Hombro', 'shoulders', 'cable', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta el accesorio del cable con un agarre prono. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del accesorio del cable directamente hacia arriba, hacia tu barbilla, guiando con los codos. Haz una pausa breve en la parte alta, apretando los omóplatos entre sí. Baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0246-cALKspW.gif', '/exercises/images/0246-cALKspW.jpg'),
('1325', 'cable wide grip rear pulldown behind neck', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza. Siéntate y agarra la barra de jalón con un agarre prono amplio. Mantén la espalda recta y el pecho elevado mientras te reclinas ligeramente hacia atrás. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1325-CmEr4pM.gif', '/exercises/images/1325-CmEr4pM.jpg'),
('0247', 'cable wrist curl', 'Antebrazo', 'lower arms', 'cable', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Apoya los antebrazos en un banco o almohadilla, con las muñecas colgando del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Haz una pausa breve en la parte alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0247-LrV4s90.gif', '/exercises/images/0247-LrV4s90.jpg'),
('1407', 'calf push stretch with hands against wall', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos contra la pared a la altura de los hombros. Da un paso atrás con un pie, manteniendo el talón en el suelo y la pierna recta. Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, sintiendo un estiramiento en la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', '/exercises/gifs/1407-PzNxakt.gif', '/exercises/images/1407-PzNxakt.jpg'),
('1377', 'calf stretch with hands against wall', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos contra la pared a la altura de los hombros. Da un paso atrás con el pie derecho, manteniendo el talón en el suelo y la pierna recta. Flexiona la rodilla izquierda e inclínate hacia adelante, manteniendo la pierna de atrás recta y el talón en el suelo. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', '/exercises/gifs/1377-m0tCHqc.gif', '/exercises/images/1377-m0tCHqc.jpg'),
('1378', 'calf stretch with rope', 'Pantorrilla', 'lower legs', 'rope', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Ponte de pie frente a una pared u objeto firme con los pies separados a la altura de las caderas. Sujeta los extremos de la cuerda con cada mano y coloca el centro de la cuerda alrededor de la planta del pie derecho. Da un paso atrás con el pie izquierdo, manteniendo el talón en el suelo y la pierna recta. Inclínate hacia adelante, manteniendo la espalda recta, y tira suavemente de la cuerda para estirar la pantorrilla. Mantén el estiramiento durante 20-30 segundos, luego suelta. Repite con la otra pierna.', '/exercises/gifs/1378-1LVFcEn.gif', '/exercises/images/1378-1LVFcEn.jpg'),
('0248', 'cambered bar lying row', 'Espalda', 'back', 'barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca una barra en el suelo y túmbate boca abajo en un banco con el pecho justo en el borde. Estírate hacia abajo y agarra la barra con un agarre prono, un poco más ancho que el ancho de los hombros. Con las piernas rectas y los pies en el suelo, levanta la barra del suelo extendiendo los brazos. Tira de la barra hacia el pecho, juntando los omóplatos. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0248-R5swFnc.gif', '/exercises/images/0248-R5swFnc.jpg'),
('2963', 'captains chair straight leg raise', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas. Mantén la parte superior del cuerpo estable y la espalda recta. Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2963-weoDEpH.gif', '/exercises/images/2963-weoDEpH.jpg'),
('1548', 'chair leg extended stretch', 'Pierna', 'upper legs', 'body weight', 'quads', 'hamstrings', ARRAY['hamstrings', 'calves'], 'Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo. Extiende una pierna recta frente a ti, manteniendo el talón en el suelo. Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps. Mantén esta posición durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', '/exercises/gifs/1548-xGgAGPm.gif', '/exercises/images/1548-xGgAGPm.jpg'),
('1271', 'chest and front of shoulder stretch', 'Pecho', 'chest', 'body weight', 'pectorals', 'deltoids', ARRAY['deltoids'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos rectos frente a ti a la altura de los hombros. Cruza los brazos frente a tu cuerpo, con el brazo derecho sobre el brazo izquierdo. Entrelaza los dedos y presiona las palmas entre sí. Aprieta suavemente los omóplatos entre sí y empuja las manos hacia adelante, sintiendo un estiramiento en el pecho y la parte delantera de los hombros. Mantén el estiramiento durante 20-30 segundos, luego suelta. Repite el número de repeticiones deseado.', '/exercises/gifs/1271-Uto7l43.gif', '/exercises/images/1271-Uto7l43.jpg'),
('0251', 'chest dip', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Colócate en las barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0251-9WTm7dq.gif', '/exercises/images/0251-9WTm7dq.jpg'),
('1430', 'chest dip (on dip-pull-up cage)', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta las barras de fondos a una altura que te permita agarrarlas cómodamente. Ponte de pie entre las barras y coloca las manos en cada barra, un poco más separadas que el ancho de los hombros. Salta y estira los brazos, sosteniendo el peso de tu cuerpo sobre las barras. Flexiona las rodillas y cruza los tobillos detrás de ti. Baja el cuerpo flexionando los codos, manteniendo el pecho elevado y los hombros bajos. Continúa bajando hasta que los hombros queden por debajo de los codos o hasta que sientas un estiramiento en el pecho. Empuja con las palmas y extiende los codos para subir el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1430-XgWyAiA.gif', '/exercises/images/1430-XgWyAiA.jpg'),
('2462', 'chest dip on straight bar', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Agarra las barras paralelas con las palmas hacia abajo y los brazos completamente extendidos. Flexiona las rodillas y cruza los tobillos. Baja el cuerpo flexionando los brazos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/2462-LQFOrMn.gif', '/exercises/images/2462-LQFOrMn.jpg'),
('1272', 'chest stretch with exercise ball', 'Pecho', 'chest', 'stability ball', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta el balón de ejercicio con ambas manos y extiende los brazos rectos frente a ti. Lleva lentamente el balón de ejercicio hacia tu pecho, sintiendo un estiramiento en los músculos del pecho. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1272-ykA5tU7.gif', '/exercises/images/1272-ykA5tU7.jpg'),
('3216', 'chest tap push-up (male)', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras te bajas, toca tu pecho con la mano derecha. Empújate de vuelta hacia arriba hasta la posición inicial. Repite el movimiento, esta vez tocando tu pecho con la mano izquierda. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/3216-7E06s6d.gif', '/exercises/images/3216-7E06s6d.jpg'),
('1326', 'chin-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1326-T2mxWqc.gif', '/exercises/images/1326-T2mxWqc.jpg'),
('0253', 'chin-ups (narrow parallel grip)', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Cuélgate de una barra de dominadas con un agarre paralelo estrecho, con las palmas hacia ti. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0253-G70mEAJ.gif', '/exercises/images/0253-G70mEAJ.jpg'),
('0257', 'circles knee stretch', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas. Flexiona ligeramente las rodillas y levanta los talones del suelo, equilibrándote sobre las puntas de los pies. Manteniendo las rodillas flexionadas, gira las rodillas en un movimiento circular, primero en el sentido de las agujas del reloj y luego en sentido contrario. Realiza el movimiento el número de repeticiones deseado.', '/exercises/gifs/0257-X7jbxra.gif', '/exercises/images/0257-X7jbxra.jpg'),
('1273', 'clap push up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado. Empuja con las palmas de forma explosiva para impulsar tu cuerpo fuera del suelo. Mientras estás en el aire, junta las manos en un aplauso antes de aterrizar de vuelta en la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1273-wigSg76.gif', '/exercises/images/1273-wigSg76.jpg'),
('0258', 'clock push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras bajas, gira el cuerpo hacia la izquierda, extendiendo el brazo izquierdo recto hacia el lado. Empuja de vuelta hacia arriba hasta la posición inicial, mientras giras el cuerpo hacia el centro. Repite la flexión de brazos, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia el lado. Continúa alternando lados en cada repetición.', '/exercises/gifs/0258-CMAxnsG.gif', '/exercises/images/0258-CMAxnsG.jpg'),
('1327', 'close grip chin-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Agarra la barra de dominadas con las palmas hacia ti y las manos separadas a la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1327-VnfUNW7.gif', '/exercises/images/1327-VnfUNW7.jpg'),
('0259', 'close-grip push-up', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0259-x6KpKpq.gif', '/exercises/images/0259-x6KpKpq.jpg'),
('2398', 'close-grip push-up (on knees)', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Comienza apoyándote sobre las manos y las rodillas, con las manos separadas a la altura de los hombros y las rodillas separadas a la altura de las caderas. Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Haz una pausa breve cuando tu pecho esté justo por encima del suelo. Empuja con las palmas para estirar los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2398-v3vLFW0.gif', '/exercises/images/2398-v3vLFW0.jpg'),
('0260', 'cocoons', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0260-SLKj2pX.gif', '/exercises/images/0260-SLKj2pX.jpg'),
('1468', 'crab twist toe touch', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Comienza sentado en el suelo con las rodillas flexionadas y los pies planos en el suelo. Coloca las manos detrás de ti, con los dedos apuntando hacia los pies, y levanta las caderas del suelo. Extiende una pierna recta frente a ti mientras al mismo tiempo llevas la mano contraria hacia los dedos del pie. Regresa a la posición inicial y repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1468-xgsGFVM.gif', '/exercises/images/1468-xgsGFVM.jpg'),
('0262', 'cross body crunch', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha. Repite el número de repeticiones deseado.', '/exercises/gifs/0262-rbu5UUb.gif', '/exercises/images/0262-rbu5UUb.jpg'),
('0267', 'crunch (hands overhead)', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos rectos por encima de la cabeza. Activando el abdomen, levanta la parte superior del cuerpo del suelo, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0267-kjJ3VoQ.gif', '/exercises/images/0267-kjJ3VoQ.jpg'),
('0271', 'crunch (on stability ball)', 'Core', 'waist', 'stability ball', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso hacia adelante. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0271-MCUhf1F.gif', '/exercises/images/0271-MCUhf1F.jpg'),
('0272', 'crunch (on stability ball, arms straight)', 'Core', 'waist', 'stability ball', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del balón, flexionando los hombros hacia las caderas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0272-Sn8wxAI.gif', '/exercises/images/0272-Sn8wxAI.jpg'),
('0274', 'crunch floor', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y levanta los hombros del suelo, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa breve en la parte alta, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0274-TFqbd8t.gif', '/exercises/images/0274-TFqbd8t.jpg'),
('3016', 'curl-up', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3016-g2oKspu.gif', '/exercises/images/3016-g2oKspu.jpg'),
('3769', 'curtsey squat', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda. Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo. Mantén el torso erguido y el peso sobre el pie delantero. Empuja con el pie delantero para regresar a la posición inicial. Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo.', '/exercises/gifs/3769-gUjqdei.gif', '/exercises/images/3769-gUjqdei.jpg'),
('2331', 'cycle cross trainer', 'Cardio', 'cardio', 'leverage machine', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes'], 'Ajusta la altura del asiento y colócate en la bicicleta elíptica. Coloca los pies en los pedales y sujeta el manillar. Comienza a pedalear con un movimiento suave y controlado. Mantén un ritmo constante y aumenta la resistencia si lo deseas. Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular.', '/exercises/gifs/2331-XSCHmiI.gif', '/exercises/images/2331-XSCHmiI.jpg'),
('0277', 'decline crunch', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0277-9Ap7miY.gif', '/exercises/images/0277-9Ap7miY.jpg'),
('0279', 'decline push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable. Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0279-i5cEhka.gif', '/exercises/images/0279-i5cEhka.jpg'),
('0282', 'decline sit-up', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del banco, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0282-QLL2gdc.gif', '/exercises/images/0282-QLL2gdc.jpg'),
('1274', 'deep push up', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1274-vptOQ4N.gif', '/exercises/images/1274-vptOQ4N.jpg'),
('0283', 'diamond push-up', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices. Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos. Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0283-soIB2rj.gif', '/exercises/images/0283-soIB2rj.jpg'),
('0284', 'donkey calf raise', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque. Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0284-u5ESqzH.gif', '/exercises/images/0284-u5ESqzH.jpg'),
('1275', 'drop push up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Una vez que tu pecho esté justo por encima del suelo, baja rápidamente las rodillas al suelo. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1275-Q497lAE.gif', '/exercises/images/1275-Q497lAE.jpg'),
('0285', 'dumbbell alternate biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado, alternando los brazos.', '/exercises/gifs/0285-BU15nH4.gif', '/exercises/images/0285-BU15nH4.jpg'),
('2403', 'dumbbell alternate biceps curl (with arm blaster)', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Coloca el soporte para brazos en la parte superior de tus brazos, asegurándote de que quede bien ajustado. Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna hacia el hombro mientras contraes el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo contrario. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/2403-CfKsRbG.gif', '/exercises/images/2403-CfKsRbG.jpg'),
('1646', 'dumbbell alternate hammer preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos completamente extendidos. Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', '/exercises/gifs/1646-fy7Tgy4.gif', '/exercises/images/1646-fy7Tgy4.jpg'),
('1647', 'dumbbell alternate preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba. Apoya la parte superior de los brazos en la almohadilla del banco scott, permitiendo que los brazos se extiendan completamente. Manteniendo los brazos superiores quietos, exhala y flexiona la mancuerna en tu mano derecha mientras contraes el bíceps. Continúa flexionando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/1647-NlfIbzq.gif', '/exercises/images/1647-NlfIbzq.jpg'),
('1648', 'dumbbell alternate seated hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos hacia abajo. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/1648-6em2Dxj.gif', '/exercises/images/1648-6em2Dxj.jpg'),
('0286', 'dumbbell alternate side press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros. Empuja una mancuerna por encima de la cabeza mientras mantienes la otra mancuerna a la altura del hombro. Baja la mancuerna empujada de vuelta a la altura del hombro mientras empujas la otra mancuerna por encima de la cabeza. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0286-izMnLqz.gif', '/exercises/images/0286-izMnLqz.jpg'),
('1649', 'dumbbell alternating bicep curl with leg raised on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Coloca un balón de ejercicio detrás de ti y apoya un pie sobre él, manteniendo el equilibrio. Con los brazos completamente extendidos y los codos cerca de los costados, flexiona una mancuerna hacia el hombro mientras mantienes el brazo superior quieto. Baja la mancuerna de vuelta a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/1649-Zwiw7XR.gif', '/exercises/images/1649-Zwiw7XR.jpg'),
('1650', 'dumbbell alternating seated bicep curl on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna mientras rotas el antebrazo hasta que la palma quede frente al hombro. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite la flexión con el otro brazo. Continúa alternando flexiones el número de repeticiones deseado.', '/exercises/gifs/1650-J74XlNf.gif', '/exercises/images/1650-J74XlNf.jpg'),
('2137', 'dumbbell arnold press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper chest'], 'Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante. Rota las muñecas mientras levantas, de modo que las palmas miren hacia adelante en la parte alta del movimiento. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2137-Xy4jlWA.gif', '/exercises/images/2137-Xy4jlWA.jpg'),
('0287', 'dumbbell arnold press v. 2', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper chest'], 'Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante. Rota las muñecas mientras levantas, de modo que las palmas terminen mirando hacia adelante en la parte alta del movimiento. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0287-eOrFCnx.gif', '/exercises/images/0287-eOrFCnx.jpg'),
('0288', 'dumbbell around pullover', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'latissimus dorsi'], 'Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza en un movimiento de arco. Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0288-vi8EhoE.gif', '/exercises/images/0288-vi8EhoE.jpg'),
('0290', 'dumbbell bench seated press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos. Reclínate hacia atrás y coloca las mancuernas a los lados del pecho, con las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0290-3d7wHyd.gif', '/exercises/images/0290-3d7wHyd.jpg'),
('0291', 'dumbbell bench squat', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Coloca una mancuerna en el suelo frente a un banco. Ponte de pie de espaldas al banco con los pies separados a la altura de los hombros. Flexiona las rodillas y las caderas para bajar hacia el banco, manteniendo el pecho elevado y la espalda recta. Una vez que los glúteos toquen el banco, empuja con los talones para volver a ponerte de pie en la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0291-mnzcrIB.gif', '/exercises/images/0291-mnzcrIB.jpg'),
('0293', 'dumbbell bent over row', 'Espalda', 'back', 'dumbbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que los brazos cuelguen rectos hacia el suelo, con los codos ligeramente flexionados. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0293-BJ0Hz5L.gif', '/exercises/images/0293-BJ0Hz5L.jpg'),
('1651', 'dumbbell bicep curl lunge with bowling motion', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Da un paso adelante con el pie derecho, flexionando la rodilla derecha y bajando el cuerpo a una posición de zancada. Mientras avanzas en la zancada, flexiona las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo. En la parte baja de la zancada, gira el torso hacia la derecha, como si estuvieras lanzando una bola de boliche. Invierte el movimiento, retrocediendo con el pie derecho y regresando a la posición inicial mientras bajas las mancuernas de nuevo. Repite el movimiento de zancada y flexión, esta vez girando el torso hacia la izquierda. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1651-1VpF8db.gif', '/exercises/images/1651-1VpF8db.jpg'),
('1652', 'dumbbell bicep curl on exercise ball with leg raised', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Flexiona lentamente las mancuernas hacia los hombros, manteniendo los codos cerca de los costados. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Mientras realizas el curl de bíceps, levanta una pierna del suelo y mantenla en el aire durante todo el ejercicio. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/1652-2NImIAG.gif', '/exercises/images/1652-2NImIAG.jpg'),
('1653', 'dumbbell bicep curl with stork stance', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Extiende una pierna hacia atrás, equilibrándote sobre los dedos de ese pie. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/1653-uSkDMYl.gif', '/exercises/images/1653-uSkDMYl.jpg'),
('0294', 'dumbbell biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0294-NbVPDMW.gif', '/exercises/images/0294-NbVPDMW.jpg'),
('2401', 'dumbbell biceps curl (with arm blaster)', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona las pesas mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2401-nlJsbkW.gif', '/exercises/images/2401-nlJsbkW.jpg'),
('1654', 'dumbbell biceps curl reverse', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1654-nFc4FyV.gif', '/exercises/images/1654-nFc4FyV.jpg'),
('1655', 'dumbbell biceps curl squat', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Manteniendo la espalda recta y los codos cerca de los costados, exhala y flexiona las mancuernas hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1655-niXESDw.gif', '/exercises/images/1655-niXESDw.jpg'),
('1656', 'dumbbell biceps curl v sit on bosu ball', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Siéntate en un bosu con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos hacia abajo a los lados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1656-H1XAdpk.gif', '/exercises/images/1656-H1XAdpk.jpg'),
('1201', 'dumbbell burpee', 'Cardio', 'cardio', 'dumbbell', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'shoulders', 'triceps', 'core'], 'Comienza de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano. Baja el cuerpo a una posición de sentadilla, colocando las mancuernas en el suelo frente a ti. Lleva los pies hacia atrás a una posición de flexión de brazos, manteniendo el cuerpo en línea recta. Realiza una flexión de brazos, flexionando los codos y bajando el pecho hacia el suelo. Salta con los pies hacia tus manos, aterrizando en una posición de sentadilla. Ponte de pie de forma explosiva, levantando las mancuernas del suelo y llevándolas a los hombros. Empuja las mancuernas por encima de la cabeza, extendiendo completamente los brazos. Baja las mancuernas de vuelta a los hombros y repite toda la secuencia el número de repeticiones deseado.', '/exercises/gifs/1201-0JtKWum.gif', '/exercises/images/1201-0JtKWum.jpg'),
('0295', 'dumbbell clean', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Extiende las caderas y las rodillas de forma explosiva, empujando con los talones para saltar del suelo. Mientras saltas, encoge los hombros y tira de las mancuernas hacia arriba, hacia los hombros, manteniéndolas cerca del cuerpo. Atrapa las mancuernas a la altura de los hombros, con los codos apuntando hacia adelante y las palmas hacia arriba. Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/0295-7Hg55JG.gif', '/exercises/images/0295-7Hg55JG.jpg'),
('1731', 'dumbbell close grip press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos. Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros. Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial. Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho. Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Asegúrate de usar solo los tríceps y no usar los antebrazos ni los bíceps para ayudar a levantar las mancuernas. Después de una pausa de un segundo en la posición contraída, repite el movimiento el número de repeticiones prescrito.', '/exercises/gifs/1731-7jGOBF3.gif', '/exercises/images/1731-7jGOBF3.jpg'),
('0296', 'dumbbell close-grip press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos. Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros. Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial. Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho. Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0296-RxayqAZ.gif', '/exercises/images/0296-RxayqAZ.jpg'),
('0297', 'dumbbell concentration curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la parte interna del muslo. Extiende completamente el brazo y sujeta la mancuerna con un agarre supino. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro mientras contraes el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0297-gvsWLQw.gif', '/exercises/images/0297-gvsWLQw.jpg'),
('3635', 'dumbbell contralateral forward lunge', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, manteniendo la espalda recta y el core activado. Baja el cuerpo flexionando ambas rodillas hasta que el muslo derecho quede paralelo al suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Alterna las piernas el número de repeticiones deseado.', '/exercises/gifs/3635-ecl28tP.gif', '/exercises/images/3635-ecl28tP.jpg'),
('0298', 'dumbbell cross body hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona los brazos contrayendo los bíceps, llevando las mancuernas a través del cuerpo hacia el hombro opuesto. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0298-Qyk5J3p.gif', '/exercises/images/0298-Qyk5J3p.jpg'),
('1657', 'dumbbell cross body hammer curl v. 2', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona los brazos contrayendo los bíceps, acercando las mancuernas lo más posible al hombro opuesto. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1657-HDYiZcY.gif', '/exercises/images/1657-HDYiZcY.jpg'),
('0299', 'dumbbell cuban press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo. Manteniendo el core activado y los codos ligeramente flexionados, empuja las mancuernas hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos. Gira las muñecas de modo que las palmas queden mirando hacia adelante. Baja lentamente las mancuernas a la posición inicial, girando las muñecas de vuelta a la posición inicial mientras lo haces. Repite el número de repeticiones deseado.', '/exercises/gifs/0299-QfAKy1G.gif', '/exercises/images/0299-QfAKy1G.jpg'),
('2136', 'dumbbell cuban press v. 2', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo. Manteniendo el core activado y la espalda recta, empuja las mancuernas directamente hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos. Gira las muñecas de modo que las palmas queden mirando hacia adelante. Baja las mancuernas de nuevo hasta la altura de los hombros, girando las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2136-BqgCRif.gif', '/exercises/images/2136-BqgCRif.jpg'),
('0300', 'dumbbell deadlift', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Sostén una mancuerna en cada mano, con las palmas hacia el cuerpo y los brazos extendidos hacia abajo. Flexiona las caderas y las rodillas, bajando las mancuernas hacia el suelo mientras mantienes la espalda recta. Empuja con los talones y extiende las caderas y las rodillas, levantando las mancuernas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0300-nUwVh7b.gif', '/exercises/images/0300-nUwVh7b.jpg'),
('0301', 'dumbbell decline bench press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano y extiende los brazos rectos hacia arriba por encima del pecho, con las palmas hacia adelante. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0301-DwhEmmE.gif', '/exercises/images/0301-DwhEmmE.jpg'),
('0302', 'dumbbell decline fly', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders'], 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0302-xXm4nYq.gif', '/exercises/images/0302-xXm4nYq.jpg'),
('0303', 'dumbbell decline hammer press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas a los lados del pecho, manteniendo los codos ligeramente flexionados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0303-1qrWgZ2.gif', '/exercises/images/0303-1qrWgZ2.jpg'),
('1276', 'dumbbell decline one arm fly', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders'], 'Túmbate en un banco declinado con una mancuerna en una mano, apoyándola sobre el muslo. Usando el muslo para ayudar a levantar la mancuerna, álzala hasta la altura de los hombros con la palma mirando hacia el torso. Gira la muñeca de modo que la palma de la mano quede mirando hacia adelante. Mientras inhalas, baja la mancuerna lentamente hacia el lado hasta sentir un estiramiento en el pecho. Exhala y usa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1276-NL6YBwN.gif', '/exercises/images/1276-NL6YBwN.jpg'),
('1617', 'dumbbell decline one arm hammer press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho. Extiende el brazo recto hacia arriba, manteniendo el codo ligeramente flexionado. Baja la mancuerna hacia el hombro, manteniendo el codo cerca del cuerpo. Empuja la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1617-SHUMp5H.gif', '/exercises/images/1617-SHUMp5H.jpg'),
('0305', 'dumbbell decline shrug', 'Espalda', 'back', 'dumbbell', 'traps', 'shoulders', ARRAY['shoulders', 'rhomboids'], 'Ajusta un banco declinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sostén una mancuerna en cada mano con los brazos completamente extendidos hacia el suelo. Manteniendo los brazos rectos, levanta los hombros hacia las orejas lo más alto posible. Mantén la contracción por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0305-cwsAI4G.gif', '/exercises/images/0305-cwsAI4G.jpg'),
('0304', 'dumbbell decline shrug v. 2', 'Espalda', 'back', 'dumbbell', 'traps', 'shoulders', ARRAY['shoulders', 'rhomboids'], 'Ajusta un banco declinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados sobre él. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos completamente extendidos. Manteniendo los brazos rectos, levanta los hombros lo más alto posible mientras juntas los omóplatos. Mantén la contracción durante una breve pausa, luego baja las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0304-bRlbdjK.gif', '/exercises/images/0304-bRlbdjK.jpg'),
('0306', 'dumbbell decline triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate en un banco declinado con la cabeza más baja que los pies y sostén una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende completamente los brazos, manteniendo los codos cerca de la cabeza. Baja lentamente las mancuernas detrás de la cabeza, flexionando los codos. Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0306-OTgkHwR.gif', '/exercises/images/0306-OTgkHwR.jpg'),
('0307', 'dumbbell decline twist fly', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Túmbate en un banco declinado con la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento. Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior. Repite el número de repeticiones deseado.', '/exercises/gifs/0307-reFHapa.gif', '/exercises/images/0307-reFHapa.jpg'),
('1437', 'dumbbell finger curls', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'wrist flexors', ARRAY['wrist flexors', 'wrist extensors'], 'Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta. Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo, con la palma hacia arriba. Deja que la mancuerna ruede hacia las puntas de los dedos, luego flexiona los dedos para volver a enrollarla hacia arriba. Repite el número de repeticiones deseado, luego cambia a la otra mano.', '/exercises/gifs/1437-mtXengz.gif', '/exercises/images/1437-mtXengz.jpg'),
('1732', 'dumbbell forward lunge triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mantén la espalda recta y el pecho elevado. Extiende los brazos rectos por encima de la cabeza, manteniendo los codos cerca de las orejas. Baja las mancuernas detrás de la cabeza flexionando los codos. Haz una pausa por un momento, luego estira los brazos para volver a la posición inicial. Repite el movimiento el número de repeticiones deseado, luego cambia de pierna y repite.', '/exercises/gifs/1732-XalXcvM.gif', '/exercises/images/1732-XalXcvM.jpg'),
('0311', 'dumbbell full can lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'rotator cuff'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0311-AQ0mC4Y.gif', '/exercises/images/0311-AQ0mC4Y.jpg'),
('1760', 'dumbbell goblet squat', 'Pierna', 'upper legs', 'dumbbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna verticalmente contra el pecho con ambas manos. Manteniendo el pecho erguido y el core activado, baja el cuerpo a una posición de sentadilla empujando las caderas hacia atrás y flexionando las rodillas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1760-yn8yg1r.gif', '/exercises/images/1760-yn8yg1r.jpg'),
('0313', 'dumbbell hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', '/exercises/gifs/0313-slDvUAU.gif', '/exercises/images/0313-slDvUAU.jpg'),
('1659', 'dumbbell hammer curl on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1659-fY68AyX.gif', '/exercises/images/1659-fY68AyX.jpg'),
('0312', 'dumbbell hammer curl v. 2', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', '/exercises/gifs/0312-2NpxjC1.gif', '/exercises/images/0312-2NpxjC1.jpg'),
('2402', 'dumbbell hammer curls (with arm blaster)', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo el brazo superior quieto, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', '/exercises/gifs/2402-GNhAeJ0.gif', '/exercises/images/2402-GNhAeJ0.jpg'),
('1664', 'dumbbell high curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén los brazos superiores quietos y flexiona las mancuernas lo más alto posible contrayendo los bíceps. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1664-qAmNMJY.gif', '/exercises/images/1664-qAmNMJY.jpg'),
('3545', 'dumbbell incline alternate press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Una vez a la altura de los hombros, gira las muñecas de modo que las palmas de las manos queden mirando hacia adelante. Empuja las mancuernas hacia arriba con el pecho y los hombros, extendiendo completamente los brazos. Baja las mancuernas de nuevo hasta la posición inicial, manteniendo los codos ligeramente flexionados. Repite el número de repeticiones deseado, alternando los brazos.', '/exercises/gifs/3545-TVdivgY.gif', '/exercises/images/3545-TVdivgY.jpg'),
('0314', 'dumbbell incline bench press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con los pies apoyados en el suelo y la espalda firmemente apoyada contra el banco. Sostén una mancuerna en cada mano, con las palmas hacia adelante, y levántalas hasta la altura de los hombros. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0314-ns0SIbU.gif', '/exercises/images/0314-ns0SIbU.jpg'),
('0315', 'dumbbell incline biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0315-F3xgbjF.gif', '/exercises/images/0315-F3xgbjF.jpg'),
('0316', 'dumbbell incline breeding', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sostén una mancuerna en cada mano con agarre prono, con las palmas hacia adelante. Comienza con los brazos completamente extendidos, perpendiculares al suelo. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0316-B3Rxp6L.gif', '/exercises/images/0316-B3Rxp6L.jpg'),
('0318', 'dumbbell incline curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adelante. Apoya los brazos superiores en el banco inclinado y deja que los codos cuelguen hacia abajo, extendiendo completamente los brazos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0318-ae9UoXQ.gif', '/exercises/images/0318-ae9UoXQ.jpg'),
('0317', 'dumbbell incline curl v. 2', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0317-RaflbWD.gif', '/exercises/images/0317-RaflbWD.jpg'),
('0319', 'dumbbell incline fly', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders'], 'Ajusta un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0319-ESOd5Pl.gif', '/exercises/images/0319-ESOd5Pl.jpg'),
('1278', 'dumbbell incline fly on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el banco inclinado. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1278-HYe1ZqR.gif', '/exercises/images/1278-HYe1ZqR.jpg'),
('0320', 'dumbbell incline hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia el torso y los brazos completamente extendidos. Mantén la espalda contra el banco y los pies apoyados en el suelo. Manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0320-ByX0WxV.gif', '/exercises/images/0320-ByX0WxV.jpg'),
('0321', 'dumbbell incline hammer press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y coloca las mancuernas a la altura de los hombros con las palmas enfrentadas entre sí. Empuja las mancuernas hacia arriba y alejándolas del cuerpo hasta que los brazos queden completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0321-PG1kcIb.gif', '/exercises/images/0321-PG1kcIb.jpg'),
('1618', 'dumbbell incline hammer press on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Camina con los pies hacia adelante y baja el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados. Empuja las mancuernas hacia arriba y ligeramente hacia adentro, manteniendo las palmas enfrentadas entre sí. Extiende completamente los brazos, contrayendo los tríceps en la parte superior del movimiento. Baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1618-wkgnGfb.gif', '/exercises/images/1618-wkgnGfb.jpg'),
('0322', 'dumbbell incline inner biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Apoya los brazos superiores en el banco, permitiendo que los codos cuelguen hacia abajo y las palmas miren hacia adelante. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0322-LCtQPn8.gif', '/exercises/images/0322-LCtQPn8.jpg'),
('1279', 'dumbbell incline one arm fly', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Ajusta el banco inclinado a un ángulo de 30-45 grados. Siéntate en el banco con una mancuerna en una mano, apoyándola sobre el muslo. Recuéstate en el banco, manteniendo los pies apoyados en el suelo. Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho. Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo. Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1279-Gw2HFvW.gif', '/exercises/images/1279-Gw2HFvW.jpg'),
('1280', 'dumbbell incline one arm fly on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders'], 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento cuando el brazo esté paralelo al suelo. Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1280-LLNh6q5.gif', '/exercises/images/1280-LLNh6q5.jpg'),
('1619', 'dumbbell incline one arm hammer press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'chest'], 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo. Recuéstate en el banco y usa el muslo para ayudar a levantar la mancuerna hasta la altura de los hombros. Gira la muñeca de modo que la palma quede mirando hacia adentro, hacia el cuerpo. Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1619-LL1UiTX.gif', '/exercises/images/1619-LL1UiTX.jpg'),
('1620', 'dumbbell incline one arm hammer press on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'chest'], 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados. Empuja la mancuerna hacia el techo, estirando el brazo. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1620-jDnrkar.gif', '/exercises/images/1620-jDnrkar.jpg'),
('0323', 'dumbbell incline one arm lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'triceps'], 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyándola sobre el muslo. Inclínate hacia adelante y coloca el brazo superior contra la parte interna del muslo. Levanta la mancuerna hacia el lado, manteniendo el brazo ligeramente flexionado y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0323-aTNKZiC.gif', '/exercises/images/0323-aTNKZiC.jpg'),
('1281', 'dumbbell incline one arm press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo. Recuéstate en el banco y coloca la mancuerna a la altura del hombro, con la palma hacia adelante. Empuja la mancuerna hacia arriba y ligeramente hacia adentro, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1281-rDAiRf9.gif', '/exercises/images/1281-rDAiRf9.jpg'),
('1282', 'dumbbell incline one arm press on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano, con los pies apoyados en el suelo. Camina lentamente con los pies hacia adelante, haciendo rodar el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna a la altura del hombro con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1282-Bg5JKSH.gif', '/exercises/images/1282-Bg5JKSH.jpg'),
('0324', 'dumbbell incline palm-in press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Planta los pies firmemente en el suelo y mantén la espalda recta contra el banco. Comienza con las mancuernas a la altura de los hombros, con los codos flexionados y las palmas enfrentadas entre sí. Empuja las mancuernas hacia arriba y alejándolas del cuerpo, extendiendo completamente los brazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0324-OVLmUuL.gif', '/exercises/images/0324-OVLmUuL.jpg'),
('1283', 'dumbbell incline press on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas hacia adelante. Camina lentamente con los pies hacia adelante, bajando el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados. Empuja las mancuernas hacia arriba, extendiendo completamente los brazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1283-bfiHMpI.gif', '/exercises/images/1283-bfiHMpI.jpg'),
('0325', 'dumbbell incline raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'triceps'], 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y levanta las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Manteniendo la espalda contra el banco, exhala y levanta las mancuernas por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0325-nxW6BkN.gif', '/exercises/images/0325-nxW6BkN.jpg'),
('0326', 'dumbbell incline rear lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con el pecho contra el respaldo y sostén una mancuerna en cada mano. Extiende los brazos rectos hacia abajo con las palmas enfrentadas entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0326-vYk8lqw.gif', '/exercises/images/0326-vYk8lqw.jpg'),
('0327', 'dumbbell incline row', 'Espalda', 'back', 'dumbbell', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Toma una mancuerna en cada mano y siéntate en el banco con el pecho apoyado contra la inclinación. Extiende completamente los brazos, dejando que las mancuernas cuelguen rectas hacia abajo desde los hombros. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0327-7vG5o25.gif', '/exercises/images/0327-7vG5o25.jpg'),
('0328', 'dumbbell incline shoulder raise', 'Pecho', 'chest', 'dumbbell', 'serratus anterior', 'deltoids', ARRAY['deltoids', 'trapezius'], 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia abajo. Apoya las mancuernas sobre los muslos y recuéstate en el banco. Usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia adelante. Exhala y levanta lentamente las mancuernas por encima de la cabeza, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0328-6e2DcYX.gif', '/exercises/images/0328-6e2DcYX.jpg'),
('0329', 'dumbbell incline shrug', 'Espalda', 'back', 'dumbbell', 'traps', 'shoulders', ARRAY['shoulders'], 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano. Coloca los pies planos sobre el suelo y deja que los brazos cuelguen rectos hacia abajo con las palmas hacia el cuerpo. Manteniendo los brazos rectos, encoge los hombros hacia las orejas lo más alto posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0329-JymLInS.gif', '/exercises/images/0329-JymLInS.jpg'),
('3542', 'dumbbell incline t-raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate hacia adelante y deja que los brazos cuelguen rectos hacia abajo, perpendiculares al suelo. Manteniendo los brazos rectos, levántalos hacia los lados hasta que queden paralelos al suelo, formando una ''T'' con el cuerpo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3542-jgbvVJ0.gif', '/exercises/images/3542-jgbvVJ0.jpg'),
('0330', 'dumbbell incline triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adentro. Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza. Baja las mancuernas detrás de la cabeza flexionando los codos, manteniendo los brazos superiores quietos. Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0330-OVIKwsd.gif', '/exercises/images/0330-OVIKwsd.jpg'),
('0331', 'dumbbell incline twisted flyes', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho, con los brazos extendidos. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento. Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior. Repite el número de repeticiones deseado.', '/exercises/gifs/0331-1PLE8e9.gif', '/exercises/images/0331-1PLE8e9.jpg'),
('1733', 'dumbbell incline two arm extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate lentamente en el banco, manteniendo las mancuernas cerca del pecho. Una vez completamente recostado, extiende los brazos rectos hacia el techo, manteniendo los codos ligeramente flexionados. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1733-U7D9Fx3.gif', '/exercises/images/1733-U7D9Fx3.jpg'),
('3541', 'dumbbell incline y-raise', 'Espalda', 'back', 'dumbbell', 'upper back', 'shoulders', ARRAY['shoulders', 'rear deltoids'], 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate ligeramente hacia adelante y deja que los brazos cuelguen rectos hacia abajo, manteniendo una ligera flexión en los codos. Levanta los brazos hacia los lados y hacia arriba formando una Y hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3541-PbzNu7c.gif', '/exercises/images/3541-PbzNu7c.jpg'),
('0332', 'dumbbell iron cross', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo. Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0332-cALkHHX.gif', '/exercises/images/0332-cALkHHX.jpg'),
('0333', 'dumbbell kickback', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0333-W6PxUkg.gif', '/exercises/images/0333-W6PxUkg.jpg'),
('1734', 'dumbbell kickbacks on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'back'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1734-cAvTaSg.gif', '/exercises/images/1734-cAvTaSg.jpg'),
('1660', 'dumbbell kneeling bicep curl exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Arrodíllate en el suelo con un balón de estabilidad frente a ti. Coloca los codos sobre el balón de estabilidad, sosteniendo una mancuerna en cada mano con las palmas hacia arriba. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1660-2JCuFTU.gif', '/exercises/images/1660-2JCuFTU.jpg'),
('0335', 'dumbbell lateral to front raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Luego, levanta los brazos frente a ti hasta que queden paralelos al suelo, manteniendo nuevamente una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0335-xMjBKwn.gif', '/exercises/images/0335-xMjBKwn.jpg'),
('0336', 'dumbbell lunge', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Alterna las piernas el número de repeticiones deseado.', '/exercises/gifs/0336-RRWFUcw.gif', '/exercises/images/0336-RRWFUcw.jpg'),
('1658', 'dumbbell lunge with bicep curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'quadriceps', ARRAY['quadriceps', 'hamstrings'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. La rodilla derecha debe quedar flexionada en un ángulo de 90 grados y la rodilla izquierda debe quedar justo por encima del suelo. Mientras avanzas en la zancada, flexiona simultáneamente las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte baja de la zancada, luego empuja con el talón derecho para volver a la posición inicial, bajando las mancuernas de nuevo a los costados. Repite la zancada y el curl de bíceps en el lado opuesto, dando un paso adelante con el pie izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1658-Mz6lLcW.gif', '/exercises/images/1658-Mz6lLcW.jpg'),
('0337', 'dumbbell lying extension (across face)', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho, con las palmas enfrentadas entre sí. Manteniendo los brazos superiores quietos, baja lentamente la mancuerna describiendo un arco detrás de la cabeza hasta que los antebrazos queden paralelos al suelo. Haz una pausa por un momento, luego contrae los tríceps para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0337-L2V5Nan.gif', '/exercises/images/0337-L2V5Nan.jpg'),
('1729', 'dumbbell lying alternate extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Baja una mancuerna hacia la cabeza, flexionando el codo, mientras mantienes el otro brazo extendido. Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial. Repite con el otro brazo, alternando lados el número de repeticiones deseado.', '/exercises/gifs/1729-NfP83rA.gif', '/exercises/images/1729-NfP83rA.jpg'),
('0338', 'dumbbell lying elbow press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho. Baja las mancuernas hacia los hombros flexionando los codos, manteniendo los brazos superiores quietos. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial extendiendo los codos. Repite el número de repeticiones deseado.', '/exercises/gifs/0338-eOCOwIR.gif', '/exercises/images/0338-eOCOwIR.jpg'),
('0863', 'dumbbell lying external shoulder rotation', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'rotator cuff', ARRAY['rotator cuff', 'triceps'], 'Túmbate de lado en un banco plano con el brazo superior contra el costado y el codo flexionado a 90 grados. Sostén una mancuerna en la mano con la palma hacia abajo. Manteniendo el brazo superior contra el costado, gira lentamente el antebrazo hacia arriba lo más posible. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0863-bmBf7LN.gif', '/exercises/images/0863-bmBf7LN.jpg'),
('0339', 'dumbbell lying femoral', 'Pierna', 'upper legs', 'dumbbell', 'hamstrings', 'glutes', ARRAY['glutes'], 'Túmbate boca arriba con las piernas extendidas y una mancuerna apoyada sobre el abdomen bajo. Flexiona las rodillas y lleva la mancuerna hacia los glúteos, manteniendo los pies apoyados en el suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0339-FkBIE6a.gif', '/exercises/images/0339-FkBIE6a.jpg'),
('0340', 'dumbbell lying hammer press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba. Baja las mancuernas a los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0340-7gdLIXa.gif', '/exercises/images/0340-7gdLIXa.jpg'),
('2470', 'dumbbell lying on floor rear delt raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Túmbate boca abajo en el suelo con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos frente a ti, manteniendo una ligera flexión en los codos. Activando los músculos de los hombros, levanta los brazos hacia arriba y hacia los lados, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2470-Ion0XWz.gif', '/exercises/images/2470-Ion0XWz.jpg'),
('0341', 'dumbbell lying one arm deltoid rear', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia adentro. Extiende el brazo recto hacia el suelo, manteniéndolo cerca del cuerpo. Levanta el brazo hacia arriba y hacia atrás, acercando el omóplato hacia la columna. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0341-gSw59a4.gif', '/exercises/images/0341-gSw59a4.jpg'),
('0343', 'dumbbell lying one arm press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate boca arriba en un banco con una mancuerna en una mano y los pies apoyados en el suelo. Sostén la mancuerna a la altura del hombro con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0343-zGSIWQi.gif', '/exercises/images/0343-zGSIWQi.jpg'),
('0342', 'dumbbell lying one arm press v. 2', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate boca arriba en un banco con la espalda apoyada y los pies planos sobre el suelo. Sostén una mancuerna en una mano con la palma hacia los pies. Extiende el brazo recto hacia el techo, manteniendo el codo ligeramente flexionado. Baja lentamente la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0342-K3dIO25.gif', '/exercises/images/0342-K3dIO25.jpg'),
('0344', 'dumbbell lying one arm pronated triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en una mano con la palma hacia abajo, y extiende el brazo recto por encima del hombro. Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo. Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0344-wyaqzOS.gif', '/exercises/images/0344-wyaqzOS.jpg'),
('0345', 'dumbbell lying one arm rear lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, colgando hacia el suelo. Mantén el brazo recto y levanta la mancuerna hacia el lado, alejándola del cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0345-KwFGiEP.gif', '/exercises/images/0345-KwFGiEP.jpg'),
('0346', 'dumbbell lying one arm supinated triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'forearms', ARRAY['forearms'], 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre supino, y extiende el brazo recto por encima del hombro. Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo. Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0346-zZlORz6.gif', '/exercises/images/0346-zZlORz6.jpg'),
('0347', 'dumbbell lying pronation', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'shoulders'], 'Túmbate boca abajo en un banco con el pecho hacia abajo y los brazos extendidos rectos hacia abajo, sosteniendo una mancuerna en cada mano. Gira las palmas de modo que queden mirando hacia arriba. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas mientras giras las palmas hacia abajo. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0347-mym4hJo.gif', '/exercises/images/0347-mym4hJo.jpg'),
('2705', 'dumbbell lying pronation on floor', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'triceps'], 'Túmbate boca abajo en el suelo con los brazos extendidos rectos frente a ti, sosteniendo una mancuerna en cada mano. Gira las palmas de modo que queden mirando hacia el suelo. Manteniendo los brazos rectos, levanta las mancuernas del suelo contrayendo los antebrazos. Continúa levantando hasta que los antebrazos estén completamente contraídos y las mancuernas queden a la altura de los hombros. Mantén la posición por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2705-7RWNjiB.gif', '/exercises/images/2705-7RWNjiB.jpg'),
('1284', 'dumbbell lying pullover on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'back'], 'Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el balón. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1284-iK59oEA.gif', '/exercises/images/1284-iK59oEA.jpg'),
('1328', 'dumbbell lying rear delt row', 'Espalda', 'back', 'dumbbell', 'upper back', 'shoulders', ARRAY['shoulders', 'biceps'], 'Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas hacia adentro. Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos. Activando los músculos de la espalda, levanta las mancuernas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1328-XUUD0Fs.gif', '/exercises/images/1328-XUUD0Fs.jpg'),
('0348', 'dumbbell lying rear lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos. Activando los músculos de los hombros, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0348-53Ttlck.gif', '/exercises/images/0348-53Ttlck.jpg'),
('1735', 'dumbbell lying single extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con una mancuerna en una mano y el brazo completamente extendido por encima del pecho. Baja la mancuerna de manera controlada hacia la frente, manteniendo el brazo superior quieto. Haz una breve pausa en la parte inferior del movimiento, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1735-6MfS53i.gif', '/exercises/images/1735-6MfS53i.jpg'),
('0349', 'dumbbell lying supination', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'shoulders'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, flexiona las mancuernas hacia los hombros contrayendo los antebrazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0349-M2Pm3zj.gif', '/exercises/images/0349-M2Pm3zj.jpg'),
('2706', 'dumbbell lying supination on floor', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'shoulders'], 'Túmbate boca arriba en el suelo con las piernas extendidas y los brazos a los costados, sosteniendo una mancuerna en cada mano. Gira las palmas hacia arriba, manteniendo los codos cerca de los costados. Flexiona lentamente las mancuernas hacia los hombros, contrayendo los antebrazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2706-rEhi2o5.gif', '/exercises/images/2706-rEhi2o5.jpg'),
('1661', 'dumbbell lying supine biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1661-XVzF3iZ.gif', '/exercises/images/1661-XVzF3iZ.jpg'),
('0350', 'dumbbell lying supine curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0350-KUaZst7.gif', '/exercises/images/0350-KUaZst7.jpg'),
('0351', 'dumbbell lying triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, manteniendo los codos cerca del cuerpo. Baja las mancuernas hacia la frente, flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0351-mpKZGWz.gif', '/exercises/images/0351-mpKZGWz.jpg'),
('1662', 'dumbbell lying wide curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1662-qm9veZw.gif', '/exercises/images/1662-qm9veZw.jpg'),
('0352', 'dumbbell neutral grip bench press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sostén una mancuerna en cada mano con agarre neutro (palmas enfrentadas entre sí) y los brazos extendidos rectos hacia arriba sobre el pecho. Baja lentamente las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0352-pP8wP2P.gif', '/exercises/images/0352-pP8wP2P.jpg'),
('1285', 'dumbbell one arm bench fly', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco plano con una mancuerna en una mano, apoyándola sobre el muslo. Recuéstate en el banco, manteniendo la mancuerna presionada contra el muslo. Usando la mano libre, ayuda a levantar la mancuerna hasta la posición inicial. Sostén la mancuerna directamente sobre el hombro con el brazo extendido y la palma hacia adentro. Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo. Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento y lleva la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo y repite.', '/exercises/gifs/1285-o5Jsk92.gif', '/exercises/images/1285-o5Jsk92.jpg'),
('0292', 'dumbbell one arm bent-over row', 'Espalda', 'back', 'dumbbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que la mancuerna cuelgue recta hacia el suelo, con el brazo completamente extendido. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0292-C0MA9bC.gif', '/exercises/images/0292-C0MA9bC.jpg'),
('1286', 'dumbbell one arm chest fly on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo. Camina con los pies hacia adelante, haciendo rodar el balón hasta que la parte superior de la espalda quede apoyada en el balón y la cabeza, el cuello y los hombros queden fuera de él. Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento cuando el brazo esté paralelo al suelo. Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1286-Bpkf41o.gif', '/exercises/images/1286-Bpkf41o.jpg'),
('0353', 'dumbbell one arm concentration curl (on stability ball)', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo extendido hacia el suelo. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa por un momento en la parte superior del movimiento, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo y repite.', '/exercises/gifs/0353-k5IpyHg.gif', '/exercises/images/0353-k5IpyHg.jpg'),
('1287', 'dumbbell one arm decline chest press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho. Coloca los pies planos sobre el suelo y mantén la espalda presionada contra el banco. Extiende el brazo y empuja la mancuerna hacia el techo, extendiendo completamente el codo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1287-REGM1dE.gif', '/exercises/images/1287-REGM1dE.jpg'),
('1288', 'dumbbell one arm fly on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la parte superior de la espalda quede apoyada sobre el balón de estabilidad. Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1288-Am02iPd.gif', '/exercises/images/1288-Am02iPd.jpg'),
('1736', 'dumbbell one arm french press on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el codo flexionado en un ángulo de 90 grados. Extiende el brazo recto hacia el techo, manteniendo el codo quieto. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1736-ziFKQXP.gif', '/exercises/images/1736-ziFKQXP.jpg'),
('1663', 'dumbbell one arm hammer preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott con una mancuerna en una mano y el brazo superior apoyado sobre la almohadilla. Sostén la mancuerna con agarre neutro (palmas hacia el cuerpo). Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1663-4dF3maG.gif', '/exercises/images/1663-4dF3maG.jpg'),
('1621', 'dumbbell one arm hammer press on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'chest'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados. Coloca la otra mano en la cadera para mantener el equilibrio. Empuja la mancuerna hacia arriba, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1621-VYmYxK5.gif', '/exercises/images/1621-VYmYxK5.jpg'),
('1289', 'dumbbell one arm incline chest press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ajusta el banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre prono, apoyándola sobre el hombro. Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1289-PDaMuyV.gif', '/exercises/images/1289-PDaMuyV.jpg'),
('0354', 'dumbbell one arm kickback', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados. Extiende el brazo derecho recto hacia atrás, contrayendo el tríceps en la parte superior del movimiento. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0354-bQy2Eni.gif', '/exercises/images/0354-bQy2Eni.jpg'),
('0355', 'dumbbell one arm lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo. Mantén la espalda recta y el core activado durante todo el ejercicio. Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0355-n5cWCsI.gif', '/exercises/images/0355-n5cWCsI.jpg'),
('0356', 'dumbbell one arm lateral raise with support', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rotator cuff'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano, con la palma hacia el cuerpo. Coloca la otra mano sobre una superficie estable, como un banco o una pared, para apoyarte. Mantén la espalda recta y activa el core. Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0356-Yg7MJAT.gif', '/exercises/images/0356-Yg7MJAT.jpg'),
('1290', 'dumbbell one arm press on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps', 'core'], 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna en una mano y colócala a la altura del hombro, con el codo flexionado y la palma hacia adelante. Empuja lentamente la mancuerna hacia arriba hasta que el brazo quede completamente extendido, manteniendo el core activado y el equilibrio sobre el balón de estabilidad. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1290-QZFv5ui.gif', '/exercises/images/1290-QZFv5ui.jpg'),
('1665', 'dumbbell one arm prone curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia abajo. Extiende completamente el brazo, dejando que cuelgue recto hacia el suelo. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1665-JWjujiY.gif', '/exercises/images/1665-JWjujiY.jpg'),
('1666', 'dumbbell one arm prone hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo y el brazo completamente extendido. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1666-LIGZSTA.gif', '/exercises/images/1666-LIGZSTA.jpg'),
('1291', 'dumbbell one arm pullover on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'latissimus dorsi', 'rhomboids'], 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1291-bQHPBU3.gif', '/exercises/images/1291-bQHPBU3.jpg'),
('0358', 'dumbbell one arm reverse wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'wrist extensors', ARRAY['wrist extensors'], 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén una mancuerna en una mano con agarre prono, con la palma hacia abajo. Apoya el antebrazo sobre el muslo, con la muñeca colgando fuera del borde. Baja lentamente la mancuerna hacia el suelo flexionando la muñeca. Haz una pausa por un momento en la parte inferior, luego flexiona lentamente la muñeca de vuelta hacia el cuerpo. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0358-BwSNDGt.gif', '/exercises/images/0358-BwSNDGt.jpg'),
('0359', 'dumbbell one arm reverse fly (with support)', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia adentro. Inclínate hacia adelante y coloca la mano libre sobre el banco para apoyarte. Mantén el brazo ligeramente flexionado y levántalo hacia el lado hasta que quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0359-e25F58f.gif', '/exercises/images/0359-e25F58f.jpg'),
('1622', 'dumbbell one arm reverse grip press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Siéntate en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo. Coloca los pies planos sobre el suelo y mantén la espalda recta. Levanta la mancuerna hasta la altura del hombro, manteniendo el codo cerca del cuerpo. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1622-Ze7MoIb.gif', '/exercises/images/1622-Ze7MoIb.jpg'),
('1414', 'dumbbell one arm reverse preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott con el pecho contra la almohadilla y el brazo extendido sobre el borde del banco, sosteniendo una mancuerna con agarre supino. Baja lentamente la mancuerna hasta que el brazo quede completamente extendido. Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto. Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1414-bWxq4op.gif', '/exercises/images/1414-bWxq4op.jpg'),
('1667', 'dumbbell one arm reverse spider curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en una mano, con la palma hacia abajo y el brazo completamente extendido. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro flexionando el codo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1667-VdLZ3nB.gif', '/exercises/images/1667-VdLZ3nB.jpg'),
('1668', 'dumbbell one arm seated bicep curl on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1668-s999Hdo.gif', '/exercises/images/1668-s999Hdo.jpg'),
('1669', 'dumbbell one arm seated hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí). Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1669-jK2hZ6n.gif', '/exercises/images/1669-jK2hZ6n.jpg'),
('1415', 'dumbbell one arm seated neutral wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba. Apoya el antebrazo sobre el muslo, dejando que la muñeca cuelgue fuera del borde. Manteniendo el antebrazo quieto, flexiona la muñeca hacia arriba lo más posible. Haz una pausa por un momento en la parte superior, luego baja lentamente la muñeca de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra mano.', '/exercises/gifs/1415-YtaCTYl.gif', '/exercises/images/1415-YtaCTYl.jpg'),
('0361', 'dumbbell one arm shoulder press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0361-84RyJf8.gif', '/exercises/images/0361-84RyJf8.jpg'),
('0360', 'dumbbell one arm shoulder press v. 2', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Activa el core y empuja la mancuerna directamente hacia arriba por encima de la cabeza, extendiendo completamente el brazo. Haz una pausa por un momento en la parte superior, luego baja lentamente la mancuerna de vuelta a la altura del hombro. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0360-1TkiAFK.gif', '/exercises/images/0360-1TkiAFK.jpg'),
('3888', 'dumbbell one arm snatch', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo. Extiende explosivamente las caderas, las rodillas y los tobillos, impulsando la mancuerna hacia arriba en línea recta. Cuando la mancuerna alcance la altura del hombro, gira rápidamente la mano y empújala por encima de la cabeza, extendiendo completamente el brazo. Recibe la mancuerna por encima de la cabeza con una ligera flexión en las rodillas y las caderas. Baja la mancuerna de nuevo a la posición inicial de manera controlada. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/3888-6pTkI99.gif', '/exercises/images/3888-6pTkI99.jpg'),
('1670', 'dumbbell one arm standing curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en una mano, con la palma hacia adelante y el brazo completamente extendido. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia arriba contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1670-ffQsyBj.gif', '/exercises/images/1670-ffQsyBj.jpg'),
('1671', 'dumbbell one arm standing hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona las pesas mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1671-2sQGZ5b.gif', '/exercises/images/1671-2sQGZ5b.jpg'),
('0362', 'dumbbell one arm triceps extension (on bench)', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano y coloca la otra mano sobre el banco para apoyarte. Levanta la mancuerna por encima de la cabeza, manteniendo el brazo superior cerca de la cabeza y el codo apuntando hacia adelante. Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto. Extiende el brazo de vuelta a la posición inicial, estirando completamente el codo. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0362-nAuHPcD.gif', '/exercises/images/0362-nAuHPcD.jpg'),
('0363', 'dumbbell one arm upright row', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Deja que la mancuerna cuelgue a la distancia de un brazo frente a los muslos, con la palma hacia el cuerpo. Manteniendo la espalda recta y el core activado, exhala y levanta la mancuerna recta hacia la barbilla, guiando con el codo. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0363-6cKQC5E.gif', '/exercises/images/0363-6cKQC5E.jpg'),
('0364', 'dumbbell one arm wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo. Permite que la muñeca se extienda, dejando que la mancuerna ruede hacia los dedos. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Repite el número de repeticiones deseado, luego cambia a la otra mano.', '/exercises/gifs/0364-q8aHNoF.gif', '/exercises/images/0364-q8aHNoF.jpg'),
('1672', 'dumbbell one arm zottman preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott y sostén una mancuerna en una mano con agarre supino. Apoya el brazo superior sobre la almohadilla del banco scott, permitiendo que el brazo se extienda completamente. Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto. En la parte superior del curl, gira la muñeca de modo que la palma quede hacia arriba. Baja lentamente la mancuerna de vuelta a la posición inicial, girando la muñeca de regreso a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1672-sxY5Biu.gif', '/exercises/images/1672-sxY5Biu.jpg'),
('1292', 'dumbbell one leg fly on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Coloca un pie en el suelo y extiende la otra pierna recta hacia adelante. Inclínate ligeramente hacia adelante y lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Baja lentamente las mancuernas hacia abajo y hacia los lados, sintiendo un estiramiento en el pecho. Haz una pausa por un momento en la parte inferior, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/1292-pH2x2jj.gif', '/exercises/images/1292-pH2x2jj.jpg'),
('0365', 'dumbbell over bench neutral wrist curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas hacia los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0365-BKa8dmT.gif', '/exercises/images/0365-BKa8dmT.jpg'),
('0366', 'dumbbell over bench one arm neutral wrist curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0366-IvV6C9M.gif', '/exercises/images/0366-IvV6C9M.jpg'),
('1441', 'dumbbell over bench one arm reverse wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1441-4Jc36XM.gif', '/exercises/images/1441-4Jc36XM.jpg'),
('0367', 'dumbbell over bench one arm wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'shoulders'], 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0367-KI1DjNN.gif', '/exercises/images/0367-KI1DjNN.jpg'),
('0368', 'dumbbell over bench revers wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas hacia abajo. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0368-3tAXPQ6.gif', '/exercises/images/0368-3tAXPQ6.jpg'),
('0369', 'dumbbell over bench wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco con los antebrazos apoyados en él y las palmas hacia arriba, sujetando una mancuerna en cada mano. Deja que tus muñecas cuelguen del borde del banco. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento. Haz una pausa por un momento y luego baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0369-D1xYJAU.gif', '/exercises/images/0369-D1xYJAU.jpg'),
('1329', 'dumbbell palm rotational bent over row', 'Espalda', 'back', 'dumbbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Deja que los brazos cuelguen rectos hacia abajo, con las palmas hacia tu cuerpo. Activa el core y tira de las mancuernas hacia tu pecho, manteniendo los codos cerca del cuerpo. Mientras subes las mancuernas, gira las palmas para que queden mirando hacia afuera, alejadas de tu cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja lentamente las mancuernas hasta la posición inicial, girando las palmas de vuelta a su posición original. Repite el número de repeticiones deseado.', '/exercises/gifs/1329-wt6rwjk.gif', '/exercises/images/1329-wt6rwjk.jpg'),
('1623', 'dumbbell palms in incline bench press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia adentro. Extiende los brazos rectos hacia arriba, por encima del pecho, manteniendo una ligera flexión en los codos. Baja las mancuernas lentamente hacia los hombros, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la posición más baja y luego presiona las mancuernas de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1623-8eqjhOl.gif', '/exercises/images/1623-8eqjhOl.jpg'),
('0370', 'dumbbell peacher hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', '/exercises/gifs/0370-F1KxjBa.gif', '/exercises/images/0370-F1KxjBa.jpg'),
('0371', 'dumbbell plyo squat', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Cuando llegues al punto más bajo de la sentadilla, impúlsate explosivamente hacia arriba, saltando del suelo. Mientras estás en el aire, cambia rápidamente la posición de los pies, aterrizando con el pie opuesto adelante. Baja inmediatamente el cuerpo de vuelta a la posición de sentadilla y repite el salto, cambiando de nuevo los pies. Continúa alternando la posición de los pies en cada salto durante el número de repeticiones deseado.', '/exercises/gifs/0371-S4pwGlc.gif', '/exercises/images/0371-S4pwGlc.jpg'),
('0372', 'dumbbell preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0372-jivWf8n.gif', '/exercises/images/0372-jivWf8n.jpg'),
('1673', 'dumbbell preacher curl over exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna con una mano con agarre supino, apoyando el codo sobre el balón de estabilidad. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1673-hwygydB.gif', '/exercises/images/1673-hwygydB.jpg'),
('1293', 'dumbbell press on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de estabilidad con los pies planos en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad hasta que tu zona lumbar quede apoyada sobre el balón y tus rodillas formen un ángulo de 90 grados. Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1293-O8o7q4d.gif', '/exercises/images/1293-O8o7q4d.jpg'),
('0373', 'dumbbell pronate-grip triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo. Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza. Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0373-bpJL2Qs.gif', '/exercises/images/0373-bpJL2Qs.jpg'),
('0374', 'dumbbell prone incline curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta el banco a una inclinación de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sujeta una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0374-mwpPcr1.gif', '/exercises/images/0374-mwpPcr1.jpg'),
('1674', 'dumbbell prone incline hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta el banco a una inclinación de 45 grados. Túmbate boca abajo en el banco con una mancuerna en cada mano, con las palmas mirándose entre sí. Deja que los brazos cuelguen rectos hacia el suelo, manteniendo los codos ligeramente flexionados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1674-cWemPG8.gif', '/exercises/images/1674-cWemPG8.jpg'),
('1700', 'dumbbell push press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros. Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza. Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/1700-FS63wTN.gif', '/exercises/images/1700-FS63wTN.jpg'),
('0376', 'dumbbell raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0376-c9MnDRp.gif', '/exercises/images/0376-c9MnDRp.jpg'),
('2292', 'dumbbell rear delt raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2292-mu5Guxt.gif', '/exercises/images/2292-mu5Guxt.jpg'),
('0377', 'dumbbell rear delt row_shoulder', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende los brazos rectos hacia el suelo, con una ligera flexión en los codos. Levanta las mancuernas hacia los lados, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0377-EKXOMEh.gif', '/exercises/images/0377-EKXOMEh.jpg'),
('0378', 'dumbbell rear fly', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0378-8DiFDVA.gif', '/exercises/images/0378-8DiFDVA.jpg'),
('0380', 'dumbbell rear lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0380-v1qBec9.gif', '/exercises/images/0380-v1qBec9.jpg'),
('0379', 'dumbbell rear lateral raise (support head)', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0379-UzkLrem.gif', '/exercises/images/0379-UzkLrem.jpg'),
('0381', 'dumbbell rear lunge', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso hacia atrás con el pie derecho, bajando el cuerpo a una posición de zancada. Flexiona la rodilla izquierda y baja el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Haz una pausa por un momento, luego empuja con el talón izquierdo para volver a la posición inicial. Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.', '/exercises/gifs/0381-SSsBDwB.gif', '/exercises/images/0381-SSsBDwB.jpg'),
('0382', 'dumbbell revers grip biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0382-e4ojVhP.gif', '/exercises/images/0382-e4ojVhP.jpg'),
('1624', 'dumbbell reverse bench press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies. Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos. Baja lentamente las mancuernas hacia el pecho, permitiendo que los codos se abran hacia los lados. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1624-UIbGx6H.gif', '/exercises/images/1624-UIbGx6H.jpg'),
('0383', 'dumbbell reverse fly', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0383-EAs3xL9.gif', '/exercises/images/0383-EAs3xL9.jpg'),
('1330', 'dumbbell reverse grip incline bench one arm row', 'Espalda', 'back', 'dumbbell', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Coloca una mancuerna en el suelo junto al banco. Ponte de pie frente al banco con los pies separados a la altura de los hombros. Inclínate desde la cintura y coloca la rodilla izquierda y la mano izquierda sobre el banco para apoyarte. Toma la mancuerna con la mano derecha usando un agarre inverso (con la palma hacia abajo). Mantén la espalda recta y el core activado. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Aprieta los músculos de la espalda en la parte superior del movimiento. Baja la mancuerna de nuevo a la posición inicial de manera controlada. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el brazo izquierdo.', '/exercises/gifs/1330-ZIViNh1.gif', '/exercises/images/1330-ZIViNh1.jpg'),
('1331', 'dumbbell reverse grip incline bench two arm row', 'Espalda', 'back', 'dumbbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con el pecho apoyado en el respaldo y los pies planos en el suelo. Sujeta una mancuerna en cada mano con agarre supino. Inclínate hacia adelante y deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1331-9pQSkH8.gif', '/exercises/images/1331-9pQSkH8.jpg'),
('2327', 'dumbbell reverse grip row (female)', 'Espalda', 'back', 'dumbbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tu cuerpo. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos, con una ligera flexión en los codos. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2327-Nh3mvOO.gif', '/exercises/images/2327-Nh3mvOO.jpg'),
('0384', 'dumbbell reverse preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte. Sujeta una mancuerna en cada mano con agarre supino, con las palmas hacia arriba. Manteniendo la parte superior de los brazos fija, exhala y flexiona las mancuernas mientras contraes los bíceps. Continúa flexionando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0384-O8Aq69u.gif', '/exercises/images/0384-O8Aq69u.jpg'),
('1675', 'dumbbell reverse spider curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con la espalda recta, con una mancuerna en cada mano, las palmas hacia tu cuerpo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1675-6sMAmNv.gif', '/exercises/images/1675-6sMAmNv.jpg'),
('0385', 'dumbbell reverse wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0385-BLCvwr2.gif', '/exercises/images/0385-BLCvwr2.jpg'),
('0386', 'dumbbell rotation reverse fly', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Gira los brazos de modo que las palmas queden mirando hacia abajo. Baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0386-prbWx1D.gif', '/exercises/images/0386-prbWx1D.jpg'),
('2397', 'dumbbell scott press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2397-5vfAI0I.gif', '/exercises/images/2397-5vfAI0I.jpg'),
('0387', 'dumbbell seated alternate front raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'biceps'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos extendidos hacia abajo a los lados. Manteniendo los brazos rectos, levanta una mancuerna frente a ti hasta que quede paralela al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', '/exercises/gifs/0387-gH5fRsC.gif', '/exercises/images/0387-gH5fRsC.jpg'),
('1676', 'dumbbell seated alternate hammer curl on exercise ball', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos. Manteniendo la parte superior de los brazos fija, exhala y flexiona una mancuerna hacia el hombro mientras mantienes la palma hacia tu cuerpo. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo contrario. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/1676-QLRmNeT.gif', '/exercises/images/1676-QLRmNeT.jpg'),
('0388', 'dumbbell seated alternate press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona una mancuerna hacia arriba, por encima de la cabeza, extendiendo completamente el brazo. Baja la mancuerna de vuelta a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/0388-QT5Q0nK.gif', '/exercises/images/0388-QT5Q0nK.jpg'),
('3546', 'dumbbell seated alternate shoulder', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano, con las palmas hacia adentro, y levántalas a la altura de los hombros. Presiona una mancuerna hacia arriba, por encima de la cabeza, mientras mantienes la otra mancuerna a la altura de los hombros. Baja la mancuerna levantada de vuelta a la altura de los hombros mientras presionas simultáneamente la otra mancuerna por encima de la cabeza. Continúa alternando entre los brazos durante el número de repeticiones deseado.', '/exercises/gifs/3546-q7qkONO.gif', '/exercises/images/3546-q7qkONO.jpg'),
('0389', 'dumbbell seated bench extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza. Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas. Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0389-JhYSVwT.gif', '/exercises/images/0389-JhYSVwT.jpg'),
('2317', 'dumbbell seated bent arm lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos flexionados en un ángulo de 90 grados. Manteniendo los codos flexionados, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2317-JzQbv7J.gif', '/exercises/images/2317-JzQbv7J.jpg'),
('1730', 'dumbbell seated bent over alternate kickback', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'back'], 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende un brazo recto hacia atrás, manteniéndolo cerca de tu cuerpo, hasta que el brazo esté completamente extendido. Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/1730-x0lwvfq.gif', '/exercises/images/1730-x0lwvfq.jpg'),
('1737', 'dumbbell seated bent over triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'back'], 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y la cabeza erguida. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca de la cabeza. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1737-4ievMJ9.gif', '/exercises/images/1737-4ievMJ9.jpg'),
('1677', 'dumbbell seated bicep curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1677-xiA6lRr.gif', '/exercises/images/1677-xiA6lRr.jpg'),
('0390', 'dumbbell seated biceps curl (on stability ball)', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0390-WgJnBH5.gif', '/exercises/images/0390-WgJnBH5.jpg'),
('3547', 'dumbbell seated biceps curl to shoulder press', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los codos cerca de tus costados, flexiona las mancuernas hacia los hombros. Una vez que tus antebrazos estén verticales, gira las muñecas de modo que las palmas queden hacia adelante. Presiona las mancuernas por encima de la cabeza hasta que los brazos estén completamente extendidos. Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/3547-OeL23VY.gif', '/exercises/images/3547-OeL23VY.jpg'),
('1379', 'dumbbell seated calf raise', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos. Coloca la punta de los pies sobre una superficie elevada, como un escalón o un bloque, con los talones colgando del borde. Sujétate de la mancuerna para mantener la estabilidad. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1379-r29jP7S.gif', '/exercises/images/1379-r29jP7S.jpg'),
('0391', 'dumbbell seated curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, con las palmas hacia adelante. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0391-TiaZTxx.gif', '/exercises/images/0391-TiaZTxx.jpg'),
('0392', 'dumbbell seated front raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'biceps'], 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas frente a ti, con las palmas hacia abajo, hasta que queden a la altura de los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0392-Ys97II0.gif', '/exercises/images/0392-Ys97II0.jpg'),
('1678', 'dumbbell seated hammer curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos rectos hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1678-IGtBdNT.gif', '/exercises/images/1678-IGtBdNT.jpg'),
('0393', 'dumbbell seated inner biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya la parte superior de los brazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo. Manteniendo la parte superior de los brazos fija, flexiona las mancuernas hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0393-KXyoEtA.gif', '/exercises/images/0393-KXyoEtA.jpg'),
('0394', 'dumbbell seated kickback', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Acerca la parte superior de los brazos a tus costados y mantén los codos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0394-en550rk.gif', '/exercises/images/0394-en550rk.jpg'),
('0396', 'dumbbell seated lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'upper back'], 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0396-hxyTtWj.gif', '/exercises/images/0396-hxyTtWj.jpg'),
('0395', 'dumbbell seated lateral raise v. 2', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'triceps'], 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0395-hrrS0Ed.gif', '/exercises/images/0395-hrrS0Ed.jpg'),
('0397', 'dumbbell seated neutral wrist curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas mirándose entre sí. Apoya los antebrazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo. Manteniendo las muñecas en posición neutra, flexiona las mancuernas hacia los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0397-uJmK7Z1.gif', '/exercises/images/0397-uJmK7Z1.jpg'),
('1679', 'dumbbell seated one arm bicep curl on exercise ball with leg raised', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido. Coloca la otra mano en la cadera para mantener el equilibrio. Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo. Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', '/exercises/gifs/1679-84sESNy.gif', '/exercises/images/1679-84sESNy.jpg'),
('0398', 'dumbbell seated one arm kickback', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano. Inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0398-VQ3sNCn.gif', '/exercises/images/0398-VQ3sNCn.jpg'),
('0399', 'dumbbell seated one arm rotate', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'shoulders', ARRAY['shoulders', 'biceps'], 'Siéntate en un banco con la espalda recta y sujeta una mancuerna con una mano, apoyándola sobre el muslo. Sube la mancuerna hasta la altura del hombro, manteniendo el codo cerca de tu cuerpo. Gira el antebrazo hacia afuera, alejándolo de tu cuerpo, mientras mantienes fija la parte superior del brazo. Haz una pausa por un momento en la parte superior, luego gira lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0399-7f2jsqP.gif', '/exercises/images/0399-7f2jsqP.jpg'),
('0400', 'dumbbell seated one leg calf raise', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre el muslo derecho. Extiende la pierna izquierda recta hacia adelante, manteniendo el pie flexionado. Coloca la punta del pie derecho sobre una superficie elevada, como un escalón o un disco de peso. Usando los músculos de la pantorrilla, eleva el talón derecho lo más alto posible. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0400-Ia7tumC.gif', '/exercises/images/0400-Ia7tumC.jpg'),
('1380', 'dumbbell seated one leg calf raise - hammer grip', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos. Coloca un pie sobre una superficie elevada, como un escalón o un bloque, con el talón colgando del borde. Sujeta la mancuerna con agarre neutro, es decir, con las palmas mirándose entre sí y los dedos envolviendo la barra. Manteniendo el core activado y la espalda recta, eleva lentamente el talón lo más alto posible empujando con la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', '/exercises/gifs/1380-FxhcxUW.gif', '/exercises/images/1380-FxhcxUW.jpg'),
('1381', 'dumbbell seated one leg calf raise - palm up', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo. Sujeta una mancuerna con una mano y colócala sobre el muslo, con la palma hacia arriba. Levanta una pierna del suelo y extiéndela frente a ti, manteniendo la rodilla ligeramente flexionada. Eleva el talón lo más alto posible empujando con la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/1381-VW88JNd.gif', '/exercises/images/1381-VW88JNd.jpg'),
('0401', 'dumbbell seated palms up wrist curl', 'Antebrazo', 'lower arms', 'dumbbell', 'forearms', 'biceps', ARRAY['biceps', 'shoulders'], 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento. Haz una pausa por un momento y luego baja las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0401-2dImyQ8.gif', '/exercises/images/0401-2dImyQ8.jpg'),
('0402', 'dumbbell seated preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott con los pies apoyados en el suelo. Sujeta una mancuerna con una mano con agarre supino, apoyando la parte superior del brazo en la almohadilla del banco scott. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0402-7D5bgLT.gif', '/exercises/images/0402-7D5bgLT.jpg'),
('0403', 'dumbbell seated revers grip concentration curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0403-lyKCLmK.gif', '/exercises/images/0403-lyKCLmK.jpg'),
('1738', 'dumbbell seated reverse grip one arm overhead tricep extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con agarre supino y extiende el brazo recto por encima de la cabeza. Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto. Haz una pausa por un momento, luego extiende el brazo de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1738-5fKX7wi.gif', '/exercises/images/1738-5fKX7wi.jpg'),
('0405', 'dumbbell seated shoulder press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos. Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0405-znQUdHY.gif', '/exercises/images/0405-znQUdHY.jpg'),
('0404', 'dumbbell seated shoulder press (parallel grip)', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0404-f1jf47L.gif', '/exercises/images/0404-f1jf47L.jpg'),
('2188', 'dumbbell seated triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza. Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Haz una pausa por un momento, luego endereza los brazos y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2188-kont8Ut.gif', '/exercises/images/2188-kont8Ut.jpg'),
('0407', 'dumbbell side bend', 'Core', 'waist', 'dumbbell', 'abs', 'obliques', ARRAY['obliques'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano y dejando que cuelgue a tu costado. Manteniendo la espalda recta y el core activado, inclínate lentamente hacia el lado opuesto de la mancuerna, bajando el peso tanto como te sea posible con comodidad. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite.', '/exercises/gifs/0407-IpONWYv.gif', '/exercises/images/0407-IpONWYv.jpg'),
('0408', 'dumbbell side lying one hand raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo. Sujeta una mancuerna con la mano de arriba, con la palma hacia abajo. Manteniendo el brazo recto, sube la mancuerna hasta la altura del hombro. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0408-fTlkJop.gif', '/exercises/images/0408-fTlkJop.jpg'),
('3548', 'dumbbell single arm overhead carry', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo. Activa el core y mantén la espalda recta mientras caminas hacia adelante, sosteniendo la mancuerna por encima de la cabeza. Continúa caminando durante la distancia o el tiempo deseado. Cambia de mano y repite el ejercicio.', '/exercises/gifs/3548-mWBtgmb.gif', '/exercises/images/3548-mWBtgmb.jpg'),
('0409', 'dumbbell single leg calf raise', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'ankles', ARRAY['ankles'], 'Ponte de pie en el borde de un escalón o plataforma, con los talones colgando y la punta de los pies sobre el escalón. Sujeta una mancuerna con una mano y coloca la otra mano sobre una pared o barandilla para apoyarte. Eleva el talón lo más alto posible, levantando el cuerpo sobre la punta de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón por debajo del nivel del escalón. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', '/exercises/gifs/0409-1kB3Wmk.gif', '/exercises/images/0409-1kB3Wmk.jpg'),
('1757', 'dumbbell single leg deadlift', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha. Traslada tu peso a la pierna izquierda y levanta el pie derecho ligeramente del suelo. Manteniendo la espalda recta, inclínate hacia adelante desde las caderas y baja la mancuerna hacia el suelo. Al mismo tiempo, extiende la pierna derecha recta hacia atrás, manteniendo una ligera flexión en la rodilla izquierda. Baja la mancuerna hasta que tu torso y tu pierna derecha queden paralelos al suelo. Haz una pausa por un momento, luego activa los glúteos y los isquiotibiales para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1757-gKozT8X.gif', '/exercises/images/1757-gKozT8X.jpg'),
('2805', 'dumbbell single leg deadlift with stepbox support', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha. Coloca el pie izquierdo sobre un cajón de step o una superficie elevada detrás de ti. Manteniendo la espalda recta y el core activado, inclínate hacia adelante desde las caderas, bajando la mancuerna hacia el suelo. Mientras bajas la mancuerna, levanta al mismo tiempo la pierna izquierda detrás de ti, manteniendo una línea recta desde la cabeza hasta el talón. Baja la mancuerna hasta sentir un estiramiento en el isquiotibial derecho, luego vuelve a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/2805-daBmy1Y.gif', '/exercises/images/2805-daBmy1Y.jpg'),
('0410', 'dumbbell single leg split squat', 'Pierna', 'upper legs', 'dumbbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso hacia adelante con un pie y coloca los pies de modo que el pie delantero quede plano en el suelo y el pie trasero quede elevado sobre un banco o escalón. Baja el cuerpo flexionando la rodilla y la cadera delanteras, manteniendo la rodilla trasera ligeramente flexionada y el talón trasero levantado del suelo. Continúa bajando hasta que el muslo delantero quede paralelo al suelo, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/0410-qx4fgX7.gif', '/exercises/images/0410-qx4fgX7.jpg'),
('0411', 'dumbbell single leg squat', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Extiende una pierna hacia adelante y mantenla levantada del suelo durante todo el ejercicio. Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla. Mantén el pecho arriba y la espalda recta. Haz una pausa por un momento en la posición más baja, luego empuja con el talón para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0411-H6ybluc.gif', '/exercises/images/0411-H6ybluc.jpg'),
('0413', 'dumbbell squat', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Manteniendo el pecho arriba y el core activado, baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0413-HsvHqgf.gif', '/exercises/images/0413-HsvHqgf.jpg'),
('3560', 'dumbbell standing alternate hammer curl and press', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y la espalda recta. Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el curl con la mano izquierda. Después de completar el curl con la mano izquierda, exhala y presiona la mancuerna de la mano derecha por encima de la cabeza. Extiende completamente el brazo y mantén la posición por un momento en la parte superior. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el press con la mano izquierda. Continúa alternando entre curls y press durante el número de repeticiones deseado.', '/exercises/gifs/3560-LeaZOIz.gif', '/exercises/images/3560-LeaZOIz.jpg'),
('0414', 'dumbbell standing alternate overhead press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante. Presiona una mancuerna por encima de la cabeza, extendiendo completamente el brazo. Baja la mancuerna de vuelta a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/0414-bBi35y3.gif', '/exercises/images/0414-bBi35y3.jpg'),
('0415', 'dumbbell standing alternate raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y el core activado. Levanta una mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', '/exercises/gifs/0415-SxHteRW.gif', '/exercises/images/0415-SxHteRW.jpg'),
('1739', 'dumbbell standing alternating tricep kickback', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite con el otro brazo, alternando lados en cada repetición.', '/exercises/gifs/1739-Gi2BXfK.gif', '/exercises/images/1739-Gi2BXfK.jpg'),
('2143', 'dumbbell standing around world', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Extiende los brazos rectos hacia los lados a la altura de los hombros, con las palmas hacia abajo. Manteniendo los brazos rectos, gira lentamente los brazos en un movimiento circular, llevando las mancuernas frente al cuerpo y luego por encima de la cabeza. Continúa el movimiento circular, bajando las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2143-RSOsp5d.gif', '/exercises/images/2143-RSOsp5d.jpg'),
('1740', 'dumbbell standing bent over one arm triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1740-CJwa0vD.gif', '/exercises/images/1740-CJwa0vD.jpg'),
('1741', 'dumbbell standing bent over two arm triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders', 'back'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo. Baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1741-3T12T87.gif', '/exercises/images/1741-3T12T87.jpg'),
('0416', 'dumbbell standing biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0416-3s4NnTh.gif', '/exercises/images/0416-3s4NnTh.jpg'),
('0417', 'dumbbell standing calf raise', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'ankles', ARRAY['ankles'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0417-dPmaUaU.gif', '/exercises/images/0417-dPmaUaU.jpg'),
('0418', 'dumbbell standing concentration curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano, con el brazo completamente extendido y la palma hacia adentro. Apoya la otra mano sobre el muslo para mayor estabilidad. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0418-7inpWch.gif', '/exercises/images/0418-7inpWch.jpg'),
('0419', 'dumbbell standing front raise above head', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Mantén los brazos rectos y levanta las mancuernas frente a ti, elevándolas por encima de la cabeza. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0419-laVRfDf.gif', '/exercises/images/0419-laVRfDf.jpg'),
('2321', 'dumbbell standing inner biceps curl v. 2', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Manteniendo fija la parte superior de los brazos, flexiona los pesos mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Comienza a llevar lentamente las mancuernas de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones recomendado.', '/exercises/gifs/2321-vKilzz3.gif', '/exercises/images/2321-vKilzz3.jpg'),
('0420', 'dumbbell standing kickback', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0420-UmpPAAe.gif', '/exercises/images/0420-UmpPAAe.jpg'),
('0421', 'dumbbell standing one arm concentration curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia arriba. Coloca la mano libre sobre el muslo para apoyarte. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0421-8fgqP5a.gif', '/exercises/images/0421-8fgqP5a.jpg'),
('0422', 'dumbbell standing one arm curl (over incline bench)', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia adelante. Coloca la otra mano sobre un banco inclinado para apoyarte. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/0422-BIb1tGo.gif', '/exercises/images/0422-BIb1tGo.jpg'),
('1680', 'dumbbell standing one arm curl over incline bench', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Coloca la otra mano sobre un banco inclinado para apoyarte. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1680-EmlJR2y.gif', '/exercises/images/1680-EmlJR2y.jpg'),
('0423', 'dumbbell standing one arm extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo. Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo. Baja lentamente la mancuerna detrás de la cabeza, flexionando el codo. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0423-BCUR88E.gif', '/exercises/images/0423-BCUR88E.jpg'),
('0424', 'dumbbell standing one arm palm in press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano a la altura del hombro, con la palma hacia adentro. Activa el core y mantén la espalda recta. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0424-ocYc6Db.gif', '/exercises/images/0424-ocYc6Db.jpg'),
('0425', 'dumbbell standing one arm reverse curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano con agarre prono. Mantén el brazo completamente extendido y cerca del cuerpo, con la palma hacia abajo. Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0425-DU5Kkj2.gif', '/exercises/images/0425-DU5Kkj2.jpg'),
('0426', 'dumbbell standing overhead press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0426-A6wtbuL.gif', '/exercises/images/0426-A6wtbuL.jpg'),
('0427', 'dumbbell standing palms in press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adentro. Manteniendo el core activado y la espalda recta, presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0427-UilDHSs.gif', '/exercises/images/0427-UilDHSs.jpg'),
('0428', 'dumbbell standing preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Apoya la parte posterior de la parte superior de los brazos contra el banco scott o un banco inclinado, con los codos ligeramente flexionados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0428-hq2hyDH.gif', '/exercises/images/0428-hq2hyDH.jpg'),
('0429', 'dumbbell standing reverse curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano, con las palmas hacia tu cuerpo. Manteniendo fija la parte superior de los brazos, exhala y flexiona los pesos mientras contraes los bíceps. Continúa subiendo los pesos hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0429-0IgNjSM.gif', '/exercises/images/0429-0IgNjSM.jpg'),
('0430', 'dumbbell standing triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, manteniendo el brazo recto. Flexiona el codo y baja la mancuerna detrás de la cabeza, manteniendo fija la parte superior del brazo. Extiende el brazo de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0430-PdmaD0N.gif', '/exercises/images/0430-PdmaD0N.jpg'),
('2293', 'dumbbell standing zottman preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Apoya la parte superior de los brazos contra el banco scott y mantén los codos ligeramente flexionados. Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos. En la parte superior del movimiento, gira las muñecas de modo que las palmas queden hacia abajo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original. Repite el número de repeticiones deseado.', '/exercises/gifs/2293-P2nRiUa.gif', '/exercises/images/2293-P2nRiUa.jpg'),
('1684', 'dumbbell step up single leg balance with bicep curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'quadriceps', ARRAY['quadriceps', 'glutes', 'hamstrings'], 'Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté en contacto con la superficie. Activa el core y empuja con el talón derecho para subir el cuerpo sobre el escalón, llevando la rodilla izquierda hacia el pecho. En la parte superior del movimiento, realiza un curl de bíceps flexionando los codos y llevando las mancuernas hacia los hombros. Baja las mancuernas y, al mismo tiempo, baja el pie izquierdo de vuelta al suelo. Repite el movimiento del lado contrario, subiendo con el pie izquierdo y flexionando las mancuernas. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1684-76vfTdU.gif', '/exercises/images/1684-76vfTdU.jpg'),
('0431', 'dumbbell step-up', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Empuja con el talón derecho y sube el cuerpo sobre el banco o escalón, enderezando la pierna derecha. Sube el pie izquierdo hasta el banco o escalón, quedando completamente erguido. Baja con el pie izquierdo, seguido del pie derecho, volviendo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0431-aXtJhlg.gif', '/exercises/images/0431-aXtJhlg.jpg'),
('2796', 'dumbbell step-up lunge', 'Pierna', 'upper legs', 'dumbbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tus costados. Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté sobre la superficie. Empuja con el talón derecho y sube el cuerpo sobre el escalón, llevando también el pie izquierdo hacia arriba. Una vez que ambos pies estén sobre el escalón, baja el pie izquierdo de vuelta a la posición inicial, manteniendo el pie derecho sobre el escalón. Repite el movimiento, alternando el pie con el que subes cada vez. Continúa durante el número de repeticiones deseado.', '/exercises/gifs/2796-gFyFj9z.gif', '/exercises/images/2796-gFyFj9z.jpg'),
('2812', 'dumbbell step-up split squat', 'Pierna', 'upper legs', 'dumbbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo. Mientras subes, levanta al mismo tiempo la rodilla izquierda hacia el pecho. Haz una pausa en la parte superior del movimiento, luego baja lentamente el pie izquierdo de vuelta al suelo mientras mantienes el pie derecho sobre el banco o escalón. Repite el movimiento con el pie izquierdo sobre el banco o escalón. Continúa alternando entre el pie derecho y el izquierdo durante el número de repeticiones deseado.', '/exercises/gifs/2812-QjE2DcA.gif', '/exercises/images/2812-QjE2DcA.jpg'),
('0432', 'dumbbell stiff leg deadlift', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo una ligera flexión en las rodillas. Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego aprieta los glúteos y empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0432-5eLRITT.gif', '/exercises/images/0432-5eLRITT.jpg'),
('0433', 'dumbbell straight arm pullover', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'latissimus dorsi', ARRAY['latissimus dorsi', 'triceps'], 'Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza con un movimiento en forma de arco. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0433-i8BdLTK.gif', '/exercises/images/0433-i8BdLTK.jpg'),
('0434', 'dumbbell straight leg deadlift', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que el torso se incline hacia adelante. Continúa bajando las mancuernas hasta sentir un estiramiento en los isquiotibiales, manteniendo las rodillas ligeramente flexionadas. Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0434-oom75KC.gif', '/exercises/images/0434-oom75KC.jpg'),
('2808', 'dumbbell sumo pull through', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'core'], 'Ponte de pie con los pies más separados que la altura de los hombros, con las puntas de los pies hacia afuera. Sujeta una mancuerna con ambas manos frente a tu cuerpo, con los brazos extendidos. Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta. Baja la mancuerna entre las piernas, manteniendo los brazos rectos. Empuja con los talones y extiende las caderas hacia adelante, llevando la mancuerna hacia arriba y frente a tu cuerpo. Aprieta los glúteos en la parte superior del movimiento, luego baja la mancuerna de vuelta entre las piernas. Repite el número de repeticiones deseado.', '/exercises/gifs/2808-BmrwWzo.gif', '/exercises/images/2808-BmrwWzo.jpg'),
('2803', 'dumbbell supported squat', 'Pierna', 'upper legs', 'dumbbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Manteniendo el pecho arriba y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2803-r5DgrW9.gif', '/exercises/images/2803-r5DgrW9.jpg'),
('0436', 'dumbbell tate press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí. Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros. Gira las muñecas de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0436-s5PdDyY.gif', '/exercises/images/0436-s5PdDyY.jpg'),
('1742', 'dumbbell tricep kickback with stork stance', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados. Extiende el brazo derecho recto hacia atrás, apretando el tríceps. Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1742-wOLmCXc.gif', '/exercises/images/1742-wOLmCXc.jpg'),
('1743', 'dumbbell twisting bench press', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta una mancuerna en cada mano con agarre prono, con las palmas alejadas de ti. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Baja las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden hacia ti en la parte más baja del movimiento. Haz una pausa por un momento en la parte más baja, luego invierte el movimiento presionando las mancuernas de vuelta hacia arriba, hasta la posición inicial. Mientras presionas las mancuernas hacia arriba, gira las muñecas de vuelta a la posición inicial con las palmas alejadas de ti. Repite el número de repeticiones deseado.', '/exercises/gifs/1743-z6TAHoT.gif', '/exercises/images/1743-z6TAHoT.jpg'),
('0437', 'dumbbell upright row', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos. Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0437-ainizkb.gif', '/exercises/images/0437-ainizkb.jpg'),
('1765', 'dumbbell upright row (back pov)', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos y las palmas hacia tu cuerpo. Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos. Continúa subiendo hasta que las mancuernas estén a la altura de los hombros, con los codos apuntando hacia los lados. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1765-Iptlv6x.gif', '/exercises/images/1765-Iptlv6x.jpg'),
('0864', 'dumbbell upright shoulder external rotation', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'rotator cuff', ARRAY['rotator cuff', 'trapezius'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo los codos ligeramente flexionados. Gira los brazos hacia afuera, llevando las mancuernas hacia la cabeza mientras mantienes los codos en la misma posición. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0864-x306lCW.gif', '/exercises/images/0864-x306lCW.jpg'),
('5201', 'dumbbell waiter biceps curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén la parte superior de los brazos cerca del cuerpo y los codos pegados. Flexiona lentamente las mancuernas hacia los hombros, manteniendo las muñecas rectas. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/5201-KOpzGBL.gif', '/exercises/images/5201-KOpzGBL.jpg'),
('0438', 'dumbbell w-press', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Baja las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0438-vmwLyCg.gif', '/exercises/images/0438-vmwLyCg.jpg'),
('0439', 'dumbbell zottman curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y gira las palmas para que queden hacia adelante. Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos. En la parte superior del movimiento, gira las muñecas de modo que las palmas queden alejadas de tu cuerpo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando las palmas de nuevo hacia tu cuerpo. Repite el número de repeticiones deseado.', '/exercises/gifs/0439-kXaIn5A.gif', '/exercises/images/0439-kXaIn5A.jpg'),
('2294', 'dumbbell zottman preacher curl', 'Brazo', 'upper arms', 'dumbbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba y los codos apoyados en la almohadilla. Flexiona las mancuernas hacia los hombros, manteniendo fija la parte superior de los brazos y las palmas hacia arriba. En la parte superior del curl, gira las muñecas de modo que las palmas queden hacia abajo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original mientras lo haces. Repite el número de repeticiones deseado.', '/exercises/gifs/2294-y5U5B9Y.gif', '/exercises/images/2294-y5U5B9Y.jpg'),
('2189', 'dumbbells seated triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos con agarre prono y levántala por encima de la cabeza. Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Extiende los brazos y sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2189-FQXdXzY.gif', '/exercises/images/2189-FQXdXzY.jpg'),
('1167', 'dynamic chest stretch (male)', 'Pecho', 'chest', 'body weight', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos hacia los lados, paralelos al suelo. Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo. Siente el estiramiento en los músculos del pecho. Mantén el estiramiento durante 10-30 segundos. Vuelve a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/1167-3uj0Ozg.gif', '/exercises/images/1167-3uj0Ozg.jpg'),
('3287', 'elbow dips', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas. Desliza las caderas hacia adelante, fuera del banco, y estira las piernas, manteniendo los talones en el suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3287-LkoAWAE.gif', '/exercises/images/3287-LkoAWAE.jpg'),
('1772', 'elbow lift - reverse push-up', 'Espalda', 'back', 'body weight', 'upper back', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros. Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados. Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta. Baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1772-wbUYILZ.gif', '/exercises/images/1772-wbUYILZ.jpg'),
('0443', 'elbow-to-knee', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Comienza tumbado boca arriba con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda. Al mismo tiempo, lleva la rodilla izquierda hacia el codo derecho, creando un movimiento de torsión. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo y extiende las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y la rodilla derecha hacia el codo izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0443-jvp6DiD.gif', '/exercises/images/0443-jvp6DiD.jpg'),
('3292', 'elevator', 'Espalda', 'back', 'body weight', 'upper back', 'shoulders', ARRAY['shoulders', 'trapezius'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Coloca las manos sobre las caderas o crúzalas frente al pecho. Manteniendo la espalda recta, inclínate lentamente hacia adelante desde la cintura, bajando la parte superior del cuerpo hacia el suelo. Haz una pausa por un momento en la posición más baja, luego sube lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3292-zYmNaoY.gif', '/exercises/images/3292-zYmNaoY.jpg'),
('1332', 'exercise ball alternating arm ups', 'Espalda', 'back', 'stability ball', 'lats', 'shoulders', ARRAY['shoulders', 'core'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adentro y los brazos extendidos hacia abajo a los lados. Activa el core y levanta lentamente un brazo hacia el hombro, manteniendo el codo ligeramente flexionado. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el movimiento con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/1332-EyLrNC2.gif', '/exercises/images/1332-EyLrNC2.jpg'),
('1333', 'exercise ball back extension with arms extended', 'Espalda', 'back', 'stability ball', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Extiende los brazos rectos hacia adelante, con las palmas hacia abajo. Activa el core y levanta lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta y el cuello alineado con la columna. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1333-PERjVm8.gif', '/exercises/images/1333-PERjVm8.jpg'),
('1334', 'exercise ball back extension with hands behind head', 'Espalda', 'back', 'stability ball', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él con las caderas apoyadas en el balón. Coloca los pies contra una pared u otra superficie estable para apoyarte. Cruza los brazos detrás de la cabeza, con las manos tocando la parte de atrás de la cabeza. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta las caderas. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1334-o1HGDSq.gif', '/exercises/images/1334-o1HGDSq.jpg'),
('1335', 'exercise ball back extension with knees off ground', 'Espalda', 'back', 'stability ball', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1335-WME869U.gif', '/exercises/images/1335-WME869U.jpg'),
('1336', 'exercise ball back extension with rotation', 'Espalda', 'back', 'stability ball', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Comienza tumbado boca abajo sobre el balón de estabilidad, con las caderas apoyadas en el balón y los pies firmemente apoyados en el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables. Vuelve al centro y repite el giro hacia el otro lado. Baja la parte superior del cuerpo de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/1336-WVD66ff.gif', '/exercises/images/1336-WVD66ff.jpg'),
('1744', 'exercise ball dip', 'Brazo', 'upper arms', 'stability ball', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos sobre el balón junto a las caderas, con los dedos apuntando hacia adelante. Activa el tríceps y empuja con las manos para levantar el cuerpo del balón, enderezando los brazos. Baja el cuerpo flexionando los codos, manteniéndolos cerca de los costados. Repite el número de repeticiones deseado.', '/exercises/gifs/1744-kprile3.gif', '/exercises/images/1744-kprile3.jpg'),
('1559', 'exercise ball hip flexor stretch', 'Pierna', 'upper legs', 'stability ball', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings'], 'Coloca el balón de estabilidad en el suelo y arrodíllate frente a él. Coloca el pie derecho sobre el balón de estabilidad, con la rodilla flexionada en un ángulo de 90 grados. Extiende la pierna izquierda hacia atrás, manteniéndola recta. Inclínate hacia adelante, empujando las caderas hacia el balón de estabilidad, hasta sentir un estiramiento en el flexor de la cadera derecha. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', '/exercises/gifs/1559-2LQkNPW.gif', '/exercises/images/1559-2LQkNPW.jpg'),
('1338', 'exercise ball hug', 'Espalda', 'back', 'stability ball', 'spine', 'shoulders', ARRAY['shoulders', 'chest'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta el balón de estabilidad con ambas manos, abrazándolo cerca del pecho. Activa los músculos del core y reclínate lentamente hacia atrás, manteniendo la espalda recta y los pies apoyados en el suelo. Continúa reclinándote hacia atrás hasta sentir un estiramiento en los músculos de la espalda. Mantén la posición durante unos segundos, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1338-d7z1Y7V.gif', '/exercises/images/1338-d7z1Y7V.jpg'),
('1339', 'exercise ball lat stretch', 'Espalda', 'back', 'stability ball', 'lats', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sujeta una mancuerna con una mano y extiende el brazo recto por encima de la cabeza. Inclínate lentamente hacia el lado opuesto, sintiendo un estiramiento en el músculo dorsal. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite del otro lado.', '/exercises/gifs/1339-sM84pE4.gif', '/exercises/images/1339-sM84pE4.jpg'),
('1341', 'exercise ball lower back stretch (pyramid)', 'Espalda', 'back', 'stability ball', 'lats', 'glutes', ARRAY['glutes', 'hamstrings'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Camina lentamente hacia adelante con los pies, haciendo rodar el balón por tu espalda hasta que tu zona lumbar quede apoyada sobre el balón. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, permitiendo que tu zona lumbar se estire sobre el balón. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1341-yU7w7CA.gif', '/exercises/images/1341-yU7w7CA.jpg'),
('1342', 'exercise ball lying side lat stretch', 'Espalda', 'back', 'stability ball', 'lats', 'shoulders', ARRAY['shoulders', 'triceps'], 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el balón de estabilidad. Coloca el brazo de arriba sobre el balón para mantener la estabilidad. Extiende el brazo de arriba por encima de la cabeza y permite que tu torso gire ligeramente. Siente el estiramiento en los músculos dorsales del costado de tu cuerpo. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', '/exercises/gifs/1342-rTbyBYV.gif', '/exercises/images/1342-rTbyBYV.jpg'),
('1382', 'exercise ball on the wall calf raise', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared. Coloca los pies separados a la altura de los hombros, con la punta de los pies hacia adelante. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Levanta los talones del suelo, llevando el peso de tu cuerpo hacia la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1382-xo6sENf.gif', '/exercises/images/1382-xo6sENf.jpg'),
('3241', 'exercise ball on the wall calf raise (tennis ball between ankles)', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Ponte de pie frente a una pared con los pies separados a la altura de los hombros. Coloca un balón de ejercicio entre la pared y tu zona lumbar. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Coloca una pelota de tenis entre los tobillos. Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3241-FY3UdNT.gif', '/exercises/images/3241-FY3UdNT.jpg'),
('3240', 'exercise ball on the wall calf raise (tennis ball between knees)', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'quadriceps', ARRAY['quadriceps', 'hamstrings'], 'Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared. Coloca los pies separados a la altura de los hombros y ligeramente por delante de ti. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Coloca una pelota de tenis entre las rodillas. Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3240-j74M6Zn.gif', '/exercises/images/3240-j74M6Zn.jpg'),
('1416', 'exercise ball one leg prone lower body rotation', 'Pierna', 'upper legs', 'stability ball', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'core'], 'Túmbate boca abajo sobre el balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti. Coloca las manos en el suelo frente a ti para mayor apoyo. Activa los glúteos y el abdomen para estabilizar el cuerpo. Levanta lentamente una pierna del suelo, manteniéndola recta y paralela al piso. Gira la pierna hacia afuera, alejándola del cuerpo, mientras mantienes las caderas y la parte superior del cuerpo estables. Haz una pausa al final de la rotación, luego regresa lentamente la pierna a la posición inicial. Repite la rotación con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/1416-M72BExt.gif', '/exercises/images/1416-M72BExt.jpg'),
('1417', 'exercise ball one legged diagonal kick hamstring curl', 'Pierna', 'upper legs', 'stability ball', 'glutes', 'hamstrings', ARRAY['hamstrings', 'calves'], 'Comienza acostado sobre la espalda con las piernas extendidas y los talones apoyados sobre el balón de estabilidad. Coloca los brazos a los lados del cuerpo para mantener el equilibrio. Activa los glúteos y el abdomen para levantar las caderas del suelo, formando una línea recta desde los hombros hasta los talones. Dobla la rodilla derecha y llévala hacia el pecho, manteniendo la pierna izquierda extendida y el pie en flexión. Lleva la pierna derecha en diagonal a través del cuerpo, extendiéndola por completo y activando los isquiotibiales. Regresa lentamente la pierna derecha a la posición inicial, manteniendo el control y el equilibrio. Repite el movimiento con la pierna izquierda, alternando los lados durante el número de repeticiones deseado.', '/exercises/gifs/1417-GOJKFfO.gif', '/exercises/images/1417-GOJKFfO.jpg'),
('1296', 'exercise ball pike push up', 'Pecho', 'chest', 'stability ball', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps', 'core'], 'Comienza en posición de flexión de brazos con las manos en el suelo y las espinillas apoyadas sobre el balón de estabilidad. Activa el core y levanta las caderas hacia el techo, haciendo rodar el balón hacia las manos. Mantén las piernas rectas y el cuerpo en posición de pica, formando una V invertida. Dobla los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo la cabeza alineada con las manos. Empuja con las manos y extiende los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1296-sVvXT5J.gif', '/exercises/images/1296-sVvXT5J.jpg'),
('1343', 'exercise ball prone leg raise', 'Espalda', 'back', 'stability ball', 'spine', 'abdominals', ARRAY['abdominals', 'glutes'], 'Túmbate boca abajo sobre una esterilla con las piernas extendidas y los dedos de los pies apoyados sobre el balón de estabilidad. Coloca las manos en el suelo, separadas a la altura de los hombros, y activa el abdomen. Manteniendo las piernas rectas, levántalas lentamente del suelo, usando la zona lumbar y los glúteos para elevarlas tan alto como sea posible. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1343-lCKm4Rs.gif', '/exercises/images/1343-lCKm4Rs.jpg'),
('1560', 'exercise ball seated hamstring stretch', 'Pierna', 'upper legs', 'stability ball', 'hamstrings', 'glutes', ARRAY['glutes', 'lower back'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Haz rodar el balón lentamente hacia adelante, caminando con los pies hacia afuera hasta que la parte superior de la espalda quede apoyada sobre el balón y las piernas queden extendidas rectas frente a ti. Coloca las manos en las caderas para mayor apoyo. Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, manteniendo la espalda recta y el pecho elevado. Detente cuando sientas un estiramiento en los isquiotibiales y mantén la posición durante 20-30 segundos. Regresa lentamente a la posición inicial empujando con los talones y usando los isquiotibiales para volver a subir. Repite el número de repeticiones deseado.', '/exercises/gifs/1560-yRYyfdA.gif', '/exercises/images/1560-yRYyfdA.jpg'),
('1745', 'exercise ball seated triceps stretch', 'Brazo', 'upper arms', 'stability ball', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sostén una mancuerna con una mano y extiende el brazo recto por encima de la cabeza. Dobla el codo y baja la mancuerna detrás de la cabeza, manteniendo el brazo cerca de la oreja. Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial. Repite con el otro brazo.', '/exercises/gifs/1745-7ePTw4B.gif', '/exercises/images/1745-7ePTw4B.jpg'),
('1746', 'exercise ball supine triceps extension', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia el techo. Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas. Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1746-Gm2Uv1z.gif', '/exercises/images/1746-Gm2Uv1z.jpg'),
('1747', 'ez bar french press on exercise ball', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate sobre un balón de ejercicio y sostén una barra EZ con agarre prono. Extiende los brazos rectos hacia arriba, manteniendo los codos cerca de la cabeza. Baja lentamente la barra detrás de la cabeza doblando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1747-CFN9P8G.gif', '/exercises/images/1747-CFN9P8G.jpg'),
('3010', 'ez bar lying bent arms pullover', 'Espalda', 'back', 'ez barbell', 'lats', 'triceps', ARRAY['triceps', 'chest'], 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sostén la barra EZ con agarre prono (palmas hacia afuera) y las manos separadas a la altura de los hombros. Extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la barra describiendo un arco detrás de la cabeza, manteniendo la ligera flexión en los codos. Haz una pausa breve, luego regresa la barra a la posición inicial invirtiendo el movimiento del arco. Repite el número de repeticiones deseado.', '/exercises/gifs/3010-nDK1HJ0.gif', '/exercises/images/3010-nDK1HJ0.jpg'),
('1748', 'ez bar lying close grip triceps extension behind head', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sostén la barra EZ con agarre cerrado, palmas hacia arriba, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1748-6CKUx7o.gif', '/exercises/images/1748-6CKUx7o.jpg'),
('1344', 'ez bar reverse grip bent over row', 'Espalda', 'back', 'ez barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo. Tira de la barra EZ hacia la parte baja del pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte superior, luego baja lentamente la barra EZ a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1344-G8dXpNG.gif', '/exercises/images/1344-G8dXpNG.jpg'),
('1682', 'ez bar seated close grip concentration curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados en el suelo y sostén una barra EZ con agarre supino. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Sube la barra curvando el brazo hacia el hombro mientras mantienes el brazo superior inmóvil. Contrae los bíceps en la parte superior del movimiento, luego baja lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1682-Dsfz0Id.gif', '/exercises/images/1682-Dsfz0Id.jpg'),
('1749', 'ez bar standing french press', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1749-1cTf2Ux.gif', '/exercises/images/1749-1cTf2Ux.jpg'),
('0445', 'ez barbell anti gravity press', 'Hombro', 'shoulders', 'ez barbell', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra EZ con agarre prono. Eleva la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y las palmas hacia adelante. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', '/exercises/gifs/0445-fprd84i.gif', '/exercises/images/0445-fprd84i.jpg'),
('1627', 'ez barbell close grip preacher curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott y coloca los brazos superiores sobre la almohadilla, sujetando la barra EZ con agarre supino. Apoya los tríceps sobre la almohadilla y extiende los brazos por completo, manteniendo la espalda recta. Sube lentamente la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Baja la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/1627-hacCyUv.gif', '/exercises/images/1627-hacCyUv.jpg'),
('0446', 'ez barbell close-grip curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Sube la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0446-V4ryaZa.gif', '/exercises/images/0446-V4ryaZa.jpg'),
('0447', 'ez barbell curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Exhala mientras subes la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0447-6TG6x2w.gif', '/exercises/images/0447-6TG6x2w.jpg'),
('0448', 'ez barbell decline close grip face press', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate en un banco declinado con la cabeza más baja que los pies. Sujeta la barra EZ con agarre cerrado, palmas una frente a la otra. Extiende los brazos rectos por encima del pecho, manteniendo los codos cerca del cuerpo. Baja la barra hacia la frente doblando los codos. Haz una pausa breve, luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0448-DgZQ11d.gif', '/exercises/images/0448-DgZQ11d.jpg'),
('2186', 'ez barbell decline triceps extension', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Túmbate en un banco declinado con la cabeza más baja que los pies y los pies asegurados. Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros. Extiende completamente los brazos, manteniendo los codos cerca de la cabeza. Baja la barra lentamente hacia la frente, doblando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2186-CQHoDm0.gif', '/exercises/images/2186-CQHoDm0.jpg'),
('0449', 'ez barbell incline triceps extension', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y sostén la barra EZ con agarre prono. Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza. Baja la barra detrás de la cabeza doblando los codos, manteniendo los brazos superiores inmóviles. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0449-KyLtiLT.gif', '/exercises/images/0449-KyLtiLT.jpg'),
('0450', 'ez barbell jm bench press', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra EZ con agarre prono, ligeramente más ancho que la altura de los hombros. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0450-hnOYgH3.gif', '/exercises/images/0450-hnOYgH3.jpg'),
('0451', 'ez barbell reverse grip curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino. Mantén los codos cerca del torso y los brazos superiores inmóviles durante todo el ejercicio. Sube la barra contrayendo los bíceps, mientras exhalas. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Comienza a regresar la barra lentamente a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', '/exercises/gifs/0451-Y5X65IB.gif', '/exercises/images/0451-Y5X65IB.jpg'),
('0452', 'ez barbell reverse grip preacher curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco scott con el pecho apoyado en la almohadilla y los pies planos sobre el suelo. Sujeta la barra EZ con agarre supino, manos separadas a la altura de los hombros. Apoya los brazos superiores en la almohadilla, dejando que los antebrazos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0452-vBNyir7.gif', '/exercises/images/0452-vBNyir7.jpg'),
('1458', 'ez barbell seated curls', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Apoya los brazos superiores en los muslos, dejando que la barra EZ cuelgue frente a ti. Manteniendo los brazos superiores inmóviles, exhala y sube la barra EZ hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra EZ a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1458-jtFKbt5.gif', '/exercises/images/1458-jtFKbt5.jpg'),
('0453', 'ez barbell seated triceps extension', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores inmóviles, baja la barra detrás de la cabeza doblando los codos. Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0453-iaapw0g.gif', '/exercises/images/0453-iaapw0g.jpg'),
('0454', 'ez barbell spider curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0454-Ye5Qxb0.gif', '/exercises/images/0454-Ye5Qxb0.jpg'),
('1628', 'ez barbell spider curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1628-2kattbR.gif', '/exercises/images/1628-2kattbR.jpg'),
('2404', 'ez-bar biceps curl (with arm blaster)', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Coloca los brazos superiores contra el soporte de aislamiento de brazos, manteniéndolos inmóviles durante todo el ejercicio. Manteniendo los codos cerca del cuerpo, exhala y sube la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/2404-tJ5nYqo.gif', '/exercises/images/2404-tJ5nYqo.jpg'),
('2432', 'ez-bar close-grip bench press', 'Brazo', 'upper arms', 'ez barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra EZ con agarre cerrado, manos separadas a la altura de los hombros, palmas hacia adelante. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/2432-da4cXST.gif', '/exercises/images/2432-da4cXST.jpg'),
('2741', 'ez-barbell standing wide grip biceps curl', 'Brazo', 'upper arms', 'ez barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos más separadas que la altura de los hombros. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Sube la barra hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2741-OVTZ65k.gif', '/exercises/images/2741-OVTZ65k.jpg'),
('2133', 'farmers walk', 'Pierna', 'upper legs', 'dumbbell', 'quads', 'calves', ARRAY['calves', 'forearms', 'core'], 'Ponte de pie con una mancuerna en cada mano, palmas hacia los costados. Mantén la espalda recta y los hombros hacia atrás. Da pasos pequeños y controlados hacia adelante, manteniendo una postura erguida. Continúa caminando durante la distancia o el tiempo deseado. Para terminar, deja de caminar y baja con cuidado las mancuernas a los costados.', '/exercises/gifs/2133-qPEzJjA.gif', '/exercises/images/2133-qPEzJjA.jpg'),
('0455', 'finger curls', 'Antebrazo', 'lower arms', 'barbell', 'forearms', 'wrist flexors', ARRAY['wrist flexors', 'grip muscles'], 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Curva lentamente los dedos hacia las palmas, apretando la barra con fuerza. Mantén la contracción por un momento, luego suelta lentamente los dedos hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0455-awG04cF.gif', '/exercises/images/0455-awG04cF.jpg'),
('3303', 'flag', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'shoulders'], 'Comienza sujetando un poste vertical con ambas manos, palmas una frente a la otra, y los brazos completamente extendidos. Activa el core y levanta las piernas del suelo, manteniéndolas rectas. Usando la fuerza del core y de la parte superior del cuerpo, levanta las piernas hasta que queden paralelas al suelo. Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3303-pQ0Mx1Z.gif', '/exercises/images/3303-pQ0Mx1Z.jpg'),
('0456', 'flexion leg sit up (bent knee)', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Al mismo tiempo, levanta las piernas del suelo, doblando las rodillas y llevándolas hacia el pecho. Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0456-AR0ig3o.gif', '/exercises/images/0456-AR0ig3o.jpg'),
('0457', 'flexion leg sit up (straight arm)', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'quadriceps'], 'Túmbate boca arriba con las piernas extendidas y los brazos rectos por encima de la cabeza. Activando el abdomen, levanta la parte superior del cuerpo del suelo mientras al mismo tiempo levantas las piernas hacia el pecho. Extiende las manos hacia los dedos de los pies mientras levantas la parte superior del cuerpo y las piernas. Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0457-KZn52RC.gif', '/exercises/images/0457-KZn52RC.jpg'),
('0458', 'floor fly (with barbell)', 'Pecho', 'chest', 'barbell', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sostén una barra con agarre prono, brazos extendidos rectos por encima del pecho. Baja lentamente la barra hacia los lados, manteniendo una ligera flexión en los codos. Baja la barra hasta que los brazos queden paralelos al suelo, sintiendo un estiramiento en el pecho. Haz una pausa breve, luego contrae los músculos del pecho para llevar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0458-neonEDL.gif', '/exercises/images/0458-neonEDL.jpg'),
('0459', 'flutter kicks', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hip flexors', ARRAY['hip flexors', 'lower abs'], 'Túmbate boca arriba con las piernas extendidas y las manos a los costados. Activa el core y levanta las piernas del suelo unos 15 centímetros. Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra. Continúa este movimiento de aleteo durante el número de repeticiones deseado.', '/exercises/gifs/0459-UVo2Qs2.gif', '/exercises/images/0459-UVo2Qs2.jpg'),
('1472', 'forward jump', 'Pierna', 'upper legs', 'body weight', 'quads', 'calves', ARRAY['calves', 'hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Balancea los brazos hacia atrás para generar impulso. Salta hacia adelante de forma explosiva, extendiendo las caderas, las rodillas y los tobillos. Aterriza suavemente sobre la punta de los pies y pasa de inmediato al siguiente salto. Repite el número de repeticiones deseado.', '/exercises/gifs/1472-uZKq7lo.gif', '/exercises/images/1472-uZKq7lo.jpg'),
('3470', 'forward lunge (male)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas. Da un paso grande hacia adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Dobla la rodilla derecha hasta unos 90 grados, manteniendo la rodilla alineada con el tobillo. Empuja con el pie derecho y vuelve a la posición inicial. Repite con la pierna izquierda, alternando los lados durante el número de repeticiones deseado.', '/exercises/gifs/3470-kMzUs9Y.gif', '/exercises/images/3470-kMzUs9Y.jpg'),
('3194', 'frankenstein squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra frente al cuerpo con los brazos rectos. Manteniendo la espalda recta, baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3194-bdWcbaU.gif', '/exercises/images/3194-bdWcbaU.jpg'),
('2429', 'frog crunch', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2429-FFRP97T.gif', '/exercises/images/2429-FFRP97T.jpg'),
('3301', 'frog planche', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'chest', 'triceps'], 'Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los pies juntos. Dobla los codos y baja el cuerpo hacia el suelo, manteniendo la espalda recta. Mientras bajas el cuerpo, levanta los pies del suelo y lleva las rodillas hacia el pecho. Mantén esta posición durante unos segundos, luego extiende las piernas de nuevo y empújate hacia arriba a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3301-rQhGcin.gif', '/exercises/images/3301-rQhGcin.jpg'),
('3296', 'front lever', 'Core', 'waist', 'body weight', 'abs', 'lats', ARRAY['lats', 'shoulders', 'forearms'], 'Comienza colgado de una barra de dominadas con agarre prono, manos separadas a la altura de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Flexiona las rodillas y llévalas hacia el pecho. Al mismo tiempo, levanta las piernas y extiéndelas rectas frente a ti, manteniendo el cuerpo paralelo al suelo. Mantén esta posición todo el tiempo que puedas, intentando lograr una posición completa de palanca frontal. Para soltar, baja lentamente las piernas y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3296-PkCN2lv.gif', '/exercises/images/3296-PkCN2lv.jpg'),
('3295', 'front lever reps', 'Espalda', 'back', 'body weight', 'upper back', 'core', ARRAY['core', 'shoulders'], 'Cuélgate de una barra de dominadas con agarre prono, palmas hacia afuera. Activa el core y lleva los omóplatos hacia abajo y atrás. Manteniendo el cuerpo recto, levanta las piernas hasta que queden paralelas al suelo. Mantén esta posición todo el tiempo que puedas, intentando llegar a 10-20 segundos. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3295-hbY9wqG.gif', '/exercises/images/3295-hbY9wqG.jpg'),
('3315', 'full maltese', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'chest'], 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos rectos hacia los lados. Inclínate lentamente hacia adelante, manteniendo los brazos rectos, hasta que la parte superior del cuerpo quede paralela al suelo. Activa el core y mantén esta posición durante unos segundos. Regresa a la posición inicial empujando con los pies y volviendo a ponerte de pie. Repite el número de repeticiones deseado.', '/exercises/gifs/3315-YRaCa5Y.gif', '/exercises/images/3315-YRaCa5Y.jpg'),
('3299', 'full planche', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'chest', 'triceps'], 'Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los dedos apuntando hacia adelante. Activa el core y desplaza lentamente el peso hacia adelante, levantando los pies del suelo. Continúa desplazando el peso hacia adelante hasta que el cuerpo quede paralelo al suelo, equilibrándote sobre las manos. Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta. Baja lentamente los pies de nuevo al suelo y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3299-YZ4961r.gif', '/exercises/images/3299-YZ4961r.jpg'),
('3327', 'full planche push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps', 'core'], 'Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Mientras te bajas, inclina el cuerpo hacia adelante y levanta los pies del suelo, equilibrándote sobre las manos. Continúa bajando el cuerpo hasta que el pecho quede justo por encima del suelo. Empuja con las manos y extiende los brazos para volver a subir el cuerpo a la posición inicial. Mantén una línea recta desde la cabeza hasta los talones durante todo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/3327-gw9PqGk.gif', '/exercises/images/3327-gw9PqGk.jpg'),
('0466', 'gironda sternum chin', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Ponte de pie frente a una barra alta con los pies separados a la altura de los hombros. Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los dorsales y los bíceps para llevar el pecho hacia la barra, guiando con el esternón. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0466-IL0JUxR.gif', '/exercises/images/0466-IL0JUxR.jpg'),
('3561', 'glute bridge march', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros. Manteniendo las caderas elevadas, levanta un pie del suelo y lleva la rodilla hacia el pecho. Baja el pie de nuevo al suelo y repite el movimiento con la otra pierna. Continúa alternando las piernas con un movimiento de marcha mientras mantienes la posición de puente. Repite el número de repeticiones deseado.', '/exercises/gifs/3561-GibBPPg.gif', '/exercises/images/3561-GibBPPg.jpg'),
('3523', 'glute bridge two legs on bench (male)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'core'], 'Siéntate en el borde de un banco con la espalda apoyada en él y los pies planos sobre el suelo. Coloca las manos en el banco junto a las caderas para mayor apoyo. Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3523-aWedzZX.gif', '/exercises/images/3523-aWedzZX.jpg'),
('3193', 'glute-ham raise', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes', 'lower back'], 'Ajusta la máquina de extensión de glúteos e isquiotibiales para que se adapte a tu cuerpo. Colócate boca abajo en la máquina con los tobillos asegurados. Coloca las manos sobre el pecho o crúzalas sobre el pecho. Activa los isquiotibiales y los glúteos para levantar la parte superior del cuerpo hacia el techo. Continúa levantando hasta que el cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3193-Vvwjz6N.gif', '/exercises/images/3193-Vvwjz6N.jpg'),
('0467', 'gorilla chin', 'Core', 'waist', 'body weight', 'abs', 'forearms', ARRAY['forearms', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra de dominadas con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y las palmas hacia afuera. Activa el core y tira del cuerpo hacia la barra, llevando la barbilla por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0467-bmwlYvD.gif', '/exercises/images/0467-bmwlYvD.jpg'),
('0469', 'groin crunch', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'inner thighs'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0469-mWppALS.gif', '/exercises/images/0469-mWppALS.jpg'),
('1383', 'hack calf raise', 'Pantorrilla', 'lower legs', 'sled machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta la máquina de trineo a un peso adecuado. Ponte de pie sobre la máquina de trineo con la punta de los pies en la plataforma y los talones colgando. Sujétate de las asas para mantener el equilibrio. Levanta los talones lo más alto posible empujando con la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1383-2ORFMoR.gif', '/exercises/images/1383-2ORFMoR.jpg'),
('1384', 'hack one leg calf raise', 'Pantorrilla', 'lower legs', 'sled machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta la máquina de trineo a un peso adecuado. Ponte de pie sobre la máquina de trineo con un pie, manteniendo el otro pie levantado del suelo. Sujétate de las asas para mantener el equilibrio. Levanta el talón lo más alto posible, elevando el cuerpo sobre la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de pierna y repite el ejercicio.', '/exercises/gifs/1384-AxFoqAD.gif', '/exercises/images/1384-AxFoqAD.jpg'),
('3221', 'half knee bends (male)', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros. Dobla las rodillas y baja el cuerpo como si te fueras a sentar en una silla. Mantén el pecho elevado y el peso en los talones. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3221-ia6kIIl.gif', '/exercises/images/3221-ia6kIIl.jpg'),
('3202', 'half sit-up (male)', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3202-iQ241UP.gif', '/exercises/images/3202-iQ241UP.jpg'),
('1511', 'hamstring stretch', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes'], 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho y traslada el peso hacia la pierna derecha. Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas, alcanzando el pie derecho con ambas manos. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite del otro lado.', '/exercises/gifs/1511-99rWm7w.gif', '/exercises/images/1511-99rWm7w.jpg'),
('2139', 'hands bike', 'Pecho', 'chest', 'upper body ergometer', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la altura del asiento y la posición del manillar a un nivel cómodo. Siéntate en el ergómetro con la espalda recta y los pies sobre los pedales. Sujeta las asas con las manos y coloca los brazos en un ángulo de 90 grados. Comienza a pedalear con las manos, empujando y tirando de las asas con un movimiento controlado. Continúa pedaleando durante el tiempo o el número de repeticiones deseado.', '/exercises/gifs/2139-pAIWRGu.gif', '/exercises/images/2139-pAIWRGu.jpg'),
('3218', 'hands clasped circular toe touch (male)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y las manos entrelazadas frente al pecho. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja las manos hacia los dedos de los pies con un movimiento circular, llegando tan lejos como puedas sin forzar. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3218-B5xca8s.gif', '/exercises/images/3218-B5xca8s.jpg'),
('3215', 'hands reversed clasped circular toe touch (male)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende las manos hacia abajo y entrelázalas detrás de las piernas. Sube lentamente las manos en un movimiento circular por encima de la cabeza, manteniendo las piernas rectas. Continúa el movimiento circular hasta que las manos toquen los dedos de los pies. Invierte el movimiento y regresa las manos a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3215-yq3GAJX.gif', '/exercises/images/3215-yq3GAJX.jpg'),
('3302', 'handstand', 'Brazo', 'upper arms', 'body weight', 'triceps', 'shoulders', ARRAY['shoulders', 'core'], 'Busca un espacio abierto con suficiente espacio para hacer un pino. Coloca las manos en el suelo separadas a la altura de los hombros, con los dedos apuntando hacia adelante. Lanza las piernas hacia la pared, usando el core y los hombros para mantener el equilibrio. Una vez en posición de pino, activa los tríceps para sostener el peso corporal. Mantén el pino el mayor tiempo posible mientras conserves el equilibrio. Para bajar, lleva lentamente las piernas de vuelta al suelo. Repite el número de repeticiones deseado.', '/exercises/gifs/3302-XooAdhl.gif', '/exercises/images/3302-XooAdhl.jpg'),
('0471', 'handstand push-up', 'Brazo', 'upper arms', 'body weight', 'triceps', 'shoulders', ARRAY['shoulders', 'chest', 'core'], 'Busca una pared y colócate de espaldas a ella, de pie a unos pasos de distancia. Coloca las manos en el suelo separadas a la altura de los hombros y lanza los pies hacia la pared, llegando a una posición de pino. Dobla los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo en línea recta. Empuja con las manos y extiende los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0471-rQxwMxO.gif', '/exercises/images/0471-rQxwMxO.jpg'),
('1764', 'hanging leg hip raise', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas flexionando las caderas y las rodillas hasta que los muslos queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1764-VEcJRo2.gif', '/exercises/images/1764-VEcJRo2.jpg'),
('1761', 'hanging oblique knee raise', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite hacia el otro lado, girando el torso en la dirección opuesta. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1761-BaE7O6U.gif', '/exercises/images/1761-BaE7O6U.jpg'),
('0473', 'hanging pike', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'shoulders'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas hacia la barra, manteniéndolas rectas. Continúa levantando hasta que el cuerpo forme una ''V'', con las piernas paralelas al suelo. Mantén la posición por un momento, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0473-nuBF9MO.gif', '/exercises/images/0473-nuBF9MO.jpg'),
('0474', 'hanging straight leg hip raise', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0474-pj0X0tF.gif', '/exercises/images/0474-pj0X0tF.jpg'),
('0475', 'hanging straight leg raise', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0475-4Ml7QFO.gif', '/exercises/images/0475-4Ml7QFO.jpg'),
('0476', 'hanging straight twisting leg hip raise', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas rectas. Activa el core y levanta las piernas hacia el pecho, manteniéndolas rectas. Cuando las piernas queden paralelas al suelo, gira las caderas hacia un lado, llevando las piernas hacia ese lado. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento, pero esta vez gira las caderas hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0476-Q6bvyen.gif', '/exercises/images/0476-Q6bvyen.jpg'),
('3636', 'high knee against wall', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves'], 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos en la pared para mayor apoyo. Activa el core y levanta la rodilla derecha hacia el pecho, mientras mantienes el pie izquierdo en el suelo. Cambia rápidamente de pierna, llevando la rodilla izquierda hacia el pecho y bajando el pie derecho de nuevo. Continúa alternando las piernas con un movimiento de carrera, llevando las rodillas lo más alto posible. Mantén un ritmo rápido y la parte superior del cuerpo estable durante todo el ejercicio. Repite durante la duración o el número de repeticiones deseado.', '/exercises/gifs/3636-ealLwvX.gif', '/exercises/images/3636-ealLwvX.jpg'),
('0484', 'hip raise (bent knee)', 'Core', 'waist', 'body weight', 'abs', 'glutes', ARRAY['glutes', 'hamstrings'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados, con las palmas hacia abajo. Activa el core y los glúteos, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0484-196HJGw.gif', '/exercises/images/0484-196HJGw.jpg'),
('1418', 'hug keens to chest', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Comienza de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Al ponerte en cuclillas, lleva las rodillas hacia el pecho y abrázalas con los brazos. Mantén esta posición por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1418-znP9SIh.gif', '/exercises/images/1418-znP9SIh.jpg'),
('3234', 'hyght dumbbell fly', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Manteniendo una ligera flexión en los codos, baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3234-P9ZRyLT.gif', '/exercises/images/3234-P9ZRyLT.jpg'),
('0489', 'hyperextension', 'Espalda', 'back', 'body weight', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Ajusta el banco de hiperextensiones para que la parte superior de los muslos quede apoyada en la almohadilla y los pies queden asegurados. Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza. Baja la parte superior del cuerpo hacia el suelo manteniendo la espalda recta. Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas. Repite el número de repeticiones deseado.', '/exercises/gifs/0489-zhMwOwE.gif', '/exercises/images/0489-zhMwOwE.jpg'),
('0488', 'hyperextension (on bench)', 'Espalda', 'back', 'body weight', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Ajusta el banco de hiperextensiones para que las caderas queden apoyadas cómodamente en la almohadilla y los pies queden asegurados. Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza. Baja lentamente la parte superior del cuerpo hacia el suelo manteniendo la espalda recta. Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas. Repite el número de repeticiones deseado.', '/exercises/gifs/0488-zkgRrbK.gif', '/exercises/images/0488-zkgRrbK.jpg'),
('3289', 'impossible dips', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire. Flexiona las rodillas y cruza los tobillos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/3289-05Cf2v8.gif', '/exercises/images/3289-05Cf2v8.jpg'),
('1471', 'inchworm', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'hamstrings'], 'Comienza de pie con los pies separados a la altura de las caderas. Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti. Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies. Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible. Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1471-ZgsNQ6d.gif', '/exercises/images/1471-ZgsNQ6d.jpg'),
('3698', 'inchworm v. 2', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'hamstrings'], 'Comienza de pie con los pies separados a la altura de las caderas. Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti. Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies. Manteniendo las piernas rectas, camina con los pies hacia las manos, llevando las caderas hacia el techo. Continúa caminando con las manos hacia adelante, repitiendo el movimiento durante el número de repeticiones deseado.', '/exercises/gifs/3698-TV87DNB.gif', '/exercises/images/3698-TV87DNB.jpg'),
('0490', 'incline close-grip push-up', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, con el cuerpo formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la superficie elevada doblando los codos, manteniéndolos cerca de los costados. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0490-1YB40kg.gif', '/exercises/images/0490-1YB40kg.jpg'),
('0491', 'incline leg hip raise (leg straight)', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate en un banco inclinado con la espalda apoyada plana en el banco y las piernas extendidas rectas frente a ti. Coloca las manos a los lados del banco para apoyarte. Activando el abdomen, levanta las piernas del banco, elevándolas tan alto como puedas mientras las mantienes rectas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0491-eVxAzgz.gif', '/exercises/images/0491-eVxAzgz.jpg'),
('0492', 'incline push up depth jump', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Busca una superficie elevada, como un banco o un escalón, y coloca las manos separadas a la altura de los hombros en el borde. Da un paso hacia atrás con los pies, manteniendo el cuerpo en línea recta desde la cabeza hasta los talones. Baja el pecho hacia el borde de la superficie, doblando los codos y manteniendo el cuerpo alineado. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Salta desde el borde de la superficie, aterrizando suavemente con las rodillas ligeramente flexionadas. Repite la flexión de brazos y el salto en profundidad durante el número de repeticiones deseado.', '/exercises/gifs/0492-CB8WET1.gif', '/exercises/images/0492-CB8WET1.jpg'),
('0493', 'incline push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0493-B1EVP9F.gif', '/exercises/images/0493-B1EVP9F.jpg'),
('3785', 'incline push-up (on box)', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Coloca las manos en el borde de una caja o una superficie elevada, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la caja doblando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/3785-F7vjXqT.gif', '/exercises/images/3785-F7vjXqT.jpg'),
('0494', 'incline reverse grip push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Coloca las manos en el borde de un banco o una superficie elevada, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia el banco doblando los codos, manteniéndolos cerca de los costados. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0494-XaaRnRn.gif', '/exercises/images/0494-XaaRnRn.jpg'),
('3011', 'incline scapula push up', 'Pecho', 'chest', 'body weight', 'serratus anterior', 'triceps', ARRAY['triceps', 'shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros. Coloca los pies en el suelo, separados a la altura de las caderas. Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo. Mientras bajas, retrae los omóplatos, apretándolos entre sí. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3011-GdMa1ET.gif', '/exercises/images/3011-GdMa1ET.jpg'),
('0495', 'incline twisting sit-up', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del banco, curvándote hacia adelante. Mientras te incorporas, gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el movimiento, esta vez girando el torso hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0495-9ZGZuOD.gif', '/exercises/images/0495-9ZGZuOD.jpg'),
('1564', 'intermediate hip flexor and quad stretch', 'Pierna', 'upper legs', 'rope', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Sujétate de un objeto estable para mayor apoyo. Dobla la rodilla derecha y lleva el pie derecho hacia los glúteos, sujetando la cuerda con la mano derecha. Tira lentamente del pie derecho hacia los glúteos, sintiendo un estiramiento en el cuádriceps derecho. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite en el lado izquierdo.', '/exercises/gifs/1564-tFGKm99.gif', '/exercises/images/1564-tFGKm99.jpg'),
('2400', 'inverse leg curl (on pull-up cable machine)', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes', 'calves'], 'Ajusta la máquina de cable para que las correas de tobillo estén en el ajuste más bajo. Túmbate boca abajo en el banco con las piernas extendidas y las correas de tobillo sujetas a los pies. Sujétate de las agarraderas del banco para mantener la estabilidad. Dobla las rodillas y curva las piernas hacia los glúteos, contrayendo los isquiotibiales. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2400-0rHfvy9.gif', '/exercises/images/2400-0rHfvy9.jpg'),
('0499', 'inverted row', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca una barra a la altura de la cintura o usa un entrenador de suspensión. Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros. Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros. Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo. Tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0499-bZGHsAZ.gif', '/exercises/images/0499-bZGHsAZ.jpg'),
('2300', 'inverted row bent knees', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca una barra a la altura de la cintura y túmbate debajo de ella. Agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Coloca el cuerpo de manera que los talones queden en el suelo y el cuerpo esté recto. Tira del pecho hacia arriba en dirección a la barra apretando los omóplatos entre sí. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2300-VPPtusI.gif', '/exercises/images/2300-VPPtusI.jpg'),
('2298', 'inverted row on bench', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca un banco a una altura que permita que el cuerpo cuelgue libremente debajo de él. Túmbate boca arriba en el suelo con la cabeza hacia el banco. Estira los brazos hacia arriba y agarra el banco con agarre prono, ligeramente más ancho que la altura de los hombros. Coloca el cuerpo de manera que los talones queden en el suelo y los brazos completamente extendidos. Activa el core y aprieta los omóplatos entre sí mientras tiras del pecho hacia el banco. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2298-Mxa7Cr8.gif', '/exercises/images/2298-Mxa7Cr8.jpg'),
('0497', 'inverted row v. 2', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca una barra a la altura de la cintura en una máquina Smith o usa un entrenador de suspensión. Ponte de pie frente a la barra o al entrenador de suspensión y agárrala con agarre prono, manos separadas a la altura de los hombros. Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en un ligero ángulo. Mantén el cuerpo recto y tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0497-uX3sUBz.gif', '/exercises/images/0497-uX3sUBz.jpg'),
('0498', 'inverted row with straps', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Coloca un entrenador de suspensión o correas a la altura del pecho. Ponte de pie frente al punto de anclaje y agarra las asas con agarre prono. Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en ángulo. Mantén el cuerpo recto y activa el core. Tira del pecho hacia las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0498-jdiExfW.gif', '/exercises/images/0498-jdiExfW.jpg'),
('1419', 'iron cross stretch', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Túmbate boca arriba con los brazos extendidos hacia los lados. Levanta las piernas hacia el techo, manteniéndolas rectas. Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies. Mantén el estiramiento durante unos segundos, luego regresa las piernas a la posición inicial. Repite el estiramiento en el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1419-pZwUsKB.gif', '/exercises/images/1419-pZwUsKB.jpg'),
('1297', 'isometric chest squeeze', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos rectos frente a ti, paralelos al suelo, con las palmas una frente a la otra. Aprieta los músculos del pecho con la mayor fuerza posible, manteniendo los brazos rectos. Mantén esta posición durante unos segundos, concentrándote en contraer los músculos del pecho. Suelta la contracción y relaja los músculos del pecho. Repite el número de repeticiones deseado.', '/exercises/gifs/1297-HbSG1Pw.gif', '/exercises/images/1297-HbSG1Pw.jpg'),
('0500', 'isometric wipers', 'Pecho', 'chest', 'body weight', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps', 'core'], 'Comienza acostado boca arriba en una esterilla o un banco. Extiende los brazos hacia los lados, perpendiculares al cuerpo. Activa el core y levanta ambas piernas del suelo, manteniéndolas juntas y rectas. Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies mientras mantienes el control. Haz una pausa breve, luego usa el core para llevar las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez bajando las piernas hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0500-11wrviz.gif', '/exercises/images/0500-11wrviz.jpg'),
('0501', 'jack burpee', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'shoulders', 'triceps', 'core'], 'Comienza de pie con los pies separados a la altura de los hombros. Baja el cuerpo a una posición de sentadilla, colocando las manos en el suelo frente a ti. Lanza los pies hacia atrás, aterrizando en posición de flexión de brazos. Realiza una flexión de brazos, bajando el pecho hacia el suelo y luego empujando de nuevo hacia arriba. Salta con los pies hacia adelante, aterrizando en posición de sentadilla. Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza. Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.', '/exercises/gifs/0501-mr7pkqP.gif', '/exercises/images/0501-mr7pkqP.jpg'),
('3224', 'jack jump (male)', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'calves'], 'Ponte de pie con los pies juntos y los brazos a los costados. Salta, separando los pies y levantando los brazos por encima de la cabeza. Al aterrizar, salta rápidamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3224-1g5bPpA.gif', '/exercises/images/3224-1g5bPpA.jpg'),
('0507', 'jackknife sit-up', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate boca arriba con las piernas extendidas y los brazos por encima de la cabeza. Activa el core y levanta las piernas y la parte superior del cuerpo al mismo tiempo, llevando las manos hacia los dedos de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0507-mbkgB44.gif', '/exercises/images/0507-mbkgB44.jpg'),
('0508', 'janda sit-up', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0508-1GPHRyK.gif', '/exercises/images/0508-1GPHRyK.jpg'),
('0514', 'jump squat', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta de forma explosiva desde el suelo, extendiendo las caderas, las rodillas y los tobillos. Mientras estás en el aire, lleva rápidamente los brazos hacia adelante para mantener el equilibrio. Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición. Repite el número de repeticiones deseado.', '/exercises/gifs/0514-LIlE5Tn.gif', '/exercises/images/0514-LIlE5Tn.jpg'),
('0513', 'jump squat v. 2', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta de forma explosiva, extendiendo por completo las caderas y las rodillas. Aterriza suavemente sobre la punta de los pies y de inmediato baja el cuerpo de nuevo a una posición de sentadilla. Repite el número de repeticiones deseado.', '/exercises/gifs/0513-TDYiji6.gif', '/exercises/images/0513-TDYiji6.jpg'),
('0517', 'kettlebell advanced windmill', 'Core', 'waist', 'kettlebell', 'abs', 'obliques', ARRAY['obliques', 'shoulders'], 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sostén una pesa rusa en la mano derecha, con el brazo extendido por encima de la cabeza y la palma hacia adelante. Gira el pie izquierdo ligeramente hacia la derecha y traslada el peso hacia la pierna izquierda. Dobla la rodilla izquierda y flexiona la cadera, bajando el torso hacia el lado izquierdo. Mantén el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa. Mientras bajas el torso, permite que la pierna derecha se enderece y que el pie derecho gire ligeramente. Baja el torso hasta sentir un estiramiento en el isquiotibial izquierdo y que el brazo derecho apunte hacia el suelo. Haz una pausa breve, luego activa el core y empuja con el talón izquierdo para regresar a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0517-Kal9cQQ.gif', '/exercises/images/0517-Kal9cQQ.jpg'),
('0518', 'kettlebell alternating hang clean', 'Antebrazo', 'lower arms', 'kettlebell', 'forearms', 'shoulders', ARRAY['shoulders', 'traps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen frente al cuerpo con los brazos completamente extendidos. En un solo movimiento fluido, extiende las caderas de forma explosiva, encoge los hombros y tira de las pesas rusas hacia los hombros. Cuando las pesas rusas alcancen la altura de los hombros, gira las muñecas y atrápalas en posición de descanso, con las palmas hacia adentro y las pesas rusas apoyadas en la parte externa de los antebrazos. Baja las pesas rusas de nuevo a la posición inicial y repite el movimiento con el brazo opuesto. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/0518-I4tibZG.gif', '/exercises/images/0518-I4tibZG.jpg'),
('0520', 'kettlebell alternating press', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Empuja una pesa rusa por encima de la cabeza, extendiendo el brazo por completo. Baja la pesa rusa de nuevo a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/0520-5KLbZWx.gif', '/exercises/images/0520-5KLbZWx.jpg'),
('0519', 'kettlebell alternating press on floor', 'Pecho', 'chest', 'kettlebell', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo. Sostén una pesa rusa en cada mano, con las palmas hacia los pies y los brazos extendidos rectos hacia el techo. Baja una pesa rusa hacia el hombro mientras mantienes la otra pesa rusa extendida recta hacia arriba. Empuja la pesa rusa bajada de vuelta hacia la posición inicial mientras al mismo tiempo bajas la otra pesa rusa hacia el hombro. Continúa alternando el movimiento de empuje con cada pesa rusa durante el número de repeticiones deseado.', '/exercises/gifs/0519-7w6i0vE.gif', '/exercises/images/0519-7w6i0vE.jpg'),
('0521', 'kettlebell alternating renegade row', 'Espalda', 'back', 'kettlebell', 'upper back', 'core', ARRAY['core', 'shoulders'], 'Comienza en posición de plancha alta con las manos sujetando las pesas rusas y los pies separados a la altura de las caderas. Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones. Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo. Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/0521-b9kqlBy.gif', '/exercises/images/0521-b9kqlBy.jpg'),
('0522', 'kettlebell alternating row', 'Espalda', 'back', 'kettlebell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y apretando los omóplatos entre sí. Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', '/exercises/gifs/0522-Ca76jUE.gif', '/exercises/images/0522-Ca76jUE.jpg'),
('0523', 'kettlebell arnold press', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros con las palmas hacia ti. Activa el core y empuja las pesas rusas por encima de la cabeza, girando las palmas hacia adelante mientras extiendes los brazos. Haz una pausa en la parte superior del movimiento, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0523-UM8mgyG.gif', '/exercises/images/0523-UM8mgyG.jpg'),
('0524', 'kettlebell bent press', 'Core', 'waist', 'kettlebell', 'abs', 'shoulders', ARRAY['shoulders', 'triceps', 'obliques'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha. Dobla ligeramente las rodillas y empuja la pesa rusa por encima de la cabeza con el brazo derecho, manteniendo el codo bloqueado. Rota el torso hacia la izquierda, trasladando tu peso al pie izquierdo. Flexiona la rodilla izquierda y baja el torso hacia el suelo, manteniendo el brazo derecho extendido por encima de la cabeza. Mientras bajas, mantén la mirada en la pesa rusa y el pecho elevado. Cuando tu mano izquierda toque el suelo, empuja con el pie izquierdo y estira la pierna izquierda, llevando las caderas hacia adelante. Mientras llevas las caderas hacia adelante, usa el core y el brazo derecho para empujar la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0524-kjE55n5.gif', '/exercises/images/0524-kjE55n5.jpg'),
('0525', 'kettlebell bottoms up clean from the hang position', 'Brazo', 'upper arms', 'kettlebell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido. En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras tiras de la pesa rusa hacia el hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca de modo que la base de la pesa rusa quede hacia arriba. Atrapa la pesa rusa a la altura del hombro con el codo flexionado y la palma hacia arriba. Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0525-4KJEpzb.gif', '/exercises/images/0525-4KJEpzb.jpg'),
('0526', 'kettlebell double alternating hang clean', 'Brazo', 'upper arms', 'kettlebell', 'biceps', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen rectas frente a tu cuerpo. En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras encoges los hombros. Mientras las pesas rusas suben, tira de ellas hacia los hombros, manteniendo los codos altos y hacia los lados. Atrapa las pesas rusas a la altura del hombro, con las palmas hacia adentro y los codos apuntando hacia adelante. Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0526-a4F9Oyc.gif', '/exercises/images/0526-a4F9Oyc.jpg'),
('0527', 'kettlebell double jerk', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Flexiona ligeramente las rodillas y activa el core. Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Flexiona las rodillas y baja rápidamente a una sentadilla parcial. Extiende explosivamente las caderas y las rodillas, impulsando las pesas rusas hacia arriba. Bloquea los brazos y atrapa las pesas rusas por encima de la cabeza con las rodillas ligeramente flexionadas. Ponte de pie recto y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0527-tznL2Ad.gif', '/exercises/images/0527-tznL2Ad.jpg'),
('0528', 'kettlebell double push press', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Inicia el movimiento extendiendo explosivamente las caderas, las rodillas y los tobillos, impulsando las pesas rusas por encima de la cabeza. Cuando las pesas rusas lleguen arriba, presiónalas completamente por encima de la cabeza, bloqueando los brazos. Baja las pesas rusas a la posición inicial flexionando los codos y llevándolas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', '/exercises/gifs/0528-I4KkPdl.gif', '/exercises/images/0528-I4KkPdl.jpg'),
('0529', 'kettlebell double snatch', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'trapezius', ARRAY['trapezius', 'forearms', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano con el brazo extendido frente a los muslos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. En un solo movimiento explosivo, extiende las caderas, las rodillas y los tobillos, y al mismo tiempo tira de las pesas rusas hacia los hombros. Cuando las pesas rusas lleguen a la altura del hombro, rota las muñecas y lanza las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0529-M74kdvm.gif', '/exercises/images/0529-M74kdvm.jpg'),
('0530', 'kettlebell double windmill', 'Core', 'waist', 'kettlebell', 'abs', 'shoulders', ARRAY['shoulders', 'hamstrings'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha. Extiende el brazo derecho por encima de la cabeza, manteniendo la mirada en la pesa rusa. Rota el pie izquierdo 45 grados hacia la izquierda y el pie derecho 90 grados hacia la derecha. Flexiona la cintura hacia la izquierda, manteniendo el brazo derecho extendido por encima de la cabeza. Baja la pesa rusa hacia el suelo, extendiéndote hacia el pie izquierdo. Haz una pausa breve, luego activa el core y empuja con el pie derecho para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0530-OaE7CpD.gif', '/exercises/images/0530-OaE7CpD.jpg'),
('0531', 'kettlebell extended range one arm press on floor', 'Pecho', 'chest', 'kettlebell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo. Sujeta una pesa rusa con una mano, con la palma hacia los pies. Extiende el brazo recto hacia el techo, manteniendo el codo bloqueado y la muñeca recta. Baja lentamente la pesa rusa de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0531-rseLfH3.gif', '/exercises/images/0531-rseLfH3.jpg'),
('0532', 'kettlebell figure 8', 'Core', 'waist', 'kettlebell', 'abs', 'shoulders', ARRAY['shoulders', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Pasa la pesa rusa entre las piernas, cambiándola de mano cuando llegue detrás de las piernas. Cuando la pesa rusa vuelva hacia adelante, pásala a la otra mano entre las piernas. Continúa pasando la pesa rusa entre las piernas con un movimiento en forma de ocho. Mantén un ritmo constante y activa el core durante todo el ejercicio. Repite el número de repeticiones deseado.', '/exercises/gifs/0532-L4ay0PW.gif', '/exercises/images/0532-L4ay0PW.jpg'),
('0533', 'kettlebell front squat', 'Pierna', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la pesa rusa con ambas manos frente al pecho, cerca del cuerpo. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta. Repite el número de repeticiones deseado.', '/exercises/gifs/0533-DB0n8AG.gif', '/exercises/images/0533-DB0n8AG.jpg'),
('0534', 'kettlebell goblet squat', 'Pierna', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa cerca del pecho con ambas manos. Manteniendo el pecho elevado y el core activado, baja el cuerpo a una posición de sentadilla flexionando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0534-ZA8b5hc.gif', '/exercises/images/0534-ZA8b5hc.jpg'),
('0535', 'kettlebell hang clean', 'Pierna', 'upper legs', 'kettlebell', 'hamstrings', 'glutes', ARRAY['glutes', 'quadriceps', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas. Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro. Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo. Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado.', '/exercises/gifs/0535-LHWF7us.gif', '/exercises/images/0535-LHWF7us.jpg'),
('0536', 'kettlebell lunge pass through', 'Pierna', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mientras avanzas en la zancada, pasa la pesa rusa por debajo del muslo derecho y trasládala a la mano izquierda. Empuja con el pie derecho para volver a la posición inicial, mientras pasas la pesa rusa de vuelta a la mano derecha al mismo tiempo. Repite la zancada en el lado opuesto, pasando la pesa rusa por debajo del muslo izquierdo. Continúa alternando zancadas y pasando la pesa rusa entre las manos durante el número de repeticiones deseado.', '/exercises/gifs/0536-WKMQzCD.gif', '/exercises/images/0536-WKMQzCD.jpg'),
('0537', 'kettlebell one arm clean and jerk', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas y inclínate desde las caderas, bajando la pesa rusa entre las piernas. Extiende explosivamente las caderas, las rodillas y los tobillos, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca y lanza la mano recta hacia arriba, bloqueando el brazo por encima de la cabeza. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0537-vzAxBtt.gif', '/exercises/images/0537-vzAxBtt.jpg'),
('1298', 'kettlebell one arm floor press', 'Pecho', 'chest', 'kettlebell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la pesa rusa con una mano con la palma hacia los pies y el brazo extendido recto hacia el techo. Baja lentamente la pesa rusa hacia el pecho flexionando el codo, manteniendo el brazo superior cerca del cuerpo. Haz una pausa cuando la pesa rusa esté justo encima del pecho, luego empújala de vuelta hacia arriba a la posición inicial extendiendo el codo. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1298-rg59QCH.gif', '/exercises/images/1298-rg59QCH.jpg'),
('0538', 'kettlebell one arm jerk', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Presiona la pesa rusa por encima de la cabeza en línea recta, extendiendo el brazo por completo. Mientras presionas la pesa rusa por encima de la cabeza, flexiona las rodillas simultáneamente y estíralas rápidamente para generar impulso. Cuando la pesa rusa llegue a su punto más alto, baja rápidamente por debajo de ella flexionando las rodillas y las caderas. Atrapa la pesa rusa con una ligera flexión de rodillas y caderas, y el brazo completamente extendido por encima de la cabeza. Ponte de pie recto, extendiendo por completo las rodillas y las caderas, y estabiliza la pesa rusa por encima de la cabeza. Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y las caderas, y repite el número de repeticiones deseado.', '/exercises/gifs/0538-S37C94C.gif', '/exercises/images/0538-S37C94C.jpg'),
('0539', 'kettlebell one arm military press to the side', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Activa el core y mantén la espalda recta. Presiona la pesa rusa por encima de la cabeza, extendiendo el brazo por completo. Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0539-yCvYdi7.gif', '/exercises/images/0539-yCvYdi7.jpg'),
('0540', 'kettlebell one arm push press', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Presiona la pesa rusa por encima de la cabeza extendiendo el brazo y estirando por completo las piernas. Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y devolviendo la pesa rusa al hombro. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0540-osdXT3K.gif', '/exercises/images/0540-osdXT3K.jpg'),
('0541', 'kettlebell one arm row', 'Espalda', 'back', 'kettlebell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.', '/exercises/gifs/0541-g9AsZ8P.gif', '/exercises/images/0541-g9AsZ8P.jpg'),
('0542', 'kettlebell one arm snatch', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'trapezius', ARRAY['trapezius', 'forearms', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano entre las piernas. Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo. Extiende explosivamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hacia el hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la mano y lánzala recta hacia arriba por encima de la cabeza, extendiendo el brazo por completo. Baja la pesa rusa de vuelta entre las piernas y repite el número de repeticiones deseado.', '/exercises/gifs/0542-aXcUyKb.gif', '/exercises/images/0542-aXcUyKb.jpg'),
('0543', 'kettlebell pirate supper legs', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta la pesa rusa hasta la altura del hombro, manteniendo el codo cerca del cuerpo. Extiende el brazo por completo por encima de la cabeza, enderezando el codo. Baja la pesa rusa de vuelta a la altura del hombro, luego vuelve a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0543-kuXhl0o.gif', '/exercises/images/0543-kuXhl0o.jpg'),
('0544', 'kettlebell pistol squat', 'Pierna', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos. Levanta el pie izquierdo del suelo y extiéndelo hacia adelante, manteniéndolo paralelo al suelo. Baja lentamente el cuerpo a una posición de sentadilla, manteniendo el pie derecho plano en el suelo y la pierna izquierda extendida. Haz una pausa breve en la parte baja de la sentadilla, luego empuja con el talón derecho para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0544-5bpPTHv.gif', '/exercises/images/0544-5bpPTHv.jpg'),
('0545', 'kettlebell plyo push-up', 'Pecho', 'chest', 'kettlebell', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Comienza en una posición de plancha alta con las manos sobre las pesas rusas, separadas a la altura de los hombros. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Empuja con las manos de forma explosiva, levantándolas de las pesas rusas y extendiendo los brazos por completo. Aterriza suavemente sobre las pesas rusas y baja el pecho de inmediato para la siguiente repetición. Repite el número de repeticiones deseado.', '/exercises/gifs/0545-ktf3nvW.gif', '/exercises/images/0545-ktf3nvW.jpg'),
('0546', 'kettlebell seated press', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una pesa rusa en cada mano a la altura del hombro, con las palmas hacia adelante. Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Baja las pesas rusas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', '/exercises/gifs/0546-BkxB8LW.gif', '/exercises/images/0546-BkxB8LW.jpg'),
('1438', 'kettlebell seated two arm military press', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante. Presiona las pesas rusas por encima de la cabeza extendiendo los brazos por completo. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', '/exercises/gifs/1438-ZEkjZDi.gif', '/exercises/images/1438-ZEkjZDi.jpg'),
('0547', 'kettlebell seesaw press', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Presiona una pesa rusa por encima de la cabeza mientras mantienes la otra pesa rusa a la altura del hombro. Baja la pesa rusa presionada de vuelta a la altura del hombro mientras presionas simultáneamente la otra pesa rusa por encima de la cabeza. Continúa alternando el movimiento de presión, creando un movimiento similar a un balancín. Repite el número de repeticiones deseado.', '/exercises/gifs/0547-UDm6cGl.gif', '/exercises/images/0547-UDm6cGl.jpg'),
('0548', 'kettlebell sumo high pull', 'Espalda', 'back', 'kettlebell', 'traps', 'shoulders', ARRAY['shoulders', 'glutes', 'hamstrings'], 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Sujeta una pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos hacia abajo. Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta. Empuja con los talones y extiende explosivamente las caderas y las rodillas, tirando de la pesa rusa hacia la barbilla. Mientras tiras de la pesa rusa hacia arriba, mantén los codos altos y abiertos, y junta los omóplatos. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0548-8ARQ9Hw.gif', '/exercises/images/0548-8ARQ9Hw.jpg'),
('0549', 'kettlebell swing', 'Pierna', 'upper legs', 'kettlebell', 'glutes', 'hamstrings', ARRAY['hamstrings', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos. Flexiona ligeramente las rodillas e inclínate desde las caderas, empujando los glúteos hacia atrás. Lleva la pesa rusa hacia atrás entre las piernas, manteniendo los brazos rectos y la espalda plana. Lleva las caderas hacia adelante y haz que la pesa rusa suba hasta la altura del hombro, usando el impulso generado por las caderas. Deja que la pesa rusa se balancee de vuelta hacia abajo entre las piernas y repite el movimiento el número de repeticiones deseado.', '/exercises/gifs/0549-UHJlbu3.gif', '/exercises/images/0549-UHJlbu3.jpg'),
('0550', 'kettlebell thruster', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'quadriceps', ARRAY['quadriceps', 'glutes', 'core'], 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos, con las palmas una frente a la otra. Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás, manteniendo el pecho elevado y la espalda recta. Al llegar a la parte baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando al mismo tiempo la pesa rusa por encima de la cabeza. Bloquea los brazos en la parte alta del movimiento, extendiendo los codos por completo. Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento, flexionando los codos y bajando el peso de vuelta al pecho. Repite el número de repeticiones deseado.', '/exercises/gifs/0550-yWxMvB5.gif', '/exercises/images/0550-yWxMvB5.jpg'),
('0551', 'kettlebell turkish get up (squat style)', 'Pierna', 'upper legs', 'kettlebell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'core'], 'Comienza tumbado boca arriba con las piernas extendidas y la pesa rusa sostenida en la mano derecha, con el brazo completamente extendido por encima del hombro. Flexiona la rodilla derecha y coloca el pie derecho plano en el suelo, manteniendo la pierna izquierda extendida. Presionando con el pie derecho, levanta las caderas del suelo, llegando a una posición de puente. Desliza la pierna izquierda por debajo del cuerpo, flexionando la rodilla izquierda y colocando el pie izquierdo plano en el suelo. Rota el torso hacia la izquierda, llevando la mano izquierda al suelo como apoyo. Presionando con el pie derecho y la mano izquierda, levanta el torso del suelo, llegando a una posición de rodillas. Desde la posición de rodillas, ponte de pie, manteniendo la pesa rusa extendida por encima de la cabeza. Invierte el movimiento para volver a la posición inicial. Repite el ejercicio en el otro lado, comenzando con la pesa rusa en la mano izquierda.', '/exercises/gifs/0551-Ha7SZ3y.gif', '/exercises/images/0551-Ha7SZ3y.jpg'),
('0552', 'kettlebell two arm clean', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'traps', ARRAY['traps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos con ambas manos, con las palmas hacia ti. Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo. Extiende explosivamente las caderas y las rodillas, usando el impulso para tirar de la pesa rusa hacia los hombros. Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con los codos pegados al cuerpo y la pesa rusa apoyada en la parte posterior del antebrazo. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0552-7Ba7bQ2.gif', '/exercises/images/0552-7Ba7bQ2.jpg'),
('0553', 'kettlebell two arm military press', 'Hombro', 'shoulders', 'kettlebell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante. Activa el core y presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0553-blBXysN.gif', '/exercises/images/0553-blBXysN.jpg'),
('1345', 'kettlebell two arm row', 'Espalda', 'back', 'kettlebell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de las pesas rusas hacia el pecho, juntando los omóplatos. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1345-wf24o8S.gif', '/exercises/images/1345-wf24o8S.jpg'),
('0554', 'kettlebell windmill', 'Core', 'waist', 'kettlebell', 'abs', 'obliques', ARRAY['obliques', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en la mano derecha por encima de la cabeza. Rota el pie izquierdo hacia afuera unos 45 grados y mantén el pie derecho apuntando hacia adelante. Inclina el torso hacia el lado izquierdo, manteniendo el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa. Baja el torso tanto como puedas mientras mantienes el brazo derecho recto y el brazo izquierdo extendido hacia el lado. Haz una pausa breve, luego vuelve a la posición inicial empujando con el pie derecho y activando los oblicuos. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0554-9Tkqa9O.gif', '/exercises/images/0554-9Tkqa9O.jpg'),
('0555', 'kick out sit', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'quadriceps', ARRAY['quadriceps', 'glutes'], 'Siéntate en el borde de un banco o una silla con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Inclínate ligeramente hacia atrás y coloca las manos en el borde del banco o la silla como apoyo. Activando los isquiotibiales, levanta los pies del suelo y extiende las piernas rectas hacia adelante. Haz una pausa breve en lo alto, luego flexiona lentamente las rodillas y lleva los pies de vuelta hacia el cuerpo. Repite el número de repeticiones deseado.', '/exercises/gifs/0555-v7p5bYl.gif', '/exercises/images/0555-v7p5bYl.jpg'),
('0558', 'kipping muscle up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'triceps', 'shoulders', 'core'], 'Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Activa el core y usa un movimiento de balanceo para generar impulso. Mientras te balanceas hacia adelante, tira del pecho hacia la barra, usando los dorsales y los bíceps para iniciar el movimiento. Continúa el movimiento ascendente hasta que el pecho llegue a la barra, luego pasa a una posición de fondos empujando hacia abajo en la barra y extendiendo los brazos. Bájate de vuelta a la posición inicial flexionando los brazos y controlando el descenso. Repite el número de repeticiones deseado.', '/exercises/gifs/0558-pM07UxU.gif', '/exercises/images/0558-pM07UxU.jpg'),
('3640', 'knee touch crunch', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta los omóplatos del suelo y extiende la mano derecha hacia la rodilla izquierda. Vuelve a la posición inicial y repite, esta vez extendiendo la mano izquierda hacia la rodilla derecha. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/3640-dTg95eZ.gif', '/exercises/images/3640-dTg95eZ.jpg'),
('1420', 'kneeling jump squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Comienza arrodillado en el suelo con los pies separados a la altura de las caderas y los dedos de los pies apuntando hacia adelante. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros. Activa el core y los glúteos, luego salta explosivamente hacia arriba, extendiendo las caderas y las rodillas. Mientras saltas, empuja con los dedos de los pies y extiende por completo los tobillos, las rodillas y las caderas. Aterriza suavemente de vuelta en el suelo, flexionando las rodillas para absorber el impacto. Pasa de inmediato a la siguiente repetición, repitiendo el movimiento de sentadilla con salto.', '/exercises/gifs/1420-UgDm3oy.gif', '/exercises/images/1420-UgDm3oy.jpg'),
('1346', 'kneeling lat stretch', 'Espalda', 'back', 'body weight', 'lats', 'shoulders', ARRAY['shoulders', 'triceps'], 'Arrodíllate en el suelo con las rodillas separadas a la altura de las caderas y los dedos de los pies apuntando hacia atrás. Extiende los brazos por encima de la cabeza y entrelaza los dedos. Manteniendo la espalda recta, inclínate lentamente hacia el lado derecho, sintiendo un estiramiento en el dorsal izquierdo. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite el estiramiento en el lado izquierdo, inclinándote hacia la izquierda y sintiendo un estiramiento en el dorsal derecho. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1346-f38OEuO.gif', '/exercises/images/1346-f38OEuO.jpg'),
('3239', 'kneeling plank tap shoulder (male)', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'triceps'], 'Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros. Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha. Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto. Devuelve la mano al suelo y repite con la otra mano. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/3239-h1ezqSu.gif', '/exercises/images/3239-h1ezqSu.jpg'),
('3211', 'kneeling push-up (male)', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza arrodillado en el suelo con las manos separadas a la altura de los hombros, los dedos apuntando hacia adelante. Extiende las piernas hacia atrás, apoyándote en la punta de los pies, de modo que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Continúa bajando hasta que el pecho esté justo encima del suelo, luego empuja hacia arriba a la posición inicial enderezando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/3211-ZOuKWir.gif', '/exercises/images/3211-ZOuKWir.jpg'),
('3288', 'korean dips', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Colócate entre dos barras paralelas con los brazos extendidos sosteniendo el peso de tu cuerpo. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/3288-rWoBmi5.gif', '/exercises/images/3288-rWoBmi5.jpg'),
('3418', 'l-pull-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate con los brazos completamente extendidos y el cuerpo recto. Activa los dorsales y los bíceps para llevar el cuerpo hacia arriba en dirección a la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3418-d1GgzTU.gif', '/exercises/images/3418-d1GgzTU.jpg'),
('3419', 'l-sit on floor', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Coloca las manos en el suelo junto a las caderas, con los dedos apuntando hacia adelante. Activa el core y levanta las piernas del suelo, manteniéndolas rectas. Intenta llevar las piernas paralelas al suelo, formando una ''L'' con el cuerpo. Mantén esta posición durante el mayor tiempo posible. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3419-UpWmA5E.gif', '/exercises/images/3419-UpWmA5E.jpg'),
('0562', 'landmine 180', 'Core', 'waist', 'barbell', 'abs', 'obliques', ARRAY['obliques', 'quadriceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente al pecho. Flexiona ligeramente las rodillas y rota el torso hacia la derecha, llevando la barra hacia la cadera derecha. Cuando llegues a la parte baja del movimiento, invierte rápidamente el movimiento y rota el torso hacia la izquierda, llevando la barra hacia arriba y a través del cuerpo en dirección al hombro izquierdo. Continúa este movimiento de giro, alternando lados, durante el número de repeticiones deseado.', '/exercises/gifs/0562-QYysSLV.gif', '/exercises/images/0562-QYysSLV.jpg'),
('3237', 'landmine lateral raise', 'Hombro', 'shoulders', 'barbell', 'delts', 'traps', ARRAY['traps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con un agarre prono, apoyándola en la parte delantera de los hombros. Manteniendo el core activado y la espalda recta, levanta la barra alejándola del cuerpo, elevándola hasta la altura del hombro. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3237-eXMFHww.gif', '/exercises/images/3237-eXMFHww.jpg'),
('3300', 'lean planche', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'chest', 'triceps'], 'Comienza en una posición de flexión con las manos separadas a la altura de los hombros y el cuerpo recto. Activa el core y traslada lentamente el peso hacia adelante, llevando los hombros más allá de las manos. Mantén los codos ligeramente flexionados y el cuerpo recto mientras te inclinas hacia adelante. Mantén esta posición durante unos segundos, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3300-LYJodFS.gif', '/exercises/images/3300-LYJodFS.jpg'),
('2271', 'left hook. boxing', 'Hombro', 'shoulders', 'body weight', 'delts', 'biceps', ARRAY['biceps', 'triceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla. Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe. Gira el torso y activa los músculos del core para generar potencia en el golpe. Lleva el brazo rápidamente de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/2271-hoXt6wv.gif', '/exercises/images/2271-hoXt6wv.jpg'),
('0570', 'leg pull in flat bench', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Siéntate en un banco plano con las piernas extendidas rectas hacia adelante. Coloca las manos en el banco junto a las caderas para mayor apoyo. Activa el abdomen y levanta las piernas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0570-OyoZ3Pu.gif', '/exercises/images/0570-OyoZ3Pu.jpg'),
('1576', 'leg up hamstring stretch', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes'], 'Túmbate boca arriba con las piernas extendidas. Flexiona una rodilla y llévala hacia el pecho, sujetándote del muslo o la espinilla. Endereza la pierna tanto como sea posible mientras la mantienes elevada. Mantén el estiramiento durante 20-30 segundos. Repite con la otra pierna.', '/exercises/gifs/1576-sU5BrfP.gif', '/exercises/images/1576-sU5BrfP.jpg'),
('2287', 'lever alternate leg press', 'Pierna', 'upper legs', 'leverage machine', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta el asiento y la plataforma para los pies de la máquina de palanca a la posición deseada. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma para los pies. Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad. Empuja un pie contra la plataforma para los pies, extendiendo la pierna hasta que esté casi completamente recta. Haz una pausa breve, luego flexiona lentamente la pierna y vuelve a la posición inicial. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/2287-V07qpXy.gif', '/exercises/images/2287-V07qpXy.jpg'),
('0571', 'lever alternating narrow grip seated row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta. Siéntate en la máquina con la espalda recta y los pies planos sobre la placa para los pies. Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra. Mantén el pecho elevado y los hombros hacia atrás durante todo el ejercicio. Tira de una asa hacia el torso mientras mantienes la otra asa inmóvil. Aprieta los omóplatos al final del movimiento. Devuelve lentamente el asa a la posición inicial y repite con el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0571-w2oRpuH.gif', '/exercises/images/0571-w2oRpuH.jpg'),
('0572', 'lever assisted chin-up', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la máquina de palanca al nivel de resistencia deseado. Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Cuélgate con los brazos completamente extendidos, manteniendo el cuerpo recto. Activa los músculos de la espalda y tira del cuerpo hacia arriba en dirección a las asas, liderando con el pecho. Continúa subiendo hasta que la barbilla quede por encima de las agarraderas. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0572-MaMuGH6.gif', '/exercises/images/0572-MaMuGH6.jpg'),
('0573', 'lever back extension', 'Espalda', 'back', 'leverage machine', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Ajusta la máquina según el tamaño de tu cuerpo y tu rango de movimiento. Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies asegurados. Coloca las manos en las asas o en las barras de agarre. Activa el core e inclínate lentamente hacia adelante, permitiendo que la espalda se redondee ligeramente. Haz una pausa breve en la posición baja, sintiendo un estiramiento en la zona lumbar. Usando los músculos de la espalda, levanta lentamente el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0573-rUXfn3R.gif', '/exercises/images/0573-rUXfn3R.jpg'),
('0574', 'lever bent over row', 'Espalda', 'back', 'barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado. Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0574-X3cqyXz.gif', '/exercises/images/0574-X3cqyXz.jpg'),
('3200', 'lever bent-over row with v-bar', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y colócate frente a la máquina. Sujeta la barra en V con un agarre prono, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Tira de la barra en V hacia el abdomen, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3200-LuBEORI.gif', '/exercises/images/3200-LuBEORI.jpg'),
('0575', 'lever bicep curl', 'Brazo', 'upper arms', 'leverage machine', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Sujeta las asas con un agarre supino, con las palmas hacia arriba, y mantén los codos cerca de los costados. Exhala y flexiona las asas hacia arriba, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0575-q6y3OhV.gif', '/exercises/images/0575-q6y3OhV.jpg'),
('2289', 'lever calf press', 'Pantorrilla', 'lower legs', 'leverage machine', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Ajusta el asiento de la máquina de palanca de modo que los hombros queden alineados con la almohadilla de la palanca. Coloca los dedos de los pies sobre la almohadilla de la palanca, con los talones colgando fuera del borde. Sujeta las asas o los soportes laterales para mayor estabilidad. Empuja la almohadilla de la palanca hacia abajo extendiendo los tobillos, contrayendo los músculos de las pantorrillas. Haz una pausa por un momento en la parte baja del movimiento. Vuelve lentamente a la posición inicial dejando que los talones se eleven de nuevo. Repite el número de repeticiones deseado.', '/exercises/gifs/2289-7B4F5nZ.gif', '/exercises/images/2289-7B4F5nZ.jpg'),
('0577', 'lever chest press', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla. Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento. Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces. Repite el número de repeticiones deseado.', '/exercises/gifs/0577-T0yTjgW.gif', '/exercises/images/0577-T0yTjgW.jpg'),
('0576', 'lever chest press', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla. Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento. Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces. Repite el número de repeticiones deseado.', '/exercises/gifs/0576-DOoWcnA.gif', '/exercises/images/0576-DOoWcnA.jpg'),
('0578', 'lever deadlift', 'Pierna', 'upper legs', 'leverage machine', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Ajusta la altura del asiento y la plataforma para los pies a la posición deseada. Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies planos sobre la plataforma para los pies. Sujeta las asas o los lados del asiento para mayor estabilidad. Activa los glúteos y los isquiotibiales, y empuja con los talones para levantar el peso. Mantén la espalda recta y evita redondear los hombros. Extiende por completo las caderas en la parte alta del movimiento, apretando los glúteos. Baja el peso de manera controlada, manteniendo la tensión en los glúteos y los isquiotibiales. Repite el número de repeticiones deseado.', '/exercises/gifs/0578-GUT8I22.gif', '/exercises/images/0578-GUT8I22.jpg'),
('1300', 'lever decline chest press', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos. Baja lentamente las asas de vuelta hacia el pecho, manteniendo los codos ligeramente flexionados. Haz una pausa breve en la parte baja, luego empuja las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1300-vsVoPHt.gif', '/exercises/images/1300-vsVoPHt.jpg'),
('1253', 'lever donkey calf raise', 'Pantorrilla', 'lower legs', 'leverage machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta la máquina de palanca a la altura adecuada para tu cuerpo. Colócate de frente a la máquina, con los dedos de los pies en la plataforma y los talones colgando fuera del borde. Coloca las manos en las asas o en las barras de soporte para mayor estabilidad. Activa las pantorrillas y levanta los talones tan alto como sea posible, usando la parte delantera de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1253-C9LuR4A.gif', '/exercises/images/1253-C9LuR4A.jpg'),
('0579', 'lever front pulldown', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Siéntate erguido con el pecho elevado y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar. Activa los dorsales y tira de las asas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0579-7F1DVzn.gif', '/exercises/images/0579-7F1DVzn.jpg'),
('0580', 'lever gripless shrug', 'Espalda', 'back', 'leverage machine', 'traps', 'shoulders', ARRAY['shoulders', 'forearms'], 'Ajusta la altura del asiento y colócate en la máquina de palanca. Sujeta las asas con las palmas hacia adentro y los brazos completamente extendidos. Manteniendo la espalda recta, exhala y eleva los hombros tan alto como sea posible. Mantén la contracción por un momento breve, luego inhala y baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0580-f91FwXG.gif', '/exercises/images/0580-f91FwXG.jpg'),
('1439', 'lever gripless shrug v. 2', 'Espalda', 'back', 'leverage machine', 'traps', 'shoulders', ARRAY['shoulders', 'forearms'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Sujeta las asas o barras con un agarre prono, manteniendo los brazos rectos. Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1439-cbuFJrn.gif', '/exercises/images/1439-cbuFJrn.jpg'),
('2288', 'lever gripper hands', 'Antebrazo', 'lower arms', 'leverage machine', 'forearms', 'biceps', ARRAY['biceps', 'triceps'], 'Ajusta la altura del asiento y sujeta las asas de la máquina de palanca. Mantén la espalda recta y los pies planos en el suelo. Exhala y aprieta las asas, contrayendo los antebrazos. Mantén la contracción durante un segundo, luego suelta lentamente y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2288-mKwcrHn.gif', '/exercises/images/2288-mKwcrHn.jpg'),
('1615', 'lever hammer grip preacher curl', 'Brazo', 'upper arms', 'leverage machine', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la altura del asiento y colócate en la máquina de palanca. Coloca los brazos superiores sobre la almohadilla de predicador, asegurándote de que el pecho quede apoyado contra ella. Sujeta las asas con agarre neutro (palmas una frente a la otra). Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1615-OAguZoG.gif', '/exercises/images/1615-OAguZoG.jpg'),
('0581', 'lever high row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'rear deltoids'], 'Ajusta la altura del asiento y la plataforma para los pies a una posición cómoda. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la plataforma para los pies. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y activa el core. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0581-nZZZy9m.gif', '/exercises/images/0581-nZZZy9m.jpg'),
('2286', 'lever hip extension v. 2', 'Pierna', 'upper legs', 'leverage machine', 'glutes', 'hamstrings', ARRAY['hamstrings'], 'Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo. Coloca los pies en los apoyapiés y sujeta las asas para mayor estabilidad. Activa los glúteos y los isquiotibiales, luego empuja contra los apoyapiés para extender las caderas y levantar las piernas hacia atrás. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2286-OPqShYN.gif', '/exercises/images/2286-OPqShYN.jpg'),
('2611', 'lever horizontal one leg press', 'Pierna', 'upper legs', 'leverage machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta el asiento de la máquina de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa para los pies. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies. Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad. Empuja la placa para los pies alejándola del cuerpo extendiendo la pierna, manteniendo la espalda apoyada en el respaldo. Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente la pierna para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/2611-9KU9TYF.gif', '/exercises/images/2611-9KU9TYF.jpg'),
('1299', 'lever incline chest press', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ajusta el asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos. Haz una pausa breve, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho. Repite el número de repeticiones deseado.', '/exercises/gifs/1299-jHAnWmT.gif', '/exercises/images/1299-jHAnWmT.jpg'),
('1479', 'lever incline chest press v. 2', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la altura del asiento y el ángulo del respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho. Repite el número de repeticiones deseado.', '/exercises/gifs/1479-o17Jfkt.gif', '/exercises/images/1479-o17Jfkt.jpg'),
('0582', 'lever kneeling leg curl', 'Pierna', 'upper legs', 'leverage machine', 'hamstrings', 'glutes', ARRAY['glutes'], 'Ajusta la máquina a tu cuerpo y selecciona el peso deseado. Arrodíllate en la máquina mirando hacia abajo, con las rodillas apoyadas en la almohadilla y los pies asegurados bajo las almohadillas para los pies. Sujeta las asas o los lados de la máquina para mayor estabilidad. Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas. Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales. Inhala y baja lentamente las piernas de vuelta a la posición inicial, extendiendo por completo las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/0582-nnmCTLN.gif', '/exercises/images/0582-nnmCTLN.jpg'),
('0583', 'lever kneeling twist', 'Core', 'waist', 'leverage machine', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Ajusta la altura del asiento y colócate en la máquina con las rodillas apoyadas en las almohadillas y la parte superior del cuerpo mirando hacia adelante. Sujeta las asas o los lados de la máquina para mayor estabilidad. Manteniendo el core activado, gira el torso hacia un lado tanto como sea cómodamente posible. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0583-sZOR9EV.gif', '/exercises/images/0583-sZOR9EV.jpg'),
('0584', 'lever lateral raise', 'Hombro', 'shoulders', 'leverage machine', 'delts', 'traps', ARRAY['traps', 'upper back'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Sujeta las asas con un agarre prono y mantén los brazos rectos. Exhala y levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa breve en lo alto, luego inhala y baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0584-dRTfGZT.gif', '/exercises/images/0584-dRTfGZT.jpg'),
('0585', 'lever leg extension', 'Pierna', 'upper legs', 'leverage machine', 'quads', 'hamstrings', ARRAY['hamstrings'], 'Ajusta la altura del asiento y el respaldo de la máquina a tu cuerpo. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la almohadilla para los pies. Sujeta las asas o las barras laterales para mayor estabilidad. Extiende las piernas hacia adelante enderezando las rodillas, levantando el peso. Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0585-my33uHU.gif', '/exercises/images/0585-my33uHU.jpg'),
('0586', 'lever lying leg curl', 'Pierna', 'upper legs', 'leverage machine', 'hamstrings', 'calves', ARRAY['calves'], 'Ajusta la máquina a tu cuerpo y selecciona el peso deseado. Túmbate boca abajo en la máquina con las piernas rectas y los talones contra la palanca acolchada. Sujeta las asas o los lados de la máquina para mayor estabilidad. Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba tanto como sea posible sin levantar las caderas de la almohadilla. Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales. Inhala y baja lentamente la palanca de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0586-17lJ1kr.gif', '/exercises/images/0586-17lJ1kr.jpg'),
('3195', 'lever lying two-one leg curl', 'Pierna', 'upper legs', 'leverage machine', 'hamstrings', 'glutes', ARRAY['glutes'], 'Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo. Coloca las piernas sobre la almohadilla de la palanca, justo encima de los tobillos. Sujeta las asas a los lados de la máquina para mayor apoyo. Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia los glúteos. Haz una pausa breve en lo alto, luego inhala y baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3195-UXpKJoq.gif', '/exercises/images/3195-UXpKJoq.jpg'),
('0587', 'lever military press', 'Hombro', 'shoulders', 'leverage machine', 'delts', 'triceps', ARRAY['triceps', 'upper chest'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0587-CggQhII.gif', '/exercises/images/0587-CggQhII.jpg'),
('0588', 'lever narrow grip seated row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y los apoyapiés para asegurar una postura correcta. Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia adelante. Tira de las asas hacia el torso, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente las asas y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0588-IGjKj1v.gif', '/exercises/images/0588-IGjKj1v.jpg'),
('0589', 'lever one arm bent over row', 'Espalda', 'back', 'barbell', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con agarre prono. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la cabeza erguida. Deja que la barra cuelgue frente a ti con los brazos completamente extendidos. Tira de la barra hacia el pecho, manteniendo los codos cerca del cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0589-Fhdtwf3.gif', '/exercises/images/0589-Fhdtwf3.jpg'),
('1356', 'lever one arm lateral high row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Ajusta la altura del asiento y colócate frente a la máquina. Sujeta el asa con una mano y mantén la espalda recta. Tira del asa hacia el cuerpo, manteniendo el codo cerca del costado. Aprieta los músculos de la espalda en la parte superior del movimiento. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1356-OIFMAp1.gif', '/exercises/images/1356-OIFMAp1.jpg'),
('1347', 'lever one arm lateral wide pulldown', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Sujeta el asa con un agarre prono y extiende el brazo por completo, manteniendo una ligera flexión en el codo. Tira del asa hacia abajo y a través del cuerpo en dirección a la cadera opuesta, apretando el dorsal en la parte baja del movimiento. Devuelve lentamente el asa a la posición inicial, extendiendo el brazo por completo. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1347-tTuZSDT.gif', '/exercises/images/1347-tTuZSDT.jpg'),
('0590', 'lever one arm shoulder press', 'Hombro', 'shoulders', 'leverage machine', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Sujeta el asa de la palanca con una mano y coloca el codo en un ángulo de 90 grados. Presiona la palanca hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/0590-2KGnL6M.gif', '/exercises/images/0590-2KGnL6M.jpg'),
('0591', 'lever overhand triceps dip', 'Brazo', 'upper arms', 'leverage machine', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Ajusta la máquina a la altura adecuada y asegura tu cuerpo en posición. Sujeta las asas con un agarre prono y coloca el cuerpo de modo que los brazos queden completamente extendidos. Baja el cuerpo flexionando los codos, manteniendo los brazos superiores cerca de los costados. Continúa bajando hasta que los brazos superiores queden paralelos al suelo. Haz una pausa breve, luego empújate de vuelta hacia arriba a la posición inicial extendiendo los codos. Repite el número de repeticiones deseado.', '/exercises/gifs/0591-D5yqP2p.gif', '/exercises/images/0591-D5yqP2p.jpg'),
('0592', 'lever preacher curl', 'Brazo', 'upper arms', 'leverage machine', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la altura del asiento y colócate en la máquina de palanca. Coloca los brazos superiores en la almohadilla y sujeta las asas con un agarre supino. Mantén la espalda recta y los codos colocados sobre la almohadilla. Exhala y flexiona los antebrazos hacia los brazos superiores, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0592-b6hQYMb.gif', '/exercises/images/0592-b6hQYMb.jpg'),
('1614', 'lever preacher curl v. 2', 'Brazo', 'upper arms', 'leverage machine', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la altura del asiento y colócate en la máquina con los brazos superiores apoyados en la almohadilla y el pecho contra el soporte. Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros. Mantén los brazos superiores inmóviles y exhala mientras flexionas las asas hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala mientras bajas lentamente las asas de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/1614-ye84CTU.gif', '/exercises/images/1614-ye84CTU.jpg'),
('2285', 'lever pullover', 'Espalda', 'back', 'leverage machine', 'lats', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta el asiento y las asas de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en la almohadilla y sujeta las asas con un agarre prono. Mantén los brazos ligeramente flexionados y el core activado. Tira lentamente de las asas hacia el pecho, apretando los dorsales. Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2285-4U7iLb5.gif', '/exercises/images/2285-4U7iLb5.jpg'),
('2736', 'lever reverse grip lateral pulldown', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar. Tira de las asas hacia el pecho, liderando con los codos y juntando los omóplatos. Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2736-ky8FLU8.gif', '/exercises/images/2736-ky8FLU8.jpg'),
('1616', 'lever reverse grip preacher curl', 'Brazo', 'upper arms', 'leverage machine', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la altura del asiento y colócate en la máquina de palanca. Sujeta las asas con un agarre supino, con las palmas hacia arriba. Apoya los brazos superiores sobre la almohadilla de predicador, asegurándote de que los codos queden completamente extendidos. Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/1616-kj3hy6W.gif', '/exercises/images/1616-kj3hy6W.jpg'),
('1348', 'lever reverse grip vertical row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies. Sujeta las asas con un agarre supino, con las palmas hacia arriba. Mantén la espalda recta y activa el core. Tira de las asas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1348-ZqNOWQ6.gif', '/exercises/images/1348-ZqNOWQ6.jpg'),
('0593', 'lever reverse hyperextension', 'Pierna', 'upper legs', 'leverage machine', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ajusta la máquina de palanca a tu cuerpo y asegura los pies en las almohadillas para los pies. Túmbate boca abajo en la máquina con la parte superior del cuerpo colgando fuera del borde y las caderas apoyadas en la almohadilla. Cruza los brazos sobre el pecho o colócalos detrás de la cabeza. Activa los glúteos y los isquiotibiales para levantar las piernas hacia arriba hasta que queden paralelas al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0593-Krmb3cB.gif', '/exercises/images/0593-Krmb3cB.jpg'),
('1349', 'lever reverse t-bar row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y la posición de la placa para los pies en la máquina de palanca. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y activa el core. Tira de las asas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1349-BgljGjd.gif', '/exercises/images/1349-BgljGjd.jpg'),
('2315', 'lever rotary calf', 'Pantorrilla', 'lower legs', 'leverage machine', 'calves', 'soleus', ARRAY['soleus', 'ankle stabilizers'], 'Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies. Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde. Sujeta las asas o los lados de la máquina para mayor estabilidad. Empuja con la parte delantera de los pies, elevando los talones tan alto como sea posible. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2315-MrgP9L6.gif', '/exercises/images/2315-MrgP9L6.jpg'),
('2335', 'lever seated calf press', 'Pantorrilla', 'lower legs', 'leverage machine', 'calves', 'soleus', ARRAY['soleus', 'hamstrings'], 'Ajusta el asiento de la máquina de modo que los hombros queden alineados con la almohadilla de la palanca. Coloca los dedos de los pies en la parte inferior de la plataforma y posiciona las rodillas debajo de la almohadilla de la palanca. Sujeta las asas a los lados del asiento para mayor estabilidad. Presiona la almohadilla de la palanca hacia abajo extendiendo los tobillos, elevando los talones tan alto como sea posible. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2335-Ie9UGty.gif', '/exercises/images/2335-Ie9UGty.jpg'),
('0594', 'lever seated calf raise', 'Pantorrilla', 'lower legs', 'leverage machine', 'calves', 'soleus', ARRAY['soleus', 'ankle stabilizers'], 'Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies. Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde. Sujeta las asas o los lados del asiento para mayor estabilidad. Empuja con la parte delantera de los pies para elevar los talones tan alto como sea posible. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0594-bOOdeyc.gif', '/exercises/images/0594-bOOdeyc.jpg'),
('1452', 'lever seated crunch', 'Core', 'waist', 'leverage machine', 'abs', 'obliques', ARRAY['obliques'], 'Siéntate en la máquina de palanca con la espalda apoyada en la almohadilla y los pies planos en el suelo. Sujeta las asas o coloca las manos sobre las almohadillas laterales para mayor apoyo. Activa el abdomen e inclínate lentamente hacia atrás, dejando que la almohadilla se mueva contigo. Cuando la parte superior del cuerpo esté en un ángulo de 45 grados, contrae el abdomen y haz un crunch hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa breve en lo alto, luego suelta lentamente y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1452-Wgaz7pm.gif', '/exercises/images/1452-Wgaz7pm.jpg'),
('0595', 'lever seated crunch (chest pad)', 'Core', 'waist', 'leverage machine', 'abs', 'obliques', ARRAY['obliques'], 'Ajusta la altura del asiento y la posición de la almohadilla para el pecho según tu comodidad. Siéntate en la máquina con la espalda apoyada en la almohadilla para el pecho y los pies planos en el suelo. Sujeta las asas o las barras laterales para mayor estabilidad. Activa el abdomen y reclínate lentamente hacia atrás, permitiendo que el respaldo se mueva contigo. Haz una pausa en la contracción máxima, sintiendo la tensión en el abdomen. Vuelve lentamente a la posición inicial contrayendo el abdomen y tirando de tu cuerpo hacia arriba. Repite el número de repeticiones deseado.', '/exercises/gifs/0595-ZnJHhMk.gif', '/exercises/images/0595-ZnJHhMk.jpg'),
('3760', 'lever seated crunch v. 2', 'Core', 'waist', 'leverage machine', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sujetos bajo las almohadillas. Coloca las manos en las asas o en los lados del asiento para mayor apoyo. Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen. Vuelve lentamente a la posición inicial, dejando que tu espalda se redondee ligeramente. Repite el número de repeticiones deseado.', '/exercises/gifs/3760-eXFXCY0.gif', '/exercises/images/3760-eXFXCY0.jpg'),
('1451', 'lever seated dip', 'Brazo', 'upper arms', 'leverage machine', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Ajusta la altura del asiento de modo que tus pies queden planos en el suelo y tus rodillas formen un ángulo de 90 grados. Agarra las asas de la máquina de palanca con las palmas hacia abajo y los brazos completamente extendidos. Baja lentamente el cuerpo flexionando los codos hasta que tus brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1451-BRImeP8.gif', '/exercises/images/1451-BRImeP8.jpg'),
('0596', 'lever seated fly', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'deltoids', ARRAY['deltoids', 'trapezius'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Agarra las asas con un agarre pronado y mantén los codos ligeramente flexionados. Exhala y empuja las asas hacia adelante, juntándolas frente a tu pecho. Haz una pausa por un momento, contrayendo los músculos del pecho. Inhala y vuelve lentamente a la posición inicial, permitiendo que los músculos del pecho se estiren. Repite el número de repeticiones deseado.', '/exercises/gifs/0596-v3xmPAR.gif', '/exercises/images/0596-v3xmPAR.jpg'),
('3759', 'lever seated good morning', 'Pierna', 'upper legs', 'leverage machine', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Ajusta la altura del asiento de modo que tus caderas queden un poco más altas que tus rodillas. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre los apoyapiés. Sujeta las asas o los lados del asiento para mayor estabilidad. Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas hasta que la parte superior de tu cuerpo quede paralela al suelo. Haz una pausa por un momento y luego vuelve lentamente a la posición inicial empujando con los glúteos y los isquiotibiales. Repite el número de repeticiones deseado.', '/exercises/gifs/3759-XsCcxCC.gif', '/exercises/images/3759-XsCcxCC.jpg'),
('0597', 'lever seated hip abduction', 'Pierna', 'upper legs', 'leverage machine', 'abductors', 'glutes', ARRAY['glutes', 'hamstrings'], 'Ajusta la altura del asiento de modo que tus rodillas formen un ángulo de 90 grados. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre los apoyapiés. Coloca las manos en las asas laterales para mayor estabilidad. Activa los abductores y empuja lentamente las piernas hacia afuera, alejándolas de la línea media del cuerpo. Haz una pausa al final del movimiento y luego junta lentamente las piernas de nuevo hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0597-CHpahtl.gif', '/exercises/images/0597-CHpahtl.jpg'),
('0598', 'lever seated hip adduction', 'Pierna', 'upper legs', 'leverage machine', 'adductors', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo. Coloca los pies sobre los apoyapiés y agarra las asas para mayor estabilidad. Activa los aductores y junta lentamente las piernas, apretando la parte interna de los muslos. Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0598-oHsrypV.gif', '/exercises/images/0598-oHsrypV.jpg'),
('0599', 'lever seated leg curl', 'Pierna', 'upper legs', 'leverage machine', 'hamstrings', 'calves', ARRAY['calves'], 'Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo. Coloca la parte baja de las piernas debajo de la palanca acolchada, justo por encima de los tobillos. Sujeta las asas a los lados de la máquina para mayor apoyo. Manteniendo la parte superior de las piernas inmóvil, exhala y flexiona las piernas hacia arriba todo lo que puedas. Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales. Inhala y baja lentamente la palanca de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0599-Zg3XY7P.gif', '/exercises/images/0599-Zg3XY7P.jpg'),
('0600', 'lever seated leg raise crunch', 'Core', 'waist', 'leverage machine', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sobre los apoyapiés. Sujeta las asas o las barras laterales para mayor estabilidad. Activa el abdomen y eleva lentamente las piernas hacia el pecho, mientras curvas el torso hacia adelante al mismo tiempo. Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas y el torso a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0600-PQ2AtC3.gif', '/exercises/images/0600-PQ2AtC3.jpg'),
('0602', 'lever seated reverse fly', 'Hombro', 'shoulders', 'leverage machine', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las asas con un agarre prono y mantén los brazos ligeramente flexionados. Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo. Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0602-myfUsKf.gif', '/exercises/images/0602-myfUsKf.jpg'),
('0601', 'lever seated reverse fly (parallel grip)', 'Hombro', 'shoulders', 'leverage machine', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las asas con un agarre paralelo, con las palmas enfrentadas, y mantén los brazos ligeramente flexionados. Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo. Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0601-xiHiJcA.gif', '/exercises/images/0601-xiHiJcA.jpg'),
('1350', 'lever seated row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y los apoyapiés a una posición cómoda. Siéntate en la máquina con el pecho apoyado en la almohadilla y los pies sobre los apoyapiés. Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros. Mantén la espalda recta y el core activado. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente las asas y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1350-7I6LNUG.gif', '/exercises/images/1350-7I6LNUG.jpg'),
('1385', 'lever seated squat calf raise on leg press machine', 'Pantorrilla', 'lower legs', 'leverage machine', 'calves', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes'], 'Ajusta el asiento de la máquina de prensa de piernas de modo que tus rodillas queden ligeramente flexionadas cuando los pies estén sobre la plataforma. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre la plataforma, separados a la altura de los hombros. Coloca los dedos y la planta de los pies sobre la plataforma, manteniendo los talones alejados del borde. Suelta las palancas de seguridad y empuja la plataforma alejándola de ti extendiendo las rodillas. Una vez que tus rodillas estén completamente extendidas, baja lentamente los talones flexionando las pantorrillas. Haz una pausa por un momento en la parte baja y luego empuja la plataforma de nuevo hacia arriba extendiendo las pantorrillas. Repite el número de repeticiones deseado.', '/exercises/gifs/1385-IeDEXTe.gif', '/exercises/images/1385-IeDEXTe.jpg'),
('0603', 'lever shoulder press', 'Hombro', 'shoulders', 'leverage machine', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo. Agarra las asas con un agarre prono y coloca las manos a la altura de los hombros. Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0603-67n3r98.gif', '/exercises/images/0603-67n3r98.jpg'),
('0869', 'lever shoulder press v. 2', 'Hombro', 'shoulders', 'leverage machine', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros. Empuja las asas hacia arriba y hacia adelante hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0869-vqsbmL0.gif', '/exercises/images/0869-vqsbmL0.jpg'),
('2318', 'lever shoulder press v. 3', 'Hombro', 'shoulders', 'leverage machine', 'delts', 'triceps', ARRAY['triceps', 'chest'], 'Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros. Empuja las asas hacia arriba y hacia adelante hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2318-dNFYIU1.gif', '/exercises/images/2318-dNFYIU1.jpg'),
('0604', 'lever shrug', 'Espalda', 'back', 'leverage machine', 'traps', 'shoulders', ARRAY['shoulders'], 'Ajusta la altura del asiento y colócate en la máquina de palanca con la espalda apoyada en la almohadilla. Sujeta las asas con un agarre prono y mantén los brazos rectos. Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0604-ZZKbeMw.gif', '/exercises/images/0604-ZZKbeMw.jpg'),
('0605', 'lever standing calf raise', 'Pantorrilla', 'lower legs', 'leverage machine', 'calves', 'soleus', ARRAY['soleus', 'ankle stabilizers'], 'Ajusta la máquina a tu altura y ponte de pie con los pies separados a la altura de los hombros. Coloca los hombros debajo de las almohadillas y sujétate de las asas para mayor estabilidad. Eleva los talones tan alto como puedas extendiendo los tobillos. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0605-ykUOVze.gif', '/exercises/images/0605-ykUOVze.jpg'),
('3758', 'lever standing chest press', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ajusta la altura del asiento y colócate en la máquina con los pies planos en el suelo. Agarra las asas con un agarre prono y coloca las manos a la altura del pecho. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, manteniendo los codos ligeramente flexionados. Haz una pausa por un momento y luego lleva lentamente las asas de vuelta hacia el pecho, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/3758-WbNq5Xu.gif', '/exercises/images/3758-WbNq5Xu.jpg'),
('0606', 'lever t bar row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y activa el core. Tira de las asas hacia el torso, juntando los omóplatos. Haz una pausa en el punto de máxima contracción y luego suelta lentamente las asas hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0606-aaXr7ld.gif', '/exercises/images/0606-aaXr7ld.jpg'),
('1351', 'lever t-bar reverse grip row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y activa el core. Tira de las asas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1351-FVM1AUZ.gif', '/exercises/images/1351-FVM1AUZ.jpg'),
('0607', 'lever triceps extension', 'Brazo', 'upper arms', 'leverage machine', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Agarra las asas con un agarre prono y extiende completamente los brazos frente a ti. Manteniendo la parte superior de los brazos inmóvil, baja lentamente las asas hacia tu frente flexionando los codos. Haz una pausa por un momento en la parte baja y luego empuja las asas de vuelta hacia arriba hasta la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0607-Ser9eQp.gif', '/exercises/images/0607-Ser9eQp.jpg'),
('1313', 'lever unilateral row', 'Espalda', 'back', 'leverage machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y colócate frente a la máquina. Agarra las asas con un agarre prono y mantén la espalda recta. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa en el punto máximo del movimiento y luego suelta lentamente, extendiendo los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1313-oROuvrX.gif', '/exercises/images/1313-oROuvrX.jpg'),
('0609', 'london bridge', 'Espalda', 'back', 'rope', 'upper back', 'shoulders', ARRAY['shoulders', 'biceps', 'forearms'], 'Sujeta la cuerda a un punto de anclaje alto. Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros. Agarra la cuerda con un agarre prono, con las palmas hacia abajo. Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado. Tira de la cuerda hacia tu cuerpo, juntando las escápulas. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0609-bLyQokI.gif', '/exercises/images/0609-bLyQokI.jpg'),
('3013', 'low glute bridge on floor', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'core'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca los brazos a los lados del cuerpo, con las palmas hacia abajo. Activa los glúteos y el core, y luego eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa breve en la parte alta, apretando los glúteos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3013-u0cNiij.gif', '/exercises/images/3013-u0cNiij.jpg'),
('1352', 'lower back curl', 'Espalda', 'back', 'body weight', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Túmbate boca abajo con las piernas extendidas y los brazos a los lados del cuerpo. Activa los glúteos y los isquiotibiales, y eleva lentamente la parte superior del cuerpo del suelo, curvando la espalda hacia arriba. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1352-ANbbry2.gif', '/exercises/images/1352-ANbbry2.jpg'),
('3582', 'lunge with jump', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Comienza de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Empújate con el pie derecho y salta al aire, cambiando la posición de los pies en pleno vuelo. Aterriza suavemente con el pie izquierdo hacia adelante y baja inmediatamente el cuerpo a una posición de zancada. Continúa alternando entre zancadas y saltos el número de repeticiones deseado.', '/exercises/gifs/3582-PM1PZjg.gif', '/exercises/images/3582-PM1PZjg.jpg'),
('1688', 'lunge with twist', 'Core', 'waist', 'body weight', 'abs', 'quadriceps', ARRAY['quadriceps', 'glutes', 'hamstrings'], 'Comienza de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Al hacer la zancada, gira el torso hacia la derecha, llevando el codo izquierdo hacia la rodilla derecha. Haz una pausa breve y luego vuelve a la posición inicial. Repite hacia el otro lado, dando un paso adelante con el pie izquierdo y girando el torso hacia la izquierda. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1688-K9VL0Jq.gif', '/exercises/images/1688-K9VL0Jq.jpg'),
('0613', 'lying (side) quads stretch', 'Pierna', 'upper legs', 'body weight', 'quads', 'hamstrings', ARRAY['hamstrings'], 'Túmbate de lado con las piernas rectas. Flexiona la pierna de arriba y agarra tu tobillo o pie con la mano. Tira suavemente del tobillo o del pie hacia los glúteos hasta sentir un estiramiento en los cuádriceps. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite del otro lado.', '/exercises/gifs/0613-BWnJR72.gif', '/exercises/images/0613-BWnJR72.jpg'),
('2312', 'lying elbow to knee', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda. Al mismo tiempo, extiende la pierna derecha en línea recta y levántala del suelo. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y extendiendo la pierna izquierda. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/2312-AQIhRjM.gif', '/exercises/images/2312-AQIhRjM.jpg'),
('0620', 'lying leg raise flat bench', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate en un banco plano con la espalda presionada contra él. Coloca las manos debajo de los glúteos como apoyo. Mantén las piernas rectas y juntas, y elévalas hacia el techo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0620-WhuFnR7.gif', '/exercises/images/0620-WhuFnR7.jpg'),
('0865', 'lying leg-hip raise', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el core y levanta las piernas del suelo, elevándolas hacia el techo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0865-9IxJdtC.gif', '/exercises/images/0865-9IxJdtC.jpg'),
('1301', 'machine inner chest press', 'Pecho', 'chest', 'leverage machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla. Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento. Haz una pausa al final del movimiento y luego vuelve lentamente a la posición inicial, inhalando mientras lo haces. Repite el número de repeticiones deseado.', '/exercises/gifs/1301-wDN97Ca.gif', '/exercises/images/1301-wDN97Ca.jpg'),
('0624', 'march sit (wall)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con la espalda contra una pared y los pies separados a la altura de las caderas. Desliza lentamente la espalda hacia abajo por la pared hasta que las rodillas formen un ángulo de 90 grados. Levanta el pie derecho del suelo y lleva la rodilla hacia el pecho. Baja el pie derecho de nuevo y levanta el pie izquierdo del suelo, llevando la rodilla hacia el pecho. Continúa alternando entre levantar el pie derecho y el izquierdo el número de repeticiones deseado.', '/exercises/gifs/0624-sVQCCeG.gif', '/exercises/images/0624-sVQCCeG.jpg'),
('1353', 'medicine ball catch and overhead throw', 'Espalda', 'back', 'medicine ball', 'lats', 'shoulders', ARRAY['shoulders', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos a la altura del pecho. Flexiona ligeramente las rodillas y activa el core. Baja el cuerpo a una posición de sentadilla, manteniendo la espalda recta y el pecho hacia arriba. Extiende explosivamente las caderas y las piernas, mientras lanzas simultáneamente el balón medicinal por encima de la cabeza. Suelta el balón en la parte más alta del movimiento y atrápalo cuando vaya bajando. Baja de nuevo el cuerpo a la posición de sentadilla y repite el número de repeticiones deseado.', '/exercises/gifs/1353-PsVS1QP.gif', '/exercises/images/1353-PsVS1QP.jpg'),
('1302', 'medicine ball chest pass', 'Pecho', 'chest', 'medicine ball', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho. Extiende los brazos hacia adelante, empujando el balón medicinal con fuerza para alejarlo del pecho. Al soltar el balón, continúa el movimiento con los brazos y el torso, transfiriendo el peso del pie de atrás al pie de adelante. Atrapa el balón cuando rebote en la pared o en tu compañero, y repite el movimiento de inmediato. Continúa durante el número de repeticiones deseado.', '/exercises/gifs/1302-aDoFKrE.gif', '/exercises/images/1302-aDoFKrE.jpg'),
('1303', 'medicine ball chest push from 3 point stance', 'Pecho', 'chest', 'medicine ball', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Comienza en una posición de apoyo de 3 puntos con una mano sobre el balón medicinal y la otra en el suelo. Extiende las piernas y coloca tu cuerpo en línea recta. Baja el pecho hacia el suelo manteniendo la espalda recta. Empuja el balón medicinal alejándolo de tu cuerpo, extendiendo completamente el brazo. Vuelve a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/1303-dCJnuVq.gif', '/exercises/images/1303-dCJnuVq.jpg'),
('1304', 'medicine ball chest push multiple response', 'Pecho', 'chest', 'medicine ball', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho. Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho. Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho. Repite el número de repeticiones deseado.', '/exercises/gifs/1304-7aolH9D.gif', '/exercises/images/1304-7aolH9D.jpg'),
('1305', 'medicine ball chest push single response', 'Pecho', 'chest', 'medicine ball', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho. Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho. Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho. Repite el número de repeticiones deseado.', '/exercises/gifs/1305-jeHtrlO.gif', '/exercises/images/1305-jeHtrlO.jpg'),
('1312', 'medicine ball chest push with run release', 'Pecho', 'chest', 'medicine ball', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho. Da un paso adelante con el pie derecho y, al mismo tiempo, empuja el balón medicinal hacia adelante, extendiendo completamente los brazos. Mientras empujas el balón hacia adelante, suéltalo y déjalo rodar. Corre rápidamente hacia adelante y atrapa el balón antes de que toque el suelo. Una vez que atrapes el balón, llévalo de vuelta al pecho y repite el movimiento con el pie izquierdo adelante. Continúa alternando piernas y repitiendo el ejercicio el número de repeticiones deseado.', '/exercises/gifs/1312-pX9Elbe.gif', '/exercises/images/1312-pX9Elbe.jpg'),
('1701', 'medicine ball close grip push up', 'Brazo', 'upper arms', 'medicine ball', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Empuja de vuelta hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1701-8K7m2SS.gif', '/exercises/images/1701-8K7m2SS.jpg'),
('1354', 'medicine ball overhead slam', 'Espalda', 'back', 'medicine ball', 'upper back', 'shoulders', ARRAY['shoulders', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos por encima de la cabeza. Activa el core y mantén la espalda recta. Flexiona ligeramente las rodillas y lanza con fuerza el balón medicinal contra el suelo frente a ti. Al lanzar el balón al suelo, utiliza todo el cuerpo para generar potencia, incluidos los hombros y el core. Atrapa el balón al rebotar y repite el número de repeticiones deseado.', '/exercises/gifs/1354-oHg8eop.gif', '/exercises/images/1354-oHg8eop.jpg'),
('1750', 'medicine ball supine chest throw', 'Brazo', 'upper arms', 'medicine ball', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Túmbate boca arriba en un banco con las rodillas flexionadas y los pies planos en el suelo. Sostén el balón medicinal con ambas manos, extendiendo los brazos rectos por encima del pecho. Baja el balón medicinal hacia el pecho, manteniendo los codos cerca del cuerpo. Empuja el balón medicinal explosivamente hacia arriba, extendiendo completamente los brazos y lanzando el balón lo más alto posible. Atrapa el balón medicinal y repite el número de repeticiones deseado.', '/exercises/gifs/1750-Al3tP0D.gif', '/exercises/images/1750-Al3tP0D.jpg'),
('0627', 'mixed grip chin-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Agarra la barra de dominadas con un agarre supino (las palmas hacia ti) y las manos un poco más separadas que la anchura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0627-T8UpLkb.gif', '/exercises/images/0627-T8UpLkb.jpg'),
('3217', 'modified hindu push-up (male)', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies separados a la altura de las caderas. Baja el cuerpo hacia el suelo, flexionando los codos y manteniendo el core activado. Mientras bajas el cuerpo, desplaza el peso hacia atrás y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo. Sigue bajando el cuerpo hasta que el pecho quede justo por encima del suelo y luego invierte el movimiento, empujando las caderas hacia abajo y extendiendo los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3217-epOSYUZ.gif', '/exercises/images/3217-epOSYUZ.jpg'),
('1421', 'modified push up to lower arms', 'Antebrazo', 'lower arms', 'body weight', 'forearms', 'triceps', ARRAY['triceps', 'chest', 'shoulders'], 'Comienza en posición de flexión con las manos directamente debajo de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de tu costado. Cuando los codos formen un ángulo de 90 grados, baja los antebrazos hasta el suelo, manteniendo los codos justo debajo de los hombros. Haz una pausa por un momento y luego empuja con las palmas para llevar los antebrazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1421-arvaszz.gif', '/exercises/images/1421-arvaszz.jpg'),
('0628', 'monster walk', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Coloca una banda elástica alrededor de los tobillos. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Da un paso hacia el lado con el pie derecho, manteniendo la tensión en la banda elástica. Continúa con el pie izquierdo, dando un paso lateral para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0628-O95afRA.gif', '/exercises/images/0628-O95afRA.jpg'),
('0630', 'mountain climber', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'core', ARRAY['core', 'shoulders', 'triceps'], 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y lleva la rodilla derecha hacia el pecho, luego cambia rápidamente y lleva la rodilla izquierda hacia el pecho. Continúa alternando las piernas con un movimiento de carrera, manteniendo las caderas bajas y el core activado. Mantén un ritmo constante y respira de forma regular durante todo el ejercicio. Repite el número de repeticiones deseado.', '/exercises/gifs/0630-RJgzwny.gif', '/exercises/images/0630-RJgzwny.jpg'),
('0631', 'muscle up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'triceps', 'shoulders', 'chest'], 'Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti. Sigue tirando hacia arriba hasta que el pecho quede por encima de la barra y los brazos estén completamente flexionados. Invierte el movimiento bajando lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0631-yJUHKTn.gif', '/exercises/images/0631-yJUHKTn.jpg'),
('1401', 'muscle-up (on vertical bar)', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'triceps', 'forearms'], 'Comienza colgándote de una barra vertical con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Al subir tu cuerpo, inclínate ligeramente hacia atrás y lleva los codos hacia los costados. Sigue tirando hasta que el pecho llegue a la barra y los codos estén completamente flexionados. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1401-Af0EW2I.gif', '/exercises/images/1401-Af0EW2I.jpg'),
('2328', 'narrow push-up on exercise ball', 'Brazo', 'upper arms', 'stability ball', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Coloca el balón de estabilidad en el suelo y ponte en posición de flexión con las manos sobre el balón, un poco más juntas que la anchura de los hombros. Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies. Baja el pecho hacia el balón flexionando los codos, manteniéndolos cerca del cuerpo. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/2328-4cWjYEN.gif', '/exercises/images/2328-4cWjYEN.jpg'),
('0634', 'negative crunch', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0634-szIn2UK.gif', '/exercises/images/0634-szIn2UK.jpg'),
('1495', 'oblique crunch v. 2', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado. Haz una pausa por un momento y luego baja las escápulas de nuevo a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1495-cJgSTmh.gif', '/exercises/images/1495-cJgSTmh.jpg'),
('0635', 'oblique crunches floor', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado. Haz una pausa por un momento y luego baja las escápulas de nuevo hasta el suelo. Repite hacia el otro lado, alternando los lados en cada repetición.', '/exercises/gifs/0635-QUDd8WS.gif', '/exercises/images/0635-QUDd8WS.jpg'),
('0636', 'olympic barbell hammer curl', 'Brazo', 'upper arms', 'olympic barbell', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra olímpica con un agarre prono. Deja que la barra cuelgue a la altura de los brazos frente a tus muslos, con las palmas hacia tu cuerpo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0636-o1ntciW.gif', '/exercises/images/0636-o1ntciW.jpg'),
('0637', 'olympic barbell triceps extension', 'Brazo', 'upper arms', 'olympic barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra con un agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0637-wu5LXwz.gif', '/exercises/images/0637-wu5LXwz.jpg'),
('1355', 'one arm against wall', 'Espalda', 'back', 'body weight', 'lats', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ponte de pie frente a una pared con los pies separados a la altura de los hombros. Extiende un brazo recto hacia adelante y coloca la palma contra la pared. Activa el core e inclina el cuerpo hacia adelante, manteniendo el brazo recto y la espalda plana. Empuja lentamente la pared con la palma, activando los dorsales. Mantén la posición durante unos segundos, luego suelta y repite con el otro brazo.', '/exercises/gifs/1355-ZZTGMKh.gif', '/exercises/images/1355-ZZTGMKh.jpg'),
('0638', 'one arm chin-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros. Estírate y agarra la barra con un agarre supino, con una mano sujetando la barra y la otra sosteniendo la muñeca como apoyo. Cuélgate de la barra con el brazo completamente extendido, manteniendo el cuerpo recto y el core activado. Tira de tu cuerpo hacia la barra flexionando el codo y contrayendo los músculos de la espalda. Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo y repite.', '/exercises/gifs/0638-HjdqmZa.gif', '/exercises/images/0638-HjdqmZa.jpg'),
('0639', 'one arm dip', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Ponte de pie de espaldas a un banco o silla, con los pies separados a la altura de los hombros. Coloca una mano en el banco o silla detrás de ti, con los dedos apuntando hacia tu cuerpo. Extiende las piernas hacia adelante, manteniendo los talones en el suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco o silla. Haz una pausa por un momento en la parte baja y luego empuja con las palmas para estirar los brazos y volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.', '/exercises/gifs/0639-FAoIFMw.gif', '/exercises/images/0639-FAoIFMw.jpg'),
('0640', 'one arm slam (with medicine ball)', 'Core', 'waist', 'medicine ball', 'abs', 'shoulders', ARRAY['shoulders', 'back'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal con una mano frente a la cintura. Flexiona ligeramente las rodillas y activa el core. Eleva el balón medicinal por encima de la cabeza, extendiendo completamente el brazo. Lanza con fuerza el balón medicinal contra el suelo, usando el core y los hombros para generar potencia. Atrapa el balón medicinal al rebotar y repite el número de repeticiones deseado.', '/exercises/gifs/0640-jCrtE9b.gif', '/exercises/images/0640-jCrtE9b.jpg'),
('1773', 'one arm towel row', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende completamente el brazo, dejando que la toalla cuelgue frente a ti. Tira de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', '/exercises/gifs/1773-bKWbrTA.gif', '/exercises/images/1773-bKWbrTA.jpg'),
('1386', 'one leg donkey calf raise', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Coloca las manos sobre una superficie estable para apoyarte, como una pared o una barra. Levanta una pierna del suelo, manteniendo la rodilla ligeramente flexionada. Eleva el talón lo más alto posible, usando los músculos de la pantorrilla. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/1386-A2upspL.gif', '/exercises/images/1386-A2upspL.jpg'),
('1387', 'one leg floor calf raise', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'ankles', ARRAY['ankles', 'feet'], 'Ponte de pie con los pies separados a la altura de las caderas y coloca las manos en una pared u objeto firme para mantener el equilibrio. Levanta un pie del suelo y mantén el equilibrio sobre el otro pie. Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/1387-0jp9Rlz.gif', '/exercises/images/1387-0jp9Rlz.jpg'),
('1476', 'one leg squat', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Extiende una pierna hacia adelante, manteniéndola elevada del suelo. Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla. Mantén el pecho arriba y la espalda recta. Empuja con el talón para regresar a la posición inicial. Repite con la otra pierna.', '/exercises/gifs/1476-C31LMnP.gif', '/exercises/images/1476-C31LMnP.jpg'),
('0641', 'otis up', 'Core', 'waist', 'weighted', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0641-UVL20oz.gif', '/exercises/images/0641-UVL20oz.jpg'),
('0642', 'outside leg kick push-up', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado. Al empujar de vuelta hacia arriba, lanza una pierna hacia el lado, extendiéndola completamente y activando los glúteos. Vuelve a colocar la pierna en la posición inicial y repite la flexión, alternando las piernas en cada repetición. Continúa alternando las patadas de pierna y las flexiones el número de repeticiones deseado.', '/exercises/gifs/0642-jNU1gFQ.gif', '/exercises/images/0642-jNU1gFQ.jpg'),
('0643', 'overhead triceps stretch', 'Brazo', 'upper arms', 'body weight', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie o siéntate erguido con los pies separados a la altura de los hombros. Extiende un brazo por encima de la cabeza, flexionando el codo de modo que la mano llegue hacia la escápula opuesta. Con la otra mano, tira suavemente del codo del brazo extendido hacia el lado opuesto de la cabeza, sintiendo un estiramiento en el tríceps. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del otro lado.', '/exercises/gifs/0643-Z5YStHW.gif', '/exercises/images/0643-Z5YStHW.jpg'),
('3147', 'pelvic tilt', 'Core', 'waist', 'body weight', 'abs', 'lower back', ARRAY['lower back'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados del cuerpo. Activa el abdomen e inclina la pelvis hacia arriba, presionando la zona lumbar contra el suelo. Mantén esta posición durante unos segundos, concentrándote en contraer el abdomen. Deshaz la inclinación y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3147-NKJ8o6x.gif', '/exercises/images/3147-NKJ8o6x.jpg'),
('1422', 'pelvic tilt into bridge', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'core'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca los brazos a los lados del cuerpo con las palmas hacia abajo. Activa los glúteos y los músculos del core. Inclina la pelvis hacia arriba, levantando las caderas del suelo. Mantén la posición de puente durante unos segundos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1422-D9qe7CM.gif', '/exercises/images/1422-D9qe7CM.jpg'),
('1388', 'peroneals stretch', 'Pantorrilla', 'lower legs', 'rope', 'calves', 'ankles', ARRAY['ankles', 'feet'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos. Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla. Mantén el estiramiento durante 15-30 segundos. Suelta la tensión de la cuerda y repite el estiramiento en la otra pierna. Repite el número de repeticiones deseado.', '/exercises/gifs/1388-XhfS1DZ.gif', '/exercises/images/1388-XhfS1DZ.jpg'),
('3662', 'pike-to-cobra push-up', 'Pierna', 'upper legs', 'body weight', 'glutes', 'core', ARRAY['core', 'shoulders', 'triceps'], 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Activa el core y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo. Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Al bajar, desplaza el peso hacia adelante y haz la transición a una postura de cobra estirando los brazos y elevando el pecho. Invierte el movimiento flexionando los codos y bajando el pecho de nuevo hacia el suelo. Empuja con las manos para volver a la posición de V invertida. Continúa el movimiento bajando las caderas de nuevo hacia el suelo, volviendo a la posición inicial de flexión. Repite el número de repeticiones deseado.', '/exercises/gifs/3662-XPUDTt7.gif', '/exercises/images/3662-XPUDTt7.jpg'),
('1306', 'plyo push up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros. Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta. Empuja explosivamente contra el suelo, usando los músculos del pecho para impulsar la parte superior del cuerpo fuera del suelo. Aterriza suavemente con las manos de vuelta en la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1306-Snj1wSv.gif', '/exercises/images/1306-Snj1wSv.jpg'),
('1687', 'posterior step to overhead reach', 'Core', 'waist', 'body weight', 'abs', 'glutes', ARRAY['glutes', 'hamstrings', 'quadriceps', 'shoulders'], 'Ponte de pie con los pies separados a la altura de las caderas y los brazos a los lados del cuerpo. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona la rodilla izquierda y baja el cuerpo a una posición de zancada. Mientras bajas a la zancada, lleva simultáneamente los brazos por encima de la cabeza. Haz una pausa por un momento en la parte baja de la zancada y luego vuelve a la posición inicial empujando con el talón izquierdo y llevando el pie derecho hacia adelante. Repite el movimiento hacia el otro lado, retrocediendo con el pie izquierdo y flexionando la rodilla derecha. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1687-ErqK3UL.gif', '/exercises/images/1687-ErqK3UL.jpg'),
('1389', 'posterior tibialis stretch', 'Pantorrilla', 'lower legs', 'rope', 'calves', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos. Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Suelta la tensión de la cuerda y relaja el pie. Repite el estiramiento en la otra pierna.', '/exercises/gifs/1389-DEEqoI2.gif', '/exercises/images/1389-DEEqoI2.jpg'),
('3119', 'potty squat', 'Core', 'waist', 'body weight', 'abs', 'quadriceps', ARRAY['quadriceps', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3119-75Bgtjy.gif', '/exercises/images/3119-75Bgtjy.jpg'),
('3132', 'potty squat with support', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3132-b63ZzGe.gif', '/exercises/images/3132-b63ZzGe.jpg'),
('0648', 'power clean', 'Pierna', 'upper legs', 'barbell', 'hamstrings', 'glutes', ARRAY['glutes', 'quadriceps', 'calves'], 'Comienza con la barra en el suelo frente a ti, con los pies separados a la altura de los hombros. Agáchate y agarra la barra con un agarre prono, un poco más separado que la anchura de los hombros. Mantén la espalda recta y el pecho hacia arriba al levantar la barra del suelo, extendiendo las caderas y las rodillas. Cuando la barra llegue a la mitad del muslo, tira de ella explosivamente hacia arriba, encogiendo los hombros y llevando los codos hacia arriba y hacia los lados. Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, rotando los codos y atrapando la barra sobre los hombros en una posición de sentadilla frontal. Ponte de pie con la barra, extendiendo completamente las caderas y las rodillas. Baja la barra de nuevo a la posición inicial, manteniendo el control del peso durante todo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/0648-SiWCcTN.gif', '/exercises/images/0648-SiWCcTN.jpg'),
('3665', 'power point plank', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'triceps', 'glutes'], 'Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies. Activa el core y aprieta los glúteos para mantener una posición estable. Baja el cuerpo hasta los antebrazos, un brazo a la vez, manteniendo una línea recta de la cabeza a los pies. Mantén esta posición durante el tiempo deseado, con el core y los glúteos activados. Para volver a la posición inicial, empuja con los antebrazos y eleva el cuerpo de nuevo a una posición de plancha alta. Repite el número de repeticiones deseado.', '/exercises/gifs/3665-hCjGsRQ.gif', '/exercises/images/3665-hCjGsRQ.jpg'),
('3203', 'prisoner half sit-up (male)', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3203-mgejmGP.gif', '/exercises/images/3203-mgejmGP.jpg'),
('1707', 'prone twist on stability ball', 'Core', 'waist', 'stability ball', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Comienza tumbándote boca abajo sobre un balón de estabilidad con los pies separados a la altura de los hombros y los dedos de los pies tocando el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa los músculos del core y eleva lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta. Rota el torso hacia un lado, llevando el hombro hacia la cadera. Mantén las caderas y las piernas estables durante todo el movimiento. Haz una pausa breve y luego vuelve a la posición inicial. Repite la rotación hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/1707-1IG6gVF.gif', '/exercises/images/1707-1IG6gVF.jpg'),
('0650', 'pull-in (on stability ball)', 'Core', 'waist', 'stability ball', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Comienza sentándote en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas a un ángulo de 90 grados. Coloca las manos a los lados del balón de estabilidad para mayor apoyo. Activa el abdomen y rueda lentamente las caderas hacia adelante, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte alta del movimiento y luego extiende lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0650-UQr48Oi.gif', '/exercises/images/0650-UQr48Oi.jpg'),
('0652', 'pull-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia la barra flexionando los codos y llevando el pecho hacia la barra. Haz una pausa en la parte alta del movimiento y luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0652-lBDjFxJ.gif', '/exercises/images/0652-lBDjFxJ.jpg'),
('1689', 'push and pull bodyweight', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'deltoids'], 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Desde la posición de flexión, tira del pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1689-wXvUZC8.gif', '/exercises/images/1689-wXvUZC8.jpg'),
('3638', 'push to run', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las manos para extender los brazos y volver a la posición inicial. Lleva rápidamente una rodilla hacia el pecho, luego cambia rápidamente y lleva la otra rodilla hacia el pecho. Continúa alternando las rodillas tan rápido como puedas manteniendo una buena forma. Continúa durante el tiempo o el número de repeticiones deseado.', '/exercises/gifs/3638-PrQbjvB.gif', '/exercises/images/3638-PrQbjvB.jpg'),
('1307', 'push up on bosu ball', 'Pecho', 'chest', 'bosu ball', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1307-wVompEp.gif', '/exercises/images/1307-wVompEp.jpg'),
('0662', 'push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'deltoids', 'core'], 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa cuando el pecho esté justo por encima del suelo y luego empújate de vuelta a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0662-I4hDWkc.gif', '/exercises/images/0662-I4hDWkc.jpg'),
('0653', 'push-up (bosu ball)', 'Pecho', 'chest', 'bosu ball', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0653-2kr2lWy.gif', '/exercises/images/0653-2kr2lWy.jpg'),
('0655', 'push-up (on stability ball)', 'Pecho', 'chest', 'stability ball', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros. Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies. Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0655-Y4BRNQF.gif', '/exercises/images/0655-Y4BRNQF.jpg'),
('0656', 'push-up (on stability ball)', 'Pecho', 'chest', 'stability ball', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros. Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies. Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0656-tgryw5Y.gif', '/exercises/images/0656-tgryw5Y.jpg'),
('0659', 'push-up (wall)', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'deltoids'], 'Ponte de pie frente a una pared, a una distancia aproximada de un brazo. Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros. Da un paso atrás, manteniendo el cuerpo recto y los pies separados a la altura de las caderas. Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo en línea recta. Empuja de vuelta a la posición inicial, estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0659-LEH9jxP.gif', '/exercises/images/0659-LEH9jxP.jpg'),
('0658', 'push-up (wall) v. 2', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ponte de pie frente a una pared, a una distancia aproximada de un brazo. Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros. Retrocede con los pies, manteniéndolos separados a la altura de las caderas. Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones. Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo recto. Haz una pausa por un momento y luego empújate de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0658-NCmbLCw.gif', '/exercises/images/0658-NCmbLCw.jpg'),
('0660', 'push-up close-grip off dumbbell', 'Brazo', 'upper arms', 'dumbbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Comienza en posición de flexión con las manos juntas, directamente debajo de los hombros. Sostén una mancuerna en cada mano, apoyándolas en el suelo. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0660-KZXAtKQ.gif', '/exercises/images/0660-KZXAtKQ.jpg'),
('0661', 'push-up inside leg kick', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'core'], 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado. Al empujar de vuelta hacia arriba, levanta una pierna del suelo y lánzala hacia el lado, manteniéndola recta. Baja la pierna de nuevo y repite la flexión, luego cambia a la otra pierna. Continúa alternando las patadas de pierna en cada repetición de la flexión.', '/exercises/gifs/0661-0br45wL.gif', '/exercises/images/0661-0br45wL.jpg'),
('0663', 'push-up medicine ball', 'Pecho', 'chest', 'medicine ball', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0663-W8KAlkI.gif', '/exercises/images/0663-W8KAlkI.jpg'),
('1467', 'push-up on lower arms', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Comienza en posición de plancha con los antebrazos en el suelo y los codos directamente debajo de los hombros. Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1467-4Jt8QsQ.gif', '/exercises/images/1467-4Jt8QsQ.jpg'),
('3145', 'push-up plus', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo. En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo. Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3145-pvBMLHA.gif', '/exercises/images/3145-pvBMLHA.jpg'),
('0664', 'push-up to side plank', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'chest', 'triceps'], 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado. Empuja hacia arriba para volver a la posición inicial. Desplaza el peso hacia la mano izquierda y rota el cuerpo hacia la derecha, elevando el brazo derecho hacia el techo. Mantén la posición de plancha lateral durante unos segundos y luego vuelve a la posición inicial. Repite la flexión y la plancha lateral en el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0664-KhHJ338.gif', '/exercises/images/0664-KhHJ338.jpg'),
('3533', 'quads', 'Pierna', 'upper legs', 'body weight', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla. Mantén el pecho arriba y la espalda recta. Baja hasta que los muslos queden paralelos al suelo. Empuja con los talones para volver a ponerte de pie en la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3533-6YUfHPL.gif', '/exercises/images/3533-6YUfHPL.jpg'),
('3201', 'quarter sit-up', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3201-enxnJcM.gif', '/exercises/images/3201-enxnJcM.jpg'),
('3552', 'quick feet v. 2', 'Pierna', 'upper legs', 'body weight', 'quads', 'calves', ARRAY['calves', 'hamstrings'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio. Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies. Continúa durante el tiempo o el número de repeticiones deseado.', '/exercises/gifs/3552-mweqJin.gif', '/exercises/images/3552-mweqJin.jpg'),
('0666', 'raise single arm push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Extiende un brazo hacia el lado, paralelo al suelo. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado. Empuja de vuelta a la posición inicial, usando los músculos del pecho para elevar el cuerpo. Repite con el otro brazo extendido.', '/exercises/gifs/0666-13TpY4H.gif', '/exercises/images/0666-13TpY4H.jpg'),
('0668', 'rear decline bridge', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas. Coloca los brazos a los lados del cuerpo con las palmas hacia abajo. Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros. Mantén esta posición durante unos segundos y luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0668-UpAlold.gif', '/exercises/images/0668-UpAlold.jpg'),
('0669', 'rear deltoid stretch', 'Hombro', 'shoulders', 'body weight', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende el brazo derecho a través del pecho, colocando la mano izquierda sobre el codo derecho. Tira suavemente del brazo derecho hacia el hombro izquierdo, sintiendo un estiramiento en el hombro derecho. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del otro lado.', '/exercises/gifs/0669-xifhB5W.gif', '/exercises/images/0669-xifhB5W.jpg'),
('0670', 'rear pull-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0670-CbFSYC1.gif', '/exercises/images/0670-CbFSYC1.jpg'),
('1582', 'reclining big toe pose with rope', 'Pierna', 'upper legs', 'rope', 'hamstrings', 'calves', ARRAY['calves', 'glutes'], 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Enrolla la cuerda alrededor de la planta del pie derecho y sujeta los extremos de la cuerda con las manos. Eleva lentamente la pierna derecha hacia el pecho, manteniendo la rodilla recta y el pie flexionado. Mantén el estiramiento durante unos segundos y luego baja lentamente la pierna de vuelta a la posición inicial. Repite con la pierna izquierda. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/1582-K5xgdvI.gif', '/exercises/images/1582-K5xgdvI.jpg'),
('3236', 'resistance band hip thrusts on knees (female)', 'Pierna', 'upper legs', 'resistance band', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas y los pies flexionados. Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas. Coloca las manos en las caderas o extiéndelas frente a ti para mantener el equilibrio. Activa los glúteos y los músculos del core. Empuja las caderas hacia adelante y aprieta los glúteos mientras levantas las rodillas del suelo, extendiendo las caderas hasta que los muslos queden paralelos al suelo. Mantén la posición por un momento y luego baja lentamente las rodillas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3236-Pjbc0Kt.gif', '/exercises/images/3236-Pjbc0Kt.jpg'),
('3007', 'resistance band leg extension', 'Pierna', 'upper legs', 'resistance band', 'quads', 'hamstrings', ARRAY['hamstrings'], 'Sujeta la banda elástica a un punto de anclaje firme y asegúrala alrededor de tu tobillo. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Manteniendo el core activado y la parte superior del cuerpo estable, extiende la pierna recta frente a ti. Haz una pausa por un momento en la parte alta y luego vuelve lentamente la pierna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/3007-Y1MsI1l.gif', '/exercises/images/3007-Y1MsI1l.jpg'),
('3123', 'resistance band seated biceps curl', 'Brazo', 'upper arms', 'resistance band', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén la banda elástica con un agarre supino, con las palmas hacia arriba y los brazos extendidos a los lados del cuerpo. Manteniendo la parte superior de los brazos inmóvil, exhala y flexiona la banda elástica hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la banda elástica de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3123-XFc3vpY.gif', '/exercises/images/3123-XFc3vpY.jpg'),
('3124', 'resistance band seated chest press', 'Pecho', 'chest', 'resistance band', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén las asas de la banda elástica en cada mano, con las palmas hacia abajo y los codos flexionados en un ángulo de 90 grados. Extiende los brazos hacia adelante, alejando la banda elástica de tu pecho. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3124-4x5Okof.gif', '/exercises/images/3124-4x5Okof.jpg'),
('3006', 'resistance band seated hip abduction', 'Pierna', 'upper legs', 'resistance band', 'abductors', 'glutes', ARRAY['glutes', 'hamstrings'], 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas. Coloca las manos en los lados de la silla o el banco para mayor apoyo. Activa los abductores (los músculos externos del muslo) y empuja lentamente las rodillas hacia afuera, contra la resistencia de la banda. Haz una pausa al final del movimiento y luego junta lentamente las rodillas de nuevo. Repite el número de repeticiones deseado.', '/exercises/gifs/3006-0xDpB4L.gif', '/exercises/images/3006-0xDpB4L.jpg'),
('3122', 'resistance band seated shoulder press', 'Hombro', 'shoulders', 'resistance band', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén la banda elástica con ambas manos, con las palmas hacia adelante, y elévala hasta la altura de los hombros. Empuja la banda por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa por un momento en la parte alta y luego baja lentamente la banda hasta la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/3122-S93zLTG.gif', '/exercises/images/3122-S93zLTG.jpg'),
('3144', 'resistance band seated straight back row', 'Espalda', 'back', 'resistance band', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Siéntate en el suelo con las piernas extendidas y enrolla la banda elástica alrededor de los pies. Sostén los extremos de la banda elástica con las manos, con las palmas enfrentadas. Mantén la espalda recta e inclínate ligeramente hacia atrás, activando el core. Tira de la banda elástica hacia el pecho, juntando las escápulas. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3144-Nu7jqFE.gif', '/exercises/images/3144-Nu7jqFE.jpg'),
('0872', 'reverse crunch', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate boca arriba con los brazos extendidos a los lados del cuerpo. Flexiona las rodillas y levanta los pies del suelo, llevando los muslos perpendiculares al suelo. Contrae el abdomen y eleva las caderas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0872-nCU1Ekp.gif', '/exercises/images/0872-nCU1Ekp.jpg'),
('0672', 'reverse dip', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0672-NZ5Qqkz.gif', '/exercises/images/0672-NZ5Qqkz.jpg'),
('0673', 'reverse grip machine lat pulldown', 'Espalda', 'back', 'leverage machine', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo. Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros. Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar. Tira de las asas hacia el pecho, juntando las escápulas. Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0673-ecpY0rH.gif', '/exercises/images/0673-ecpY0rH.jpg'),
('0674', 'reverse grip pull-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Agarra la barra de dominadas con un agarre supino, con las manos separadas a la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0674-YAk5dIw.gif', '/exercises/images/0674-YAk5dIw.jpg'),
('0675', 'reverse hyper extension (on stability ball)', 'Pierna', 'upper legs', 'stability ball', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Túmbate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti. Coloca las manos en el suelo frente a ti para mayor estabilidad. Activando los glúteos y los isquiotibiales, eleva las piernas hacia el techo tan alto como puedas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0675-vM5YS2g.gif', '/exercises/images/0675-vM5YS2g.jpg'),
('1423', 'reverse hyper on flat bench', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Túmbate boca abajo en un banco plano con las caderas en el borde y las piernas colgando del banco. Sujétate del banco para mantener la estabilidad. Manteniendo las piernas rectas, elévalas hacia el techo tan alto como puedas. Aprieta los glúteos en la parte alta del movimiento. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1423-OrETs32.gif', '/exercises/images/1423-OrETs32.jpg'),
('3663', 'reverse plank with leg lift', 'Core', 'waist', 'body weight', 'abs', 'glutes', ARRAY['glutes', 'hamstrings', 'shoulders'], 'Siéntate en el suelo con las piernas extendidas frente a ti y las manos apoyadas en el suelo detrás de ti, con los dedos apuntando hacia los pies. Presiona con las manos y levanta las caderas del suelo, llegando a una posición de plancha inversa. Activa el core y levanta una pierna del suelo, extendiéndola recta hacia el techo. Mantén la posición por un momento y luego baja la pierna de nuevo. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/3663-tFToB7l.gif', '/exercises/images/3663-tFToB7l.jpg'),
('0677', 'ring dips', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Comienza colgándote de las anillas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0677-ezTvXcr.gif', '/exercises/images/0677-ezTvXcr.jpg'),
('2571', 'rocking frog stretch', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas. Coloca las manos en el suelo frente a ti para mayor apoyo. Inclínate lentamente hacia adelante, desplazando el peso hacia las manos y extendiendo las piernas detrás de ti. Mantén la espalda recta y activa los glúteos mientras empujas las caderas hacia atrás y hacia arriba en dirección al techo. Mantén esta posición durante unos segundos, sintiendo un estiramiento en los glúteos. Vuelve lentamente a la posición inicial flexionando las rodillas y bajando las caderas de nuevo. Repite el número de repeticiones deseado.', '/exercises/gifs/2571-2Dk4xQV.gif', '/exercises/images/2571-2Dk4xQV.jpg'),
('0678', 'rocky pull-up pulldown', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros. Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0678-cQ19bBP.gif', '/exercises/images/0678-cQ19bBP.jpg'),
('2208', 'roller back stretch', 'Espalda', 'back', 'roller', 'spine', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Comienza sentándote en el suelo con las piernas extendidas frente a ti. Coloca el rodillo perpendicular a tu cuerpo, justo debajo de los glúteos. Rueda lentamente el cuerpo hacia atrás, dejando que el rodillo se desplace hacia arriba por tu espalda. Continúa rodando hasta que el rodillo llegue a la parte superior de tu espalda. Haz una pausa por un momento y luego rueda lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2208-isofgzg.gif', '/exercises/images/2208-isofgzg.jpg'),
('2204', 'roller body saw', 'Core', 'waist', 'roller', 'abs', 'shoulders', ARRAY['shoulders', 'triceps', 'core'], 'Comienza en posición de plancha con los antebrazos sobre el rodillo y el cuerpo en línea recta. Activa el core y rueda lentamente el rodillo hacia adelante, extendiendo el cuerpo tanto como puedas mientras mantienes el control. Haz una pausa por un momento en el punto más lejano y luego rueda lentamente el rodillo de vuelta hacia tu posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2204-XeMvLgE.gif', '/exercises/images/2204-XeMvLgE.jpg'),
('2205', 'roller hip lat stretch', 'Pierna', 'upper legs', 'roller', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Comienza arrodillándote en el suelo con el rodillo colocado debajo de las caderas. Coloca las manos sobre el rodillo para mayor apoyo. Rueda lentamente el rodillo hacia adelante, extendiendo las caderas y estirando los glúteos. Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2205-0L2KwtI.gif', '/exercises/images/2205-0L2KwtI.jpg'),
('2202', 'roller hip stretch', 'Pierna', 'upper legs', 'roller', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Comienza sentándote en el suelo con las piernas extendidas frente a ti. Coloca el rodillo debajo de los glúteos, justo por encima de las rodillas. Inclínate hacia atrás y coloca las manos en el suelo detrás de ti para apoyarte. Activa los glúteos y rueda lentamente el rodillo hacia adelante, flexionando las rodillas y llevándolas hacia el pecho. Haz una pausa al final del movimiento, sintiendo un estiramiento en los glúteos. Rueda lentamente el rodillo de vuelta a la posición inicial, extendiendo las piernas. Repite el número de repeticiones deseado.', '/exercises/gifs/2202-oMypNrz.gif', '/exercises/images/2202-oMypNrz.jpg'),
('2206', 'roller reverse crunch', 'Core', 'waist', 'roller', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate boca arriba con los brazos extendidos rectos por encima de la cabeza y las piernas rectas frente a ti. Coloca el rodillo entre los pies y sujétalo con los dedos de los pies. Activando el abdomen, levanta las piernas del suelo y flexiona las rodillas hacia el pecho, rodando el rodillo hacia tu cuerpo. Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas de vuelta a la posición inicial, rodando el rodillo alejándolo de tu cuerpo. Repite el número de repeticiones deseado.', '/exercises/gifs/2206-SKXQAx3.gif', '/exercises/images/2206-SKXQAx3.jpg'),
('2203', 'roller seated shoulder flexor depresor retractor', 'Pecho', 'chest', 'roller', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Siéntate sobre una superficie plana con las piernas extendidas frente a ti. Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos. Inclínate ligeramente hacia delante y aleja el rodillo de tu cuerpo, extendiendo los brazos rectos frente a ti. Haz una pausa por un momento, luego rueda el rodillo lentamente de vuelta hacia tu cuerpo, doblando los brazos y trayéndolo de nuevo hacia los muslos. Repite el número de repeticiones deseado.', '/exercises/gifs/2203-8coXSYU.gif', '/exercises/images/2203-8coXSYU.jpg'),
('2209', 'roller seated single leg shoulder flexor depresor retractor', 'Pecho', 'chest', 'roller', 'pectorals', 'deltoids', ARRAY['deltoids', 'triceps'], 'Siéntate sobre una superficie plana con las piernas extendidas frente a ti. Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos. Inclínate ligeramente hacia atrás y contrae los músculos del core. Eleva el rodillo hasta la altura de los hombros, manteniendo los brazos rectos. Baja lentamente el rodillo de nuevo hacia los muslos. Repite el número de repeticiones deseado.', '/exercises/gifs/2209-CjETvlw.gif', '/exercises/images/2209-CjETvlw.jpg'),
('2207', 'roller side lat stretch', 'Espalda', 'back', 'roller', 'lats', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta el rodillo con ambas manos frente al cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos hacia delante y rueda el rodillo hacia los pies, sintiendo un estiramiento en los dorsales. Mantén el estiramiento durante unos segundos, luego rueda el rodillo lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2207-c3Pfhti.gif', '/exercises/images/2207-c3Pfhti.jpg'),
('0680', 'rope climb', 'Espalda', 'back', 'rope', 'upper back', 'forearms', ARRAY['forearms', 'biceps', 'shoulders'], 'Ponte de pie frente a la cuerda con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas mirando hacia ti. Flexiona ligeramente las rodillas y activa el core. Comienza a subir por la cuerda alternando los movimientos de las manos. Usa las piernas para ayudar en el movimiento ascendente. Continúa trepando hasta alcanzar la altura deseada o la parte superior de la cuerda. Para descender, invierte el movimiento alterno de las manos mientras controlas tu descenso. Repite el número de repeticiones deseado.', '/exercises/gifs/0680-yaAxcQr.gif', '/exercises/images/0680-yaAxcQr.jpg'),
('0685', 'run', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Comienza de pie con los pies separados a la altura de la cadera. Activa el core y mantén la parte superior del cuerpo relajada. Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies. Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada. Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.', '/exercises/gifs/0685-oLrKqDH.gif', '/exercises/images/0685-oLrKqDH.jpg'),
('0684', 'run (equipment)', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Comienza de pie con los pies separados a la altura de la cadera. Activa el core y mantén la parte superior del cuerpo relajada. Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies. Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada. Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.', '/exercises/gifs/0684-y5p0H8a.gif', '/exercises/images/0684-y5p0H8a.jpg'),
('1585', 'runners stretch', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'calves', ARRAY['calves', 'quadriceps'], 'Ponte de pie con los pies separados a la altura de la cadera. Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo. Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta. Coloca las manos sobre el muslo derecho para apoyarte. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', '/exercises/gifs/1585-0mB6wHO.gif', '/exercises/images/1585-0mB6wHO.jpg'),
('0687', 'russian twist', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado. Junta las manos frente al pecho o sujeta una pesa si lo deseas. Levanta los pies del suelo, equilibrándote sobre los isquiones. Gira el torso hacia la derecha, llevando las manos o la pesa hacia el lado derecho del cuerpo. Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando las manos o la pesa hacia el lado izquierdo del cuerpo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0687-XVDdcoj.gif', '/exercises/images/0687-XVDdcoj.jpg'),
('3012', 'scapula dips', 'Espalda', 'back', 'body weight', 'traps', 'rhomboids', ARRAY['rhomboids', 'deltoids'], 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja el cuerpo doblando los codos y retrayendo las escápulas, como si intentaras apretar un lápiz entre ellas. Haz una pausa por un momento en la posición baja, luego empuja con las manos para extender los codos y volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3012-7xeukSt.gif', '/exercises/images/3012-7xeukSt.jpg'),
('3021', 'scapula push-up', 'Pecho', 'chest', 'body weight', 'serratus anterior', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. A medida que bajas, junta las escápulas y empuja el pecho hacia delante. Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3021-jV65tKx.gif', '/exercises/images/3021-jV65tKx.jpg'),
('0688', 'scapular pull-up', 'Espalda', 'back', 'body weight', 'traps', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Retrae las escápulas llevándolas hacia abajo y atrás. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, enfocándote en juntar las escápulas. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0688-uTBt1HV.gif', '/exercises/images/0688-uTBt1HV.jpg'),
('3219', 'scissor jumps (male)', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Salta del suelo y al mismo tiempo cruza la pierna derecha por delante de la pierna izquierda. Al aterrizar, cambia rápidamente de pierna, cruzando la pierna izquierda por delante de la pierna derecha. Continúa alternando las piernas y saltando lo más rápido posible. Repite el número de repeticiones deseado.', '/exercises/gifs/3219-Eh2v5Iu.gif', '/exercises/images/3219-Eh2v5Iu.jpg'),
('1390', 'seated calf stretch (male)', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Siéntate en el borde de una silla o banco con los pies planos sobre el suelo. Extiende una pierna recta frente a ti, manteniendo el talón en el suelo. Inclínate ligeramente hacia delante, sintiendo un estiramiento en la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', '/exercises/gifs/1390-17bqEXD.gif', '/exercises/images/1390-17bqEXD.jpg'),
('1424', 'seated glute stretch', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Dobla la rodilla derecha y cruza el tobillo derecho sobre el muslo izquierdo. Coloca la mano derecha en el suelo detrás de ti para apoyarte. Con la mano izquierda, presiona suavemente la rodilla derecha para profundizar el estiramiento. Mantén el estiramiento durante 30 segundos a 1 minuto. Cambia de lado y repite.', '/exercises/gifs/1424-DeDThfG.gif', '/exercises/images/1424-DeDThfG.jpg'),
('0689', 'seated leg raise', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo. Coloca las manos a los lados del banco para apoyarte. Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0689-Hgs6Nl1.gif', '/exercises/images/0689-Hgs6Nl1.jpg'),
('0690', 'seated lower back stretch', 'Espalda', 'back', 'body weight', 'lats', 'glutes', ARRAY['glutes', 'hamstrings'], 'Siéntate en el borde de una silla con los pies planos sobre el suelo. Coloca las manos sobre los muslos o a los lados de la silla para apoyarte. Inclínate lentamente hacia delante desde la cadera, manteniendo la espalda recta. Siente el estiramiento en la zona lumbar y mantén la posición durante 20-30 segundos. Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0690-QFmz6ch.gif', '/exercises/images/0690-QFmz6ch.jpg'),
('2567', 'seated piriformis stretch', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda. Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', '/exercises/gifs/2567-QY39eBr.gif', '/exercises/images/2567-QY39eBr.jpg'),
('0691', 'seated side crunch (wall)', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques'], 'Siéntate en el suelo con la espalda contra una pared y las piernas extendidas frente a ti. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Contrae el abdomen e inclínate hacia un lado, llevando el codo hacia la cadera. Haz una pausa breve y luego vuelve a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0691-Y9hNPcN.gif', '/exercises/images/0691-Y9hNPcN.jpg'),
('1587', 'seated wide angle pose sequence', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'quadriceps', ARRAY['quadriceps', 'calves'], 'Siéntate en el suelo con las piernas extendidas formando un ángulo amplio. Flexiona los pies y contrae los cuádriceps. Coloca las manos en el suelo detrás de ti para apoyarte. Manteniendo la espalda recta, inclínate hacia delante desde la cadera. Continúa inclinándote hacia delante hasta sentir un estiramiento en los isquiotibiales. Mantén esta posición durante unas cuantas respiraciones. Libera lentamente el estiramiento y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1587-HIgYKAB.gif', '/exercises/images/1587-HIgYKAB.jpg'),
('0697', 'self assisted inverse leg curl', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes', 'calves'], 'Túmbate boca arriba sobre una esterilla o banco con las piernas extendidas. Coloca las manos a los lados o debajo de los glúteos para apoyarte. Dobla las rodillas y levanta los pies del suelo, llevando los muslos hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0697-GwYwElT.gif', '/exercises/images/0697-GwYwElT.jpg'),
('1766', 'self assisted inverse leg curl', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes', 'calves'], 'Túmbate boca abajo en una máquina de curl femoral con las piernas extendidas y los tobillos enganchados bajo la palanca acolchada. Coloca las manos en las asas laterales de la máquina para apoyarte. Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba lo más posible. Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales. Baja lentamente las piernas de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', '/exercises/gifs/1766-ZSY3MsL.gif', '/exercises/images/1766-ZSY3MsL.jpg'),
('0696', 'self assisted inverse leg curl (on floor)', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes', 'calves'], 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Levanta las caderas del suelo, activando los glúteos y los isquiotibiales. Flexiona lentamente las piernas hacia los glúteos, manteniendo las caderas elevadas. Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial. Baja las caderas de nuevo hacia el suelo. Repite el número de repeticiones deseado.', '/exercises/gifs/0696-E4PwJqI.gif', '/exercises/images/0696-E4PwJqI.jpg'),
('3222', 'semi squat jump (male)', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Salta de forma explosiva, extendiendo las caderas y las rodillas mientras balanceas los brazos para generar impulso. Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición. Repite el número de repeticiones deseado.', '/exercises/gifs/3222-6FMU51h.gif', '/exercises/images/3222-6FMU51h.jpg'),
('3656', 'short stride run', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Busca un espacio abierto o una cinta de correr para realizar el ejercicio. Ponte de pie con los pies separados a la altura de la cadera. Comienza a trotar en el lugar, levantando las rodillas alto y moviendo los brazos. Después de unos segundos, comienza a dar pasos cortos hacia delante, manteniendo un ritmo rápido. Continúa corriendo con pasos cortos durante la duración o distancia deseada.', '/exercises/gifs/3656-CcWEoWV.gif', '/exercises/images/3656-CcWEoWV.jpg'),
('1763', 'shoulder grip pull-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la barra de dominadas con un agarre a la altura de los hombros, con las palmas mirando hacia fuera. Cuélgate libremente con los brazos completamente extendidos. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra hasta que la barbilla quede por encima de ella. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1763-YtgD7Xq.gif', '/exercises/images/1763-YtgD7Xq.jpg'),
('3699', 'shoulder tap', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'triceps'], 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y levanta la mano derecha del suelo, extendiéndola para tocar el hombro izquierdo. Coloca la mano derecha de nuevo en el suelo y repite tocando el hombro derecho con la mano izquierda. Continúa alternando los toques de hombro mientras mantienes las caderas y el torso estables. Repite el número de repeticiones deseado.', '/exercises/gifs/3699-yRpV5TC.gif', '/exercises/images/3699-yRpV5TC.jpg'),
('0699', 'shoulder tap push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'core'], 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras empujas hacia arriba, levanta la mano derecha del suelo y toca el hombro izquierdo. Vuelve a colocar la mano derecha en el suelo y repite la flexión, esta vez levantando la mano izquierda y tocando el hombro derecho. Continúa alternando los toques de hombro en cada repetición de la flexión. Mantén el core estable y evita una rotación excesiva de la cadera durante todo el ejercicio. Repite el número de repeticiones deseado.', '/exercises/gifs/0699-qEse6fe.gif', '/exercises/images/0699-qEse6fe.jpg'),
('1774', 'side bridge hip abduction', 'Pierna', 'upper legs', 'body weight', 'abductors', 'glutes', ARRAY['glutes', 'obliques'], 'Túmbate de lado con las piernas extendidas y una sobre la otra. Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Manteniendo el core activado, levanta la pierna superior lo más alto posible sin rotar las caderas. Haz una pausa por un momento en la posición alta, luego baja la pierna de nuevo. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1774-WL4EmxJ.gif', '/exercises/images/1774-WL4EmxJ.jpg'),
('0705', 'side bridge v. 2', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'glutes'], 'Túmbate de lado con las piernas extendidas y una sobre la otra. Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Mantén esta posición durante el tiempo deseado. Baja las caderas de vuelta a la posición inicial. Repite del otro lado.', '/exercises/gifs/0705-RKjH6Lt.gif', '/exercises/images/0705-RKjH6Lt.jpg'),
('0709', 'side hip (on parallel bars)', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Ponte de pie entre dos barras paralelas con los pies separados a la altura de los hombros. Coloca las manos sobre las barras y levanta el cuerpo del suelo, apoyando tu peso en los brazos. Contrae el abdomen y levanta lentamente las piernas hacia el lado, manteniéndolas rectas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0709-jTkSc6o.gif', '/exercises/images/0709-jTkSc6o.jpg'),
('0710', 'side hip abduction', 'Pierna', 'upper legs', 'body weight', 'abductors', 'glutes', ARRAY['glutes', 'quadriceps'], 'Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas. Traslada el peso a una pierna y levanta la pierna opuesta hacia el lado, manteniéndola recta. Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0710-7WaDzyL.gif', '/exercises/images/0710-7WaDzyL.jpg'),
('1358', 'side lying floor stretch', 'Espalda', 'back', 'body weight', 'lats', 'obliques', ARRAY['obliques', 'glutes'], 'Túmbate de lado con las piernas rectas y el brazo de abajo extendido recto por encima de la cabeza. Dobla la rodilla de arriba y coloca el pie en el suelo frente a la pierna de abajo. Extiende el brazo de arriba por encima de la cabeza y agárrate a algo estable, como una pared o un mueble. Levanta lentamente la pierna de abajo del suelo, manteniéndola recta, hasta sentir un estiramiento en el costado. Mantén el estiramiento durante 20-30 segundos, luego baja lentamente la pierna de nuevo. Repite del otro lado.', '/exercises/gifs/1358-jDOKRM5.gif', '/exercises/images/1358-jDOKRM5.jpg'),
('3667', 'side lying hip adduction (male)', 'Pierna', 'upper legs', 'body weight', 'adductors', 'glutes', ARRAY['glutes', 'hamstrings'], 'Túmbate de lado con las piernas rectas y apiladas una sobre la otra. Coloca el brazo de abajo bajo la cabeza para apoyarte. Activa los aductores y levanta la pierna de arriba lo más alto posible sin rotar las caderas ni inclinarte hacia atrás. Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/3667-c8f5cSY.gif', '/exercises/images/3667-c8f5cSY.jpg'),
('1775', 'side plank hip adduction', 'Pierna', 'upper legs', 'body weight', 'adductors', 'obliques', ARRAY['obliques', 'glutes'], 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta. Baja lentamente la pierna de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1775-VO2qeJg.gif', '/exercises/images/1775-VO2qeJg.jpg'),
('0716', 'side push neck stretch', 'Cuello', 'neck', 'body weight', 'levator scapulae', 'trapezius', ARRAY['trapezius', 'sternocleidomastoid'], 'Ponte de pie o siéntate erguido con los hombros relajados. Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho. Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento. Mantén el estiramiento durante 15-30 segundos. Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda. Repite el estiramiento 2-3 veces en cada lado.', '/exercises/gifs/0716-oQRJYkC.gif', '/exercises/images/0716-oQRJYkC.jpg'),
('0717', 'side push-up', 'Brazo', 'upper arms', 'body weight', 'triceps', 'shoulders', ARRAY['shoulders', 'chest', 'core'], 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca la mano de abajo en el suelo directamente debajo del hombro, con los dedos apuntando hacia delante. Empuja con la mano de abajo para levantar el cuerpo del suelo, manteniendo las piernas rectas y el core activado. Extiende el brazo de arriba recto hacia el techo, formando una línea recta desde la cabeza hasta los talones. Baja el cuerpo de nuevo a la posición inicial con control. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0717-wpbD28t.gif', '/exercises/images/0717-wpbD28t.jpg'),
('0721', 'side wrist pull stretch', 'Antebrazo', 'lower arms', 'body weight', 'forearms', 'wrists', ARRAY['wrists', 'hands'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Extiende el brazo derecho hacia el lado, paralelo al suelo, con la palma hacia abajo. Con la mano izquierda, sujeta la mano derecha y tira de ella suavemente hacia tu cuerpo, sintiendo un estiramiento en el antebrazo derecho. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del otro lado.', '/exercises/gifs/0721-UtmIqcI.gif', '/exercises/images/0721-UtmIqcI.jpg'),
('0720', 'side-to-side chin', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo relajado. Levántate doblando los codos y llevando la barbilla hacia la barra, manteniendo el cuerpo recto. Una vez que la barbilla esté por encima de la barra, bájate de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0720-isAAZWA.gif', '/exercises/images/0720-isAAZWA.jpg'),
('3213', 'side-to-side toe touch (male)', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Dobla la cintura hacia la derecha, llevando la mano derecha hacia el pie derecho mientras mantienes la mano izquierda extendida hacia el lado. Vuelve a la posición inicial y luego dobla la cintura hacia la izquierda, llevando la mano izquierda hacia el pie izquierdo mientras mantienes la mano derecha extendida hacia el lado. Repite el movimiento de flexión lateral el número de repeticiones deseado.', '/exercises/gifs/3213-WCAvOfC.gif', '/exercises/images/3213-WCAvOfC.jpg'),
('0725', 'single arm push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y una mano colocada un poco más ancha que la otra. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta. Al bajar, traslada el peso hacia un lado y levanta el brazo opuesto del suelo, extendiéndolo recto hacia el lado. Empuja con el pecho y los tríceps para subir el cuerpo de nuevo a la posición inicial, mientras bajas simultáneamente el brazo extendido de vuelta al suelo. Repite el movimiento, alternando el brazo que extiendes en cada repetición.', '/exercises/gifs/0725-MUic5zN.gif', '/exercises/images/0725-MUic5zN.jpg'),
('3645', 'single leg bridge with outstretched leg', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende una pierna recta hacia delante. Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros. Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/3645-rmEukuS.gif', '/exercises/images/3645-rmEukuS.jpg'),
('0727', 'single leg calf raise (on a dumbbell)', 'Pantorrilla', 'lower legs', 'dumbbell', 'calves', 'ankles', ARRAY['ankles', 'feet'], 'Ponte de pie con los pies separados a la altura de la cadera y sujeta una mancuerna en una mano. Levanta un pie del suelo y mantén el equilibrio sobre el otro pie. Eleva lentamente el talón lo más alto posible, usando los músculos de la pantorrilla. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', '/exercises/gifs/0727-fKZgDEO.gif', '/exercises/images/0727-fKZgDEO.jpg'),
('0730', 'single leg platform slide', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes', 'quadriceps'], 'Comienza de pie con un pie sobre una plataforma o tabla deslizante. Dobla ligeramente la rodilla y desliza el pie sobre la plataforma hacia atrás, extendiendo la pierna. Mantén el core activado y conserva una postura recta durante todo el movimiento. Vuelve lentamente a la posición inicial deslizando el pie de regreso a la posición inicial. Repite el movimiento el número de repeticiones deseado y luego cambia de pierna.', '/exercises/gifs/0730-LNE3wfo.gif', '/exercises/images/0730-LNE3wfo.jpg'),
('1759', 'single leg squat (pistol) male', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Levanta el pie derecho del suelo y extiéndelo hacia delante. Baja lentamente el cuerpo doblando la rodilla izquierda y empujando las caderas hacia atrás. Mantén el pecho elevado y la espalda recta mientras bajas el cuerpo. Baja hasta que el muslo izquierdo quede paralelo al suelo, o lo más abajo que puedas llegar cómodamente. Haz una pausa por un momento en la posición baja, luego empuja con el talón izquierdo para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/1759-nqs5HGV.gif', '/exercises/images/1759-nqs5HGV.jpg'),
('1489', 'sissy squat', 'Pierna', 'upper legs', 'body weight', 'quads', 'calves', ARRAY['calves', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido. Continúa bajando hasta que los muslos queden paralelos al suelo o tan lejos como puedas llegar cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1489-xdYPUtE.gif', '/exercises/images/1489-xdYPUtE.jpg'),
('0735', 'sit-up v. 2', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0735-Bn6TXyO.gif', '/exercises/images/0735-Bn6TXyO.jpg'),
('3679', 'sit-up with arms on chest', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Cruza los brazos sobre el pecho. Contrayendo el abdomen, levanta la parte superior del cuerpo del suelo hacia las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3679-6ZCiYWQ.gif', '/exercises/images/3679-6ZCiYWQ.jpg'),
('3361', 'skater hops', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Dobla ligeramente las rodillas y salta hacia la derecha, aterrizando sobre el pie derecho. Al aterrizar, balancea la pierna izquierda detrás de la pierna derecha y toca el suelo con los dedos del pie izquierdo. Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo. Al aterrizar, balancea la pierna derecha detrás de la pierna izquierda y toca el suelo con los dedos del pie derecho. Continúa alternando los lados, saltando y tocando el suelo con cada pierna. Repite el número de repeticiones deseado.', '/exercises/gifs/3361-zfNHMN9.gif', '/exercises/images/3361-zfNHMN9.jpg'),
('2142', 'ski ergometer', 'Brazo', 'upper arms', 'skierg machine', 'triceps', 'shoulders', ARRAY['shoulders', 'forearms'], 'Ajusta la altura del asiento y los apoyapiés a una posición cómoda. Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo. Siéntate erguido con los pies planos sobre los apoyapiés. Extiende los brazos rectos frente a ti, manteniendo los codos ligeramente flexionados. Activa los tríceps y empuja las asas hacia abajo, hacia los muslos. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2142-vpQaQkH.gif', '/exercises/images/2142-vpQaQkH.jpg'),
('3671', 'ski step', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Dobla ligeramente las rodillas y mantén la espalda recta. Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha. Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda. Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí. Repite el número de repeticiones deseado.', '/exercises/gifs/3671-5MRH8H2.gif', '/exercises/images/3671-5MRH8H2.jpg'),
('3304', 'skin the cat', 'Espalda', 'back', 'body weight', 'upper back', 'shoulders', ARRAY['shoulders', 'core'], 'Comienza colgándote de una barra con los brazos completamente extendidos y el cuerpo relajado. Activa el core y levanta las piernas, llevando las rodillas hacia el pecho. Continúa levantando las piernas por encima de la cabeza, permitiendo que el cuerpo pase entre los brazos. Una vez que las piernas estén completamente extendidas por encima de la cabeza, comienza a bajarlas de nuevo hacia la posición inicial. Mientras bajas las piernas, permite que el cuerpo pase de nuevo entre los brazos hasta quedar colgado con los brazos completamente extendidos otra vez. Repite el número de repeticiones deseado.', '/exercises/gifs/3304-MSfvriJ.gif', '/exercises/images/3304-MSfvriJ.jpg'),
('1425', 'sled 45 degrees one leg press', 'Pierna', 'upper legs', 'sled machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta la máquina de trineo a un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la placa. Coloca un pie sobre la placa y extiende la pierna, empujando el trineo alejándolo de ti. Dobla lentamente la rodilla y baja el trineo de vuelta a la posición inicial. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/1425-WWD6FzI.gif', '/exercises/images/1425-WWD6FzI.jpg'),
('0738', 'sled 45в° calf press', 'Pantorrilla', 'lower legs', 'sled machine', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Ajusta la máquina de trineo a un ángulo de 45 grados. Coloca los pies sobre la plataforma del trineo con los dedos de los pies apuntando hacia delante. Empuja la plataforma del trineo alejándola de ti extendiendo los tobillos y las pantorrillas. Haz una pausa por un momento en la posición alta, luego baja lentamente la plataforma del trineo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0738-qCNVnaU.gif', '/exercises/images/0738-qCNVnaU.jpg'),
('0739', 'sled 45в° leg press', 'Pierna', 'upper legs', 'sled machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta el asiento y la placa de la máquina de trineo a una posición cómoda. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa. Continúa empujando hasta que las piernas estén casi completamente extendidas, pero sin bloquear las rodillas. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la placa de vuelta hacia tu cuerpo doblando las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/0739-10Z2DXU.gif', '/exercises/images/0739-10Z2DXU.jpg'),
('1464', 'sled 45в° leg press (back pov)', 'Pierna', 'upper legs', 'sled machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa. Haz una pausa por un momento en la posición completamente extendida. Dobla lentamente las rodillas y baja la placa de vuelta hacia tu cuerpo, controlando el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/1464-yn2lLSI.gif', '/exercises/images/1464-yn2lLSI.jpg'),
('1463', 'sled 45° leg press (side pov)', 'Pierna', 'upper legs', 'sled machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa. Siéntate en la máquina de trineo con la espalda plana contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja contra la placa para extender las piernas, estirándolas por completo. Haz una pausa por un momento en la posición alta, luego dobla lentamente las rodillas para bajar la placa de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1463-2Qh2J1e.gif', '/exercises/images/1463-2Qh2J1e.jpg'),
('0740', 'sled 45в° leg wide press', 'Pierna', 'upper legs', 'sled machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta la máquina de trineo a un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma. Coloca los pies más separados que el ancho de los hombros. Empuja contra la plataforma para extender las piernas y enderezar las rodillas. Haz una pausa por un momento al final del movimiento, luego dobla lentamente las rodillas para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0740-tj41Nu6.gif', '/exercises/images/0740-tj41Nu6.jpg'),
('1391', 'sled calf press on leg press', 'Pantorrilla', 'lower legs', 'sled machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'quadriceps'], 'Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo. Coloca los pies separados a la altura de los hombros sobre el trineo, con los dedos de los pies apuntando hacia delante. Suelta las asas de seguridad y empuja el trineo alejándolo de ti extendiendo las rodillas y los tobillos. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente el trineo doblando las rodillas y los tobillos. Repite el número de repeticiones deseado.', '/exercises/gifs/1391-ykHcWme.gif', '/exercises/images/1391-ykHcWme.jpg'),
('0741', 'sled closer hack squat', 'Pierna', 'upper legs', 'sled machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta la máquina de trineo a un peso cómodo y colócate con la espalda contra el respaldo. Coloca los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera. Sujeta las asas a los lados de la máquina para mayor estabilidad. Activa el core y baja lentamente el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la posición baja, luego empuja con los talones para extender las piernas y volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0741-gf3ZjB9.gif', '/exercises/images/0741-gf3ZjB9.jpg'),
('0742', 'sled forward angled calf raise', 'Pantorrilla', 'lower legs', 'sled machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta la máquina de trineo a un peso cómodo y colócate en la máquina con la punta de los pies sobre la plataforma y los talones colgando. Coloca las manos en las asas o a los lados de la máquina para apoyarte. Activa las pantorrillas y eleva lentamente los talones lo más alto posible, empujando contra la resistencia del trineo. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0742-XDOiFns.gif', '/exercises/images/0742-XDOiFns.jpg'),
('0743', 'sled hack squat', 'Pierna', 'upper legs', 'sled machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta la máquina de trineo a una posición cómoda según tu altura. Ponte de pie con los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera. Sujétate de las asas o barras para mayor estabilidad. Baja el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento, luego empuja con los talones para subir el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0743-Qa55kX1.gif', '/exercises/images/0743-Qa55kX1.jpg'),
('2334', 'sled lying calf press', 'Pantorrilla', 'lower legs', 'sled machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta la máquina de trineo a un peso adecuado. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma. Coloca la punta y la almohadilla de los pies en el borde de la plataforma, con los talones colgando. Empuja la plataforma alejándola de ti extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas. Continúa empujando hasta que las pantorrillas estén completamente contraídas. Mantén la contracción por un momento, luego baja lentamente la plataforma de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2334-g376LuL.gif', '/exercises/images/2334-g376LuL.jpg'),
('0744', 'sled lying squat', 'Pierna', 'upper legs', 'sled machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta la máquina de trineo a un peso adecuado. Túmbate boca arriba en la máquina de trineo con los pies sobre la placa. Coloca los pies separados a la altura de los hombros y ligeramente angulados hacia fuera. Sujeta las asas de la máquina de trineo para mayor estabilidad. Activa los glúteos y los músculos del core. Empuja con los talones y extiende las piernas para levantar el trineo. Baja el trineo de nuevo doblando las rodillas y las caderas. Repite el número de repeticiones deseado.', '/exercises/gifs/0744-9n2149Z.gif', '/exercises/images/0744-9n2149Z.jpg'),
('1392', 'sled one leg calf press on leg press', 'Pantorrilla', 'lower legs', 'sled machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo. Siéntate en la máquina con la espalda contra el respaldo y los pies sobre el trineo, separados a la altura de los hombros. Coloca la punta y la almohadilla de los pies sobre el trineo, manteniendo los talones levantados. Empuja el trineo hacia delante extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas. Haz una pausa por un momento en la posición alta, luego baja lentamente el trineo flexionando los tobillos. Repite el número de repeticiones deseado.', '/exercises/gifs/1392-u0pLNgz.gif', '/exercises/images/1392-u0pLNgz.jpg'),
('1496', 'sledge hammer', 'Core', 'waist', 'hammer', 'abs', 'forearms', ARRAY['forearms', 'shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta el mazo con ambas manos. Activa el core y mantén la espalda recta. Balancea el mazo hacia el suelo, usando la fuerza del core y de la parte superior del cuerpo. Mientras balanceas hacia abajo, gira las caderas y transfiere la fuerza al mazo. Repite el número de repeticiones deseado.', '/exercises/gifs/1496-REXmfVC.gif', '/exercises/images/1496-REXmfVC.jpg'),
('0746', 'smith back shrug', 'Espalda', 'back', 'smith machine', 'traps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén los brazos rectos y deja que la barra cuelgue frente a los muslos. Levanta los hombros directamente hacia las orejas, contrayendo los trapecios en la parte alta. Mantén la posición por un momento, luego baja los hombros de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0746-MzNnwx9.gif', '/exercises/images/0746-MzNnwx9.jpg'),
('0747', 'smith behind neck press', 'Hombro', 'shoulders', 'smith machine', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable. Baja la barra hacia la parte de atrás del cuello, manteniendo los codos apuntando hacia delante. Empuja la barra hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0747-Gpn4ADc.gif', '/exercises/images/0747-Gpn4ADc.jpg'),
('0748', 'smith bench press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la altura de la barra de la máquina Smith a la altura del pecho. Túmbate en el banco con los pies firmemente apoyados en el suelo. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Suelta la barra del soporte y bájala hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa por un momento cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/0748-trqKQv2.gif', '/exercises/images/0748-trqKQv2.jpg'),
('0749', 'smith bent knee good morning', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'hamstrings', ARRAY['hamstrings', 'lower back'], 'Comienza de pie con los pies separados a la altura de los hombros, con los dedos de los pies apuntando hacia delante. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0749-1bQkKZK.gif', '/exercises/images/0749-1bQkKZK.jpg'),
('1359', 'smith bent over row', 'Espalda', 'back', 'smith machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Tira de la barra hacia la parte baja del pecho, juntando las escápulas. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1359-ZX9UZmj.gif', '/exercises/images/1359-ZX9UZmj.jpg'),
('0750', 'smith chair squat', 'Pierna', 'upper legs', 'smith machine', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ajusta la altura de la barra de la máquina Smith a una posición cómoda. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo doblando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0750-Gu2rNJd.gif', '/exercises/images/0750-Gu2rNJd.jpg'),
('0751', 'smith close-grip bench press', 'Brazo', 'upper arms', 'smith machine', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Ajusta la altura del asiento y colócate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0751-WcHl7ru.gif', '/exercises/images/0751-WcHl7ru.jpg'),
('0752', 'smith deadlift', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'lower back'], 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Dobla las caderas y las rodillas, manteniendo la espalda recta y el pecho elevado, y sujeta la barra con un agarre prono un poco más ancho que los hombros. Activa el core y levanta la barra extendiendo las caderas y las rodillas, manteniendo la barra cerca del cuerpo. Ponte de pie erguido, extendiendo por completo las caderas y las rodillas. Baja la barra de nuevo doblando las caderas y las rodillas, manteniendo el control y la espalda recta. Repite el número de repeticiones deseado.', '/exercises/gifs/0752-UfePqpx.gif', '/exercises/images/0752-UfePqpx.jpg'),
('0753', 'smith decline bench press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta el banco declinado al ángulo deseado. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0753-ETZfAbZ.gif', '/exercises/images/0753-ETZfAbZ.jpg'),
('0754', 'smith decline reverse-grip press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la máquina Smith a una posición declinada. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros. Suelta la barra y bájala hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0754-MY9P1WA.gif', '/exercises/images/0754-MY9P1WA.jpg'),
('1433', 'smith front squat (clean grip)', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves', 'core'], 'Configura la máquina Smith con la barra a la altura de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Da un paso atrás y coloca la barra sobre los hombros delanteros, apoyándola en la clavícula y los deltoides. Mantén el pecho elevado, la espalda recta y el core activado. Baja el cuerpo doblando las rodillas y las caderas, como si te sentaras en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1433-lFhb2Rw.gif', '/exercises/images/1433-lFhb2Rw.jpg'),
('3281', 'smith full squat', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Configura la máquina Smith con la barra a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios. Sujeta la barra con las manos un poco más separadas que el ancho de los hombros. Suelta la barra del soporte y da un paso atrás, manteniendo una postura estable. Manteniendo el pecho elevado y el core activado, inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo, o tan abajo como tu flexibilidad lo permita. Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3281-NNoHCEA.gif', '/exercises/images/3281-NNoHCEA.jpg'),
('0755', 'smith hack squat', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta la barra de la máquina Smith a una altura adecuada para tu cuerpo. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Activa el core y mantén el pecho elevado mientras sueltas la barra del soporte. Da un paso atrás y coloca los pies un poco más separados que el ancho de los hombros. Dobla las rodillas y baja el cuerpo, manteniendo el pecho elevado y la espalda recta. Continúa descendiendo hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0755-ZuPXtCK.gif', '/exercises/images/0755-ZuPXtCK.jpg'),
('0756', 'smith hip raise', 'Core', 'waist', 'smith machine', 'abs', 'glutes', ARRAY['glutes', 'hamstrings'], 'Colócate en la máquina Smith con la espalda contra la almohadilla y los pies separados a la altura de los hombros. Coloca las manos en la barra, un poco más separadas que el ancho de los hombros. Activa el core y los glúteos, luego empuja con los talones para levantar las caderas del suelo. Continúa levantando hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0756-CqhoytW.gif', '/exercises/images/0756-CqhoytW.jpg'),
('0757', 'smith incline bench press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ajusta el banco a una inclinación de 30-45 grados. Siéntate en el banco con la espalda plana contra la almohadilla y los pies firmemente apoyados en el suelo. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Suelta la barra y bájala lentamente hacia la parte alta del pecho, manteniendo los codos ligeramente pegados al cuerpo. Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/0757-5v7KYld.gif', '/exercises/images/0757-5v7KYld.jpg'),
('0758', 'smith incline reverse-grip press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta el asiento de la máquina Smith a un ángulo de inclinación cómodo. Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo. Sujeta la barra con un agarre prono un poco más ancho que el ancho de los hombros. Suelta la barra y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa por un momento cuando la barra esté justo por encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', '/exercises/gifs/0758-78VqWQK.gif', '/exercises/images/0758-78VqWQK.jpg'),
('0759', 'smith incline shoulder raises', 'Pecho', 'chest', 'smith machine', 'serratus anterior', 'deltoids', ARRAY['deltoids', 'trapezius'], 'Ajusta la máquina Smith a una posición inclinada. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Mantén la espalda recta y el core activado. Eleva la barra hacia el techo, guiando el movimiento con los codos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0759-ayAHcEm.gif', '/exercises/images/0759-ayAHcEm.jpg'),
('0760', 'smith leg press', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta el asiento y la placa para los pies de la máquina Smith a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies. Sujeta las asas o los lados de la máquina para mayor estabilidad. Empuja la placa alejándola de ti extendiendo las piernas, manteniendo la espalda contra el respaldo. Haz una pausa por un momento en la posición completamente extendida. Dobla lentamente las rodillas y baja la placa de vuelta hacia ti, regresando a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0760-7zdxRTl.gif', '/exercises/images/0760-7zdxRTl.jpg'),
('1434', 'smith low bar squat', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Configura la máquina Smith con la barra a una altura que te permita apoyarla cómodamente en la parte alta de la espalda. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios. Sujeta la barra con las manos un poco más separadas que el ancho de los hombros. Suelta la barra del soporte estirando las piernas y dando un paso atrás para alejarte del soporte. Respira profundamente y tensa el core. Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/1434-RGLscZM.gif', '/exercises/images/1434-RGLscZM.jpg'),
('1683', 'smith machine bicep curl', 'Brazo', 'upper arms', 'smith machine', 'biceps', 'forearms', ARRAY['forearms'], 'Ajusta la altura de la barra de la máquina Smith a la altura de la cintura. Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1683-zILLZ98.gif', '/exercises/images/1683-zILLZ98.jpg'),
('1625', 'smith machine decline close grip bench press', 'Brazo', 'upper arms', 'smith machine', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Ajusta el banco de la máquina Smith a una posición declinada. Túmbate en el banco con los pies firmemente apoyados en el suelo. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra esté justo encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1625-yB9SvIF.gif', '/exercises/images/1625-yB9SvIF.jpg'),
('1752', 'smith machine incline tricep extension', 'Brazo', 'upper arms', 'smith machine', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ajusta el asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Extiende los brazos por completo, levantando la barra del soporte y sosteniéndola directamente sobre el pecho. Baja la barra lentamente hacia la frente, manteniendo los codos cerca de la cabeza. Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1752-o8aOcrz.gif', '/exercises/images/1752-o8aOcrz.jpg'),
('1626', 'smith machine reverse decline close grip bench press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la máquina Smith a una posición declinada. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1626-QyO6Uma.gif', '/exercises/images/1626-QyO6Uma.jpg'),
('0761', 'smith narrow row', 'Espalda', 'back', 'smith machine', 'upper back', 'biceps', ARRAY['biceps', 'rear deltoids'], 'Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo. Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros. Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0761-JGKowMS.gif', '/exercises/images/0761-JGKowMS.jpg'),
('1360', 'smith one arm row', 'Espalda', 'back', 'smith machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Ajusta la altura de la barra de la máquina Smith a la altura de la cintura. Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con una mano usando un agarre prono, con la palma hacia abajo. Mantén el codo cerca del cuerpo y tira de la barra hacia la cintura, juntando las escápulas. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', '/exercises/gifs/1360-Q4DSJPC.gif', '/exercises/images/1360-Q4DSJPC.jpg'),
('1393', 'smith one leg floor calf raise', 'Pantorrilla', 'lower legs', 'smith machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Colócate en el suelo debajo de la barra de la máquina Smith, mirando en dirección contraria a la máquina. Coloca la punta de los pies sobre una superficie elevada, como un disco de peso o un bloque. Coloca la barra de la máquina Smith sobre la parte baja de las piernas, justo por encima de los tobillos. Sujeta la barra con las manos para mayor estabilidad. Levanta los talones del suelo extendiendo los tobillos, elevando el cuerpo hacia arriba. Haz una pausa en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1393-9GXrTE6.gif', '/exercises/images/1393-9GXrTE6.jpg'),
('0762', 'smith rear delt row', 'Hombro', 'shoulders', 'smith machine', 'delts', 'trapezius', ARRAY['trapezius', 'rhomboids', 'biceps'], 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado mientras tiras de las asas hacia el pecho, juntando las escápulas. Haz una pausa por un momento en la parte alta del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0762-nFUwqG6.gif', '/exercises/images/0762-nFUwqG6.jpg'),
('0763', 'smith reverse calf raises', 'Pantorrilla', 'lower legs', 'smith machine', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante. Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando. Sujétate de la barra para apoyarte, manteniendo la espalda recta y el core activado. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0763-ywaNfuh.gif', '/exercises/images/0763-ywaNfuh.jpg'),
('1394', 'smith reverse calf raises', 'Pantorrilla', 'lower legs', 'smith machine', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante. Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando. Sujétate de la barra para apoyarte. Levanta los talones lo más alto posible, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1394-Lsqrgh4.gif', '/exercises/images/1394-Lsqrgh4.jpg'),
('1361', 'smith reverse grip bent over row', 'Espalda', 'back', 'smith machine', 'upper back', 'biceps', ARRAY['biceps', 'forearms'], 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Tira de la barra hacia la parte baja del pecho, juntando las escápulas. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1361-aaxA3cm.gif', '/exercises/images/1361-aaxA3cm.jpg'),
('0764', 'smith reverse-grip press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta la altura de la barra de la máquina Smith a la altura del pecho. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Da un paso atrás y colócate con una ligera flexión en las rodillas. Mantén el pecho elevado y el core activado durante todo el ejercicio. Baja la barra hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0764-zK8Fu1W.gif', '/exercises/images/0764-zK8Fu1W.jpg'),
('1395', 'smith seated one leg calf raise', 'Pantorrilla', 'lower legs', 'smith machine', 'calves', 'hamstrings', ARRAY['hamstrings'], 'Siéntate en la máquina con la espalda contra la almohadilla y los pies sobre el apoyapiés. Coloca una pierna sobre el apoyapiés y mantén la otra pierna fuera de él. Eleva el talón lo más alto posible, usando los músculos de la pantorrilla. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/1395-0S75mYG.gif', '/exercises/images/1395-0S75mYG.jpg'),
('0765', 'smith seated shoulder press', 'Hombro', 'shoulders', 'smith machine', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ajusta la altura del asiento de modo que las asas queden a la altura de los hombros. Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo. Sujeta las asas con un agarre prono y levántalas de los soportes, extendiendo los brazos por completo. Baja las asas hasta la altura de los hombros, manteniendo los codos ligeramente flexionados. Empuja las asas hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos. Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', '/exercises/gifs/0765-xUwnBMT.gif', '/exercises/images/0765-xUwnBMT.jpg'),
('1426', 'smith seated wrist curl', 'Antebrazo', 'lower arms', 'smith machine', 'forearms', 'biceps', ARRAY['biceps', 'brachialis'], 'Siéntate en un banco frente a una máquina Smith con los pies planos sobre el suelo. Sujeta la barra con un agarre supino, con las manos separadas a la altura de los hombros. Apoya los antebrazos sobre los muslos, permitiendo que las muñecas cuelguen. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1426-B6dAO1t.gif', '/exercises/images/1426-B6dAO1t.jpg'),
('0766', 'smith shoulder press', 'Hombro', 'shoulders', 'smith machine', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ajusta la altura del asiento y colócate en la máquina Smith con los pies separados a la altura de los hombros. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y colócala a la altura de los hombros, con los codos flexionados y las palmas hacia delante. Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0766-903mzG8.gif', '/exercises/images/0766-903mzG8.jpg'),
('0767', 'smith shrug', 'Espalda', 'back', 'smith machine', 'traps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén los brazos rectos y los hombros relajados. Levanta los hombros hacia las orejas, contrayendo los trapecios en la parte alta. Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0767-OUQ0ZyW.gif', '/exercises/images/0767-OUQ0ZyW.jpg'),
('0768', 'smith single leg split squat', 'Pierna', 'upper legs', 'smith machine', 'quads', 'glutes', ARRAY['glutes', 'hamstrings'], 'Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Coloca un pie detrás de ti sobre un banco o escalón, con los dedos del pie apuntando hacia delante. Sujétate de la barra de la máquina Smith para mayor estabilidad. Dobla la rodilla delantera y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta. Haz una pausa por un momento en la posición baja, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0768-wWFspEi.gif', '/exercises/images/0768-wWFspEi.jpg'),
('0769', 'smith sprint lunge', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Da un paso atrás con el pie derecho y colócalo sobre la barra, apoyando la parte superior del pie en ella. Dobla la rodilla izquierda y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta. Empuja con el talón izquierdo para volver a la posición inicial. Repite del otro lado, dando un paso hacia atrás con el pie izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0769-HsjbB1z.gif', '/exercises/images/0769-HsjbB1z.jpg'),
('0770', 'smith squat', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Configura la máquina Smith con la barra a una altura adecuada para tu sentadilla. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Activa el core y suelta la barra del soporte, dando un paso atrás para alejarte del soporte. Manteniendo el pecho elevado y la espalda recta, inicia la sentadilla doblando las caderas y las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0770-jFtipLl.gif', '/exercises/images/0770-jFtipLl.jpg'),
('0771', 'smith standing back wrist curl', 'Antebrazo', 'lower arms', 'smith machine', 'forearms', 'biceps', ARRAY['biceps', 'triceps'], 'Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros. Mantén la espalda recta y los codos cerca del cuerpo. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0771-hfmQ0Tz.gif', '/exercises/images/0771-hfmQ0Tz.jpg'),
('0772', 'smith standing behind head military press', 'Hombro', 'shoulders', 'smith machine', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable. Coloca la barra detrás de la cabeza, apoyándola en la parte alta de los trapecios. Mantén el core activado y el pecho elevado durante todo el ejercicio. Empuja la barra por encima de la cabeza extendiendo los brazos, estirándolos por completo. Haz una breve pausa en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0772-ht8xDrP.gif', '/exercises/images/0772-ht8xDrP.jpg'),
('0773', 'smith standing leg calf raise', 'Pantorrilla', 'lower legs', 'smith machine', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ajusta la barra de la máquina Smith a una altura que te permita estar de pie con los pies planos sobre el suelo y los hombros debajo de la barra. Colócate debajo de la barra con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Coloca las manos sobre la barra para mayor estabilidad. Activa las pantorrillas y levanta lentamente los talones del suelo, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0773-6MaEjVA.gif', '/exercises/images/0773-6MaEjVA.jpg'),
('0774', 'smith standing military press', 'Hombro', 'shoulders', 'smith machine', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y bájala hasta la altura de los hombros, con las palmas hacia delante. Empuja la barra hacia arriba hasta que tus brazos queden completamente extendidos por encima de la cabeza. Haz una pausa de un momento en la parte superior y luego baja lentamente la barra de nuevo hasta la altura de los hombros. Repite el número de repeticiones deseado.', '/exercises/gifs/0774-jjUPrze.gif', '/exercises/images/0774-jjUPrze.jpg'),
('3142', 'smith sumo squat', 'Pierna', 'upper legs', 'smith machine', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Colócate debajo de la barra, apoyándola sobre la parte superior de la espalda y los hombros. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3142-dzz6BiV.gif', '/exercises/images/3142-dzz6BiV.jpg'),
('1396', 'smith toe raise', 'Pantorrilla', 'lower legs', 'smith machine', 'calves', 'ankles', ARRAY['ankles', 'shins'], 'Ajusta la barra de la máquina Smith a una altura que te permita pararte cómodamente con los pies planos sobre el suelo. Colócate debajo de la barra con los hombros justo debajo de ella y los pies separados a la altura de los hombros. Coloca la planta de los pies sobre una plataforma elevada o discos de peso, dejando los talones colgando fuera del borde. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Activa el core y mantén la espalda recta durante todo el ejercicio. Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1396-Y4QlY8z.gif', '/exercises/images/1396-Y4QlY8z.jpg'),
('0775', 'smith upright row', 'Hombro', 'shoulders', 'smith machine', 'delts', 'traps', ARRAY['traps', 'biceps'], 'Ponte de pie con los pies separados a la altura de los hombros, de frente a la máquina Smith. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado. Tira de la barra hacia tu barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0775-1DN3iz4.gif', '/exercises/images/0775-1DN3iz4.jpg'),
('1308', 'smith wide grip bench press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta el banco a una posición cómoda en la máquina Smith. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos hacia afuera a los costados. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1308-zoOvPcx.gif', '/exercises/images/1308-zoOvPcx.jpg'),
('1309', 'smith wide grip decline bench press', 'Pecho', 'chest', 'smith machine', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Ajusta el banco declinado al ángulo deseado. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos apuntando hacia afuera. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1309-wi2H9QX.gif', '/exercises/images/1309-wi2H9QX.jpg'),
('0776', 'snatch pull', 'Pierna', 'upper legs', 'barbell', 'quads', 'hamstrings', ARRAY['hamstrings', 'glutes', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti. Flexiona las rodillas y dobla las caderas para bajar a una posición de sentadilla, agarrando la barra con un agarre prono. Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas. Cuando la barra llegue a la altura de la cadera, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados. Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, llevando tu cuerpo a una posición de sentadilla profunda. Recibe la barra por encima de la cabeza con los brazos completamente extendidos y las rodillas flexionadas. Ponte de pie extendiendo las caderas y las rodillas, manteniendo la barra por encima de la cabeza. Baja la barra de nuevo a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/0776-dG5Smob.gif', '/exercises/images/0776-dG5Smob.jpg'),
('0777', 'spell caster', 'Core', 'waist', 'dumbbell', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta. Extiende el brazo con la mancuerna hacia el pie opuesto, rotando el torso mientras lo haces. Regresa a la posición inicial y repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0777-p9cCe2r.gif', '/exercises/images/0777-p9cCe2r.jpg'),
('1362', 'sphinx', 'Espalda', 'back', 'body weight', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Túmbate boca abajo en el suelo con los antebrazos planos sobre el piso y los codos justo debajo de los hombros. Activa el core y levanta el pecho del suelo, manteniendo los antebrazos y los dedos de los pies en el piso. Mantén esta posición durante unos segundos, asegurándote de mantener el cuello en una posición neutral. Baja lentamente el pecho de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1362-DIVyqrU.gif', '/exercises/images/1362-DIVyqrU.jpg'),
('0778', 'spider crawl push up', 'Pierna', 'upper legs', 'body weight', 'glutes', 'core', ARRAY['core', 'chest', 'shoulders'], 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Lleva la rodilla derecha hacia el codo derecho, manteniéndola elevada del suelo. Mientras llevas la rodilla derecha hacia atrás, baja simultáneamente el cuerpo hacia el suelo flexionando los codos. Empuja de nuevo hacia arriba a la posición inicial y repite llevando la rodilla izquierda hacia el codo izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0778-P9GFBME.gif', '/exercises/images/0778-P9GFBME.jpg'),
('1363', 'spine stretch', 'Espalda', 'back', 'body weight', 'spine', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Coloca las manos en el suelo detrás de ti, con los dedos apuntando hacia tu cuerpo. Activa el core e inclínate lentamente hacia atrás, manteniendo la espalda recta. Sigue inclinándote hacia atrás hasta que sientas un estiramiento en la columna. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1363-JbC2iaV.gif', '/exercises/images/1363-JbC2iaV.jpg'),
('2329', 'spine twist', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y gira lentamente el torso hacia la derecha, llevando el codo derecho hacia la rodilla izquierda. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado izquierdo, llevando el codo izquierdo hacia la rodilla derecha. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/2329-2jl9K55.gif', '/exercises/images/2329-2jl9K55.jpg'),
('2368', 'split squats', 'Pierna', 'upper legs', 'body weight', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con un pie y colócalo aproximadamente a dos pies de distancia por delante del otro pie. Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta. Sigue bajando hasta que el muslo delantero quede paralelo al suelo y la rodilla trasera quede justo por encima del suelo. Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', '/exercises/gifs/2368-9E25EOx.gif', '/exercises/images/2368-9E25EOx.jpg'),
('0786', 'squat jerk', 'Pierna', 'upper legs', 'barbell', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves', 'core'], 'Comienza con la barra apoyada sobre los hombros y los pies separados a la altura de los hombros. Baja el cuerpo a una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con la punta de los pies. Al llegar al punto más bajo de la sentadilla, empuja con fuerza a través de las piernas y eleva la barra por encima de la cabeza. Cuando la barra alcance su punto más alto, baja rápidamente a una posición de zancada dividida, con un pie adelante y otro atrás. Recibe la barra por encima de la cabeza con los brazos completamente extendidos y la rodilla trasera tocando ligeramente el suelo. Ponte de pie desde la posición dividida, juntando de nuevo los pies. Baja la barra de nuevo a los hombros y repite el número de repeticiones deseado.', '/exercises/gifs/0786-IMRsOCn.gif', '/exercises/images/0786-IMRsOCn.jpg'),
('1705', 'squat on bosu ball', 'Pierna', 'upper legs', 'bosu ball', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Coloca el bosu en el suelo con el lado plano hacia arriba. Ponte de pie con los pies separados a la altura de los hombros y colócate encima del bosu. Baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla. Mantén el pecho elevado y el peso en los talones. Baja hasta que los muslos queden paralelos al suelo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1705-T2fA5Ir.gif', '/exercises/images/1705-T2fA5Ir.jpg'),
('1685', 'squat to overhead reach', 'Pierna', 'upper legs', 'body weight', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Mientras te levantas de la sentadilla, extiende los brazos por encima de la cabeza, alcanzando hacia el techo. Vuelve a la posición inicial bajando los brazos y flexionando las rodillas para volver a hacer la sentadilla. Repite el número de repeticiones deseado.', '/exercises/gifs/1685-QChZi3x.gif', '/exercises/images/1685-QChZi3x.jpg'),
('1686', 'squat to overhead reach with twist', 'Pierna', 'upper legs', 'body weight', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Mientras te levantas de la sentadilla, eleva los brazos por encima de la cabeza y gira el torso hacia un lado. Vuelve a la posición inicial y repite la sentadilla, esta vez girando el torso hacia el lado opuesto. Continúa alternando los lados en cada repetición de la sentadilla.', '/exercises/gifs/1686-5BZHW9s.gif', '/exercises/images/1686-5BZHW9s.jpg'),
('2297', 'stability ball crunch (full range hands behind head)', 'Core', 'waist', 'stability ball', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2297-Gn5FwYT.gif', '/exercises/images/2297-Gn5FwYT.jpg'),
('3291', 'stalder press', 'Brazo', 'upper arms', 'body weight', 'triceps', 'shoulders', ARRAY['shoulders', 'core'], 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos por encima de la cabeza. Flexiona ligeramente las rodillas y activa el core. Baja el cuerpo a una posición de sentadilla mientras mantienes los brazos extendidos por encima de la cabeza. Mientras bajas en la sentadilla, empuja los brazos hacia el suelo, activando los tríceps. Haz una pausa de un momento en la parte baja de la sentadilla, luego empuja con los talones para levantarte mientras al mismo tiempo elevas de nuevo los brazos por encima de la cabeza. Repite el número de repeticiones deseado.', '/exercises/gifs/3291-zd4P4B2.gif', '/exercises/images/3291-zd4P4B2.jpg'),
('3669', 'standing archer', 'Espalda', 'back', 'body weight', 'upper back', 'shoulders', ARRAY['shoulders', 'biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos rectos hacia adelante a la altura de los hombros, paralelos al suelo. Gira el torso hacia la derecha, manteniendo los brazos extendidos y la espalda recta. Mientras giras, extiende el brazo derecho hacia adelante y el brazo izquierdo hacia atrás, imitando el movimiento de tensar un arco. Mantén la posición por un momento y luego vuelve a la posición inicial. Repite el movimiento, esta vez girando el torso hacia la izquierda y extendiendo el brazo izquierdo hacia adelante y el brazo derecho hacia atrás. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/3669-JF8AkMX.gif', '/exercises/images/3669-JF8AkMX.jpg'),
('0788', 'standing behind neck press', 'Hombro', 'shoulders', 'barbell', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra detrás del cuello con un agarre prono. Mantén la espalda recta y el core activado. Empuja la barra por encima de la cabeza extendiendo los brazos, estirando completamente los codos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0788-xDh0lJr.gif', '/exercises/images/0788-xDh0lJr.jpg'),
('1490', 'standing calf raise (on a staircase)', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'ankles', ARRAY['ankles', 'feet'], 'Ponte de pie en el borde de un escalón o una plataforma firme, con los talones colgando y la punta de los pies sobre el escalón. Sujétate de una baranda o pared para mantener el equilibrio si es necesario. Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1490-6HmFgmx.gif', '/exercises/images/1490-6HmFgmx.jpg'),
('1397', 'standing calves', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Levanta los talones del suelo lo más alto posible, apoyándote sobre la punta de los pies. Mantén la posición por un momento y luego baja lentamente los talones de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1397-XIHEoCG.gif', '/exercises/images/1397-XIHEoCG.jpg'),
('1398', 'standing calves calf stretch', 'Pantorrilla', 'lower legs', 'body weight', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie frente a una pared u objeto firme, a una distancia aproximada de un brazo. Coloca las manos sobre la pared o el objeto a la altura de los hombros. Da un paso hacia atrás con un pie, manteniendo el talón plano sobre el suelo. Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, manteniendo la pierna trasera recta. Deberías sentir un estiramiento en el músculo de la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Repite con la otra pierna.', '/exercises/gifs/1398-qOKcgVP.gif', '/exercises/images/1398-qOKcgVP.jpg'),
('1599', 'standing hamstring and calf stretch with strap', 'Pierna', 'upper legs', 'rope', 'hamstrings', 'calves', ARRAY['calves'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Sostén la correa con ambas manos y colócala alrededor de la parte anterior de la planta del pie. Mantén la pierna recta e inclínate lentamente hacia adelante desde las caderas, manteniendo la espalda recta. Siente el estiramiento en los isquiotibiales y en los músculos de la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite con la otra pierna. Repite el número de repeticiones deseado.', '/exercises/gifs/1599-xTjr103.gif', '/exercises/images/1599-xTjr103.jpg'),
('0794', 'standing lateral stretch', 'Espalda', 'back', 'body weight', 'lats', 'shoulders', ARRAY['shoulders', 'obliques'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos hacia los lados, paralelos al suelo. Inclina lentamente la parte superior del cuerpo hacia un lado, sintiendo un estiramiento en el costado y los dorsales. Mantén el estiramiento durante 15-30 segundos. Regresa a la posición inicial y repite del otro lado. Repite el número de repeticiones deseado.', '/exercises/gifs/0794-1jXLYEw.gif', '/exercises/images/0794-1jXLYEw.jpg'),
('1364', 'standing pelvic tilt', 'Espalda', 'back', 'body weight', 'spine', 'abdominals', ARRAY['abdominals'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Coloca las manos sobre las caderas o déjalas colgar a los lados. Activa los músculos del core e inclina la pelvis hacia adelante, empujando la zona lumbar hacia la pared detrás de ti. Mantén la posición durante unos segundos, luego suelta y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1364-cuKYxhu.gif', '/exercises/images/1364-cuKYxhu.jpg'),
('0795', 'standing single leg curl', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes'], 'Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas. Traslada tu peso a la pierna izquierda y levanta el pie derecho del suelo, flexionando la rodilla. Curva lentamente el talón derecho hacia los glúteos, contrayendo el isquiotibial. Haz una pausa de un momento en la parte superior y luego baja lentamente el pie derecho de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0795-C5jncD2.gif', '/exercises/images/0795-C5jncD2.jpg'),
('0796', 'standing wheel rollerout', 'Core', 'waist', 'wheel roller', 'abs', 'lower back', ARRAY['lower back', 'shoulders'], 'Comienza de pie, erguido, con los pies separados a la altura de los hombros y el rodillo frente a ti. Dobla la cintura y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el core activado. Continúa rodando hacia adelante hasta sentir un estiramiento en el abdomen y que tu cuerpo esté extendido lo máximo posible. Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia tu cuerpo, volviendo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0796-KtRomty.gif', '/exercises/images/0796-KtRomty.jpg'),
('3223', 'star jump (male)', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Flexiona ligeramente las rodillas y salta hacia arriba de forma explosiva. Mientras saltas, separa las piernas y extiende los brazos hacia los lados, formando una figura de estrella con tu cuerpo. Aterriza suavemente sobre la punta de los pies con las rodillas ligeramente flexionadas. Repite el número de repeticiones deseado.', '/exercises/gifs/3223-HtfCpfi.gif', '/exercises/images/3223-HtfCpfi.jpg'),
('2138', 'stationary bike run v. 3', 'Cardio', 'cardio', 'stationary bike', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta la altura y la posición del asiento para asegurar una alineación correcta. Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles. Comienza a pedalear a un ritmo cómodo. Mantén un ritmo constante y aumenta la resistencia según lo desees. Activa los músculos del core para mantener la estabilidad y una postura correcta. Continúa pedaleando durante la duración deseada de tu entrenamiento. Disminuye gradualmente la resistencia y reduce la velocidad antes de detenerte por completo. Estira las piernas y enfría después del entrenamiento.', '/exercises/gifs/2138-H1PESYI.gif', '/exercises/images/2138-H1PESYI.jpg'),
('0798', 'stationary bike walk', 'Cardio', 'cardio', 'leverage machine', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta la altura y la posición del asiento en la bicicleta estática para asegurar una alineación correcta. Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles. Comienza a pedalear a un ritmo cómodo, manteniendo la espalda recta y el core activado. Mantén un ritmo constante y aumenta el nivel de resistencia si lo deseas. Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular. Enfría reduciendo gradualmente tu ritmo y el nivel de resistencia. Estira los músculos de las piernas después del entrenamiento para prevenir la rigidez y favorecer la recuperación.', '/exercises/gifs/0798-a8VDgLw.gif', '/exercises/images/0798-a8VDgLw.jpg'),
('3314', 'straddle maltese', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'chest'], 'Comienza colgándote de un par de anillas con los brazos completamente extendidos y el cuerpo en línea recta. Separa bien las piernas, formando una posición a horcajadas. Activa el core y baja lentamente el cuerpo hasta que los brazos queden paralelos al suelo. Mantén esta posición durante unos segundos, luego empújate de nuevo hacia arriba a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3314-HfqciZF.gif', '/exercises/images/3314-HfqciZF.jpg'),
('3298', 'straddle planche', 'Core', 'waist', 'body weight', 'abs', 'shoulders', ARRAY['shoulders', 'triceps', 'chest'], 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y los pies bien separados. Activa el core y traslada lentamente tu peso hacia adelante, llevando los hombros por encima de las manos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3298-BL3GHeY.gif', '/exercises/images/3298-BL3GHeY.jpg'),
('1427', 'straight leg outer hip abductor', 'Pierna', 'upper legs', 'body weight', 'abductors', 'glutes', ARRAY['glutes', 'hamstrings'], 'Túmbate de lado con las piernas rectas y apiladas una sobre la otra. Coloca el brazo de abajo bajo la cabeza para apoyarte. Activa el core y levanta la pierna superior lo más alto posible sin rotar las caderas ni inclinarte hacia atrás. Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/1427-mQ1tBXn.gif', '/exercises/images/1427-mQ1tBXn.jpg'),
('0803', 'superman push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'core', ARRAY['core', 'shoulders'], 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Mientras bajas el cuerpo, levanta simultáneamente el brazo derecho y la pierna izquierda del suelo, extendiéndolos completamente. Haz una pausa de un momento en la parte superior, luego baja el brazo y la pierna mientras te empujas de nuevo hacia arriba a la posición inicial. Repite el movimiento, esta vez levantando el brazo izquierdo y la pierna derecha. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0803-4GqRrAk.gif', '/exercises/images/0803-4GqRrAk.jpg'),
('0805', 'suspended abdominal fallout', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Sujeta un entrenador de suspensión a un punto de anclaje alto y ajusta las correas a la altura de la cintura. Ponte de pie de espaldas al punto de anclaje y sostén las asas con los brazos extendidos frente a ti. Inclínate hacia adelante desde la cintura, manteniendo el cuerpo recto y el core activado. Baja el cuerpo todo lo que puedas mientras mantienes el control y la tensión en el abdomen. Haz una pausa de un momento en la parte baja, luego eleva lentamente el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0805-X3TCNEU.gif', '/exercises/images/0805-X3TCNEU.jpg'),
('0806', 'suspended push-up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders', 'core'], 'Busca un entrenador de suspensión y ajústalo a una altura adecuada. Ponte de pie de espaldas al punto de anclaje y sostén las asas con un agarre prono. Camina hacia adelante con los pies, inclinando el cuerpo hacia adelante hasta que tu peso quede sostenido por el entrenador de suspensión. Mantén el cuerpo recto desde la cabeza hasta los talones, activa el core y baja el pecho hacia las asas. Empuja con el pecho y los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0806-IaGQCrC.gif', '/exercises/images/0806-IaGQCrC.jpg'),
('0807', 'suspended reverse crunch', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y sube las rodillas hacia el pecho, curvando la pelvis hacia la caja torácica. Haz una pausa de un momento en la parte superior, luego baja lentamente las rodillas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0807-R1WYG5D.gif', '/exercises/images/0807-R1WYG5D.jpg'),
('0808', 'suspended row', 'Espalda', 'back', 'body weight', 'upper back', 'biceps', ARRAY['biceps', 'shoulders'], 'Coloca un entrenador de suspensión a una altura adecuada. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Sostén las asas con un agarre prono, con las palmas mirándose entre sí. Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo. Tira del pecho hacia las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0808-4OaumBr.gif', '/exercises/images/0808-4OaumBr.jpg'),
('0809', 'suspended split squat', 'Pierna', 'upper legs', 'body weight', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie de espaldas a un entrenador de suspensión con los pies separados a la altura de los hombros. Extiende una pierna hacia adelante y coloca el empeine del pie en el soporte para pie del entrenador de suspensión. Flexiona la pierna de apoyo y baja el cuerpo a una posición de zancada, manteniendo el pecho elevado y la rodilla alineada con la punta del pie. Empuja con el talón para regresar a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', '/exercises/gifs/0809-QpXqiq8.gif', '/exercises/images/0809-QpXqiq8.jpg'),
('3433', 'swimmer kicks v. 2 (male)', 'Pierna', 'upper legs', 'body weight', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'calves'], 'Túmbate boca abajo sobre una esterilla con los brazos extendidos por encima de la cabeza. Activa el core y levanta el pecho y las piernas del suelo al mismo tiempo. Mueve las piernas hacia arriba y hacia abajo con un movimiento de aleteo, como si estuvieras nadando. Continúa el movimiento de patada el número de repeticiones deseado. Baja el pecho y las piernas de nuevo a la posición inicial.', '/exercises/gifs/3433-SP3hUez.gif', '/exercises/images/3433-SP3hUez.jpg'),
('3318', 'swing 360', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'shoulders', ARRAY['shoulders', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Mantén los brazos extendidos rectos frente a ti, paralelos al suelo. Activa el core y mueve los brazos en un movimiento circular, rotando el torso mientras lo haces. Continúa el movimiento circular, moviendo los brazos y rotando el torso el número de repeticiones deseado. Recuerda respirar durante todo el ejercicio.', '/exercises/gifs/3318-tnaj0mT.gif', '/exercises/images/3318-tnaj0mT.jpg'),
('1753', 'three bench dip', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo. Empújate de vuelta hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1753-DQ0cqkT.gif', '/exercises/images/1753-DQ0cqkT.jpg'),
('2459', 'tire flip', 'Pierna', 'upper legs', 'tire', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, de frente al neumático. Flexiona las rodillas y dobla las caderas, bajando a una posición de sentadilla. Agáchate y agarra el borde inferior del neumático con ambas manos, con los dedos apuntando hacia ti. Activa los glúteos y los músculos de las piernas, y empuja con fuerza a través de las piernas para levantar el neumático del suelo. Mientras el neumático se voltea, usa la fuerza de la parte superior del cuerpo para guiarlo y mantener el control. Una vez que el neumático esté completamente volteado, retrocede rápidamente y reinicia tu postura. Repite el número de repeticiones deseado.', '/exercises/gifs/2459-oZjMu1t.gif', '/exercises/images/2459-oZjMu1t.jpg'),
('0811', 'trap bar deadlift', 'Pierna', 'upper legs', 'trap bar', 'glutes', 'hamstrings', ARRAY['hamstrings', 'quadriceps', 'lower back'], 'Ponte de pie con los pies separados a la altura de los hombros y la barra hexagonal en el suelo frente a ti. Flexiona las caderas y las rodillas para bajar y agarra las asas de la barra hexagonal con un agarre prono. Mantén la espalda recta y el pecho elevado mientras comienzas a levantar la barra hexagonal del suelo extendiendo las caderas y las rodillas. Al levantar, concéntrate en empujar con los talones y contraer los glúteos en la parte superior del movimiento. Baja la barra hexagonal de nuevo al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta durante todo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/0811-jQGwmxN.gif', '/exercises/images/0811-jQGwmxN.jpg'),
('0814', 'triceps dip', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0814-X6C6i5Y.gif', '/exercises/images/0814-X6C6i5Y.jpg'),
('0812', 'triceps dip (bench leg)', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Camina con los pies hacia adelante, deslizando los glúteos fuera del banco, y estira los brazos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Empuja con las palmas para estirar los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0812-VuoerH0.gif', '/exercises/images/0812-VuoerH0.jpg'),
('0813', 'triceps dip (between benches)', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en un banco con las manos agarrando el borde del banco, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0813-Wgbn9qo.gif', '/exercises/images/0813-Wgbn9qo.jpg'),
('0815', 'triceps dips floor', 'Brazo', 'upper arms', 'body weight', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el borde de una silla o banco con las manos junto a las caderas, los dedos apuntando hacia adelante. Desliza los glúteos fuera del frente de la silla con las piernas extendidas frente a ti. Estira los brazos, manteniendo una ligera flexión en los codos para conservar la tensión en los tríceps y aliviarla en las articulaciones del codo. Flexiona lentamente los codos para bajar el cuerpo hacia el suelo hasta que los codos formen un ángulo de aproximadamente 90 grados. Cuando llegues al punto más bajo del movimiento, empuja hacia abajo contra la silla para estirar los codos, volviendo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0815-7aVz15j.gif', '/exercises/images/0815-7aVz15j.jpg'),
('0816', 'triceps press', 'Brazo', 'upper arms', 'body weight', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos rectos frente a ti, paralelos al suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la parte superior de los brazos cerca de los costados. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0816-fSrPP6B.gif', '/exercises/images/0816-fSrPP6B.jpg'),
('0817', 'triceps stretch', 'Brazo', 'upper arms', 'body weight', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie o siéntate erguido con la espalda recta. Extiende un brazo por encima de la cabeza, flexionándolo por el codo. Coloca la mano opuesta sobre el codo flexionado y tira de él suavemente hacia tu cabeza. Mantén el estiramiento de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps. Suelta el estiramiento y repite con el otro brazo.', '/exercises/gifs/0817-uOV3Itw.gif', '/exercises/images/0817-uOV3Itw.jpg'),
('0871', 'tuck crunch', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas. Haz una pausa de un momento en la parte superior, luego baja lentamente los omóplatos y extiende las piernas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0871-BMMolZ3.gif', '/exercises/images/0871-BMMolZ3.jpg'),
('0818', 'twin handle parallel grip lat pulldown', 'Espalda', 'back', 'cable', 'lats', 'biceps', ARRAY['biceps', 'rhomboids', 'rear deltoids'], 'Ajusta la altura del asiento y colócate de frente a la máquina de cable. Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros. Siéntate y coloca los muslos debajo de las almohadillas para muslos, manteniendo los pies planos sobre el suelo. Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando una columna neutral. Tira de las asas hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales. Suelta lentamente las asas y vuelve a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0818-rkg41Fb.gif', '/exercises/images/0818-rkg41Fb.jpg'),
('1466', 'twist hip lift', 'Pierna', 'upper legs', 'body weight', 'glutes', 'obliques', ARRAY['obliques', 'hamstrings'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados para mayor apoyo. Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros. Manteniendo las caderas elevadas, gira la parte inferior del cuerpo hacia el lado derecho, llevando las rodillas hacia el suelo. Vuelve a la posición inicial y repite el giro hacia el lado izquierdo. Continúa alternando los giros el número de repeticiones deseado.', '/exercises/gifs/1466-AX1kB0o.gif', '/exercises/images/1466-AX1kB0o.jpg'),
('2802', 'twisted leg raise', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el abdomen y levanta ambas piernas del suelo, manteniéndolas rectas. Mientras levantas las piernas, gira las caderas hacia un lado, llevando las piernas hacia el hombro opuesto. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez girando las caderas hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/2802-C0eCeEt.gif', '/exercises/images/2802-C0eCeEt.jpg'),
('2801', 'twisted leg raise (female)', 'Core', 'waist', 'body weight', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Flexiona las rodillas y levanta las piernas del suelo, llevándolas hacia el pecho. Mientras levantas las piernas, gira las caderas hacia un lado, llevando las rodillas hacia el hombro opuesto. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez girando las caderas hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/2801-yT9tk17.gif', '/exercises/images/2801-yT9tk17.jpg'),
('3231', 'two toe touch (male)', 'Espalda', 'back', 'body weight', 'spine', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Estira los brazos hacia la punta de los pies con ambas manos, manteniendo las piernas rectas. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3231-p195zsJ.gif', '/exercises/images/3231-p195zsJ.jpg'),
('1365', 'upper back stretch', 'Espalda', 'back', 'body weight', 'upper back', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos rectos frente a ti, paralelos al suelo. Entrelaza los dedos y gira las palmas alejándolas de tu cuerpo. Eleva lentamente los brazos por encima de la cabeza, manteniéndolos rectos y paralelos entre sí. Mientras elevas los brazos, aprieta los omóplatos entre sí. Mantén el estiramiento de 15 a 30 segundos, luego suelta y repite.', '/exercises/gifs/1365-GSDioYu.gif', '/exercises/images/1365-GSDioYu.jpg'),
('1366', 'upward facing dog', 'Espalda', 'back', 'body weight', 'spine', 'shoulders', ARRAY['shoulders', 'chest'], 'Túmbate boca abajo en el suelo con las piernas extendidas detrás de ti. Coloca las manos en el suelo junto a las costillas inferiores, con los dedos apuntando hacia adelante. Presiona las manos firmemente contra el suelo y estira los brazos, levantando el torso y los muslos del suelo. Lleva los hombros hacia atrás y hacia abajo, abriendo el pecho y elevando la mirada hacia el techo. Mantén esta posición durante unas cuantas respiraciones, luego baja lentamente el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1366-01qpYSe.gif', '/exercises/images/1366-01qpYSe.jpg'),
('3420', 'v-sit on floor', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Siéntate en el suelo con las piernas extendidas frente a ti. Inclínate ligeramente hacia atrás y levanta las piernas del suelo, manteniéndolas rectas. Al mismo tiempo, levanta la parte superior del cuerpo del suelo y extiende los brazos hacia las piernas. Mantén esta posición durante unos segundos, luego baja lentamente la parte superior del cuerpo y las piernas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3420-ZuXu4Eq.gif', '/exercises/images/3420-ZuXu4Eq.jpg'),
('0826', 'vertical leg raise (on parallel bars)', 'Core', 'waist', 'body weight', 'abs', 'hip flexors', ARRAY['hip flexors'], 'Cuélgate de las barras paralelas con los brazos completamente extendidos y el cuerpo recto. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0826-ZNgOYQU.gif', '/exercises/images/0826-ZNgOYQU.jpg'),
('2141', 'walk elliptical cross trainer', 'Cardio', 'cardio', 'elliptical machine', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves'], 'Ajusta el nivel de resistencia y la inclinación de la máquina elíptica a los valores deseados. Sube a los pedales de la máquina y agarra las asas con suavidad. Comienza empujando hacia abajo con los pies y tirando de las asas hacia tu cuerpo. Continúa con este movimiento, alternando entre empujar y tirar, para simular un movimiento de caminar o correr. Mantén un ritmo constante y conserva el core activado durante todo el ejercicio. Continúa durante la duración deseada de tu entrenamiento cardiovascular. Disminuye gradualmente la intensidad y la velocidad de la máquina antes de bajarte.', '/exercises/gifs/2141-rjtuP6X.gif', '/exercises/images/2141-rjtuP6X.jpg'),
('3655', 'walking high knees lunge', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves'], 'Ponte de pie con los pies separados a la altura de la cadera. Levanta la rodilla derecha hacia el pecho lo más alto que puedas mientras mantienes el equilibrio sobre la pierna izquierda. Da un paso adelante con el pie derecho y baja el cuerpo a una posición de zancada, flexionando ambas rodillas a un ángulo de 90 grados. Empújate con el pie derecho y lleva la rodilla izquierda hacia el pecho. Da un paso adelante con el pie izquierdo y baja el cuerpo a una posición de zancada. Continúa alternando las piernas y avanzando con zancadas, manteniendo el core activado y un ritmo constante. Repite el número de repeticiones deseado.', '/exercises/gifs/3655-J9zIWig.gif', '/exercises/images/3655-J9zIWig.jpg'),
('1460', 'walking lunge', 'Pierna', 'upper legs', 'body weight', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con la pierna derecha, bajando el cuerpo a una posición de zancada. Mantén el torso erguido y la rodilla delantera alineada con el tobillo. Empújate con el pie derecho y lleva el pie izquierdo hacia adelante, entrando en una posición de zancada con la pierna izquierda. Continúa alternando las piernas y avanzando, manteniendo un ritmo controlado y constante. Repite el número de repeticiones deseado.', '/exercises/gifs/1460-IZVHb27.gif', '/exercises/images/1460-IZVHb27.jpg'),
('3666', 'walking on incline treadmill', 'Cardio', 'cardio', 'leverage machine', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ajusta el nivel de inclinación de la cinta de correr a la intensidad deseada. Ponte de pie sobre la cinta de correr con los pies separados a la altura de los hombros. Comienza a caminar a un ritmo cómodo, asegurándote de mantener una forma correcta. Activa los músculos del core y mantén la espalda recta durante todo el ejercicio. Continúa caminando en la cinta inclinada durante la duración deseada de tu entrenamiento cardiovascular. Disminuye gradualmente la inclinación y la velocidad de la cinta para enfriar antes de detenerte.', '/exercises/gifs/3666-rjiM4L3.gif', '/exercises/images/3666-rjiM4L3.jpg'),
('2311', 'walking on stepmill', 'Cardio', 'cardio', 'stepmill machine', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves'], 'Ajusta la máquina de escalones a un nivel cómodo. Sube a la máquina y coloca las manos sobre los pasamanos para apoyarte. Comienza a caminar colocando un pie en un escalón y luego el otro, alternando entre las piernas. Mantén una postura erguida y activa los músculos del core. Continúa caminando durante la duración o distancia deseada. Aumenta gradualmente la intensidad o la velocidad a medida que te sientas más cómodo con el ejercicio. Recuerda enfriar y estirar después de completar el ejercicio.', '/exercises/gifs/2311-j9Q5crt.gif', '/exercises/images/2311-j9Q5crt.jpg'),
('0830', 'weighted bench dip', 'Brazo', 'upper arms', 'weighted', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0830-MU9HnE7.gif', '/exercises/images/0830-MU9HnE7.jpg'),
('2987', 'weighted close grip chin-up on dip cage', 'Espalda', 'back', 'weighted', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie frente a la jaula de fondos y agarra las barras paralelas con un agarre supino, con las manos separadas a la altura de los hombros. Cuélgate de las barras con los brazos completamente extendidos, los pies levantados del suelo y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba en dirección a las barras, manteniendo los codos cerca de los costados. Continúa tirando hasta que tu barbilla quede por encima de las barras, luego haz una pausa de un momento. Baja lentamente el cuerpo de nuevo a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/2987-Gk1r408.gif', '/exercises/images/2987-Gk1r408.jpg'),
('3643', 'weighted cossack squats (male)', 'Pierna', 'upper legs', 'weighted', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies más separados que la anchura de los hombros y la punta de los pies apuntando ligeramente hacia afuera. Sostén un peso frente al pecho con ambas manos. Traslada tu peso hacia un lado y baja el cuerpo flexionando la rodilla del lado hacia el que te inclinaste, manteniendo la otra pierna recta. Baja todo lo que puedas mientras mantienes el equilibrio y el pecho elevado. Empuja con el talón de la pierna flexionada para volver a la posición inicial. Repite con el otro lado, alternando entre las piernas.', '/exercises/gifs/3643-GWoKnIm.gif', '/exercises/images/3643-GWoKnIm.jpg'),
('0832', 'weighted crunch', 'Core', 'waist', 'weighted', 'abs', 'obliques', ARRAY['obliques'], 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Sostén un disco de peso o una mancuerna sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que los omóplatos se separen del suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0832-s8nrDXF.gif', '/exercises/images/0832-s8nrDXF.jpg'),
('3670', 'weighted decline sit-up', 'Core', 'waist', 'weighted', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Túmbate boca arriba en un banco declinado con los pies sujetos debajo de las almohadillas para los pies. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta lentamente la parte superior del cuerpo del banco, curvándote hacia adelante hasta que el torso quede perpendicular al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3670-EZeDVzO.gif', '/exercises/images/3670-EZeDVzO.jpg'),
('0833', 'weighted donkey calf raise', 'Pantorrilla', 'lower legs', 'weighted', 'calves', 'hamstrings', ARRAY['hamstrings', 'glutes'], 'Ponte de pie sobre una plataforma elevada con la punta de los pies en el borde y los talones colgando. Sujétate de un objeto estable para mayor apoyo. Eleva los talones tan alto como puedas extendiendo los tobillos. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0833-LmaFNZS.gif', '/exercises/images/0833-LmaFNZS.jpg'),
('1310', 'weighted drop push up', 'Pecho', 'chest', 'weighted', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Cuando el pecho esté justo por encima del suelo, empújate hacia arriba de forma explosiva, levantando las manos del suelo. Mientras te empujas hacia arriba, mueve rápidamente las manos hacia los lados y un poco hacia adelante, permitiendo que tu cuerpo caiga hacia el suelo. Recíbete con las manos en la posición más ancha y baja de nuevo el pecho inmediatamente hacia el suelo. Repite el movimiento de flexión, bajando y recibiéndote con las manos en la posición más estrecha. Continúa alternando entre las posiciones de manos más ancha y más estrecha el número de repeticiones deseado.', '/exercises/gifs/1310-PSlvNMs.gif', '/exercises/images/1310-PSlvNMs.jpg'),
('2135', 'weighted front plank', 'Core', 'waist', 'weighted', 'abs', 'shoulders', ARRAY['shoulders', 'lower back'], 'Comienza tumbándote boca abajo en el suelo. Coloca los antebrazos en el suelo, con los codos justo debajo de los hombros. Extiende las piernas rectas hacia atrás, con la punta de los pies en el suelo. Activa el core y levanta el cuerpo del suelo, equilibrándote sobre los antebrazos y la punta de los pies. Mantén el cuerpo en línea recta desde la cabeza hasta los talones. Mantén esta posición durante el tiempo deseado. Baja el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2135-VBAWRPG.gif', '/exercises/images/2135-VBAWRPG.jpg'),
('0834', 'weighted front raise', 'Hombro', 'shoulders', 'weighted', 'delts', 'biceps', ARRAY['biceps', 'forearms'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos. Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0834-e4aFmFY.gif', '/exercises/images/0834-e4aFmFY.jpg'),
('0866', 'weighted hanging leg-hip raise', 'Core', 'waist', 'weighted', 'abs', 'hip flexors', ARRAY['hip flexors', 'lower back'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0866-QOA0FD0.gif', '/exercises/images/0866-QOA0FD0.jpg'),
('0835', 'weighted hyperextension (on stability ball)', 'Espalda', 'back', 'weighted', 'spine', 'glutes', ARRAY['glutes', 'hamstrings'], 'Colócate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0835-8urJS9b.gif', '/exercises/images/0835-8urJS9b.jpg'),
('3641', 'weighted kneeling step with swing', 'Hombro', 'shoulders', 'weighted', 'delts', 'triceps', ARRAY['triceps', 'core'], 'Comienza en posición de rodillas con las rodillas separadas a la altura de las caderas y la espalda recta. Sostén un peso en cada mano, con los brazos extendidos rectos hacia abajo frente a ti. Activa el core y balancea los pesos hacia arriba y por encima de la cabeza, manteniendo los brazos rectos. Baja los pesos de nuevo a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/3641-7uFJuXp.gif', '/exercises/images/3641-7uFJuXp.jpg'),
('3644', 'weighted lunge with swing', 'Pierna', 'upper legs', 'weighted', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un peso en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mientras avanzas en la zancada, balancea los pesos hacia adelante y hacia arriba, manteniendo los brazos rectos. Empújate con el pie derecho y vuelve a la posición inicial, balanceando los pesos de nuevo hacia abajo. Repite con el pie izquierdo y continúa alternando las piernas el número de repeticiones deseado.', '/exercises/gifs/3644-5WiFcYk.gif', '/exercises/images/3644-5WiFcYk.jpg'),
('3286', 'weighted muscle up', 'Espalda', 'back', 'weighted', 'lats', 'biceps', ARRAY['biceps', 'triceps', 'shoulders', 'chest'], 'Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti. Continúa subiendo hasta que el pecho llegue a la barra, luego haz una pausa de un momento. Baja lentamente de nuevo a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', '/exercises/gifs/3286-JsOV1SU.gif', '/exercises/images/3286-JsOV1SU.jpg'),
('3312', 'weighted muscle up (on bar)', 'Espalda', 'back', 'weighted', 'lats', 'biceps', ARRAY['biceps', 'triceps', 'shoulders', 'forearms'], 'Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Flexiona los codos y tira del pecho hacia la barra, manteniendo el cuerpo recto. Cuando tu pecho llegue a la barra, empuja hacia abajo con las manos y lleva los codos hacia atrás, elevando el cuerpo por encima de la barra. Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3312-MCkqdKE.gif', '/exercises/images/3312-MCkqdKE.jpg'),
('3290', 'weighted one hand pull up', 'Espalda', 'back', 'weighted', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate de la barra con un brazo completamente extendido y el cuerpo recto. Activa el core y tira de tu cuerpo hacia arriba en dirección a la barra flexionando el codo y contrayendo los músculos de la espalda. Continúa subiendo hasta que la barbilla quede por encima de la barra. Baja el cuerpo de nuevo a la posición inicial con control. Repite el número de repeticiones deseado.', '/exercises/gifs/3290-fXfqg1E.gif', '/exercises/images/3290-fXfqg1E.jpg'),
('0840', 'weighted overhead crunch (on stability ball)', 'Core', 'waist', 'weighted', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén un disco de peso o una mancuerna con ambas manos y extiende los brazos por encima de la cabeza. Activa el abdomen y curva lentamente el torso hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa de un momento en la parte superior, luego baja lentamente el torso de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0840-xmM75XG.gif', '/exercises/images/0840-xmM75XG.jpg'),
('0841', 'weighted pull-up', 'Espalda', 'back', 'weighted', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0841-HMzLjXx.gif', '/exercises/images/0841-HMzLjXx.jpg'),
('0844', 'weighted round arm', 'Hombro', 'shoulders', 'weighted', 'delts', 'triceps', ARRAY['triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Eleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Continúa elevando los brazos hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0844-VLYXo8S.gif', '/exercises/images/0844-VLYXo8S.jpg'),
('0846', 'weighted russian twist', 'Core', 'waist', 'weighted', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Sostén un peso o un balón medicinal con ambas manos frente al pecho. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado. Gira lentamente el torso hacia la derecha, llevando el peso o el balón medicinal hacia el suelo a tu lado derecho. Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso o el balón medicinal hacia el suelo a tu lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0846-fZFZ704.gif', '/exercises/images/0846-fZFZ704.jpg'),
('0845', 'weighted russian twist (legs up)', 'Core', 'waist', 'weighted', 'abs', 'obliques', ARRAY['obliques', 'hip flexors'], 'Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo, manteniendo las piernas juntas. Sostén el peso con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados. Inclínate ligeramente hacia atrás para activar los músculos del core. Gira el torso hacia la derecha, llevando el peso hacia el suelo a tu lado derecho. Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el suelo a tu lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0845-WU9BLIs.gif', '/exercises/images/0845-WU9BLIs.jpg'),
('2371', 'weighted russian twist v. 2', 'Core', 'waist', 'weighted', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Sostén el peso con ambas manos frente al pecho. Inclínate ligeramente hacia atrás para activar los músculos del core. Gira el torso hacia la derecha, llevando el peso hacia el lado derecho de tu cuerpo. Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el lado izquierdo de tu cuerpo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/2371-YIUAtYf.gif', '/exercises/images/2371-YIUAtYf.jpg'),
('0847', 'weighted seated bicep curl (on stability ball)', 'Brazo', 'upper arms', 'medicine ball', 'biceps', 'forearms', ARRAY['forearms'], 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sostén un balón medicinal con un agarre supino, las palmas hacia arriba, y deja que los brazos cuelguen a los lados. Manteniendo la parte superior de los brazos quieta, exhala y curva el balón medicinal hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente el balón medicinal de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0847-b4b6afT.gif', '/exercises/images/0847-b4b6afT.jpg'),
('0849', 'weighted seated twist (on stability ball)', 'Core', 'waist', 'weighted', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén un disco de peso o una mancuerna con ambas manos cerca del pecho. Activa el core y rota lentamente el torso hacia un lado, manteniendo las caderas estables. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite la rotación hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0849-s34Y4LR.gif', '/exercises/images/0849-s34Y4LR.jpg'),
('0850', 'weighted side bend (on stability ball)', 'Core', 'waist', 'weighted', 'abs', 'obliques', ARRAY['obliques', 'lower back'], 'Siéntate sobre un balón de estabilidad con los pies separados a la altura de los hombros y planos sobre el suelo. Sostén un peso en una mano y coloca la otra mano sobre la cadera. Activa el core e inclínate lentamente hacia el lado del peso, manteniendo la espalda recta. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/0850-6bOA1Oi.gif', '/exercises/images/0850-6bOA1Oi.jpg'),
('0851', 'weighted sissy squat', 'Pierna', 'upper legs', 'weighted', 'quads', 'glutes', ARRAY['glutes', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sostén un peso frente al pecho con ambas manos, o coloca una barra sobre la parte superior de la espalda. Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0851-0lQnxMZ.gif', '/exercises/images/0851-0lQnxMZ.jpg'),
('0852', 'weighted squat', 'Pierna', 'upper legs', 'weighted', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sostén un peso frente al pecho o sobre los hombros. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte superior. Repite el número de repeticiones deseado.', '/exercises/gifs/0852-JZuApnB.gif', '/exercises/images/0852-JZuApnB.jpg'),
('0853', 'weighted standing curl', 'Brazo', 'upper arms', 'weighted', 'biceps', 'forearms', ARRAY['forearms'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Mantén los codos cerca del torso y exhala mientras curvas los pesos hasta la altura de los hombros. Haz una pausa de un momento en la parte superior, luego inhala mientras bajas lentamente los pesos de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0853-M5Y7GPg.gif', '/exercises/images/0853-M5Y7GPg.jpg'),
('0854', 'weighted standing hand squeeze', 'Antebrazo', 'lower arms', 'weighted', 'forearms', 'biceps', ARRAY['biceps', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén un peso en cada mano. Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí. Aprieta las manos entre sí con la mayor fuerza posible, activando los antebrazos. Mantén la contracción durante unos segundos y luego suelta. Repite el número de repeticiones deseado.', '/exercises/gifs/0854-bjqbauy.gif', '/exercises/images/0854-bjqbauy.jpg'),
('3313', 'weighted straight bar dip', 'Pecho', 'chest', 'weighted', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Colócate entre las barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/3313-Ff18ItA.gif', '/exercises/images/3313-Ff18ItA.jpg'),
('3642', 'weighted stretch lunge', 'Pierna', 'upper legs', 'weighted', 'glutes', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, manteniendo la espalda recta. Baja el cuerpo flexionando las rodillas hasta que el muslo derecho quede paralelo al suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Continúa alternando las piernas durante el número de repeticiones deseado.', '/exercises/gifs/3642-13VW2VO.gif', '/exercises/images/3642-13VW2VO.jpg'),
('0856', 'weighted svend press', 'Pecho', 'chest', 'weighted', 'pectorals', 'shoulders', ARRAY['shoulders', 'triceps'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén un disco de peso frente al pecho con ambas manos. Mantén los codos ligeramente flexionados y las palmas mirándose entre sí. Empuja el disco de peso recto hacia adelante, extendiendo completamente los brazos. Haz una pausa de un momento al final del movimiento, luego lleva lentamente el disco de peso de nuevo a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0856-I1OBLnn.gif', '/exercises/images/0856-I1OBLnn.jpg'),
('1754', 'weighted three bench dips', 'Brazo', 'upper arms', 'weighted', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Camina con los pies hacia adelante, deslizando los glúteos fuera del banco y sosteniendo tu peso con los brazos. Baja el cuerpo flexionando los codos, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1754-gtO1ErP.gif', '/exercises/images/1754-gtO1ErP.jpg'),
('1755', 'weighted tricep dips', 'Brazo', 'upper arms', 'weighted', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas. Desliza los glúteos fuera del frente del banco con las piernas extendidas frente a ti. Mantén la espalda cerca del banco y los codos ligeramente flexionados. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1755-bZq4bwK.gif', '/exercises/images/1755-bZq4bwK.jpg'),
('1767', 'weighted triceps dip on high parallel bars', 'Brazo', 'upper arms', 'weighted', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Colócate entre dos barras paralelas con las manos agarrando las barras y los brazos completamente extendidos. Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo. Haz una pausa de un momento, luego empuja con las palmas para estirar los brazos y volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1767-K1vlode.gif', '/exercises/images/1767-K1vlode.jpg'),
('0857', 'wheel rollerout', 'Core', 'waist', 'wheel roller', 'abs', 'lower back', ARRAY['lower back'], 'Arrodíllate en el suelo y coloca el rodillo frente a ti. Coloca las manos en las asas del rodillo y extiende los brazos rectos hacia adelante. Activa los músculos del core y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el abdomen contraído. Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza. Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia las rodillas, manteniendo el control y el abdomen activado. Repite el número de repeticiones deseado.', '/exercises/gifs/0857-NAgVB3t.gif', '/exercises/images/0857-NAgVB3t.jpg'),
('3637', 'wheel run', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Comienza en posición de plancha con las manos sobre el rodillo y el cuerpo recto. Activa el core y comienza a hacer rodar el rodillo hacia adelante extendiendo los brazos. Continúa rodando hasta que tu cuerpo quede completamente extendido y los brazos por encima de la cabeza. Invierte el movimiento tirando del rodillo de vuelta hacia tu cuerpo, usando el core y los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/3637-km2Ljzj.gif', '/exercises/images/3637-km2Ljzj.jpg'),
('1429', 'wide grip pull-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos más separadas que la anchura de los hombros. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia arriba en dirección a la barra hasta que tu barbilla quede por encima de la barra. Baja el cuerpo de nuevo a la posición inicial con control. Repite el número de repeticiones deseado.', '/exercises/gifs/1429-Qqi7bko.gif', '/exercises/images/1429-Qqi7bko.jpg'),
('1367', 'wide grip rear pull-up', 'Espalda', 'back', 'body weight', 'lats', 'biceps', ARRAY['biceps', 'forearms'], 'Agarra la barra de dominadas con un agarre prono amplio, las manos un poco más separadas que la anchura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1367-OYFhXVD.gif', '/exercises/images/1367-OYFhXVD.jpg'),
('1311', 'wide hand push up', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Comienza en una posición de plancha alta con las manos más separadas que la anchura de los hombros. Mantén el cuerpo en línea recta de la cabeza a los pies. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1311-JmMVpR3.gif', '/exercises/images/1311-JmMVpR3.jpg'),
('2363', 'wide-grip chest dip on high parallel bars', 'Pecho', 'chest', 'body weight', 'pectorals', 'triceps', ARRAY['triceps', 'shoulders'], 'Colócate sobre las barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire. Inclínate ligeramente hacia adelante y baja el cuerpo flexionando los codos hasta que el pecho quede justo por encima de las barras. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/2363-O2K9Vb5.gif', '/exercises/images/2363-O2K9Vb5.jpg'),
('0858', 'wind sprints', 'Core', 'waist', 'body weight', 'abs', 'quadriceps', ARRAY['quadriceps', 'hamstrings', 'calves'], 'Busca un espacio abierto o una pista para realizar el ejercicio. Comienza de pie con los pies separados a la altura de los hombros. Comienza a correr lo más rápido que puedas, bombeando los brazos y elevando las rodillas. Continúa el sprint durante una distancia o periodo de tiempo específico. Descansa y repite el número de repeticiones deseado.', '/exercises/gifs/0858-Qoujh3Q.gif', '/exercises/images/0858-Qoujh3Q.jpg'),
('1604', 'world greatest stretch', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'glutes', ARRAY['glutes', 'quadriceps', 'calves'], 'Comienza en posición de zancada con el pie derecho adelante y el pie izquierdo atrás. Coloca las manos en el suelo a ambos lados de tu pie derecho. Baja la rodilla izquierda hacia el suelo y extiende la pierna derecha, manteniendo el pie derecho plano sobre el suelo. Gira el torso hacia la derecha, extendiendo el brazo derecho hacia el techo. Mantén esta posición durante unos segundos, luego vuelve a la posición inicial. Cambia de lado y repite el estiramiento con el pie izquierdo adelante.', '/exercises/gifs/1604-DFGXwZr.gif', '/exercises/images/1604-DFGXwZr.jpg'),
('1428', 'wrist circles', 'Antebrazo', 'lower arms', 'body weight', 'forearms', 'hands', ARRAY['hands', 'wrists'], 'Extiende los brazos rectos frente a ti. Cierra ambas manos en un puño. Gira las muñecas en un movimiento circular, manteniendo los brazos quietos. Continúa los círculos de muñeca el número de repeticiones deseado.', '/exercises/gifs/1428-2zNKRUB.gif', '/exercises/images/1428-2zNKRUB.jpg'),
('0859', 'wrist rollerer', 'Antebrazo', 'lower arms', 'weighted', 'forearms', 'biceps', ARRAY['biceps', 'triceps'], 'Sujeta un peso a un extremo de una cuerda o barra. Sostén el otro extremo de la cuerda o barra con ambas manos, con las palmas hacia abajo. Ponte de pie con los pies separados a la altura de los hombros y los brazos completamente extendidos frente a ti. Enrolla lentamente el peso hacia las manos flexionando las muñecas. Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0859-bd5b860.gif', '/exercises/images/0859-bd5b860.jpg')
